def parse_scalar(value: str) -> Any:
    value = value.strip()
    if value == "":
        return ""
    lowered = value.lower()
    if lowered in {"true", "yes", "on"}:
        return True
    if lowered in {"false", "no", "off"}:
        return False
    if lowered in {"null", "none", "~"}:
        return None
    if (value.startswith('"') and value.endswith('"')) or (value.startswith("'") and value.endswith("'")):
        return value[1:-1]
    try:
        if "." in value:
            return float(value)
        return int(value)
    except ValueError:
        return value


def parse_simple_yaml(text: str) -> Optional[dict[str, Any]]:
    """Parse a conservative one-level YAML subset without external deps."""
    data: dict[str, Any] = {}
    current_key: Optional[str] = None
    for raw_line in text.splitlines():
        line_no_comment = raw_line.split("#", 1)[0].rstrip()
        if not line_no_comment.strip():
            continue
        indent = len(line_no_comment) - len(line_no_comment.lstrip(" "))
        line = line_no_comment.strip()
        if indent == 0 and ":" in line and not line.startswith("- "):
            key, value = line.split(":", 1)
            current_key = key.strip()
            value = value.strip()
            data[current_key] = parse_scalar(value) if value else {}
            continue
        if current_key is None:
            continue
        if line.startswith("- "):
            if not isinstance(data.get(current_key), list):
                data[current_key] = []
            data[current_key].append(parse_scalar(line[2:]))
            continue
        if ":" in line:
            if not isinstance(data.get(current_key), dict):
                data[current_key] = {}
            key, value = line.split(":", 1)
            data[current_key][key.strip()] = parse_scalar(value)
    return data or None


def read_policy_file(project_path: Path, path: Path) -> Optional[dict[str, Any]]:
    try:
        relative = path.relative_to(project_path).as_posix()
        content = audit_core.read_repository_file(
            project_path,
            relative,
            max_bytes=1_000_000,
            max_seconds=10,
        )
        text = content.decode("utf-8-sig", errors="strict")
        if path.suffix.lower() == ".json":
            value = json.loads(text)
            return value if isinstance(value, dict) else None
        if path.suffix.lower() in {".yml", ".yaml"}:
            return parse_simple_yaml(text)
    except (ValueError, UnicodeError, json.JSONDecodeError, audit_core.AuditError):
        return None
    return None


def deep_merge(base: dict[str, Any], override: dict[str, Any]) -> dict[str, Any]:
    result = json.loads(json.dumps(base))
    for key, value in override.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = deep_merge(result[key], value)
        else:
            result[key] = value
    return result


def normalize_policy_override(
    value: dict[str, Any],
) -> tuple[dict[str, Any], list[str]]:
    """Remove v0.7/v0.8.1 custom-approval settings during a safe upgrade."""
    normalized = json.loads(json.dumps(value))
    ignored: list[str] = []
    if "externalActions" in normalized:
        normalized.pop("externalActions")
        ignored.append("externalActions")
    program_policy = normalized.get("program")
    if isinstance(program_policy, dict):
        for field in ("requireSignedApprovals", "allowedIdentityProviders"):
            if field in program_policy:
                program_policy.pop(field)
                ignored.append("program." + field)
    return normalized, ignored


def _string_list(value: Any, field: str) -> list[str]:
    if not isinstance(value, list) or not all(isinstance(item, str) and item.strip() for item in value):
        raise ToolError(f"JStack policy field '{field}' must be an array of non-empty strings.")
    return [item.strip() for item in value]


def _merge_unique(*groups: list[str]) -> list[str]:
    result: list[str] = []
    for group in groups:
        for item in group:
            if item not in result:
                result.append(item)
    return result


def validate_policy_override(value: dict[str, Any], path: Path) -> None:
    if not isinstance(value, dict):
        raise ToolError(f"JStack policy must be a JSON/YAML object: {path}")
    if "schemaVersion" in value and value["schemaVersion"] != "jstack.enterprise.v1":
        raise ToolError(f"Unsupported JStack policy schemaVersion in {path}: {value['schemaVersion']!r}")
    for field in ("requiredChecks", "protectedPaths"):
        if field in value:
            _string_list(value[field], field)
    for section in (
        "release",
        "security",
        "audit",
        "quant",
        "program",
        "launch",
    ):
        if section in value and not isinstance(value[section], dict):
            raise ToolError(f"JStack policy field '{section}' must be an object.")
    security = value.get("security") or {}
    if "sensitiveKeywords" in security:
        _string_list(security["sensitiveKeywords"], "security.sensitiveKeywords")
    audit = value.get("audit") or {}
    if "requiredDomains" in audit:
        configured_domains = _string_list(audit["requiredDomains"], "audit.requiredDomains")
        unsupported_domains = sorted(set(configured_domains) - set(audit_core.DOMAINS) - {"reliability"})
        if unsupported_domains:
            raise ToolError(
                "JStack policy audit.requiredDomains contains unsupported domains: "
                + ", ".join(unsupported_domains)
            )
    if "defaultProfile" in audit and audit["defaultProfile"] not in {"quick", "standard", "deep", "release"}:
        raise ToolError("JStack policy audit.defaultProfile must be quick, standard, deep, or release.")
    if "releaseProfile" in audit and audit["releaseProfile"] not in {"quick", "standard", "deep", "release"}:
        raise ToolError("JStack policy audit.releaseProfile must be quick, standard, deep, or release.")
    if "failOnSeverity" in audit and audit["failOnSeverity"] not in {"critical", "high", "medium", "low", "info"}:
        raise ToolError("JStack policy audit.failOnSeverity must be critical, high, medium, low, or info.")
    quant = value.get("quant") or {}
    if "requiredEvidence" in quant:
        _string_list(quant["requiredEvidence"], "quant.requiredEvidence")
    if "minimumHistoryQualityPercent" in quant:
        try:
            number = float(quant["minimumHistoryQualityPercent"])
        except (TypeError, ValueError) as exc:
            raise ToolError("JStack policy quant.minimumHistoryQualityPercent must be numeric.") from exc
        if not 0 <= number <= 100:
            raise ToolError("JStack policy quant.minimumHistoryQualityPercent must be between 0 and 100.")
    program_policy = value.get("program") or {}
    allowed_program_fields = {
        "maxPhases",
        "maxParallelPhases",
        "maxActiveMinutes",
        "requireCurrentEvidence",
        "requireFinalAudit",
    }
    unknown_program_fields = sorted(set(program_policy) - allowed_program_fields)
    if unknown_program_fields:
        raise ToolError(
            "JStack policy program contains unsupported fields: "
            + ", ".join(unknown_program_fields)
        )
    for field, maximum in (
        ("maxPhases", program_core.MAX_PHASES),
        ("maxParallelPhases", program_core.MAX_PARALLEL_PHASES),
        ("maxActiveMinutes", program_core.MAX_ACTIVE_MINUTES),
    ):
        if field in program_policy:
            configured = program_policy[field]
            if (
                not isinstance(configured, int)
                or isinstance(configured, bool)
                or not 1 <= configured <= maximum
            ):
                raise ToolError(
                    "JStack policy program.%s must be an integer from 1 to %d."
                    % (field, maximum)
                )
    for field in (
        "requireCurrentEvidence",
        "requireFinalAudit",
    ):
        if field in program_policy and not isinstance(program_policy[field], bool):
            raise ToolError("JStack policy program.%s must be boolean." % field)
    launch_policy = value.get("launch") or {}
    allowed_launch_fields = {
        "requireReceiptForProduction",
        "requireProfileDeclaration",
        "requireSurfaceReconciliation",
        "requireDeploymentFingerprint",
        "minimumRiskTier",
        "maxEvidenceAgeMinutes",
        "requiredControlIds",
        "advisoryControlIds",
        "requireReleaseAuditForSurfaces",
        "allowWaivers",
    }
    unknown_launch_fields = sorted(set(launch_policy) - allowed_launch_fields)
    if unknown_launch_fields:
        raise ToolError(
            "JStack policy launch contains unsupported fields: "
            + ", ".join(unknown_launch_fields)
        )
    for field in (
        "requireReceiptForProduction",
        "requireProfileDeclaration",
        "requireSurfaceReconciliation",
        "requireDeploymentFingerprint",
        "allowWaivers",
    ):
        if field in launch_policy and not isinstance(launch_policy[field], bool):
            raise ToolError(f"JStack policy launch.{field} must be boolean.")
    if "minimumRiskTier" in launch_policy:
        try:
            launch_core.normalize_risk_tier(
                launch_policy["minimumRiskTier"],
                "launch.minimumRiskTier",
            )
        except launch_core.LaunchError as exc:
            raise ToolError(str(exc)) from exc
    if "maxEvidenceAgeMinutes" in launch_policy:
        configured_age = launch_policy["maxEvidenceAgeMinutes"]
        if (
            not isinstance(configured_age, int)
            or isinstance(configured_age, bool)
            or not 1 <= configured_age <= 1440
        ):
            raise ToolError(
                "JStack policy launch.maxEvidenceAgeMinutes must be an integer from 1 to 1440."
            )
    try:
        launch_controls = launch_core.control_index()
    except launch_core.LaunchError as exc:
        raise ToolError("The packaged JStack launch-control catalogue is invalid.") from exc
    required_launch_controls = _string_list(
        launch_policy.get("requiredControlIds", []),
        "launch.requiredControlIds",
    )
    advisory_launch_controls = _string_list(
        launch_policy.get("advisoryControlIds", []),
        "launch.advisoryControlIds",
    )
    unknown_launch_controls = sorted(
        (set(required_launch_controls) | set(advisory_launch_controls))
        - set(launch_controls)
    )
    if unknown_launch_controls:
        raise ToolError(
            "JStack policy launch references unknown control ids: "
            + ", ".join(unknown_launch_controls)
        )
    overlapping_launch_controls = sorted(
        set(required_launch_controls) & set(advisory_launch_controls)
    )
    if overlapping_launch_controls:
        raise ToolError(
            "JStack policy launch controls cannot be both required and advisory: "
            + ", ".join(overlapping_launch_controls)
        )
    release_audit_surfaces = _string_list(
        launch_policy.get("requireReleaseAuditForSurfaces", []),
        "launch.requireReleaseAuditForSurfaces",
    )
    unknown_launch_surfaces = sorted(
        set(release_audit_surfaces) - set(launch_core.SURFACE_IDS)
    )
    if unknown_launch_surfaces:
        raise ToolError(
            "JStack policy launch.requireReleaseAuditForSurfaces contains unsupported surfaces: "
            + ", ".join(unknown_launch_surfaces)
        )
def apply_policy_floors(policy: dict[str, Any], project_path: Path) -> dict[str, Any]:
    """Enforce minimum controls that a repository policy cannot weaken."""
    policy["schemaVersion"] = "jstack.enterprise.v1"
    policy["requiredChecks"] = _merge_unique(
        _string_list(DEFAULT_ENTERPRISE_POLICY["requiredChecks"], "requiredChecks"),
        _string_list(policy.get("requiredChecks", []), "requiredChecks"),
    )
    policy_files = []
    for candidate in policy_candidates(project_path):
        try:
            policy_files.append(candidate.relative_to(project_path).as_posix())
        except ValueError:
            continue
    policy["protectedPaths"] = _merge_unique(
        _string_list(DEFAULT_ENTERPRISE_POLICY["protectedPaths"], "protectedPaths"),
        _string_list(policy.get("protectedPaths", []), "protectedPaths"),
        policy_files,
    )
    for key in ("requiresExplicitApproval", "requiresRollbackPlan", "requiresCanaryOrMonitoring", "requiresCleanDiffCheck"):
        policy.setdefault("release", {})[key] = True
    policy.setdefault("security", {})["secretScanRequired"] = True
    policy["security"]["sensitiveKeywords"] = _merge_unique(
        _string_list(DEFAULT_ENTERPRISE_POLICY["security"]["sensitiveKeywords"], "security.sensitiveKeywords"),
        _string_list(policy["security"].get("sensitiveKeywords", []), "security.sensitiveKeywords"),
    )
    audit = policy.setdefault("audit", {})
    default_audit = DEFAULT_ENTERPRISE_POLICY["audit"]
    audit["releaseProfile"] = "release"
    audit["networkAllowed"] = False
    audit["automaticFixesAllowed"] = False
    audit["arbitraryExecutablesAllowed"] = False
    audit["rawSecretsAllowed"] = False
    audit["incompleteCanPass"] = False
    audit["suppressionRequiresOwner"] = True
    audit["suppressionRequiresExpiry"] = True
    audit["requiredDomains"] = _merge_unique(
        _string_list(default_audit["requiredDomains"], "audit.requiredDomains"),
        _string_list(audit.get("requiredDomains", []), "audit.requiredDomains"),
    )
    audit.setdefault("defaultProfile", default_audit["defaultProfile"])
    severity_order = ["info", "low", "medium", "high", "critical"]
    configured_threshold = str(audit.get("failOnSeverity") or default_audit["failOnSeverity"])
    audit["failOnSeverity"] = severity_order[
        min(severity_order.index("high"), severity_order.index(configured_threshold))
    ]
    audit["releaseRequiresAuditReceipt"] = bool(audit.get("releaseRequiresAuditReceipt", False))
    policy.setdefault("quant", {})["requiresParameterFreeze"] = True
    policy["quant"]["requiresOutOfSample"] = True
    policy["quant"]["requiresCostModel"] = True
    policy["quant"]["requiredEvidence"] = _merge_unique(
        _string_list(DEFAULT_ENTERPRISE_POLICY["quant"]["requiredEvidence"], "quant.requiredEvidence"),
        _string_list(policy["quant"].get("requiredEvidence", []), "quant.requiredEvidence"),
    )
    policy["quant"]["minimumHistoryQualityPercent"] = max(
        float(DEFAULT_ENTERPRISE_POLICY["quant"]["minimumHistoryQualityPercent"]),
        float(policy["quant"].get("minimumHistoryQualityPercent", 0)),
    )
    program_policy = policy.setdefault("program", {})
    default_program = DEFAULT_ENTERPRISE_POLICY["program"]
    for field, absolute in (
        ("maxPhases", program_core.MAX_PHASES),
        ("maxParallelPhases", program_core.MAX_PARALLEL_PHASES),
        ("maxActiveMinutes", program_core.MAX_ACTIVE_MINUTES),
    ):
        program_policy[field] = min(
            int(program_policy.get(field, default_program[field])),
            int(default_program[field]),
            absolute,
        )
    program_policy["requireCurrentEvidence"] = True
    program_policy["requireFinalAudit"] = True
    launch_policy = policy.setdefault("launch", {})
    default_launch = DEFAULT_ENTERPRISE_POLICY["launch"]
    launch_policy["requireReceiptForProduction"] = True
    launch_policy["requireProfileDeclaration"] = True
    launch_policy["requireSurfaceReconciliation"] = True
    launch_policy["requireDeploymentFingerprint"] = True
    configured_risk_floor = str(
        launch_policy.get(
            "minimumRiskTier",
            default_launch["minimumRiskTier"],
        )
    )
    launch_policy["minimumRiskTier"] = launch_core.normalize_risk_tier(
        configured_risk_floor,
        "launch.minimumRiskTier",
    )
    launch_policy["maxEvidenceAgeMinutes"] = min(
        int(
            launch_policy.get(
                "maxEvidenceAgeMinutes",
                default_launch["maxEvidenceAgeMinutes"],
            )
        ),
        int(default_launch["maxEvidenceAgeMinutes"]),
        1440,
    )
    launch_policy["requiredControlIds"] = _merge_unique(
        _string_list(default_launch["requiredControlIds"], "launch.requiredControlIds"),
        _string_list(
            launch_policy.get("requiredControlIds", []),
            "launch.requiredControlIds",
        ),
    )
    launch_policy["advisoryControlIds"] = _merge_unique(
        _string_list(default_launch["advisoryControlIds"], "launch.advisoryControlIds"),
        _string_list(
            launch_policy.get("advisoryControlIds", []),
            "launch.advisoryControlIds",
        ),
    )
    launch_policy["requireReleaseAuditForSurfaces"] = _merge_unique(
        _string_list(
            default_launch["requireReleaseAuditForSurfaces"],
            "launch.requireReleaseAuditForSurfaces",
        ),
        _string_list(
            launch_policy.get("requireReleaseAuditForSurfaces", []),
            "launch.requireReleaseAuditForSurfaces",
        ),
    )
    launch_policy["allowWaivers"] = bool(
        launch_policy.get("allowWaivers", default_launch["allowWaivers"])
    )
    return policy


def policy_candidates(project_path: Path) -> list[Path]:
    return [
        project_path / "jstack.enterprise.json",
        project_path / "jstack.policy.json",
        project_path / "jstack.json",
        project_path / "jstack.yml",
        project_path / "jstack.yaml",
        project_path / ".jstack" / "jstack.enterprise.json",
        project_path / ".jstack" / "jstack.policy.json",
        project_path / ".jstack" / "jstack.yml",
        project_path / ".jstack" / "jstack.yaml",
        project_path / "gstack.enterprise.json",
        project_path / "gstack.policy.json",
        project_path / "gstack.json",
        project_path / "gstack.yml",
        project_path / "gstack.yaml",
        project_path / ".gstack" / "gstack.enterprise.json",
        project_path / ".gstack" / "gstack.policy.json",
        project_path / ".gstack" / "gstack.yml",
        project_path / ".gstack" / "gstack.yaml",
    ]


def load_enterprise_policy(project_path: Path) -> dict[str, Any]:
    project_path = project_path.resolve()
    existing = [path for path in policy_candidates(project_path) if path.exists() or path.is_symlink()]
    if len(existing) > 1:
        raise ToolError(
            "Multiple JStack policy files are ambiguous; keep exactly one: " + ", ".join(str(path) for path in existing)
        )
    for path in existing:
        if path.is_symlink():
            raise ToolError(f"JStack policy file may not be a symlink: {path}")
        metadata = path.lstat()
        if not stat.S_ISREG(metadata.st_mode) or metadata.st_size > 1_000_000:
            raise ToolError(f"JStack policy must be a regular file no larger than 1 MB: {path}")
        parsed = read_policy_file(project_path, path)
        if parsed is None:
            raise ToolError(f"Could not parse JStack policy file: {path}")
        normalized, ignored_legacy_fields = normalize_policy_override(parsed)
        validate_policy_override(normalized, path)
        policy = apply_policy_floors(
            deep_merge(DEFAULT_ENTERPRISE_POLICY, normalized), project_path
        )
        policy["_sourcePath"] = str(path)
        policy["_usingDefault"] = False
        policy["_ignoredLegacyFields"] = ignored_legacy_fields
        return policy
    policy = apply_policy_floors(json.loads(json.dumps(DEFAULT_ENTERPRISE_POLICY)), project_path)
    policy["_sourcePath"] = None
    policy["_usingDefault"] = True
    policy["_ignoredLegacyFields"] = []
    return policy


def _git_text(result: dict[str, Any]) -> str:
    stdout = result.get("stdout", b"")
    return stdout.decode("utf-8", errors="replace") if isinstance(stdout, bytes) else str(stdout)


def resolve_base_ref(project_path: Path, requested: Optional[str] = None) -> dict[str, Any]:
    candidates = [requested] if requested else ["@{upstream}", "origin/main", "origin/master", "main", "master"]
    for candidate in candidates:
        if not candidate:
            continue
        verify = run_complete(["git", "rev-parse", "--verify", f"{candidate}^{{commit}}"], project_path, timeout=8)
        if not verify["ok"]:
            continue
        merge_base = run_complete(["git", "merge-base", str(candidate), "HEAD"], project_path, timeout=8)
        if merge_base["ok"]:
            return {
                "requested": requested,
                "resolvedRef": str(candidate),
                "baseCommit": _git_text(merge_base).strip(),
            }
    if requested:
        raise ToolError(f"Could not resolve requested base_ref: {requested}")
    return {"requested": None, "resolvedRef": None, "baseCommit": None}


def git_change_evidence(project_path: Path, base_ref: Optional[str] = None) -> dict[str, Any]:
    root_raw = git_root(project_path)
    if not root_raw:
        raise ToolError(f"JStack change evidence requires a git repository: {project_path}")
    root = Path(root_raw).resolve()
    base = resolve_base_ref(root, base_ref)
    commands: list[tuple[str, list[str]]] = []
    if base["baseCommit"]:
        commands.append(("committed", ["git", "diff", "--no-ext-diff", "--no-textconv", "--name-only", "-z", f"{base['baseCommit']}..HEAD", "--"]))
    commands.extend(
        [
            ("unstaged", ["git", "diff", "--no-ext-diff", "--no-textconv", "--name-only", "-z", "--"]),
            ("staged", ["git", "diff", "--no-ext-diff", "--no-textconv", "--cached", "--name-only", "-z", "--"]),
            ("untracked", ["git", "ls-files", "--others", "--exclude-standard", "-z"]),
        ]
    )
    seen: set[str] = set()
    files: list[str] = []
    sources: dict[str, list[str]] = {}
    for source, command in commands:
        result = run_complete(command, root, timeout=15, max_bytes=10_000_000)
        if not result["ok"]:
            raise ToolError(f"Could not collect {source} git change evidence: {result['stderr']}")
        source_files: list[str] = []
        for raw in result["stdout"].split(b"\0"):
            item = decode_git_relative_path(raw, "changed") if raw else ""
            if item and item not in seen:
                seen.add(item)
                files.append(item)
            if item:
                source_files.append(item)
        sources[source] = source_files
        if len(files) > MAX_CHANGED_FILES:
            raise ToolError(f"Changed-file evidence exceeds the {MAX_CHANGED_FILES}-file safety limit.")
    return {
        "gitRoot": str(root),
        "baseRef": base["resolvedRef"],
        "baseCommit": base["baseCommit"],
        "files": files,
        "sources": sources,
        "complete": True,
    }


def git_changed_files(project_path: Path, base_ref: Optional[str] = None) -> list[str]:
    return git_change_evidence(project_path, base_ref)["files"]


def project_state(project_path: Path) -> dict[str, Any]:
    root_raw = git_root(project_path)
    if not root_raw:
        raise ToolError("JStack evidence receipts require a git repository with a committed revision.")
    root = Path(root_raw).resolve()
    head_result = run_complete(["git", "rev-parse", "HEAD"], root, timeout=8)
    if not head_result["ok"]:
        raise ToolError("JStack evidence receipts require a valid git HEAD commit.")
    head = _git_text(head_result).strip()
    status_result = run_complete(
        ["git", "status", "--porcelain=v1", "-z", "--untracked-files=all"],
        root,
        timeout=15,
        max_bytes=20_000_000,
    )
    tracked_result = run_complete(
        ["git", "ls-files", "-s", "-z"],
        root,
        timeout=20,
        max_bytes=20_000_000,
    )
    flags_result = run_complete(
        ["git", "ls-files", "-v", "-z"],
        root,
        timeout=20,
        max_bytes=20_000_000,
    )
    untracked_result = run_complete(
        ["git", "ls-files", "--others", "--exclude-standard", "-z"],
        root,
        timeout=15,
        max_bytes=20_000_000,
    )
    for label, result in (
        ("status", status_result),
        ("tracked index", tracked_result),
        ("index flags", flags_result),
        ("untracked", untracked_result),
    ):
        if not result["ok"]:
            raise ToolError(f"Could not fingerprint project {label}: {result['stderr']}")
    digest = hashlib.sha256()
    digest.update(str(root).encode("utf-8"))
    digest.update(b"\0")
    digest.update(head.encode("ascii"))
    digest.update(b"\0")
    digest.update(status_result["stdout"])
    digest.update(b"\0")
    digest.update(flags_result["stdout"])
    total_bytes = 0
    fingerprinted_files = 0

    def hash_regular_file(relative: str, label: str) -> None:
        nonlocal total_bytes, fingerprinted_files
        remaining = MAX_FINGERPRINT_BYTES - total_bytes
        if remaining <= 0:
            raise ToolError(
                f"Project fingerprint exceeds the {MAX_FINGERPRINT_BYTES}-byte safety limit."
            )
        try:
            size, file_digest = audit_core.digest_repository_file(
                root,
                relative,
                max_bytes=remaining,
                max_seconds=30,
            )
        except audit_core.AuditError as exc:
            raise ToolError(f"Cannot fingerprint regular file safely: {label}") from exc
        fingerprinted_files += 1
        if fingerprinted_files > MAX_FINGERPRINT_FILES:
            raise ToolError(f"Project fingerprint exceeds the {MAX_FINGERPRINT_FILES}-file safety limit.")
        total_bytes += size
        digest.update(b"<sha256>")
        digest.update(size.to_bytes(8, "big"))
        digest.update(bytes.fromhex(file_digest))

    tracked: list[str] = []
    submodules_present = False
    for raw in tracked_result["stdout"].split(b"\0"):
        if not raw:
            continue
        try:
            index_meta, path_raw = raw.split(b"\t", 1)
            relative = decode_git_relative_path(path_raw, "tracked index entry")
        except ValueError as exc:
            raise ToolError("Git returned a tracked index entry that cannot be represented safely.") from exc
        candidate = root / relative
        digest.update(index_meta)
        digest.update(b"\t")
        digest.update(relative.encode("utf-8"))
        digest.update(b"\0")
        try:
            metadata = candidate.lstat()
        except FileNotFoundError:
            digest.update(b"<missing>")
        else:
            if stat.S_ISLNK(metadata.st_mode):
                target = os.readlink(candidate).encode("utf-8", errors="surrogateescape")
                total_bytes += len(target)
                if total_bytes > MAX_FINGERPRINT_BYTES:
                    raise ToolError(
                        f"Project fingerprint exceeds the {MAX_FINGERPRINT_BYTES}-byte safety limit."
                    )
                digest.update(b"<symlink>")
                digest.update(target)
            elif stat.S_ISREG(metadata.st_mode):
                try:
                    candidate.resolve().relative_to(root)
                except ValueError as exc:
                    raise ToolError(f"Tracked file resolves outside the repository: {relative}") from exc
                hash_regular_file(relative, relative)
            elif stat.S_ISDIR(metadata.st_mode) and index_meta.startswith(b"160000 "):
                submodules_present = True
                digest.update(b"<gitlink>")
            else:
                raise ToolError(f"Cannot fingerprint tracked non-regular path: {relative}")
        tracked.append(relative)

    if submodules_present:
        submodules = run_complete(
            ["git", "submodule", "status", "--recursive"],
            root,
            timeout=30,
            max_bytes=5_000_000,
        )
        if not submodules["ok"]:
            raise ToolError(f"Could not fingerprint submodules: {submodules['stderr']}")
        digest.update(submodules["stdout"])

    hidden_index_flags: list[str] = []
    for raw in flags_result["stdout"].split(b"\0"):
        if len(raw) < 3:
            continue
        tag = chr(raw[0])
        if tag.islower() or tag == "S":
            hidden_index_flags.append(
                decode_git_relative_path(raw[2:], "index-flag")
            )

    untracked: list[str] = []
    for raw in untracked_result["stdout"].split(b"\0"):
        if not raw:
            continue
        relative = decode_git_relative_path(raw, "untracked")
        candidate = root / relative
        if candidate.is_symlink():
            raise ToolError(f"Cannot fingerprint symlinked untracked path: {relative}")
        path = candidate.resolve(strict=False)
        try:
            path.relative_to(root)
        except ValueError as exc:
            raise ToolError(f"Untracked path escapes repository root: {relative}") from exc
        if not path.is_file():
            raise ToolError(f"Cannot fingerprint non-regular untracked path: {relative}")
        digest.update(relative.encode("utf-8"))
        digest.update(b"\0")
        hash_regular_file(relative, relative)
        untracked.append(relative)
    return {
        "gitRoot": str(root),
        "gitHead": head,
        "projectFingerprint": digest.hexdigest(),
        "clean": not bool(status_result["stdout"]) and not hidden_index_flags,
        "trackedFileCount": len(tracked),
        "fingerprintedBytes": total_bytes,
        "hiddenIndexFlags": hidden_index_flags,
        "untrackedFiles": untracked,
    }


def evidence_subject(project_path: Path, base_ref: Optional[str] = None) -> dict[str, Any]:
    state = project_state(project_path)
    base = resolve_base_ref(Path(state["gitRoot"]), base_ref) if base_ref else {
        "requested": None,
        "resolvedRef": None,
        "baseCommit": None,
    }
    policy = load_enterprise_policy(Path(state["gitRoot"]))
    public_policy = {key: value for key, value in policy.items() if not key.startswith("_")}
    policy_digest = hashlib.sha256(
        json.dumps(public_policy, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    return {
        **state,
        "baseRef": base["resolvedRef"],
        "baseCommit": base["baseCommit"],
        "policyDigest": policy_digest,
        "toolVersion": SERVER_VERSION,
    }


def _ui_git_identity(project_path: Path, state: Optional[dict[str, Any]] = None) -> dict[str, str]:
    state = state or project_state(project_path)
    root = Path(state["gitRoot"])
    common = run_complete(["git", "rev-parse", "--git-common-dir"], root, timeout=8)
    tree = run_complete(["git", "rev-parse", "HEAD^{tree}"], root, timeout=8)
    if not common["ok"] or not tree["ok"]:
        raise ToolError("Could not derive the Product Interface Git identity.")
    common_text = _git_text(common).strip()
    common_path = Path(common_text)
    if not common_path.is_absolute():
        common_path = root / common_path
    common_path = common_path.resolve()
    tree_oid = _git_text(tree).strip()
    if not re.fullmatch(r"[0-9a-f]{40,64}", tree_oid):
        raise ToolError("Git returned an unsupported tree object identity.")
    return {
        "gitRoot": str(root),
        "commonDir": str(common_path),
        "gitHead": str(state["gitHead"]),
        "projectFingerprint": str(state["projectFingerprint"]),
        "treeSha256": hashlib.sha256(tree_oid.encode("ascii")).hexdigest(),
        "policyDigest": str(
            state.get("policyDigest") or evidence_subject(root)["policyDigest"]
        ),
    }


UI_PATH_ONLY_ASSET_SUFFIXES = {
    ".avif", ".gif", ".icns", ".ico", ".jpeg", ".jpg", ".otf", ".png",
    ".svg", ".svgz", ".ttf", ".webmanifest", ".webp", ".woff", ".woff2",
}
UI_STRONG_TEXT_SUFFIXES = {
    ".aspx", ".astro", ".axaml", ".css", ".cshtml", ".ejs", ".erb", ".ftl", ".glade",
    ".handlebars", ".hbs", ".htm", ".html", ".jsx", ".less", ".liquid",
    ".mdx", ".mustache", ".njk", ".nunjucks", ".pcss", ".php", ".pug",
    ".qml", ".razor", ".sass", ".scss", ".storyboard", ".styl", ".stylus",
    ".svelte", ".twig", ".tsx", ".ui", ".vue", ".xaml", ".xib", ".jsp", ".jspx",
}
UI_AMBIGUOUS_SOURCE_SUFFIXES = {
    ".c", ".cc", ".cjs", ".cpp", ".cs", ".csproj", ".cts", ".dart", ".gradle",
    ".h", ".hpp", ".java", ".js", ".kt", ".kts", ".m", ".mjs", ".mm",
    ".mts", ".py", ".resx", ".rs", ".swift", ".ts", ".xml",
}


def _ui_file_candidate_kind(
    relative: str,
    *,
    scoped: bool = True,
    context_platforms: Iterable[str] = (),
) -> Optional[str]:
    normalized = relative.replace("\\", "/")
    suffix = Path(normalized).suffix.lower()
    if suffix in UI_STRONG_TEXT_SUFFIXES:
        return "strong-text"
    name = Path(normalized).name.lower()
    if name in {
        "package.json", "pubspec.yaml", "cargo.toml", "tailwind.config.js",
        "tailwind.config.cjs", "tailwind.config.mjs", "tailwind.config.ts",
    }:
        return "strong-text"
    ui_path = bool(
        re.search(
            r"(^|/)(?:assets?|images?|icons?|public|static|fonts?|resources?|tokens?|design-tokens?|themes?|styles?|design-system|ui|components|Assets\.xcassets)(/|[._-])|(^|/)(?:[^/]+/)?src/main/res/(?:layout|values[^/]*|drawable[^/]*|mipmap[^/]*|font)(/|$)",
            normalized,
            re.IGNORECASE,
        )
    )
    conventional_asset_name = bool(
        re.fullmatch(
            r"(?:logo(?:[._-].*)?|favicon(?:[._-].*)?|site\.webmanifest|manifest\.webmanifest|app-icon(?:[._-].*)?)",
            Path(normalized).name,
            re.IGNORECASE,
        )
    )
    if (ui_path or conventional_asset_name or suffix == ".webmanifest") and suffix in UI_PATH_ONLY_ASSET_SUFFIXES:
        return "path-only"
    if ui_path and suffix in {".json", ".yaml", ".yml", ".toml"}:
        return "strong-text"
    contextual_path = bool(
        re.search(
            r"(^|/)(?:app|pages|routes|frontend|client|web|website|components|views|screens|ui|webview|electron|renderer|react-native|src-tauri|tauri|ios|swiftui|macos|appkit|android|compose|flutter|widgets?|gtk|qt)(/|[._-])",
            normalized,
            re.IGNORECASE,
        )
    )
    contextual_name = bool(
        re.search(
            r"(?:view|screen|window|widget|component|page|layout|theme|style|app|form|controller)",
            Path(normalized).stem,
            re.IGNORECASE,
        )
    )
    # A conventional native `main` file is worth inspecting for a scoped
    # change, but is too weak a signal for a whole-repository scan.  Its
    # contents still have to match a UI framework before the change activates
    # Product Interface routing.
    weak_entrypoint_name = scoped and Path(normalized).stem.lower() == "main"
    if suffix not in UI_AMBIGUOUS_SOURCE_SUFFIXES:
        return None
    context = {str(item) for item in context_platforms}
    contextual_suffixes = {
        "flutter": {".dart"},
        "ios": {".swift", ".m", ".mm"},
        "macos": {".swift", ".m", ".mm"},
        "android": {".gradle", ".java", ".kt", ".kts", ".xml"},
        "windows": {".cs", ".resx", ".xaml"},
        "linux": {".c", ".cc", ".cpp", ".h", ".hpp", ".py"},
        "tauri": {".rs"},
        "react-native": {".cjs", ".js", ".jsx", ".mjs", ".ts", ".tsx"},
        "electron": {".cjs", ".js", ".jsx", ".mjs", ".ts", ".tsx"},
        "webview": {".cjs", ".js", ".jsx", ".mjs", ".ts", ".tsx"},
    }
    if any(
        platform in context and suffix in suffixes
        for platform, suffixes in contextual_suffixes.items()
    ):
        return "ambiguous-text"
    backend_context = bool(
        re.search(
            r"(^|/)(?:api|backend|server|services?|workers?|scripts?|cli|tests?|fixtures?|migrations?|database|db)(/|[._-])",
            normalized,
            re.IGNORECASE,
        )
        or re.fullmatch(
            r"(?:api|backend|server|service|worker|cli|migration|database|db)(?:[._-].*)?",
            Path(normalized).stem,
            re.IGNORECASE,
        )
    )
    if backend_context and not contextual_path and not contextual_name:
        return None
    if contextual_path or contextual_name or weak_entrypoint_name:
        return "ambiguous-text"
    # JavaScript and TypeScript are common at repository roots and under generic
    # src/ directories, so changed-file routing inspects their bounded contents.
    if scoped and suffix in {".js", ".mjs", ".cjs", ".ts", ".mts", ".cts"}:
        return "ambiguous-text"
    return None


def _ui_file_candidate(
    relative: str,
    *,
    scoped: bool = True,
    context_platforms: Iterable[str] = (),
) -> bool:
    return _ui_file_candidate_kind(
        relative,
        scoped=scoped,
        context_platforms=context_platforms,
    ) is not None


def _ui_ambiguous_text_is_ui(relative: str, raw: bytes) -> bool:
    observed = ui_core.detect_product_ui(
        [(relative, raw.decode("utf-8", errors="ignore"))]
    )
    return bool(observed["applicable"])


def _ui_read_worktree_text_candidate(
    root: Path,
    relative: str,
    candidate_kind: Optional[str],
    *,
    side: str,
) -> Optional[bytes]:
    """Read a UI candidate, cheaply dismissing a bounded oversized weak source."""
    try:
        return audit_core.read_repository_file(
            root,
            relative,
            max_bytes=UI_HINT_MAX_FILE_BYTES,
            max_seconds=10,
        )
    except audit_core.AuditError as first_error:
        if candidate_kind != "ambiguous-text":
            raise ToolError(
                f"Product Interface detection could not safely read the {side} repository file: {relative}"
            ) from first_error
        try:
            probe = audit_core.read_repository_file(
                root,
                relative,
                max_bytes=UI_HINT_MAX_AMBIGUOUS_SCAN_BYTES,
                max_seconds=10,
            )
        except audit_core.AuditError as exc:
            raise ToolError(
                f"Product Interface detection could not safely classify the oversized {side} UI-capable file: {relative}"
            ) from exc
        if _ui_ambiguous_text_is_ui(relative, probe):
            raise ToolError(
                f"Product Interface detection could not safely read the {side} side of oversized UI-capable file: {relative}"
            ) from first_error
        return None


def _ui_read_revision_text_candidate(
    root: Path,
    revision: str,
    relative: str,
    candidate_kind: Optional[str],
    *,
    side: str,
) -> tuple[bool, Optional[bytes]]:
    """Return (present, bytes); bounded oversized non-UI weak sources return None bytes."""
    size = _ui_revision_blob_size(root, revision, relative)
    if size is None:
        return False, None
    raw = _audit_stage4_revision_file(
        root,
        revision,
        relative,
        max_bytes=UI_HINT_MAX_FILE_BYTES,
    )
    if raw is not None:
        return True, raw
    if candidate_kind != "ambiguous-text" or size > UI_HINT_MAX_AMBIGUOUS_SCAN_BYTES:
        raise ToolError(
            f"Product Interface detection could not safely read the {side} side of changed UI-capable file: {relative}"
        )
    probe = _audit_stage4_revision_file(
        root,
        revision,
        relative,
        max_bytes=UI_HINT_MAX_AMBIGUOUS_SCAN_BYTES,
    )
    if probe is None:
        raise ToolError(
            f"Product Interface detection could not safely read the {side} side of changed UI-capable file: {relative}"
        )
    if _ui_ambiguous_text_is_ui(relative, probe):
        raise ToolError(
            f"Product Interface detection could not safely read the {side} side of oversized UI-capable file: {relative}"
        )
    return True, None


def _ui_validate_path_only_repository_file(root: Path, relative: str) -> int:
    try:
        size, _ = audit_core.digest_repository_file(
            root,
            relative,
            max_bytes=UI_HINT_MAX_ASSET_BYTES,
            max_seconds=15,
        )
    except audit_core.AuditError as exc:
        raise ToolError(
            f"Product Interface path-only asset is not one bounded stable regular file: {relative}"
        ) from exc
    return size


def _ui_revision_blob_size(root: Path, revision: str, relative: str) -> Optional[int]:
    result = run_complete(
        ["git", "ls-tree", "-z", "-l", revision, "--", relative],
        root,
        timeout=8,
        max_bytes=100_000,
    )
    if not result["ok"]:
        return None
    entries = [item for item in result["stdout"].split(b"\0") if item]
    if len(entries) != 1:
        return None
    try:
        metadata, raw_path = entries[0].split(b"\t", 1)
        mode, kind, object_id, size_text = metadata.decode("ascii").split()
        decoded_path = decode_git_relative_path(raw_path, "UI revision asset")
        size = int(size_text)
    except (UnicodeError, ValueError, ToolError):
        return None
    if (
        decoded_path != relative
        or mode not in {"100644", "100755"}
        or kind != "blob"
        or not re.fullmatch(r"[0-9a-f]{40,64}", object_id)
        or not 0 <= size <= UI_HINT_MAX_ASSET_BYTES
    ):
        return None
    return size


def _ui_collect_documents(
    project_path: Path,
    paths: Optional[list[str]] = None,
    *,
    status: Optional[dict[str, Any]] = None,
) -> list[tuple[str, str]]:
    root = Path(git_root(project_path) or project_path).resolve()
    unscoped = paths is None
    if paths is None:
        listed = run_complete(
            ["git", "ls-files", "-z"], root, timeout=20, max_bytes=10_000_000
        )
        if not listed["ok"]:
            raise ToolError("Could not enumerate files for Product Interface detection.")
        paths = [
            decode_git_relative_path(raw, "UI detection")
            for raw in listed["stdout"].split(b"\0")
            if raw
        ]
    normalized_paths = sorted({path.replace("\\", "/") for path in paths})
    context_by_path = _ui_repository_context_by_path(root, normalized_paths)
    selected = sorted(
        {
            path
            for path in normalized_paths
            if _ui_file_candidate(
                path,
                scoped=not unscoped,
                context_platforms=context_by_path.get(path, ()),
            )
        }
    )
    candidate_count = len(selected)
    if len(selected) > UI_HINT_MAX_FILES:
        if not unscoped:
            raise ToolError(
                f"Product Interface detection exceeds the {UI_HINT_MAX_FILES}-file safety limit."
            )
        selected = selected[:UI_HINT_MAX_FILES]
    if status is not None:
        status.update(
            {
                "candidateFileCount": candidate_count,
                "inspectionTruncated": candidate_count > len(selected),
            }
        )
    total = 0
    documents: list[tuple[str, str]] = []
    for relative in selected:
        candidate_kind = _ui_file_candidate_kind(
            relative,
            scoped=not unscoped,
            context_platforms=context_by_path.get(relative, ()),
        )
        candidate = root / relative
        if not candidate.exists():
            continue
        if candidate_kind == "path-only":
            _ui_validate_path_only_repository_file(root, relative)
            documents.append((relative, ""))
            continue
        raw = _ui_read_worktree_text_candidate(
            root,
            relative,
            candidate_kind,
            side="selected",
        )
        if raw is None:
            continue
        total += len(raw)
        if total > UI_HINT_MAX_TOTAL_BYTES:
            raise ToolError(
                f"Product Interface detection exceeds the {UI_HINT_MAX_TOTAL_BYTES}-byte safety limit."
            )
        documents.append((relative, raw.decode("utf-8", errors="ignore")))
    return documents


def _ui_change_records(
    project_path: Path, baseline_head: str, candidate_head: str
) -> list[dict[str, Optional[str]]]:
    result = run_complete(
        [
            "git",
            "diff",
            "--raw",
            "-z",
            "--full-index",
            "--no-abbrev",
            "--find-renames=50%",
            baseline_head,
            candidate_head,
            "--",
        ],
        project_path,
        timeout=30,
        max_bytes=20_000_000,
    )
    if not result["ok"]:
        raise ToolError("Could not enumerate the exact Product Interface candidate change set.")
    tokens = result["stdout"].split(b"\0")
    if tokens and tokens[-1] == b"":
        tokens.pop()
    records: list[dict[str, Optional[str]]] = []
    index = 0
    while index < len(tokens):
        try:
            header = tokens[index].decode("ascii")
        except UnicodeDecodeError as exc:
            raise ToolError("Git returned an invalid Product Interface change status.") from exc
        index += 1
        fields = header.split()
        if len(fields) != 5 or not fields[0].startswith(":"):
            raise ToolError("Git returned an invalid Product Interface raw change record.")
        baseline_mode = fields[0][1:]
        candidate_mode = fields[1]
        baseline_oid, candidate_oid, status = fields[2:]
        if (
            not re.fullmatch(r"[0-7]{6}", baseline_mode)
            or not re.fullmatch(r"[0-7]{6}", candidate_mode)
            or not re.fullmatch(r"[0-9a-f]{40,64}", baseline_oid)
            or not re.fullmatch(r"[0-9a-f]{40,64}", candidate_oid)
        ):
            raise ToolError("Git returned invalid Product Interface object metadata.")
        kind = status[:1]
        if kind in {"R", "C"}:
            if index + 1 >= len(tokens):
                raise ToolError("Git returned a truncated Product Interface rename record.")
            before = decode_git_relative_path(tokens[index], "UI baseline path")
            after = decode_git_relative_path(tokens[index + 1], "UI candidate path")
            index += 2
        elif kind in {"A", "M", "D", "T"}:
            if index >= len(tokens):
                raise ToolError("Git returned a truncated Product Interface change record.")
            path = decode_git_relative_path(tokens[index], "UI changed path")
            index += 1
            before = None if kind == "A" else path
            after = None if kind == "D" else path
        else:
            raise ToolError(
                f"Git returned unsupported Product Interface change status: {status}"
            )
        records.append({
            "status": status,
            "baselinePath": before,
            "candidatePath": after,
            "baselineMode": baseline_mode,
            "candidateMode": candidate_mode,
        })
    if len(records) > UI_HINT_MAX_FILES:
        raise ToolError(
            f"Product Interface candidate changes exceed the {UI_HINT_MAX_FILES}-file safety limit."
        )
    return records


def _ui_collect_changed_documents(
    project_path: Path,
    baseline_head: str,
    records: list[dict[str, Optional[str]]],
) -> list[tuple[str, str]]:
    root = Path(git_root(project_path) or project_path).resolve()
    baseline_paths = sorted({
        str(record["baselinePath"])
        for record in records
        if record["baselinePath"] is not None
    })
    candidate_paths = sorted({
        str(record["candidatePath"])
        for record in records
        if record["candidatePath"] is not None
    })
    baseline_context_by_path = _ui_repository_context_by_path(
        root, baseline_paths, revision=baseline_head
    )
    candidate_context_by_path = _ui_repository_context_by_path(
        root, candidate_paths
    )
    documents: list[tuple[str, str]] = []
    total = 0
    for record in records:
        if "160000" in {record.get("baselineMode"), record.get("candidateMode")}:
            continue
        baseline_path = record["baselinePath"]
        candidate_path = record["candidatePath"]
        if baseline_path is not None:
            baseline_kind = _ui_file_candidate_kind(
                baseline_path,
                context_platforms=baseline_context_by_path.get(baseline_path, ()),
            )
            if baseline_kind == "path-only":
                if _ui_revision_blob_size(root, baseline_head, baseline_path) is None:
                    raise ToolError(
                        f"Could not safely bind the baseline path-only UI asset: {baseline_path}"
                    )
                documents.append((baseline_path, ""))
            elif baseline_kind is not None:
                present, raw = _ui_read_revision_text_candidate(
                    root,
                    baseline_head,
                    baseline_path,
                    baseline_kind,
                    side="baseline",
                )
                if not present:
                    raise ToolError(
                        f"Could not safely read the baseline side of changed UI-capable file: {baseline_path}"
                    )
                if raw is not None:
                    total += len(raw)
                    documents.append((baseline_path, raw.decode("utf-8", errors="ignore")))
        if candidate_path is not None:
            candidate_kind = _ui_file_candidate_kind(
                candidate_path,
                context_platforms=candidate_context_by_path.get(candidate_path, ()),
            )
            if candidate_kind == "path-only":
                _ui_validate_path_only_repository_file(root, candidate_path)
                documents.append((candidate_path, ""))
            elif candidate_kind is not None:
                raw = _ui_read_worktree_text_candidate(
                    root,
                    candidate_path,
                    candidate_kind,
                    side="candidate",
                )
                if raw is not None:
                    total += len(raw)
                    documents.append((candidate_path, raw.decode("utf-8", errors="ignore")))
        if total > UI_HINT_MAX_TOTAL_BYTES:
            raise ToolError(
                f"Product Interface candidate detection exceeds the {UI_HINT_MAX_TOTAL_BYTES}-byte safety limit."
            )
    return documents


def _ui_collect_scoped_documents(
    project_path: Path,
    baseline_head: str,
    paths: list[str],
) -> list[tuple[str, str]]:
    """Read both sides of a bounded changed path set for routing decisions."""
    root = Path(git_root(project_path) or project_path).resolve()
    normalized_paths = sorted({path.replace("\\", "/") for path in paths})
    baseline_context_by_path = _ui_repository_context_by_path(
        root, normalized_paths, revision=baseline_head
    )
    candidate_context_by_path = _ui_repository_context_by_path(
        root, normalized_paths
    )
    selected = sorted({
        path
        for path in normalized_paths
        if (
            _ui_file_candidate(
                path,
                context_platforms=baseline_context_by_path.get(path, ()),
            )
            or _ui_file_candidate(
                path,
                context_platforms=candidate_context_by_path.get(path, ()),
            )
        )
    })
    if len(selected) > UI_HINT_MAX_FILES:
        raise ToolError(
            f"Product Interface detection exceeds the {UI_HINT_MAX_FILES}-file safety limit."
        )
    documents: list[tuple[str, str]] = []
    total = 0
    for relative in selected:
        baseline_kind = _ui_file_candidate_kind(
            relative,
            context_platforms=baseline_context_by_path.get(relative, ()),
        )
        candidate_kind = _ui_file_candidate_kind(
            relative,
            context_platforms=candidate_context_by_path.get(relative, ()),
        )
        if baseline_kind == "path-only" or candidate_kind == "path-only":
            baseline_present = _ui_revision_blob_size(root, baseline_head, relative) is not None
            if baseline_present and baseline_kind == "path-only":
                documents.append((relative, ""))
            candidate = root / relative
            if candidate.exists() and candidate_kind == "path-only":
                _ui_validate_path_only_repository_file(root, relative)
                documents.append((relative, ""))
            elif not baseline_present:
                raise ToolError(
                    f"Product Interface detection could not bind either side of changed path: {relative}"
                )
            continue
        baseline_present, baseline_raw = _ui_read_revision_text_candidate(
            root,
            baseline_head,
            relative,
            baseline_kind,
            side="baseline",
        ) if baseline_kind is not None else (
            _ui_revision_blob_size(root, baseline_head, relative) is not None,
            None,
        )
        if baseline_raw is not None:
            total += len(baseline_raw)
            documents.append((relative, baseline_raw.decode("utf-8", errors="ignore")))
        candidate = root / relative
        if candidate.exists() and candidate_kind is not None:
            candidate_raw = _ui_read_worktree_text_candidate(
                root,
                relative,
                candidate_kind,
                side="changed",
            )
            if candidate_raw is not None:
                total += len(candidate_raw)
                documents.append((relative, candidate_raw.decode("utf-8", errors="ignore")))
        elif not baseline_present:
            raise ToolError(
                f"Product Interface detection could not bind either side of changed path: {relative}"
            )
        if total > UI_HINT_MAX_TOTAL_BYTES:
            raise ToolError(
                f"Product Interface detection exceeds the {UI_HINT_MAX_TOTAL_BYTES}-byte safety limit."
            )
    return documents


def _ui_repository_context_entries(
    project_path: Path,
    *,
    revision: Optional[str] = None,
) -> list[tuple[str, str]]:
    root = Path(git_root(project_path) or project_path).resolve()
    command = (
        ["git", "ls-files", "-z"]
        if revision is None
        else ["git", "ls-tree", "-r", "-z", "--name-only", revision, "--"]
    )
    listed = run_complete(
        command, root, timeout=20, max_bytes=10_000_000
    )
    if not listed["ok"]:
        side = "baseline " if revision is not None else ""
        raise ToolError(
            f"Could not enumerate {side}Product Interface wrapper context."
        )
    paths = [
        decode_git_relative_path(raw, "UI wrapper context")
        for raw in listed["stdout"].split(b"\0")
        if raw
    ]
    entries: set[tuple[str, str]] = set()
    xcode_prefixes: set[str] = set()

    def add_for_segment(normalized: str, segment: str, platform: str) -> None:
        parts = normalized.split("/")
        lowered = [part.lower() for part in parts]
        if segment.lower() in lowered:
            index = lowered.index(segment.lower())
            entries.add(("/".join(parts[:index]), platform))

    for path in paths:
        normalized = path.replace("\\", "/")
        for segment in ("src-tauri", "tauri"):
            add_for_segment(normalized, segment, "tauri")
        for segment in ("electron", "main-process", "renderer-process"):
            add_for_segment(normalized, segment, "electron")
        add_for_segment(normalized, "react-native", "react-native")
        add_for_segment(normalized, "flutter", "flutter")
        add_for_segment(normalized, "webview", "webview")
        lowered_name = Path(normalized).name.lower()
        parent = Path(normalized).parent.as_posix()
        prefix = "" if parent == "." else parent
        if lowered_name == "tauri.conf.json":
            entries.add((prefix, "tauri"))
        if lowered_name.startswith("react-native.config."):
            entries.add((prefix, "react-native"))
        if re.search(
            r"(^|/)(?:capacitor\.config\.(?:js|ts|json)|ionic\.config\.json|config\.xml)$|(^|/)(?:cordova|capacitor|ionic)(/|[._-])",
            normalized,
            re.IGNORECASE,
        ):
            entries.add((prefix, "webview"))
        android_match = re.search(
            r"(^|/)(?P<module>[^/]+)/src/main/(?:AndroidManifest\.xml|java(?:/|$)|kotlin(?:/|$)|res(?:/|$))",
            normalized,
            re.IGNORECASE,
        )
        if android_match:
            module_end = android_match.start("module") + len(android_match.group("module"))
            entries.add((normalized[:module_end], "android"))
        path_parts = normalized.split("/")
        for index, part in enumerate(path_parts):
            if part.lower().endswith((".xcodeproj", ".xcworkspace")):
                project_prefix = "/".join(path_parts[:index])
                xcode_prefixes.add(project_prefix)
        if lowered_name.endswith((".qml", ".ui", ".glade")):
            # Qt/GTK resource trees are commonly siblings of the form source,
            # so bind their context at the repository root.
            entries.add(("", "linux"))

    package_paths = sorted(
        path for path in paths if Path(path).name.lower() == "package.json"
    )
    if len(package_paths) > 256:
        raise ToolError("Product Interface wrapper context exceeds 256 package manifests.")
    context_bytes = 0

    def read_context_document(relative: str) -> bytes:
        nonlocal context_bytes
        try:
            if revision is None:
                raw = audit_core.read_repository_file(
                    root,
                    relative,
                    max_bytes=UI_HINT_MAX_AMBIGUOUS_SCAN_BYTES,
                    max_seconds=10,
                )
            else:
                raw = _audit_stage4_revision_file(
                    root,
                    revision,
                    relative,
                    max_bytes=UI_HINT_MAX_AMBIGUOUS_SCAN_BYTES,
                )
                if raw is None:
                    raise ToolError(
                        f"Could not safely read baseline {relative} for Product Interface wrapper context."
                    )
            context_bytes += len(raw)
            if context_bytes > UI_HINT_MAX_TOTAL_BYTES:
                raise ToolError(
                    "Product Interface wrapper manifests exceed the aggregate byte limit."
                )
            return raw
        except (audit_core.AuditError, UnicodeError) as exc:
            raise ToolError(
                f"Could not safely read {relative} for Product Interface wrapper context."
            ) from exc

    xcode_projects = sorted(
        path
        for path in paths
        if path.lower().endswith(".xcodeproj/project.pbxproj")
    )
    if len(xcode_projects) > 256:
        raise ToolError("Product Interface Xcode context exceeds 256 project manifests.")
    xcode_platforms_by_prefix: dict[str, set[str]] = {
        prefix: set() for prefix in xcode_prefixes
    }
    for project_path in xcode_projects:
        try:
            project_text = read_context_document(project_path).decode("utf-8")
        except UnicodeError as exc:
            raise ToolError(
                f"Could not safely parse {project_path} for Product Interface Xcode context."
            ) from exc
        project_parts = project_path.replace("\\", "/").split("/")
        project_prefix = ""
        for index, part in enumerate(project_parts):
            if part.lower().endswith(".xcodeproj"):
                project_prefix = "/".join(project_parts[:index])
                break
        detected_xcode_platforms: set[str] = set()
        if re.search(
            r"\b(?:SDKROOT\s*=\s*(?:iphoneos|iphonesimulator)|"
            r"IPHONEOS_DEPLOYMENT_TARGET\s*=|TARGETED_DEVICE_FAMILY\s*=)",
            project_text,
            re.IGNORECASE,
        ) or re.search(
            r"\bSUPPORTED_PLATFORMS\s*=\s*[^;]*(?:iphoneos|iphonesimulator)",
            project_text,
            re.IGNORECASE,
        ):
            detected_xcode_platforms.add("ios")
        if re.search(
            r"\b(?:SDKROOT\s*=\s*macosx|MACOSX_DEPLOYMENT_TARGET\s*=)",
            project_text,
            re.IGNORECASE,
        ) or re.search(
            r"\bSUPPORTED_PLATFORMS\s*=\s*[^;]*macosx",
            project_text,
            re.IGNORECASE,
        ):
            detected_xcode_platforms.add("macos")
        if not detected_xcode_platforms:
            detected_xcode_platforms.update(("ios", "macos"))
        xcode_platforms_by_prefix.setdefault(project_prefix, set()).update(
            detected_xcode_platforms
        )
    for prefix, detected_platforms in xcode_platforms_by_prefix.items():
        if not detected_platforms:
            detected_platforms.update(("ios", "macos"))
        for platform in detected_platforms:
            entries.add((prefix, platform))

    for package_path in package_paths:
        try:
            package = json.loads(read_context_document(package_path).decode("utf-8"))
        except (UnicodeError, json.JSONDecodeError) as exc:
            raise ToolError(
                f"Could not safely parse {package_path} for Product Interface wrapper context."
            ) from exc
        if not isinstance(package, dict):
            raise ToolError(
                f"{package_path} must be an object for Product Interface wrapper context."
            )
        dependency_names: set[str] = set()
        for field in ("dependencies", "devDependencies", "peerDependencies", "optionalDependencies"):
            value = package.get(field, {})
            if value is not None and not isinstance(value, dict):
                raise ToolError(
                    f"{package_path} {field} must be an object when present."
                )
            dependency_names.update(str(name) for name in (value or {}))
        package_parent = Path(package_path).parent.as_posix()
        package_prefix = "" if package_parent == "." else package_parent
        if "electron" in dependency_names:
            entries.add((package_prefix, "electron"))
        if "react-native" in dependency_names:
            entries.add((package_prefix, "react-native"))
        if dependency_names & {"@capacitor/core", "cordova", "cordova-lib", "@ionic/core", "@ionic/react", "@ionic/vue"}:
            entries.add((package_prefix, "webview"))

    pubspec_paths = sorted(
        path for path in paths if Path(path).name.lower() == "pubspec.yaml"
    )
    csproj_paths = sorted(path for path in paths if path.lower().endswith(".csproj"))
    if len(pubspec_paths) > 256 or len(csproj_paths) > 256:
        raise ToolError("Product Interface native project context exceeds 256 manifests per kind.")
    for pubspec_path in pubspec_paths:
        try:
            pubspec = read_context_document(pubspec_path).decode("utf-8")
        except UnicodeError as exc:
            raise ToolError(
                f"Could not safely parse {pubspec_path} for Product Interface wrapper context."
            ) from exc
        if re.search(r"(?m)^\s*sdk\s*:\s*flutter\s*(?:#.*)?$", pubspec):
            parent = Path(pubspec_path).parent.as_posix()
            entries.add(("" if parent == "." else parent, "flutter"))
    windows_project_pattern = re.compile(
        r"<(?:UseWPF|UseWindowsForms)>\s*true\s*</(?:UseWPF|UseWindowsForms)>"
        r"|Microsoft\.(?:WindowsAppSDK|NET\.Sdk\.(?:Razor|BlazorWebAssembly))"
        r"|(?:PackageReference|Sdk)[^>]+(?:Avalonia|WinUI)",
        re.IGNORECASE,
    )
    for csproj_path in csproj_paths:
        try:
            csproj = read_context_document(csproj_path).decode("utf-8")
        except UnicodeError as exc:
            raise ToolError(
                f"Could not safely parse {csproj_path} for Product Interface wrapper context."
            ) from exc
        if windows_project_pattern.search(csproj):
            parent = Path(csproj_path).parent.as_posix()
            entries.add(("" if parent == "." else parent, "windows"))
    return sorted(entries)


def _ui_context_entry_applies(prefix: str, relative: str) -> bool:
    return not prefix or relative == prefix or relative.startswith(prefix + "/")


def _ui_repository_context_platforms(
    project_path: Path,
    paths: Optional[list[str]] = None,
    *,
    revision: Optional[str] = None,
) -> list[str]:
    entries = _ui_repository_context_entries(project_path, revision=revision)
    selected = None if paths is None else [path.replace("\\", "/") for path in paths]
    contexts = {
        platform
        for prefix, platform in entries
        if selected is None
        or any(_ui_context_entry_applies(prefix, path) for path in selected)
    }
    return [
        platform
        for platform in (
            "webview", "ios", "android", "react-native", "flutter", "electron",
            "tauri", "macos", "windows", "linux",
        )
        if platform in contexts
    ]


def _ui_repository_context_by_path(
    project_path: Path,
    paths: list[str],
    *,
    revision: Optional[str] = None,
) -> dict[str, list[str]]:
    entries = _ui_repository_context_entries(project_path, revision=revision)
    result: dict[str, list[str]] = {}
    for raw_path in paths:
        relative = raw_path.replace("\\", "/")
        contexts = {
            platform
            for prefix, platform in entries
            if _ui_context_entry_applies(prefix, relative)
        }
        if contexts:
            result[relative] = [
                platform
                for platform in (
                    "webview", "ios", "android", "react-native", "flutter",
                    "electron", "tauri", "macos", "windows", "linux",
                )
                if platform in contexts
            ]
    return result


def _ui_merge_repository_context_by_path(
    *context_maps: dict[str, list[str]],
) -> dict[str, list[str]]:
    merged: dict[str, set[str]] = {}
    for context_map in context_maps:
        for path, platforms in context_map.items():
            merged.setdefault(path, set()).update(platforms)
    order = (
        "webview", "ios", "android", "react-native", "flutter", "electron",
        "tauri", "macos", "windows", "linux",
    )
    return {
        path: [platform for platform in order if platform in platforms]
        for path, platforms in sorted(merged.items())
    }


def _ui_changed_repository_context_by_path(
    project_path: Path,
    baseline_head: str,
    records: list[dict[str, Optional[str]]],
) -> dict[str, list[str]]:
    baseline_paths = sorted({
        str(record["baselinePath"])
        for record in records
        if record["baselinePath"] is not None
    })
    candidate_paths = sorted({
        str(record["candidatePath"])
        for record in records
        if record["candidatePath"] is not None
    })
    return _ui_merge_repository_context_by_path(
        _ui_repository_context_by_path(
            project_path, baseline_paths, revision=baseline_head
        ),
        _ui_repository_context_by_path(project_path, candidate_paths),
    )


def _ui_detection(project_path: Path, paths: Optional[list[str]] = None) -> dict[str, Any]:
    status: dict[str, Any] = {}
    documents = _ui_collect_documents(project_path, paths, status=status)
    document_paths = [path for path, _ in documents]
    return ui_core.detect_product_ui(
        documents,
        candidate_file_count=status["candidateFileCount"],
        inspection_truncated=status["inspectionTruncated"],
        context_platforms_by_path=_ui_repository_context_by_path(
            project_path, document_paths
        ),
    )


def _ui_applicability(
    project_path: Path,
    *,
    goal: str = "",
    paths: Optional[list[str]] = None,
    baseline_head: Optional[str] = None,
) -> dict[str, Any]:
    gitlink_change = False
    if paths is not None and baseline_head:
        current_state = project_state(project_path)
        if current_state["clean"]:
            selected_paths = {path.replace("\\", "/") for path in paths}
            records = [
                record
                for record in _ui_change_records(
                    Path(current_state["gitRoot"]),
                    baseline_head,
                    str(current_state["gitHead"]),
                )
                if record["baselinePath"] in selected_paths
                or record["candidatePath"] in selected_paths
            ]
            gitlink_change = any(
                "160000" in {
                    record.get("baselineMode"), record.get("candidateMode")
                }
                for record in records
            )
            documents = _ui_collect_changed_documents(
                project_path, baseline_head, records
            )
            repository_context = _ui_changed_repository_context_by_path(
                project_path, baseline_head, records
            )
        else:
            documents = _ui_collect_scoped_documents(
                project_path, baseline_head, paths
            )
            normalized_paths = sorted({
                path.replace("\\", "/") for path in paths
            })
            repository_context = _ui_merge_repository_context_by_path(
                _ui_repository_context_by_path(
                    project_path, normalized_paths, revision=baseline_head
                ),
                _ui_repository_context_by_path(project_path, normalized_paths),
            )
        detection = ui_core.detect_product_ui(
            documents,
            context_platforms_by_path=repository_context,
        )
    else:
        detection = _ui_detection(project_path, paths)
    explicit_ui = any(re.search(pattern, goal, re.IGNORECASE) for pattern in UI_INTENT_PATTERNS)
    changed_scope = paths is not None
    if gitlink_change:
        state = "review-required"
        reason = "changed-gitlink-requires-independent-ui-resolution"
    elif explicit_ui or (changed_scope and detection["applicable"]):
        state = "required"
        reason = "explicit-ui-goal" if explicit_ui else "changed-ui-paths"
    elif changed_scope:
        state = "inactive"
        reason = "no-ui-evidence-in-change-set"
    elif detection["applicable"] or detection["inspectionTruncated"]:
        state = "review-required"
        reason = (
            "unscoped-ui-inspection-truncated"
            if detection["inspectionTruncated"]
            else "repository-ui-capability-without-scoped-change"
        )
    else:
        state = "inactive"
        reason = "no-ui-evidence"
    result = {
        "schemaVersion": "jstack.ui.applicability.v1",
        "state": state,
        "reason": reason,
        "goalDigest": hashlib.sha256(goal.strip().encode("utf-8")).hexdigest(),
        "changedScopeEvaluated": changed_scope,
        "detection": detection,
    }
    result["applicabilitySha256"] = ui_core.canonical_digest(result)
    return result


def _ui_evidence_root(project_path: Path) -> Path:
    state = project_state(project_path)
    identity = _ui_git_identity(project_path, state)
    project_key = hashlib.sha256(
        (identity["commonDir"] + "\0" + identity["gitRoot"]).encode("utf-8")
    ).hexdigest()[:24]
    return Path.home() / ".jstack" / "evidence" / "ui" / project_key


def _ui_reference_root(project_path: Path, bundle_id: str) -> Path:
    state = project_state(project_path)
    identity = _ui_git_identity(project_path, state)
    project_key = hashlib.sha256(
        (identity["commonDir"] + "\0" + identity["gitRoot"]).encode("utf-8")
    ).hexdigest()[:24]
    if not re.fullmatch(r"[a-z][a-z0-9._-]{1,79}", bundle_id):
        raise ToolError("Reference bundle id is invalid.")
    return (
        Path.home()
        / ".jstack"
        / "evidence"
        / "ui-reference"
        / project_key
        / bundle_id
    )


def _validate_ui_evidence_root_authority(root: Path) -> None:
    """Reject aliasing or permissive components below the fixed user home."""
    if os.name != "posix":
        raise ToolError(
            "UI reference finalization requires a POSIX host because this "
            "stdlib-only server cannot verify Windows DACL and reparse privacy."
        )
    home = Path.home()
    try:
        relative = root.relative_to(home)
    except ValueError as exc:
        raise ToolError("The Product Interface evidence root is outside the fixed user home.") from exc
    current = home
    paths = [home]
    for part in relative.parts:
        current = current / part
        paths.append(current)
    uid = os.getuid() if hasattr(os, "getuid") else None
    for index, path in enumerate(paths):
        try:
            metadata = path.lstat()
        except OSError as exc:
            raise ToolError(
                "The complete fixed Product Interface evidence directory chain must already exist."
            ) from exc
        if stat.S_ISLNK(metadata.st_mode) or not stat.S_ISDIR(metadata.st_mode):
            raise ToolError(
                "The Product Interface evidence directory chain may not contain symlinks or non-directories."
            )
        if uid is not None and metadata.st_uid != uid:
            raise ToolError(
                "The Product Interface evidence directory chain must be current-user owned."
            )
        if index > 0 and stat.S_IMODE(metadata.st_mode) & 0o077:
            raise ToolError(
                "Product Interface evidence directories below the home must be private mode 0700."
            )


def _ui_candidate_delta(project_path: Path, baseline_head: str) -> dict[str, Any]:
    state = project_state(project_path)
    identity = _ui_git_identity(project_path, state)
    if state["gitHead"] == baseline_head:
        raise ToolError("UI finalization requires a distinct committed candidate after the baseline.")
    ancestor = run_complete(
        ["git", "merge-base", "--is-ancestor", baseline_head, state["gitHead"]],
        project_path,
        timeout=15,
    )
    if ancestor["returncode"] != 0:
        raise ToolError("The UI candidate must be a strict descendant of the contracted baseline.")
    records = _ui_change_records(project_path, baseline_head, state["gitHead"])
    committed = sorted(
        {
            path
            for record in records
            for path in (record["baselinePath"], record["candidatePath"])
            if path is not None
        }
    )
    diff = run_complete(
        [
            "git",
            "diff",
            "--no-ext-diff",
            "--no-textconv",
            "--binary",
            "--full-index",
            f"{baseline_head}..{state['gitHead']}",
            "--",
        ],
        project_path,
        timeout=30,
        max_bytes=100_000_000,
    )
    if not diff["ok"]:
        raise ToolError("Could not derive the exact Product Interface baseline-to-candidate diff.")
    return {
        **identity,
        "clean": bool(state["clean"]),
        "changedPaths": committed,
        "changedPathsSha256": ui_core.canonical_digest(committed),
        "changeRecords": records,
        "changeRecordsSha256": ui_core.canonical_digest(records),
        "diffSha256": hashlib.sha256(diff["stdout"]).hexdigest(),
    }


def _b64encode(value: bytes) -> str:
    return base64.urlsafe_b64encode(value).decode("ascii").rstrip("=")


def _b64decode(value: str) -> bytes:
    return base64.urlsafe_b64decode(value + "=" * (-len(value) % 4))


def issue_receipt(payload: dict[str, Any]) -> str:
    body = dict(payload)
    body["serverSession"] = SERVER_SESSION_ID
    body["issuedAt"] = now_iso()
    encoded = _b64encode(json.dumps(body, sort_keys=True, separators=(",", ":")).encode("utf-8"))
    signature = _b64encode(hmac.new(_RECEIPT_SECRET, encoded.encode("ascii"), hashlib.sha256).digest())
    return f"{encoded}.{signature}"


def _ui_contract_key_path() -> Path:
    return Path.home() / ".jstack" / "keys" / "ui-contract-hmac-v1"


def _ui_contract_key_metadata_valid(
    metadata: os.stat_result,
    *,
    directory: bool,
    private_directory: bool = True,
) -> bool:
    expected_type = stat.S_ISDIR if directory else stat.S_ISREG
    expected_mode = 0o700 if directory else 0o600
    if not expected_type(metadata.st_mode):
        return False
    if not directory and (
        metadata.st_nlink != 1 or metadata.st_size != UI_CONTRACT_HMAC_KEY_BYTES
    ):
        return False
    if os.name == "posix":
        if hasattr(os, "getuid") and metadata.st_uid != os.getuid():
            return False
        actual_mode = stat.S_IMODE(metadata.st_mode)
        if directory and not private_directory:
            if actual_mode & 0o022:
                return False
        elif actual_mode != expected_mode:
            return False
    return True


def _ui_contract_hmac_key_posix(path: Path, *, create: bool) -> bytes:
    """Create/read the durable UI-contract key without following child links."""
    home = Path.home()
    try:
        relative = path.relative_to(home)
    except ValueError as exc:
        raise ToolError("The Product Interface contract key must remain below the user home.") from exc
    if tuple(relative.parts) != (".jstack", "keys", "ui-contract-hmac-v1"):
        raise ToolError("The Product Interface contract key path is not the fixed JStack path.")
    directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_CLOEXEC", 0)
    nofollow = getattr(os, "O_NOFOLLOW", 0)
    try:
        current_fd = os.open(str(home), directory_flags)
    except OSError as exc:
        raise ToolError("The user home could not be opened for Product Interface key validation.") from exc
    try:
        for component in (".jstack", "keys"):
            if create:
                try:
                    os.mkdir(component, 0o700, dir_fd=current_fd)
                    os.fsync(current_fd)
                except FileExistsError:
                    pass
            try:
                child_fd = os.open(
                    component,
                    directory_flags | nofollow,
                    dir_fd=current_fd,
                )
            except OSError as exc:
                raise ToolError(
                    "The Product Interface contract key directory is missing, linked, or inaccessible."
                ) from exc
            metadata = os.fstat(child_fd)
            if not _ui_contract_key_metadata_valid(
                metadata,
                directory=True,
                private_directory=component == "keys",
            ):
                os.close(child_fd)
                raise ToolError(
                    "Product Interface key directories must be current-user real directories; the key directory must be mode 0700 and its JStack parent must not be group/world writable."
                )
            os.close(current_fd)
            current_fd = child_fd

        key_flags = (
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NONBLOCK", 0)
            | nofollow
        )
        try:
            key_fd = os.open(path.name, key_flags, dir_fd=current_fd)
        except FileNotFoundError:
            if not create:
                raise ToolError(
                    "The Product Interface contract key does not exist; create a contract before verifying one."
                )
            secret = secrets.token_bytes(UI_CONTRACT_HMAC_KEY_BYTES)
            create_flags = (
                os.O_WRONLY
                | os.O_CREAT
                | os.O_EXCL
                | getattr(os, "O_CLOEXEC", 0)
                | nofollow
            )
            try:
                created_fd = os.open(
                    path.name,
                    create_flags,
                    0o600,
                    dir_fd=current_fd,
                )
            except FileExistsError:
                key_fd = os.open(path.name, key_flags, dir_fd=current_fd)
            except OSError as exc:
                raise ToolError("The Product Interface contract key could not be created safely.") from exc
            else:
                try:
                    written = 0
                    while written < len(secret):
                        count = os.write(created_fd, secret[written:])
                        if count <= 0:
                            raise OSError("short key write")
                        written += count
                    os.fsync(created_fd)
                except OSError as exc:
                    raise ToolError("The Product Interface contract key could not be written durably.") from exc
                finally:
                    os.close(created_fd)
                os.fsync(current_fd)
                key_fd = os.open(path.name, key_flags, dir_fd=current_fd)
        except OSError as exc:
            raise ToolError(
                "The Product Interface contract key is missing, linked, or inaccessible."
            ) from exc
        try:
            before = os.fstat(key_fd)
            if not _ui_contract_key_metadata_valid(before, directory=False):
                raise ToolError(
                    "The Product Interface contract key must be a current-user mode-0600, single-link, 32-byte regular file."
                )
            chunks: list[bytes] = []
            remaining = UI_CONTRACT_HMAC_KEY_BYTES + 1
            while remaining:
                chunk = os.read(key_fd, remaining)
                if not chunk:
                    break
                chunks.append(chunk)
                remaining -= len(chunk)
            after = os.fstat(key_fd)
            stable_fields = (
                "st_dev",
                "st_ino",
                "st_mode",
                "st_nlink",
                "st_size",
                "st_uid",
                "st_mtime_ns",
                "st_ctime_ns",
            )
            if any(getattr(before, field) != getattr(after, field) for field in stable_fields):
                raise ToolError("The Product Interface contract key changed while it was read.")
            try:
                entry = os.stat(path.name, dir_fd=current_fd, follow_symlinks=False)
                reopened_fd = os.open(path.name, key_flags, dir_fd=current_fd)
            except OSError as exc:
                raise ToolError(
                    "The Product Interface contract key directory entry changed while it was read."
                ) from exc
            try:
                reopened = os.fstat(reopened_fd)
            finally:
                os.close(reopened_fd)
            if any(
                getattr(after, field) != getattr(entry, field)
                or getattr(after, field) != getattr(reopened, field)
                for field in stable_fields
            ):
                raise ToolError(
                    "The Product Interface contract key identity changed while it was read."
                )
            key = b"".join(chunks)
            if len(key) != UI_CONTRACT_HMAC_KEY_BYTES:
                raise ToolError("The Product Interface contract key has an invalid length.")
            return key
        finally:
            os.close(key_fd)
    finally:
        os.close(current_fd)


def _ui_contract_key_is_durable() -> bool:
    return bool(
        os.name == "posix"
        and os.supports_dir_fd
        and os.open in os.supports_dir_fd
    )


def _ui_contract_hmac_key(*, create: bool = False) -> bytes:
    path = _ui_contract_key_path()
    if _ui_contract_key_is_durable():
        return _ui_contract_hmac_key_posix(path, create=create)
    # The generic portable filesystem API cannot verify Windows DACLs or
    # reparse-point ancestry with the same descriptor guarantees. Keep the
    # contract usable within one server session without persisting a forgeable
    # secret; cross-session durability is explicitly POSIX-only in v1.
    return _RECEIPT_SECRET


def _ui_contract_signing_key(*, create: bool = False) -> bytes:
    return hmac.new(
        _ui_contract_hmac_key(create=create),
        UI_CONTRACT_HMAC_DOMAIN,
        hashlib.sha256,
    ).digest()


def issue_ui_contract_receipt(payload: dict[str, Any]) -> str:
    key = _ui_contract_signing_key(create=True)
    body = dict(payload)
    body["serverSession"] = SERVER_SESSION_ID
    body["issuedAt"] = now_iso()
    body["keyIdSha256"] = hashlib.sha256(key).hexdigest()
    body["keyDurability"] = (
        "posix-user-key-v1"
        if _ui_contract_key_is_durable()
        else "server-session-v1"
    )
    encoded = _b64encode(
        json.dumps(body, sort_keys=True, separators=(",", ":")).encode("utf-8")
    )
    signature = _b64encode(
        hmac.new(key, encoded.encode("ascii"), hashlib.sha256).digest()
    )
    return f"{encoded}.{signature}"


def verify_ui_contract_receipt(token: str, *, require_fresh: bool) -> dict[str, Any]:
    try:
        encoded, supplied_signature = token.split(".", 1)
        key = _ui_contract_signing_key()
        expected_signature = _b64encode(
            hmac.new(key, encoded.encode("ascii"), hashlib.sha256).digest()
        )
        if not hmac.compare_digest(supplied_signature, expected_signature):
            raise ValueError("signature mismatch")
        payload = json.loads(_b64decode(encoded).decode("utf-8"))
        issued = _dt.datetime.fromisoformat(str(payload["issuedAt"]))
        expires = _dt.datetime.fromisoformat(str(payload["expiresAt"]))
        if issued.tzinfo is None or expires.tzinfo is None:
            raise ValueError("timezone-aware timestamps required")
    except Exception as exc:
        raise ToolError("Product Interface contract receipt is malformed or has an invalid durable signature.") from exc
    now = _dt.datetime.now(_dt.timezone.utc)
    checks = {
        "kind": payload.get("kind") == "ui-contract",
        "issuerSession": bool(
            re.fullmatch(r"[0-9a-f]{32}", str(payload.get("serverSession") or ""))
        ),
        "keyId": payload.get("keyIdSha256") == hashlib.sha256(key).hexdigest(),
        "keyDurability": payload.get("keyDurability")
        == (
            "posix-user-key-v1"
            if _ui_contract_key_is_durable()
            else "server-session-v1"
        ),
        "issued": issued <= now,
        "boundedExpiry": 0 < (expires - issued).total_seconds() <= UI_CONTRACT_MAX_AGE_SECONDS,
    }
    if require_fresh:
        checks["fresh"] = issued <= now < expires
    if not all(checks.values()):
        state = "stale" if require_fresh else "invalid"
        raise ToolError(f"Product Interface contract receipt is {state} or fails its durable binding.")
    return payload


def _ui_reference_signing_key(*, create: bool = False) -> bytes:
    return hmac.new(
        _ui_contract_hmac_key(create=create),
        UI_REFERENCE_HMAC_DOMAIN,
        hashlib.sha256,
    ).digest()


def issue_ui_reference_receipt(payload: dict[str, Any]) -> str:
    key = _ui_reference_signing_key(create=True)
    body = dict(payload)
    body["serverSession"] = SERVER_SESSION_ID
    body["issuedAt"] = now_iso()
    body["keyIdSha256"] = hashlib.sha256(key).hexdigest()
    body["keyDurability"] = (
        "posix-user-key-v1"
        if _ui_contract_key_is_durable()
        else "server-session-v1"
    )
    encoded = _b64encode(
        json.dumps(body, sort_keys=True, separators=(",", ":")).encode("utf-8")
    )
    signature = _b64encode(
        hmac.new(key, encoded.encode("ascii"), hashlib.sha256).digest()
    )
    return f"{encoded}.{signature}"


def verify_ui_reference_receipt(
    token: str,
    *,
    expected_kind: str,
    require_fresh: bool,
) -> dict[str, Any]:
    if expected_kind not in {"ui-reference-contract", "ui-reference-finalization"}:
        raise ToolError("Product Interface reference receipt kind is unsupported.")
    try:
        encoded, supplied_signature = token.split(".", 1)
        key = _ui_reference_signing_key()
        expected_signature = _b64encode(
            hmac.new(key, encoded.encode("ascii"), hashlib.sha256).digest()
        )
        if not hmac.compare_digest(supplied_signature, expected_signature):
            raise ValueError("signature mismatch")
        payload = json.loads(_b64decode(encoded).decode("utf-8"))
        issued = _dt.datetime.fromisoformat(str(payload["issuedAt"]))
        expires = _dt.datetime.fromisoformat(str(payload["expiresAt"]))
        if issued.tzinfo is None or expires.tzinfo is None:
            raise ValueError("timezone-aware timestamps required")
    except Exception as exc:
        raise ToolError(
            "Product Interface reference receipt is malformed or has an invalid durable signature."
        ) from exc
    now = _dt.datetime.now(_dt.timezone.utc)
    checks = {
        "kind": payload.get("kind") == expected_kind,
        "issuerSession": bool(
            re.fullmatch(r"[0-9a-f]{32}", str(payload.get("serverSession") or ""))
        ),
        "keyId": payload.get("keyIdSha256") == hashlib.sha256(key).hexdigest(),
        "keyDurability": payload.get("keyDurability")
        == (
            "posix-user-key-v1"
            if _ui_contract_key_is_durable()
            else "server-session-v1"
        ),
        "issued": issued <= now,
        "boundedExpiry": 0
        < (expires - issued).total_seconds()
        <= UI_REFERENCE_MAX_AGE_SECONDS,
    }
    if require_fresh:
        checks["fresh"] = issued <= now < expires
    if not all(checks.values()):
        state = "stale" if require_fresh else "invalid"
        raise ToolError(
            f"Product Interface reference receipt is {state} or fails its durable binding."
        )
    return payload


def verify_signed_session_token(token: str, expected_kind: str) -> dict[str, Any]:
    try:
        encoded, supplied_signature = token.split(".", 1)
        expected_signature = _b64encode(
            hmac.new(_RECEIPT_SECRET, encoded.encode("ascii"), hashlib.sha256).digest()
        )
        if not hmac.compare_digest(supplied_signature, expected_signature):
            raise ValueError("signature mismatch")
        payload = json.loads(_b64decode(encoded).decode("utf-8"))
        issued = _dt.datetime.fromisoformat(str(payload["issuedAt"]))
        expires = _dt.datetime.fromisoformat(str(payload["expiresAt"]))
        if issued.tzinfo is None or expires.tzinfo is None:
            raise ValueError("timezone-aware timestamps required")
    except Exception as exc:
        raise ToolError(
            "Session token is malformed, expired, or was not issued by this JStack server session."
        ) from exc
    now = _dt.datetime.now(_dt.timezone.utc)
    checks = {
        "kind": payload.get("kind") == expected_kind,
        "session": payload.get("serverSession") == SERVER_SESSION_ID,
        "fresh": issued <= now < expires,
        "boundedExpiry": 0 < (expires - issued).total_seconds() <= RECEIPT_MAX_AGE_SECONDS,
    }
    if not all(checks.values()):
        raise ToolError("Session token is stale or does not match this JStack server session.")
    return payload


def verify_receipt(
    receipt: str,
    expected_kind: str,
    state: dict[str, Any],
    expected_subject: Optional[dict[str, Any]] = None,
    require_passed: bool = True,
) -> dict[str, Any]:
    try:
        encoded, supplied_signature = receipt.split(".", 1)
        expected_signature = _b64encode(hmac.new(_RECEIPT_SECRET, encoded.encode("ascii"), hashlib.sha256).digest())
        if not hmac.compare_digest(supplied_signature, expected_signature):
            raise ValueError("signature mismatch")
        payload = json.loads(_b64decode(encoded).decode("utf-8"))
        issued = _dt.datetime.fromisoformat(str(payload["issuedAt"]))
        if issued.tzinfo is None:
            raise ValueError("timezone-aware issuedAt required")
        expires = None
        if payload.get("expiresAt") is not None:
            expires = _dt.datetime.fromisoformat(str(payload["expiresAt"]))
            if expires.tzinfo is None:
                raise ValueError("timezone-aware expiresAt required")
    except Exception as exc:
        raise ToolError("Evidence receipt is malformed, expired, or was not issued by this JStack server session.") from exc
    age = (_dt.datetime.now(_dt.timezone.utc) - issued).total_seconds()
    checks = {
        "kind": payload.get("kind") == expected_kind,
        "session": payload.get("serverSession") == SERVER_SESSION_ID,
        "projectPath": payload.get("projectPath") == state["gitRoot"],
        "gitHead": payload.get("gitHead") == state["gitHead"],
        "projectFingerprint": payload.get("projectFingerprint") == state["projectFingerprint"],
        "fresh": 0 <= age <= RECEIPT_MAX_AGE_SECONDS,
    }
    if require_passed:
        checks["passed"] = payload.get("passed") is True
    if expires is not None:
        now = _dt.datetime.now(_dt.timezone.utc)
        checks["notExpired"] = issued <= now < expires
        checks["boundedExpiry"] = 0 < (expires - issued).total_seconds() <= RECEIPT_MAX_AGE_SECONDS
    if expected_subject:
        for field in ("baseCommit", "policyDigest", "toolVersion"):
            checks[field] = payload.get(field) == expected_subject.get(field)
    return {"valid": all(checks.values()), "checks": checks, "payload": payload}


def atomic_write_json(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    fd, temp_name = tempfile.mkstemp(prefix=f".{path.name}.", dir=str(path.parent))
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            handle.write(json_text(payload) + "\n")
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(temp_name, 0o600)
        os.replace(temp_name, path)
    finally:
        if os.path.exists(temp_name):
            os.unlink(temp_name)


def path_matches_patterns(path: str, patterns: list[str]) -> bool:
    normalized = tuple(part for part in path.replace("\\", "/").split("/") if part)

    def matches(pattern: str) -> bool:
        pattern_parts = tuple(
            part for part in pattern.replace("\\", "/").split("/") if part
        )
        memo: dict[tuple[int, int], bool] = {}

        def visit(path_index: int, pattern_index: int) -> bool:
            key = (path_index, pattern_index)
            if key in memo:
                return memo[key]
            if pattern_index == len(pattern_parts):
                result = path_index == len(normalized)
            elif pattern_parts[pattern_index] == "**":
                result = visit(path_index, pattern_index + 1) or (
                    path_index < len(normalized)
                    and visit(path_index + 1, pattern_index)
                )
            else:
                result = (
                    path_index < len(normalized)
                    and fnmatch.fnmatchcase(
                        normalized[path_index], pattern_parts[pattern_index]
                    )
                    and visit(path_index + 1, pattern_index + 1)
                )
            memo[key] = result
            return result

        return visit(0, 0)

    return any(matches(pattern) for pattern in patterns)


def goal_is_sensitive(goal: str, policy: dict[str, Any]) -> bool:
    goal_l = goal.lower()
    keywords = policy.get("security", {}).get("sensitiveKeywords") or []
    return any(str(keyword).lower() in goal_l for keyword in keywords)


def percentage_from_text(text: str, labels: list[str]) -> Optional[float]:
    for label in labels:
        pattern = re.compile(re.escape(label) + r"[^0-9]{0,40}([0-9]+(?:\.[0-9]+)?)\s*%", re.IGNORECASE)
        match = pattern.search(text)
        if match:
            try:
                return float(match.group(1))
            except ValueError:
                return None
    return None


def package_scripts(project_path: Path) -> dict[str, str]:
    package_json = project_path / "package.json"
    data = read_json(package_json)
    if not data:
        return {}
    scripts = data.get("scripts")
    if not isinstance(scripts, dict):
        return {}
    return {str(key): str(value) for key, value in scripts.items()}


def discover_test_commands(project_path: Path) -> list[dict[str, Any]]:
    commands: list[dict[str, Any]] = []
    scripts = package_scripts(project_path)
    for script_name in ["test", "lint", "typecheck", "type-check", "build"]:
        if script_name in scripts:
            kind = "typecheck" if script_name == "type-check" else script_name
            commands.append(
                {
                    "key": f"npm:{script_name}",
                    "kind": kind,
                    "label": f"npm run {script_name}" if script_name != "test" else "npm test",
                    "source": "package.json",
                    "script": scripts[script_name],
                    "args": ["npm", "test"] if script_name == "test" else ["npm", "run", script_name],
                }
            )
    database_test_scripts = (
        "test:db",
        "db:test",
        "test:database",
        "database:test",
        "test:migrations",
        "migrations:test",
    )
    for script_name in database_test_scripts:
        if script_name in scripts:
            commands.append(
                {
                    "key": f"npm:{script_name}",
                    "kind": "test",
                    "label": f"npm run {script_name}",
                    "source": "package.json database test convention",
                    "script": scripts[script_name],
                    "args": ["npm", "run", script_name],
                }
            )
    tests_dir = project_path / "tests"
    pyproject = project_path / "pyproject.toml"
    pyproject_text = pyproject.read_text(encoding="utf-8-sig", errors="replace") if pyproject.exists() else ""
    pytest_detected = (project_path / "pytest.ini").exists() or "pytest" in pyproject_text.lower()
    if tests_dir.exists() and pytest_detected:
        commands.append(
            {
                "key": "python:pytest",
                "kind": "test",
                "label": "python3 -m pytest",
                "source": "python project detection",
                "args": ["python3", "-m", "pytest"],
            }
        )
    elif tests_dir.exists():
        commands.append(
            {
                "key": "python:unittest",
                "kind": "test",
                "label": "python3 -m unittest discover -s tests -v",
                "source": "tests directory",
                "args": ["python3", "-m", "unittest", "discover", "-s", "tests", "-v"],
            }
        )
    if (project_path / "Cargo.toml").exists():
        commands.append({"key": "cargo:test", "kind": "test", "label": "cargo test", "source": "Cargo.toml", "args": ["cargo", "test"]})
    if (project_path / "go.mod").exists():
        commands.append({"key": "go:test", "kind": "test", "label": "go test ./...", "source": "go.mod", "args": ["go", "test", "./..."]})
    if (project_path / "pom.xml").exists():
        commands.append(
            {
                "key": "maven:test",
                "kind": "test",
                "label": "mvn --batch-mode --no-transfer-progress test",
                "source": "pom.xml",
                "args": ["mvn", "--batch-mode", "--no-transfer-progress", "test"],
            }
        )
    gradle_markers = (
        "build.gradle",
        "build.gradle.kts",
        "settings.gradle",
        "settings.gradle.kts",
    )
    if any((project_path / marker).exists() for marker in gradle_markers):
        commands.append(
            {
                "key": "gradle:test",
                "kind": "test",
                "label": "gradle --no-daemon test",
                "source": "Gradle build marker",
                "args": ["gradle", "--no-daemon", "test"],
            }
        )
    solution_targets = sorted(
        {
            path.name
            for pattern in ("*.sln", "*.slnx")
            for path in project_path.glob(pattern)
            if path.is_file()
        }
    )
    project_targets = sorted(
        {
            path.name
            for pattern in ("*.csproj", "*.fsproj", "*.vbproj")
            for path in project_path.glob(pattern)
            if path.is_file()
        }
    )
    for target in (solution_targets or project_targets)[:16]:
        commands.append(
            {
                "key": f"dotnet:test:{target}",
                "kind": "test",
                "label": f"dotnet test {target} --nologo",
                "source": target,
                "args": ["dotnet", "test", target, "--nologo"],
            }
        )
    if (project_path / "CMakeLists.txt").exists():
        commands.extend(
            [
                {
                    "key": "cmake:configure",
                    "kind": "build",
                    "label": "cmake -S . -B build -DBUILD_TESTING=ON",
                    "source": "CMakeLists.txt",
                    "args": ["cmake", "-S", ".", "-B", "build", "-DBUILD_TESTING=ON"],
                },
                {
                    "key": "cmake:build",
                    "kind": "build",
                    "label": "cmake --build build",
                    "source": "CMakeLists.txt",
                    "args": ["cmake", "--build", "build"],
                },
                {
                    "key": "ctest:test",
                    "kind": "test",
                    "label": "ctest --test-dir build --output-on-failure --no-tests=error",
                    "source": "CMakeLists.txt",
                    "args": ["ctest", "--test-dir", "build", "--output-on-failure", "--no-tests=error"],
                },
            ]
        )
    if (project_path / "dbt_project.yml").exists():
        commands.append(
            {
                "key": "dbt:test",
                "kind": "test",
                "label": "dbt test",
                "source": "dbt_project.yml",
                "args": ["dbt", "test"],
            }
        )
    for command in commands:
        fingerprint_input = json.dumps(
            {key: command.get(key) for key in ("key", "kind", "source", "script", "args")},
            sort_keys=True,
            separators=(",", ":"),
        )
        command["commandFingerprint"] = hashlib.sha256(fingerprint_input.encode("utf-8")).hexdigest()
        command["executesProjectCode"] = True
    return commands


def approved_command_env(allowlist: list[str], isolated_home: Path, project_path: Path) -> dict[str, str]:
    safe_names = {
        "PATH",
        "SYSTEMROOT",
        "WINDIR",
        "COMSPEC",
        "PATHEXT",
        "LANG",
        "LC_ALL",
        "TMPDIR",
        "TEMP",
        "TMP",
    }
    env = {name: value for name, value in os.environ.items() if name.upper() in safe_names}
    for name in allowlist:
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name):
            raise ToolError(f"Invalid env_allowlist name: {name!r}")
        if name in os.environ:
            env[name] = os.environ[name]
    env.update(
        {
            "HOME": str(isolated_home),
            "USERPROFILE": str(isolated_home),
            "XDG_CONFIG_HOME": str(isolated_home / ".config"),
            "XDG_CACHE_HOME": str(isolated_home / ".cache"),
            "CI": "1",
            "NO_COLOR": "1",
            "JSTACK_QA_EXECUTION": "1",
        }
    )
    trusted_path_entries: list[str] = []
    for entry in env.get("PATH", "").split(os.pathsep):
        if not entry or not os.path.isabs(entry):
            continue
        resolved = Path(entry).resolve()
        try:
            resolved.relative_to(project_path)
            continue
        except ValueError:
            pass
        if str(resolved) not in trusted_path_entries:
            trusted_path_entries.append(str(resolved))
    for entry in (Path(sys.executable).resolve().parent, Path("/usr/bin"), Path("/bin"), Path("/usr/local/bin"), Path("/opt/homebrew/bin")):
        if entry.exists() and str(entry) not in trusted_path_entries:
            trusted_path_entries.append(str(entry))
    env["PATH"] = os.pathsep.join(trusted_path_entries)
    return env


def run_approved_project_command(
    command: list[str],
    project_path: Path,
    timeout: int,
    env_allowlist: list[str],
    fixed_env: Optional[dict[str, str]] = None,
) -> dict[str, Any]:
    output_limit = 1_000_000

    def terminate(process: subprocess.Popen[bytes]) -> None:
        if process.poll() is not None:
            return
        if os.name == "nt":
            system_root = Path(os.environ.get("SystemRoot") or os.environ.get("WINDIR") or "C:/Windows")
            taskkill = system_root / "System32" / "taskkill.exe"
            if taskkill.is_file():
                try:
                    subprocess.run(
                        [str(taskkill), "/PID", str(process.pid), "/T", "/F"],
                        stdin=subprocess.DEVNULL,
                        stdout=subprocess.DEVNULL,
                        stderr=subprocess.DEVNULL,
                        timeout=5,
                        check=False,
                    )
                except (OSError, subprocess.TimeoutExpired):
                    process.kill()
            else:
                process.kill()
        else:
            os.killpg(process.pid, signal.SIGKILL)

    with tempfile.TemporaryDirectory(prefix="jstack-qa-") as temp_home:
        env = approved_command_env(env_allowlist, Path(temp_home), project_path)
        for name, value in (fixed_env or {}).items():
            if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name):
                raise ToolError(f"Invalid fixed command environment name: {name!r}")
            if not isinstance(value, str) or "\x00" in value:
                raise ToolError(f"Invalid fixed command environment value for {name!r}.")
            env[name] = value
        executable = sys.executable if command[0] in {"python", "python3", "py"} else shutil.which(command[0], path=env["PATH"])
        if not executable:
            return {
                "ok": False,
                "returncode": 127,
                "stdout": "",
                "stderr": f"Command not found outside the project: {command[0]}",
                "args": command,
            }
        executable_path = Path(executable).resolve()
        try:
            executable_path.relative_to(project_path)
            return {
                "ok": False,
                "returncode": 126,
                "stdout": "",
                "stderr": f"Refusing to execute a project-local command binary: {executable_path}",
                "args": command,
            }
        except ValueError:
            pass
        resolved_command = [str(executable_path), *command[1:]]
        try:
            process = subprocess.Popen(
                resolved_command,
                cwd=str(project_path),
                stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                env=env,
                start_new_session=(os.name != "nt"),
                creationflags=(
                    getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
                    if os.name == "nt"
                    else 0
                ),
            )
        except FileNotFoundError:
            return {
                "ok": False,
                "returncode": 127,
                "stdout": "",
                "stderr": f"Command not found: {command[0]}",
                "args": command,
            }
        assert process.stdout and process.stderr
        overflow = threading.Event()
        stdout_buffer = bytearray()
        stderr_buffer = bytearray()

        def read_stream(stream: Any, buffer: bytearray) -> None:
            while True:
                chunk = stream.read(8192)
                if not chunk:
                    return
                remaining = output_limit - len(buffer)
                if remaining > 0:
                    buffer.extend(chunk[:remaining])
                if len(chunk) > remaining:
                    overflow.set()
                    return

        readers = [
            threading.Thread(target=read_stream, args=(process.stdout, stdout_buffer), daemon=True),
            threading.Thread(target=read_stream, args=(process.stderr, stderr_buffer), daemon=True),
        ]
        for reader in readers:
            reader.start()
        deadline = time.monotonic() + timeout
        timed_out = False
        while process.poll() is None:
            if overflow.is_set():
                terminate(process)
                break
            if time.monotonic() >= deadline:
                timed_out = True
                terminate(process)
                break
            time.sleep(0.02)
        try:
            process.wait(timeout=5)
        except subprocess.TimeoutExpired:
            process.kill()
            process.wait(timeout=5)
        for reader in readers:
            reader.join(timeout=2)
        process.stdout.close()
        process.stderr.close()
        stdout_bytes = bytes(stdout_buffer)
        stderr_bytes = bytes(stderr_buffer)
        stdout = stdout_bytes.decode("utf-8", errors="replace")
        stderr = stderr_bytes.decode("utf-8", errors="replace")
        capture_evidence = {
            "stdoutSha256": hashlib.sha256(stdout_bytes).hexdigest(),
            "stderrSha256": hashlib.sha256(stderr_bytes).hexdigest(),
            "capturedOutputBytes": len(stdout_bytes) + len(stderr_bytes),
        }
        if timed_out:
            return {
                "ok": False,
                "returncode": 124,
                "stdout": truncate(stdout),
                "stderr": truncate(stderr + f"\nTimed out after {timeout}s; process group terminated."),
                "args": resolved_command,
                **capture_evidence,
            }
        if overflow.is_set():
            return {
                "ok": False,
                "returncode": 125,
                "stdout": truncate(stdout),
                "stderr": truncate(stderr + f"\nOutput exceeded {output_limit} bytes; process group terminated."),
                "args": resolved_command,
                **capture_evidence,
            }
    return {
        "ok": process.returncode == 0,
        "returncode": process.returncode,
        "stdout": truncate(stdout or ""),
        "stderr": truncate(stderr or ""),
        "args": resolved_command,
        **capture_evidence,
    }


def skill_files() -> list[Path]:
    files: list[Path] = []
    jstack_root = find_jstack_root()
    if jstack_root:
        bundled = jstack_root / "skills" / "jstack-dev" / "SKILL.md"
        audit_skill = jstack_root / "skills" / "jstack-audit" / "SKILL.md"
        direct = jstack_root / "SKILL.md"
        for candidate in (bundled, audit_skill, direct):
            if candidate.exists() and candidate not in files:
                files.append(candidate)
    root = find_gstack_root()
    if not root:
        return files
    for child in sorted(root.iterdir(), key=lambda p: p.name):
        if child.name in EXCLUDED_DIRS or child.name == "node_modules":
            continue
        skill_file = child / "SKILL.md"
        if skill_file.exists():
            if skill_file not in files:
                files.append(skill_file)
    root_skill = root / "SKILL.md"
    if root_skill.exists():
        if root_skill not in files:
            files.append(root_skill)
    return files


def parse_skill(skill_file: Path) -> dict[str, Any]:
    text = skill_file.read_text(encoding="utf-8", errors="replace")
    name = skill_file.parent.name
    description = ""
    if text.startswith("---"):
        parts = text.split("---", 2)
        if len(parts) >= 3:
            frontmatter = parts[1]
            name_match = re.search(r"^name:\s*(.+)$", frontmatter, re.MULTILINE)
            if name_match:
                name = name_match.group(1).strip().strip('"')
            desc_match = re.search(r"^description:\s*(?:\|\s*)?\n(?P<body>(?:\s+.+\n?)+)", frontmatter, re.MULTILINE)
            if desc_match:
                description = " ".join(line.strip() for line in desc_match.group("body").splitlines()).strip()
            else:
                one_line = re.search(r"^description:\s*(.+)$", frontmatter, re.MULTILINE)
                if one_line:
                    description = one_line.group(1).strip().strip('"')
    if not description:
        body = text.split("\n", 8)
        description = " ".join(line.strip("# ").strip() for line in body[:8] if line.strip())[:500]
    return {
        "name": name,
        "path": str(skill_file),
        "directory": skill_file.parent.name,
        "description": truncate(description, 800),
    }


