def tool_mastery_status(args: dict[str, Any]) -> dict[str, Any]:
    track = normalize_mastery_track(args.get("track"))
    profile = load_mastery_profile()
    state = mastery_track_state(profile, track)
    current = max(0, min(9, int(state.get("currentStage", 0))))
    curriculum = load_mastery_curriculum(track)
    stage = next(item for item in curriculum["stages"] if item["stage"] == current)
    return {
        "initialized": mastery_profile_path().exists(),
        "profilePath": str(mastery_profile_path()),
        "profileSchemaVersion": profile["schemaVersion"],
        "activeTrack": profile["activeTrack"],
        "track": track,
        "currentStage": stage,
        "completedStages": state.get("completedStages", []),
        "attemptCount": len(state.get("attempts", [])),
        "advancement": advancement_status(profile, current, track),
        "nextDrill": stage["drills"][0] if stage.get("drills") else None,
        "curriculumSource": curriculum["_sourcePath"],
        "curriculumDigest": mastery_curriculum_digest(curriculum),
        "recordType": "Local deliberate-practice record; it is not an external credential or certification.",
    }


def tool_mastery_start(args: dict[str, Any]) -> dict[str, Any]:
    track = normalize_mastery_track(args.get("track"))
    path = mastery_profile_path()
    if path.exists():
        profile = load_mastery_profile()
        if profile["activeTrack"] != track:
            profile["activeTrack"] = track
            profile["updatedAt"] = now_iso()
            atomic_write_json(path, profile)
        return {"created": False, "status": tool_mastery_status({"track": track})}
    profile = default_mastery_profile()
    profile["createdAt"] = now_iso()
    profile["updatedAt"] = profile["createdAt"]
    profile["learnerName"] = str(args.get("learner_name") or "Jay").strip() or "Jay"
    profile["activeTrack"] = track
    atomic_write_json(path, profile)
    return {"created": True, "status": tool_mastery_status({"track": track})}


def hash_mastery_artifact(project_path: Path, raw_path: str) -> dict[str, Any]:
    project_path = project_path.resolve()
    candidate = Path(raw_path).expanduser()
    if not candidate.is_absolute():
        candidate = project_path / candidate
    if candidate.is_symlink():
        raise ToolError(f"Mastery artifact may not be a symlink: {raw_path}")
    resolved = candidate.resolve()
    try:
        relative = resolved.relative_to(project_path).as_posix()
    except ValueError as exc:
        raise ToolError(f"Mastery artifact must be inside the project: {raw_path}") from exc
    expected_file = resolved.is_file()
    try:
        inventory = audit_core.inventory_repository(
            project_path,
            [relative],
            max_files=1000,
            max_bytes=10_000_000 if expected_file else 20_000_000,
            max_seconds=30,
        )
    except audit_core.AuditError as exc:
        raise ToolError(f"Mastery artifact could not be inventoried safely: {raw_path}") from exc
    if inventory.get("complete") is not True:
        raise ToolError(f"Mastery artifact is unreadable, unsafe, or exceeds its limits: {raw_path}")
    files = inventory.get("files") or []
    if not files:
        raise ToolError(f"Mastery artifact directory is empty: {raw_path}")
    exact = len(files) == 1 and files[0].get("path") == relative
    kind = "file" if exact else "directory"
    total = int(inventory.get("totalBytes") or 0)
    if kind == "file" and total > 10_000_000:
        raise ToolError(f"Mastery artifact exceeds 10 MB: {raw_path}")
    if kind == "file":
        digest_value = str(files[0]["sha256"])
    else:
        digest = hashlib.sha256()
        for item in files:
            nested = str(item["path"])
            prefix = relative.rstrip("/") + "/"
            if not nested.startswith(prefix):
                raise ToolError(f"Mastery artifact inventory escaped its directory: {raw_path}")
            digest.update(nested[len(prefix) :].encode("utf-8"))
            digest.update(b"\0")
            digest.update(bytes.fromhex(str(item["sha256"])))
        digest_value = digest.hexdigest()
    return {"path": relative, "kind": kind, "sha256": digest_value, "bytes": total}


def load_mastery_json_artifact(project_path: Path, artifact: dict[str, Any]) -> dict[str, Any]:
    if artifact.get("kind") != "file":
        raise ToolError("Mastery JSON artifact must be a regular JSON file.")
    relative = str(artifact.get("path") or "")
    try:
        content = audit_core.read_repository_file(
            project_path,
            relative,
            max_bytes=10_000_000,
            max_seconds=30,
        )
    except audit_core.AuditError as exc:
        raise ToolError("Mastery JSON artifact could not be read safely.") from exc
    if (
        len(content) != artifact.get("bytes")
        or hashlib.sha256(content).hexdigest() != artifact.get("sha256")
    ):
        raise ToolError("Mastery JSON artifact changed after artifact hashing.")

    def reject_duplicates(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        value: dict[str, Any] = {}
        for key, item in pairs:
            if key in value:
                raise ToolError("Mastery JSON artifact contains a duplicate JSON key.")
            value[key] = item
        return value

    try:
        parsed = json.loads(content.decode("utf-8"), object_pairs_hook=reject_duplicates)
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ToolError("Mastery JSON artifact must be valid UTF-8 JSON.") from exc
    if not isinstance(parsed, dict):
        raise ToolError("Mastery JSON artifact must contain a JSON object.")
    return parsed


def audit_stage3_reject_secret_values(value: Any, label: str) -> None:
    """Reject likely secrets while allowing explicit non-secret security classifications."""

    if isinstance(value, str):
        normalized = re.sub(
            r"\b(?:authorization|password|passwd|pwd|secret|token|api[_-]?key|"
            r"access[_-]?key|client[_-]?secret)\s*[:=]\s*"
            r"(?:absent|none|not-accessed|not-retained|redacted|present|"
            r"unverified|prohibited|denied|deny)\b",
            "",
            value,
            flags=re.IGNORECASE,
        )
        if audit_core.contains_secret_like(normalized):
            raise ToolError(
                f"{label} contains a secret-like value. Submit only a redacted classification and source location."
            )
        return
    if isinstance(value, dict):
        for child in value.values():
            audit_stage3_reject_secret_values(child, label)
        return
    if isinstance(value, list):
        for child in value:
            audit_stage3_reject_secret_values(child, label)


def validate_mastery_text_artifact(
    project_path: Path,
    artifact: dict[str, Any],
    label: str,
    *,
    max_bytes: int = 2_000_000,
) -> dict[str, Any]:
    """Validate a bounded, hashed UTF-8 mastery narrative without returning its content."""

    if artifact.get("kind") != "file":
        raise ToolError(f"{label} must be a regular text file.")
    relative = str(artifact.get("path") or "")
    try:
        content = audit_core.read_repository_file(
            project_path,
            relative,
            max_bytes=max_bytes,
            max_seconds=30,
        )
    except audit_core.AuditError as exc:
        raise ToolError(f"{label} could not be read safely.") from exc
    if (
        len(content) != artifact.get("bytes")
        or hashlib.sha256(content).hexdigest() != artifact.get("sha256")
    ):
        raise ToolError(f"{label} changed after artifact hashing.")
    try:
        text_value = content.decode("utf-8")
    except UnicodeError as exc:
        raise ToolError(f"{label} must be valid UTF-8 text.") from exc
    if not text_value.strip():
        raise ToolError(f"{label} must not be empty.")
    audit_stage3_reject_secret_values(text_value, label)
    return {
        "path": relative,
        "bytes": len(content),
        "lines": len(content.splitlines()),
        "sha256": hashlib.sha256(content).hexdigest(),
    }


def load_mastery_directory_json_artifact(
    project_path: Path,
    artifact: dict[str, Any],
    member_name: str,
) -> dict[str, Any]:
    """Load the only JSON member of a hashed mastery artifact directory."""

    if artifact.get("kind") != "directory":
        raise ToolError("Mastery directory artifact must be a directory.")
    current = hash_mastery_artifact(project_path, str(artifact.get("path") or ""))
    if current != artifact:
        raise ToolError("Mastery directory artifact changed after artifact hashing.")
    relative = str(artifact.get("path") or "").rstrip("/")
    try:
        inventory = audit_core.inventory_repository(
            project_path,
            [relative],
            max_files=1000,
            max_bytes=20_000_000,
            max_seconds=30,
        )
    except audit_core.AuditError as exc:
        raise ToolError("Mastery directory artifact could not be inventoried safely.") from exc
    if inventory.get("complete") is not True:
        raise ToolError("Mastery directory artifact is incomplete or unsafe.")
    prefix = relative + "/"
    members = []
    for item in inventory.get("files") or []:
        path = str(item.get("path") or "")
        if not path.startswith(prefix):
            raise ToolError("Mastery directory artifact inventory escaped its directory.")
        members.append(path[len(prefix) :])
    if members != [member_name]:
        raise ToolError(
            f"Mastery directory artifact must contain only {member_name}."
        )
    member_path = prefix + member_name
    try:
        content = audit_core.read_repository_file(
            project_path,
            member_path,
            max_bytes=2_000_000,
            max_seconds=30,
        )
    except audit_core.AuditError as exc:
        raise ToolError("Mastery directory JSON member could not be read safely.") from exc
    member_digest = hashlib.sha256(content).hexdigest()
    directory_digest = hashlib.sha256()
    directory_digest.update(member_name.encode("utf-8"))
    directory_digest.update(b"\0")
    directory_digest.update(bytes.fromhex(member_digest))
    if (
        len(content) != artifact.get("bytes")
        or directory_digest.hexdigest() != artifact.get("sha256")
    ):
        raise ToolError(
            "Mastery directory JSON member changed after artifact hashing."
        )

    def reject_duplicates(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        value: dict[str, Any] = {}
        for key, item in pairs:
            if key in value:
                raise ToolError("Mastery directory JSON member contains a duplicate JSON key.")
            value[key] = item
        return value

    try:
        parsed = json.loads(content.decode("utf-8"), object_pairs_hook=reject_duplicates)
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ToolError("Mastery directory JSON member must be valid UTF-8 JSON.") from exc
    if not isinstance(parsed, dict):
        raise ToolError("Mastery directory JSON member must contain a JSON object.")
    return parsed


def evaluate_audit_stage0_security_orientation(
    raw: Any, drill_id: str
) -> dict[str, Any]:
    """Evaluate one inert Stage 0 operator-boundary scenario without execution."""

    required = {
        "schemaVersion",
        "scenarioId",
        "ciaTriad",
        "authorityBoundary",
        "executionBoundary",
        "disclosureBoundary",
        "decision",
        "limitations",
    }
    if not isinstance(raw, dict) or set(raw) != required:
        raise ToolError(
            "Audit Stage 0 security-orientation.json has unsupported or missing fields."
        )
    scenario_id = str(raw.get("scenarioId") or "")
    if scenario_id not in AUDIT_STAGE0_DECISIONS:
        raise ToolError("Audit Stage 0 scenarioId is unsupported.")
    expected_scenario = AUDIT_STAGE0_REQUIRED_DRILLS.get(drill_id, scenario_id)
    failures: list[str] = []

    def check_exact_object(field: str, expected: dict[str, Any]) -> None:
        value = raw.get(field)
        if not isinstance(value, dict) or set(value) != set(expected):
            raise ToolError(
                f"Audit Stage 0 {field} has unsupported or missing fields."
            )
        for key, expected_value in expected.items():
            actual_value = value.get(key)
            if (
                type(actual_value) is not type(expected_value)
                or actual_value != expected_value
            ):
                failures.append(f"{field}.{key}")

    if raw.get("schemaVersion") != AUDIT_STAGE0_SECURITY_SCHEMA:
        failures.append("schemaVersion")
    if scenario_id != expected_scenario:
        failures.append("scenarioId")
    check_exact_object("ciaTriad", AUDIT_STAGE0_CIA_TRIAD)
    check_exact_object("authorityBoundary", AUDIT_STAGE0_AUTHORITY_BOUNDARY)
    check_exact_object("executionBoundary", AUDIT_STAGE0_EXECUTION_BOUNDARY)
    check_exact_object("disclosureBoundary", AUDIT_STAGE0_DISCLOSURE_BOUNDARY)
    check_exact_object("decision", AUDIT_STAGE0_DECISIONS[scenario_id])
    limitations = raw.get("limitations")
    if (
        not isinstance(limitations, list)
        or not all(isinstance(item, str) for item in limitations)
        or limitations != AUDIT_STAGE0_LIMITATIONS
    ):
        failures.append("limitations")
    result = {
        "schemaVersion": AUDIT_STAGE0_SECURITY_SCHEMA,
        "scenarioId": scenario_id,
        "expectedScenarioId": expected_scenario,
        "passed": not failures,
        "failureCodes": sorted(set(failures)),
    }
    return {**result, "evaluationDigest": audit_json_digest(result)}


def _audit_source_subject(
    project_path: Path, stage_label: str
) -> dict[str, Any]:
    """Return the immutable Git source subject and tracked regular-file inventory."""

    root_raw = git_root(project_path)
    if not root_raw:
        raise ToolError(
            f"Audit {stage_label} requires a readable committed Git source snapshot."
        )
    root = Path(root_raw).resolve()
    head_result = run_complete(
        ["git", "rev-parse", "HEAD"], root, timeout=8
    )
    tree_result = run_complete(
        ["git", "rev-parse", "HEAD^{tree}"], root, timeout=8
    )
    tracked_result = run_complete(
        ["git", "ls-files", "-s", "-z"],
        root,
        timeout=20,
        max_bytes=20_000_000,
    )
    if not head_result["ok"] or not tree_result["ok"] or not tracked_result["ok"]:
        raise ToolError(
            f"Audit {stage_label} requires a readable committed Git source snapshot."
        )
    tracked: dict[str, str] = {}
    for raw_entry in tracked_result["stdout"].split(b"\0"):
        if not raw_entry:
            continue
        try:
            metadata, raw_path = raw_entry.split(b"\t", 1)
            mode, _object_id, stage = metadata.decode("ascii").split()
            relative = decode_git_relative_path(raw_path, "Stage 1 tracked source")
        except (UnicodeError, ValueError) as exc:
            raise ToolError(
                f"Audit {stage_label} could not represent the tracked source inventory safely."
            ) from exc
        if stage != "0":
            raise ToolError(
                f"Audit {stage_label} cannot evaluate a conflicted Git index."
            )
        tracked[relative] = mode
    return {
        "gitHead": _git_text(head_result).strip(),
        "gitTree": _git_text(tree_result).strip(),
        "tracked": tracked,
        "_root": root,
    }


def _audit_stage1_source_subject(project_path: Path) -> dict[str, Any]:
    return _audit_source_subject(project_path, "Stage 1")


def _audit_stage1_safe_relative_path(value: Any) -> bool:
    if not isinstance(value, str) or not value or len(value) > 1024:
        return False
    if "\x00" in value or "\\" in value or value.startswith("/"):
        return False
    parts = value.split("/")
    return (
        all(part not in {"", ".", ".."} for part in parts)
        and parts[0] != ".git"
        and parts[0] != ".jstack-training"
    )


def evaluate_audit_stage1_repository_map(
    raw: Any, project_path: Path
) -> dict[str, Any]:
    """Validate one static, evidence-bound Stage 1 repository map."""

    required = {
        "schemaVersion",
        "subject",
        "collectionBoundary",
        "surfaces",
        "evidence",
        "nodes",
        "flows",
        "trustBoundaries",
        "generatedArtifacts",
        "gaps",
        "complete",
        "limitations",
    }
    if not isinstance(raw, dict) or set(raw) != required:
        raise ToolError(
            "Audit Stage 1 coverage-matrix.json has unsupported or missing fields."
        )

    source = _audit_stage1_source_subject(project_path)
    failures: list[str] = []

    def exact_object(field: str, keys: set[str]) -> dict[str, Any]:
        value = raw.get(field)
        if not isinstance(value, dict) or set(value) != keys:
            raise ToolError(
                f"Audit Stage 1 {field} has unsupported or missing fields."
            )
        return value

    def exact_list(field: str, maximum: int) -> list[Any]:
        value = raw.get(field)
        if not isinstance(value, list) or len(value) > maximum:
            raise ToolError(
                f"Audit Stage 1 {field} must be an array with at most {maximum} items."
            )
        return value

    def valid_id(value: Any) -> bool:
        return bool(
            isinstance(value, str)
            and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,127}", value)
        )

    def valid_text(value: Any, maximum: int = 1000) -> bool:
        return bool(
            isinstance(value, str)
            and value.strip()
            and len(value) <= maximum
        )

    def evidence_refs(
        value: Any,
        field: str,
        known: set[str],
        referenced: set[str],
        *,
        required_ref: bool = True,
    ) -> None:
        if (
            not isinstance(value, list)
            or len(value) > 32
            or not all(valid_id(item) for item in value)
        ):
            failures.append(field)
            return
        if required_ref and not value:
            failures.append(field)
        if len(value) != len(set(value)):
            failures.append(field + ".duplicate")
        for item in value:
            if item not in known:
                failures.append(field + ".unknown")
            else:
                referenced.add(item)

    if raw.get("schemaVersion") != AUDIT_STAGE1_REPOSITORY_MAP_SCHEMA:
        failures.append("schemaVersion")

    subject = exact_object("subject", {"gitHead", "gitTree"})
    for field in ("gitHead", "gitTree"):
        if not isinstance(subject.get(field), str) or subject.get(field) != source[field]:
            failures.append("subject." + field)

    boundary = exact_object(
        "collectionBoundary", set(AUDIT_STAGE1_COLLECTION_BOUNDARY)
    )
    for field, expected in AUDIT_STAGE1_COLLECTION_BOUNDARY.items():
        if type(boundary.get(field)) is not type(expected) or boundary.get(field) != expected:
            failures.append("collectionBoundary." + field)

    limitations = raw.get("limitations")
    if (
        not isinstance(limitations, list)
        or not all(isinstance(item, str) for item in limitations)
        or limitations != AUDIT_STAGE1_LIMITATIONS
    ):
        failures.append("limitations")

    evidence_items = exact_list("evidence", AUDIT_STAGE1_MAX_EVIDENCE)
    if not evidence_items:
        failures.append("evidence.empty")
    evidence_ids: set[str] = set()
    file_cache: dict[str, bytes] = {}
    total_evidence_bytes = 0
    for index, item in enumerate(evidence_items):
        prefix = f"evidence[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "path",
            "lineStart",
            "lineEnd",
            "sha256",
        }:
            raise ToolError(
                "Audit Stage 1 evidence entries have unsupported or missing fields."
            )
        evidence_id = item.get("id")
        if not valid_id(evidence_id):
            failures.append(prefix + ".id")
        elif evidence_id in evidence_ids:
            failures.append(prefix + ".id.duplicate")
        else:
            evidence_ids.add(evidence_id)
        path = item.get("path")
        if not _audit_stage1_safe_relative_path(path):
            failures.append(prefix + ".path")
            continue
        assert isinstance(path, str)
        if source["tracked"].get(path) not in {"100644", "100755"}:
            failures.append(prefix + ".path.untracked-or-nonregular")
            continue
        start = item.get("lineStart")
        end = item.get("lineEnd")
        if (
            not isinstance(start, int)
            or isinstance(start, bool)
            or not isinstance(end, int)
            or isinstance(end, bool)
            or start < 1
            or end < start
        ):
            failures.append(prefix + ".lines")
        try:
            if path not in file_cache:
                content = audit_core.read_repository_file(
                    source["_root"],
                    path,
                    max_bytes=AUDIT_STAGE1_MAX_EVIDENCE_FILE_BYTES,
                    max_seconds=30,
                )
                total_evidence_bytes += len(content)
                if total_evidence_bytes > AUDIT_STAGE1_MAX_EVIDENCE_TOTAL_BYTES:
                    raise ToolError(
                        "Audit Stage 1 evidence exceeds the bounded total read limit."
                    )
                file_cache[path] = content
            content = file_cache[path]
        except audit_core.AuditError:
            failures.append(prefix + ".path.unreadable")
            continue
        expected_digest = hashlib.sha256(content).hexdigest()
        if (
            not isinstance(item.get("sha256"), str)
            or item.get("sha256") != expected_digest
        ):
            failures.append(prefix + ".sha256")
        line_count = len(content.splitlines())
        if isinstance(end, int) and not isinstance(end, bool) and end > line_count:
            failures.append(prefix + ".lines")

    referenced_evidence: set[str] = set()
    surfaces = exact_list("surfaces", len(AUDIT_STAGE1_REQUIRED_SURFACES))
    surface_status: dict[str, str] = {}
    for index, item in enumerate(surfaces):
        prefix = f"surfaces[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "status",
            "reason",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 1 surface entries have unsupported or missing fields."
            )
        surface_id = item.get("id")
        status = item.get("status")
        if surface_id not in AUDIT_STAGE1_REQUIRED_SURFACES:
            failures.append(prefix + ".id")
        elif surface_id in surface_status:
            failures.append(prefix + ".id.duplicate")
        else:
            surface_status[str(surface_id)] = str(status)
        if status not in AUDIT_STAGE1_SURFACE_STATUSES:
            failures.append(prefix + ".status")
        elif status == "unsupported":
            failures.append(prefix + ".unsupported")
        if not valid_text(item.get("reason"), 500):
            failures.append(prefix + ".reason")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )
    if set(surface_status) != set(AUDIT_STAGE1_REQUIRED_SURFACES):
        failures.append("surfaces.coverage")

    nodes = exact_list("nodes", 256)
    if not nodes:
        failures.append("nodes.empty")
    node_ids: set[str] = set()
    for index, item in enumerate(nodes):
        prefix = f"nodes[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "kind",
            "name",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 1 node entries have unsupported or missing fields."
            )
        node_id = item.get("id")
        if not valid_id(node_id):
            failures.append(prefix + ".id")
        elif node_id in node_ids:
            failures.append(prefix + ".id.duplicate")
        else:
            node_ids.add(node_id)
        if item.get("kind") not in AUDIT_STAGE1_NODE_KINDS:
            failures.append(prefix + ".kind")
        if not valid_text(item.get("name"), 200):
            failures.append(prefix + ".name")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )

    trust_boundaries = exact_list("trustBoundaries", 128)
    if not trust_boundaries:
        failures.append("trustBoundaries.empty")
    boundary_ids: set[str] = set()
    for index, item in enumerate(trust_boundaries):
        prefix = f"trustBoundaries[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "name",
            "from",
            "to",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 1 trust-boundary entries have unsupported or missing fields."
            )
        boundary_id = item.get("id")
        if not valid_id(boundary_id):
            failures.append(prefix + ".id")
        elif boundary_id in boundary_ids:
            failures.append(prefix + ".id.duplicate")
        else:
            boundary_ids.add(boundary_id)
        if not valid_text(item.get("name"), 200):
            failures.append(prefix + ".name")
        if not valid_id(item.get("from")) or item.get("from") not in node_ids:
            failures.append(prefix + ".from")
        if (
            not valid_id(item.get("to"))
            or item.get("to") not in node_ids
            or item.get("to") == item.get("from")
        ):
            failures.append(prefix + ".to")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )

    flows = exact_list("flows", 512)
    if not flows:
        failures.append("flows.empty")
    flow_ids: set[str] = set()
    referenced_boundaries: set[str] = set()
    for index, item in enumerate(flows):
        prefix = f"flows[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "from",
            "to",
            "data",
            "trustBoundaryIds",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 1 flow entries have unsupported or missing fields."
            )
        flow_id = item.get("id")
        if not valid_id(flow_id):
            failures.append(prefix + ".id")
        elif flow_id in flow_ids:
            failures.append(prefix + ".id.duplicate")
        else:
            flow_ids.add(flow_id)
        if not valid_id(item.get("from")) or item.get("from") not in node_ids:
            failures.append(prefix + ".from")
        if not valid_id(item.get("to")) or item.get("to") not in node_ids:
            failures.append(prefix + ".to")
        if not valid_text(item.get("data"), 500):
            failures.append(prefix + ".data")
        boundary_refs = item.get("trustBoundaryIds")
        if (
            not isinstance(boundary_refs, list)
            or len(boundary_refs) > 32
            or not all(valid_id(value) for value in boundary_refs)
        ):
            failures.append(prefix + ".trustBoundaryIds")
        else:
            if len(boundary_refs) != len(set(boundary_refs)):
                failures.append(prefix + ".trustBoundaryIds.duplicate")
            for boundary_id in boundary_refs:
                if boundary_id not in boundary_ids:
                    failures.append(prefix + ".trustBoundaryIds.unknown")
                else:
                    referenced_boundaries.add(boundary_id)
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )
    if boundary_ids - referenced_boundaries:
        failures.append("trustBoundaries.unreferenced")

    generated = exact_list("generatedArtifacts", 256)
    generated_ids: set[str] = set()
    for index, item in enumerate(generated):
        prefix = f"generatedArtifacts[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "path",
            "sourcePath",
            "provenance",
            "driftRisk",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 1 generated-artifact entries have unsupported or missing fields."
            )
        generated_id = item.get("id")
        if not valid_id(generated_id):
            failures.append(prefix + ".id")
        elif generated_id in generated_ids:
            failures.append(prefix + ".id.duplicate")
        else:
            generated_ids.add(generated_id)
        path = item.get("path")
        source_path = item.get("sourcePath")
        if not _audit_stage1_safe_relative_path(path):
            failures.append(prefix + ".path")
        if (
            not _audit_stage1_safe_relative_path(source_path)
            or source["tracked"].get(source_path) not in {"100644", "100755"}
        ):
            failures.append(prefix + ".sourcePath")
        if path == source_path:
            failures.append(prefix + ".sourcePath.same-as-artifact")
        if item.get("provenance") not in AUDIT_STAGE1_GENERATED_PROVENANCE:
            failures.append(prefix + ".provenance")
        if item.get("driftRisk") not in AUDIT_STAGE1_DRIFT_RISKS:
            failures.append(prefix + ".driftRisk")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )
    generated_status = surface_status.get("generated-artifacts")
    if generated_status == "mapped" and not generated:
        failures.append("generatedArtifacts.empty")
    if generated_status == "not-applicable" and generated:
        failures.append("generatedArtifacts.unexpected")

    gaps = exact_list("gaps", 256)
    gap_ids: set[str] = set()
    for index, item in enumerate(gaps):
        prefix = f"gaps[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "surface",
            "description",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 1 gap entries have unsupported or missing fields."
            )
        gap_id = item.get("id")
        if not valid_id(gap_id):
            failures.append(prefix + ".id")
        elif gap_id in gap_ids:
            failures.append(prefix + ".id.duplicate")
        else:
            gap_ids.add(gap_id)
        if item.get("surface") not in AUDIT_STAGE1_REQUIRED_SURFACES:
            failures.append(prefix + ".surface")
        if not valid_text(item.get("description"), 1000):
            failures.append(prefix + ".description")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
            required_ref=False,
        )
    if gaps:
        failures.append("gaps.present")

    if not isinstance(raw.get("complete"), bool) or raw.get("complete") is not True:
        failures.append("complete")
    if evidence_ids - referenced_evidence:
        failures.append("evidence.unused")

    result = {
        "schemaVersion": AUDIT_STAGE1_REPOSITORY_MAP_SCHEMA,
        "sourceSubject": {
            "gitHead": source["gitHead"],
            "gitTree": source["gitTree"],
        },
        "surfaceCount": len(surface_status),
        "mappedSurfaceCount": sum(
            status == "mapped" for status in surface_status.values()
        ),
        "notApplicableSurfaceCount": sum(
            status == "not-applicable" for status in surface_status.values()
        ),
        "unsupportedSurfaceCount": sum(
            status == "unsupported" for status in surface_status.values()
        ),
        "evidenceCount": len(evidence_ids),
        "nodeCount": len(node_ids),
        "flowCount": len(flow_ids),
        "trustBoundaryCount": len(boundary_ids),
        "generatedArtifactCount": len(generated_ids),
        "gapCount": len(gap_ids),
        "passed": not failures,
        "failureCodes": sorted(set(failures)),
    }
    return {**result, "evaluationDigest": audit_json_digest(result)}


def evaluate_audit_stage2_correctness(
    report: Any,
    reproductions: Any,
    project_path: Path,
    artifacts: dict[str, dict[str, Any]],
    qa_verifications: list[dict[str, Any]],
) -> dict[str, Any]:
    """Validate one exact-revision Stage 2 correctness evidence package."""

    report_fields = {
        "schemaVersion",
        "subject",
        "assessmentBoundary",
        "artifactBindings",
        "coverage",
        "evidence",
        "invariants",
        "findings",
        "regressionPlans",
        "gaps",
        "complete",
        "limitations",
    }
    reproduction_fields = {"schemaVersion", "subject", "cases", "limitations"}
    if not isinstance(report, dict) or set(report) != report_fields:
        raise ToolError(
            "Audit Stage 2 correctness-report.json has unsupported or missing fields."
        )
    if not isinstance(reproductions, dict) or set(reproductions) != reproduction_fields:
        raise ToolError(
            "Audit Stage 2 reproductions/manifest.json has unsupported or missing fields."
        )
    audit_enforce_json_limit(
        report,
        "Audit Stage 2 correctness report",
        2_000_000,
    )
    audit_enforce_json_limit(
        reproductions,
        "Audit Stage 2 reproduction manifest",
        2_000_000,
    )
    audit_reject_secret_values(report, "Audit Stage 2 correctness report")
    audit_reject_secret_values(
        reproductions,
        "Audit Stage 2 reproduction manifest",
    )

    source = _audit_source_subject(project_path, "Stage 2")
    failures: list[str] = []

    def exact_object(
        container: dict[str, Any],
        field: str,
        keys: set[str],
        label: str = "correctness report",
    ) -> dict[str, Any]:
        value = container.get(field)
        if not isinstance(value, dict) or set(value) != keys:
            raise ToolError(
                f"Audit Stage 2 {label} {field} has unsupported or missing fields."
            )
        return value

    def exact_list(
        container: dict[str, Any],
        field: str,
        maximum: int,
        label: str = "correctness report",
    ) -> list[Any]:
        value = container.get(field)
        if not isinstance(value, list) or len(value) > maximum:
            raise ToolError(
                f"Audit Stage 2 {label} {field} must be an array with at most {maximum} items."
            )
        return value

    def valid_id(value: Any) -> bool:
        return bool(
            isinstance(value, str)
            and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,127}", value)
        )

    def valid_text(value: Any, maximum: int = 1000) -> bool:
        return bool(
            isinstance(value, str)
            and value.strip()
            and len(value) <= maximum
        )

    def valid_text_list(value: Any, field: str) -> None:
        if (
            not isinstance(value, list)
            or not value
            or len(value) > 32
            or not all(valid_text(item) for item in value)
        ):
            failures.append(field)

    def evidence_refs(
        value: Any,
        field: str,
        known: set[str],
        referenced: set[str],
        *,
        required_ref: bool = True,
    ) -> list[str]:
        if (
            not isinstance(value, list)
            or len(value) > 32
            or not all(valid_id(item) for item in value)
        ):
            failures.append(field)
            return []
        if required_ref and not value:
            failures.append(field)
        if len(value) != len(set(value)):
            failures.append(field + ".duplicate")
        for item in value:
            if item not in known:
                failures.append(field + ".unknown")
            else:
                referenced.add(item)
        return [str(item) for item in value]

    def identifier_refs(value: Any, field: str) -> list[str]:
        if (
            not isinstance(value, list)
            or not value
            or len(value) > 32
            or not all(valid_id(item) for item in value)
        ):
            failures.append(field)
            return []
        if len(value) != len(set(value)):
            failures.append(field + ".duplicate")
        return [str(item) for item in value]

    if report.get("schemaVersion") != AUDIT_STAGE2_CORRECTNESS_SCHEMA:
        failures.append("schemaVersion")
    if reproductions.get("schemaVersion") != AUDIT_STAGE2_REPRODUCTIONS_SCHEMA:
        failures.append("reproductions.schemaVersion")

    for container, prefix, label in (
        (report, "subject", "correctness report"),
        (reproductions, "reproductions.subject", "reproduction manifest"),
    ):
        subject = exact_object(
            container,
            "subject",
            {"gitHead", "gitTree"},
            label,
        )
        for field in ("gitHead", "gitTree"):
            if not isinstance(subject.get(field), str) or subject.get(field) != source[field]:
                failures.append(prefix + "." + field)

    boundary = exact_object(
        report,
        "assessmentBoundary",
        set(AUDIT_STAGE2_ASSESSMENT_BOUNDARY),
    )
    for field, expected in AUDIT_STAGE2_ASSESSMENT_BOUNDARY.items():
        if type(boundary.get(field)) is not type(expected) or boundary.get(field) != expected:
            failures.append("assessmentBoundary." + field)

    limitations = report.get("limitations")
    if (
        not isinstance(limitations, list)
        or not all(isinstance(item, str) for item in limitations)
        or limitations != AUDIT_STAGE2_LIMITATIONS
    ):
        failures.append("limitations")
    reproduction_limitations = reproductions.get("limitations")
    if (
        not isinstance(reproduction_limitations, list)
        or not all(isinstance(item, str) for item in reproduction_limitations)
        or reproduction_limitations != AUDIT_STAGE2_REPRODUCTION_LIMITATIONS
    ):
        failures.append("reproductions.limitations")

    bindings = exact_object(
        report,
        "artifactBindings",
        {"invariants", "reproductions"},
    )
    for binding_name, artifact_name in (
        ("invariants", "invariants.md"),
        ("reproductions", "reproductions"),
    ):
        binding = bindings.get(binding_name)
        if not isinstance(binding, dict) or set(binding) != {"path", "sha256"}:
            raise ToolError(
                "Audit Stage 2 artifactBindings entries have unsupported or missing fields."
            )
        artifact = artifacts.get(artifact_name) or {}
        if binding.get("path") != artifact.get("path"):
            failures.append("artifactBindings." + binding_name + ".path")
        if binding.get("sha256") != artifact.get("sha256"):
            failures.append("artifactBindings." + binding_name + ".sha256")
    if artifacts.get("invariants.md", {}).get("kind") != "file":
        failures.append("artifactBindings.invariants.kind")
    if int(artifacts.get("invariants.md", {}).get("bytes") or 0) <= 0:
        failures.append("artifactBindings.invariants.empty")
    if artifacts.get("reproductions", {}).get("kind") != "directory":
        failures.append("artifactBindings.reproductions.kind")

    evidence_items = exact_list(report, "evidence", AUDIT_STAGE2_MAX_ITEMS)
    if not evidence_items:
        failures.append("evidence.empty")
    evidence_ids: set[str] = set()
    file_cache: dict[str, bytes] = {}
    total_evidence_bytes = 0
    for index, item in enumerate(evidence_items):
        prefix = f"evidence[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "path",
            "lineStart",
            "lineEnd",
            "sha256",
        }:
            raise ToolError(
                "Audit Stage 2 evidence entries have unsupported or missing fields."
            )
        evidence_id = item.get("id")
        if not valid_id(evidence_id):
            failures.append(prefix + ".id")
        elif evidence_id in evidence_ids:
            failures.append(prefix + ".id.duplicate")
        else:
            evidence_ids.add(str(evidence_id))
        path = item.get("path")
        if not _audit_stage1_safe_relative_path(path):
            failures.append(prefix + ".path")
            continue
        assert isinstance(path, str)
        if source["tracked"].get(path) not in {"100644", "100755"}:
            failures.append(prefix + ".path.untracked-or-nonregular")
            continue
        start = item.get("lineStart")
        end = item.get("lineEnd")
        if (
            not isinstance(start, int)
            or isinstance(start, bool)
            or not isinstance(end, int)
            or isinstance(end, bool)
            or start < 1
            or end < start
        ):
            failures.append(prefix + ".lines")
        try:
            if path not in file_cache:
                content = audit_core.read_repository_file(
                    source["_root"],
                    path,
                    max_bytes=AUDIT_STAGE2_MAX_EVIDENCE_FILE_BYTES,
                    max_seconds=30,
                )
                total_evidence_bytes += len(content)
                if total_evidence_bytes > AUDIT_STAGE2_MAX_EVIDENCE_TOTAL_BYTES:
                    raise ToolError(
                        "Audit Stage 2 evidence exceeds the bounded total read limit."
                    )
                file_cache[path] = content
            content = file_cache[path]
        except audit_core.AuditError:
            failures.append(prefix + ".path.unreadable")
            continue
        expected_digest = hashlib.sha256(content).hexdigest()
        if (
            not isinstance(item.get("sha256"), str)
            or item.get("sha256") != expected_digest
        ):
            failures.append(prefix + ".sha256")
        line_count = len(content.splitlines())
        if isinstance(end, int) and not isinstance(end, bool) and end > line_count:
            failures.append(prefix + ".lines")

    referenced_evidence: set[str] = set()
    coverage_items = exact_list(
        report,
        "coverage",
        len(AUDIT_STAGE2_REQUIRED_SURFACES),
    )
    coverage_status: dict[str, str] = {}
    for index, item in enumerate(coverage_items):
        prefix = f"coverage[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "status",
            "reason",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 2 coverage entries have unsupported or missing fields."
            )
        surface_id = item.get("id")
        status = item.get("status")
        if surface_id not in AUDIT_STAGE2_REQUIRED_SURFACES:
            failures.append(prefix + ".id")
        elif surface_id in coverage_status:
            failures.append(prefix + ".id.duplicate")
        else:
            coverage_status[str(surface_id)] = str(status)
        if status not in AUDIT_STAGE2_SURFACE_STATUSES:
            failures.append(prefix + ".status")
        elif status == "unsupported":
            failures.append(prefix + ".unsupported")
        if not valid_text(item.get("reason"), 500):
            failures.append(prefix + ".reason")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )
    if set(coverage_status) != set(AUDIT_STAGE2_REQUIRED_SURFACES):
        failures.append("coverage.surfaces")

    invariant_items = exact_list(report, "invariants", AUDIT_STAGE2_MAX_ITEMS)
    if not invariant_items:
        failures.append("invariants.empty")
    invariant_ids: set[str] = set()
    invariant_status: dict[str, str] = {}
    for index, item in enumerate(invariant_items):
        prefix = f"invariants[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "statement",
            "scope",
            "status",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 2 invariant entries have unsupported or missing fields."
            )
        invariant_id = item.get("id")
        if not valid_id(invariant_id):
            failures.append(prefix + ".id")
        elif invariant_id in invariant_ids:
            failures.append(prefix + ".id.duplicate")
        else:
            invariant_ids.add(str(invariant_id))
            invariant_status[str(invariant_id)] = str(item.get("status"))
        if not valid_text(item.get("statement")):
            failures.append(prefix + ".statement")
        if not valid_text(item.get("scope"), 500):
            failures.append(prefix + ".scope")
        if item.get("status") not in {"holds", "violated"}:
            failures.append(prefix + ".status")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )

    finding_items = exact_list(report, "findings", AUDIT_STAGE2_MAX_ITEMS)
    if not finding_items:
        failures.append("findings.empty")
    finding_ids: set[str] = set()
    verified_finding_ids: set[str] = set()
    blocker_ids: set[str] = set()
    high_critical_ids: set[str] = set()
    hypothesis_ids: set[str] = set()
    finding_invariants: dict[str, list[str]] = {}
    finding_reproductions: dict[str, list[str]] = {}
    for index, item in enumerate(finding_items):
        prefix = f"findings[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "category",
            "title",
            "severity",
            "confidence",
            "disposition",
            "verificationStatus",
            "reachability",
            "rootCause",
            "trigger",
            "expectedBehavior",
            "observedBehavior",
            "impact",
            "evidence",
            "invariantIds",
            "reproductionIds",
        }:
            raise ToolError(
                "Audit Stage 2 finding entries have unsupported or missing fields."
            )
        finding_id = item.get("id")
        if not valid_id(finding_id):
            failures.append(prefix + ".id")
            normalized_id = ""
        elif finding_id in finding_ids:
            failures.append(prefix + ".id.duplicate")
            normalized_id = str(finding_id)
        else:
            normalized_id = str(finding_id)
            finding_ids.add(normalized_id)
        if item.get("category") not in AUDIT_STAGE2_REQUIRED_SURFACES:
            failures.append(prefix + ".category")
        if not valid_text(item.get("title"), 200):
            failures.append(prefix + ".title")
        severity = item.get("severity")
        confidence = item.get("confidence")
        disposition = item.get("disposition")
        verification_status = item.get("verificationStatus")
        reachability = item.get("reachability")
        if severity not in AUDIT_STAGE2_SEVERITIES:
            failures.append(prefix + ".severity")
        if confidence not in {"low", "medium", "high"}:
            failures.append(prefix + ".confidence")
        if disposition not in {"blocker", "non-blocking", "hypothesis"}:
            failures.append(prefix + ".disposition")
        if verification_status not in {"verified", "unverified"}:
            failures.append(prefix + ".verificationStatus")
        if reachability not in {"reachable", "conditional", "unproven"}:
            failures.append(prefix + ".reachability")
        for field in (
            "rootCause",
            "trigger",
            "expectedBehavior",
            "observedBehavior",
            "impact",
        ):
            if not valid_text(item.get(field)):
                failures.append(prefix + "." + field)
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )
        invariant_refs = identifier_refs(
            item.get("invariantIds"), prefix + ".invariantIds"
        )
        reproduction_refs = identifier_refs(
            item.get("reproductionIds"), prefix + ".reproductionIds"
        )
        if normalized_id:
            finding_invariants[normalized_id] = invariant_refs
            finding_reproductions[normalized_id] = reproduction_refs
        if verification_status == "verified" and normalized_id:
            verified_finding_ids.add(normalized_id)
        if disposition == "blocker" and normalized_id:
            blocker_ids.add(normalized_id)
        if severity in {"high", "critical"} and normalized_id:
            high_critical_ids.add(normalized_id)
        if disposition == "hypothesis" and normalized_id:
            hypothesis_ids.add(normalized_id)

        strong_claim = disposition == "blocker" or severity in {"high", "critical"}
        if strong_claim:
            if verification_status != "verified":
                failures.append(prefix + ".strong-claim-unverified")
            if confidence != "high":
                failures.append(prefix + ".strong-claim-confidence")
            if reachability not in {"reachable", "conditional"}:
                failures.append(prefix + ".strong-claim-reachability")
            if disposition == "hypothesis":
                failures.append(prefix + ".speculative-high-severity")
        if disposition == "blocker" and severity not in {"high", "critical"}:
            failures.append(prefix + ".blocker-severity")
        if verification_status == "unverified" and disposition != "hypothesis":
            failures.append(prefix + ".unverified-disposition")
        if disposition == "hypothesis":
            if verification_status != "unverified":
                failures.append(prefix + ".hypothesis-verification")
            if severity in {"high", "critical"}:
                failures.append(prefix + ".speculative-high-severity")
    if not blocker_ids:
        failures.append("blockers.empty")

    valid_qa_payloads = [
        item.get("payload") or {}
        for item in qa_verifications
        if item.get("valid") is True and (item.get("payload") or {}).get("passed") is True
    ]
    case_items = exact_list(
        reproductions,
        "cases",
        AUDIT_STAGE2_MAX_ITEMS,
        "reproduction manifest",
    )
    if not case_items:
        failures.append("reproductions.cases.empty")
    case_ids: set[str] = set()
    case_findings: dict[str, list[str]] = {}
    case_invariants: dict[str, list[str]] = {}
    qa_case_count = 0
    static_case_count = 0
    matched_qa_bindings: set[tuple[str, str]] = set()
    for index, item in enumerate(case_items):
        prefix = f"reproductions.cases[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "method",
            "findingIds",
            "invariantIds",
            "preconditions",
            "steps",
            "expected",
            "observed",
            "repeatCount",
            "deterministic",
            "evidence",
            "qaBinding",
        }:
            raise ToolError(
                "Audit Stage 2 reproduction cases have unsupported or missing fields."
            )
        case_id = item.get("id")
        if not valid_id(case_id):
            failures.append(prefix + ".id")
            normalized_case_id = ""
        elif case_id in case_ids:
            failures.append(prefix + ".id.duplicate")
            normalized_case_id = str(case_id)
        else:
            normalized_case_id = str(case_id)
            case_ids.add(normalized_case_id)
        method = item.get("method")
        if method not in {"static-invariant", "jstack-qa"}:
            failures.append(prefix + ".method")
        finding_refs = identifier_refs(
            item.get("findingIds"), prefix + ".findingIds"
        )
        invariant_refs = identifier_refs(
            item.get("invariantIds"), prefix + ".invariantIds"
        )
        if normalized_case_id:
            case_findings[normalized_case_id] = finding_refs
            case_invariants[normalized_case_id] = invariant_refs
        valid_text_list(item.get("preconditions"), prefix + ".preconditions")
        valid_text_list(item.get("steps"), prefix + ".steps")
        if not valid_text(item.get("expected")):
            failures.append(prefix + ".expected")
        if not valid_text(item.get("observed")):
            failures.append(prefix + ".observed")
        repeat_count = item.get("repeatCount")
        if (
            not isinstance(repeat_count, int)
            or isinstance(repeat_count, bool)
            or repeat_count < 1
            or repeat_count > 100
        ):
            failures.append(prefix + ".repeatCount")
        if not isinstance(item.get("deterministic"), bool) or item.get("deterministic") is not True:
            failures.append(prefix + ".deterministic")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )
        qa_binding = item.get("qaBinding")
        if method == "static-invariant":
            static_case_count += 1
            if qa_binding is not None:
                failures.append(prefix + ".qaBinding.unexpected")
        elif method == "jstack-qa":
            qa_case_count += 1
            if not isinstance(qa_binding, dict) or set(qa_binding) != {
                "commandKey",
                "commandFingerprint",
                "executionProfile",
                "returncode",
            }:
                failures.append(prefix + ".qaBinding")
            else:
                command_key = qa_binding.get("commandKey")
                command_fingerprint = qa_binding.get("commandFingerprint")
                if not valid_text(command_key, 200):
                    failures.append(prefix + ".qaBinding.commandKey")
                if not isinstance(command_fingerprint, str) or not re.fullmatch(
                    r"[0-9a-f]{64}", command_fingerprint
                ):
                    failures.append(prefix + ".qaBinding.commandFingerprint")
                if qa_binding.get("executionProfile") != "local-scrubbed-no-os-sandbox-v1":
                    failures.append(prefix + ".qaBinding.executionProfile")
                if (
                    not isinstance(qa_binding.get("returncode"), int)
                    or isinstance(qa_binding.get("returncode"), bool)
                    or qa_binding.get("returncode") != 0
                ):
                    failures.append(prefix + ".qaBinding.returncode")
                matched = next(
                    (
                        payload
                        for payload in valid_qa_payloads
                        if payload.get("commandKey") == command_key
                        and payload.get("commandFingerprint") == command_fingerprint
                        and payload.get("executionProfile")
                        == qa_binding.get("executionProfile")
                        and payload.get("returncode") == qa_binding.get("returncode")
                    ),
                    None,
                )
                if matched is None:
                    failures.append(prefix + ".qaBinding.unverified")
                elif isinstance(command_key, str) and isinstance(command_fingerprint, str):
                    matched_qa_bindings.add((command_key, command_fingerprint))

    referenced_cases: set[str] = set()
    for finding_id, invariant_refs in finding_invariants.items():
        for invariant_id in invariant_refs:
            if invariant_id not in invariant_ids:
                failures.append("findings.invariantIds.unknown")
            elif finding_id in verified_finding_ids and invariant_status.get(invariant_id) != "violated":
                failures.append("findings.invariantIds.not-violated")
    for finding_id, reproduction_refs in finding_reproductions.items():
        for case_id in reproduction_refs:
            if case_id not in case_ids:
                failures.append("findings.reproductionIds.unknown")
            else:
                referenced_cases.add(case_id)
                if finding_id not in case_findings.get(case_id, []):
                    failures.append("findings.reproductionIds.not-reciprocal")
    for case_id, finding_refs in case_findings.items():
        for finding_id in finding_refs:
            if finding_id not in finding_ids:
                failures.append("reproductions.findingIds.unknown")
            elif case_id not in finding_reproductions.get(finding_id, []):
                failures.append("reproductions.findingIds.not-reciprocal")
    for invariant_refs in case_invariants.values():
        for invariant_id in invariant_refs:
            if invariant_id not in invariant_ids:
                failures.append("reproductions.invariantIds.unknown")
            elif invariant_status.get(invariant_id) != "violated":
                failures.append("reproductions.invariantIds.not-violated")
    if case_ids - referenced_cases:
        failures.append("reproductions.cases.unused")

    regression_items = exact_list(
        report,
        "regressionPlans",
        AUDIT_STAGE2_MAX_ITEMS,
    )
    regression_ids: set[str] = set()
    for index, item in enumerate(regression_items):
        prefix = f"regressionPlans[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "findingId",
            "testLevel",
            "permanentTest",
            "failsBeforeFix",
            "passesAfterFix",
            "unrelatedBehaviorChecks",
            "failureStateChecks",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 2 regression-plan entries have unsupported or missing fields."
            )
        finding_id = item.get("findingId")
        if not valid_id(finding_id):
            failures.append(prefix + ".findingId")
        elif finding_id in regression_ids:
            failures.append(prefix + ".findingId.duplicate")
        else:
            regression_ids.add(str(finding_id))
        if finding_id not in finding_ids:
            failures.append(prefix + ".findingId.unknown")
        elif finding_id not in verified_finding_ids:
            failures.append(prefix + ".findingId.unverified")
        if item.get("testLevel") not in {
            "unit",
            "integration",
            "system",
            "property",
            "model",
        }:
            failures.append(prefix + ".testLevel")
        if not valid_text(item.get("permanentTest")):
            failures.append(prefix + ".permanentTest")
        for field in ("failsBeforeFix", "passesAfterFix"):
            if not isinstance(item.get(field), bool) or item.get(field) is not True:
                failures.append(prefix + "." + field)
        valid_text_list(
            item.get("unrelatedBehaviorChecks"),
            prefix + ".unrelatedBehaviorChecks",
        )
        valid_text_list(
            item.get("failureStateChecks"),
            prefix + ".failureStateChecks",
        )
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )
    if verified_finding_ids - regression_ids:
        failures.append("regressionPlans.missing")
    if regression_ids - verified_finding_ids:
        failures.append("regressionPlans.unexpected")

    gap_items = exact_list(report, "gaps", AUDIT_STAGE2_MAX_ITEMS)
    gap_ids: set[str] = set()
    for index, item in enumerate(gap_items):
        prefix = f"gaps[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "category",
            "description",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 2 gap entries have unsupported or missing fields."
            )
        gap_id = item.get("id")
        if not valid_id(gap_id):
            failures.append(prefix + ".id")
        elif gap_id in gap_ids:
            failures.append(prefix + ".id.duplicate")
        else:
            gap_ids.add(str(gap_id))
        if item.get("category") not in AUDIT_STAGE2_REQUIRED_SURFACES:
            failures.append(prefix + ".category")
        if not valid_text(item.get("description")):
            failures.append(prefix + ".description")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
            required_ref=False,
        )
    if gap_items:
        failures.append("gaps.present")

    if not isinstance(report.get("complete"), bool) or report.get("complete") is not True:
        failures.append("complete")
    if evidence_ids - referenced_evidence:
        failures.append("evidence.unused")

    result = {
        "schemaVersion": AUDIT_STAGE2_CORRECTNESS_SCHEMA,
        "reproductionSchemaVersion": AUDIT_STAGE2_REPRODUCTIONS_SCHEMA,
        "sourceSubject": {
            "gitHead": source["gitHead"],
            "gitTree": source["gitTree"],
        },
        "surfaceCount": len(coverage_status),
        "assessedSurfaceCount": sum(
            status == "assessed" for status in coverage_status.values()
        ),
        "notApplicableSurfaceCount": sum(
            status == "not-applicable" for status in coverage_status.values()
        ),
        "unsupportedSurfaceCount": sum(
            status == "unsupported" for status in coverage_status.values()
        ),
        "evidenceCount": len(evidence_ids),
        "invariantCount": len(invariant_ids),
        "violatedInvariantCount": sum(
            status == "violated" for status in invariant_status.values()
        ),
        "findingCount": len(finding_ids),
        "verifiedFindingCount": len(verified_finding_ids),
        "blockerCount": len(blocker_ids),
        "highCriticalFindingCount": len(high_critical_ids),
        "hypothesisCount": len(hypothesis_ids),
        "reproductionCount": len(case_ids),
        "qaReproductionCount": qa_case_count,
        "staticInvariantReproductionCount": static_case_count,
        "matchedQaBindingCount": len(matched_qa_bindings),
        "regressionPlanCount": len(regression_ids),
        "gapCount": len(gap_ids),
        "passed": not failures,
        "failureCodes": sorted(set(failures)),
    }
    return {**result, "evaluationDigest": audit_json_digest(result)}


def evaluate_audit_stage3_threat_model(
    report: Any,
    project_path: Path,
    artifacts: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    """Validate one exact-revision, static-only Stage 3 threat-model package."""

    report_fields = {
        "schemaVersion",
        "subject",
        "assessmentBoundary",
        "methodology",
        "artifactBindings",
        "coverage",
        "evidence",
        "assets",
        "adversaries",
        "trustBoundaries",
        "controls",
        "abuseCases",
        "attackPaths",
        "findings",
        "standardsMappings",
        "gaps",
        "complete",
        "limitations",
    }
    if not isinstance(report, dict) or set(report) != report_fields:
        raise ToolError(
            "Audit Stage 3 security-findings.json has unsupported or missing fields."
        )
    audit_enforce_json_limit(
        report,
        "Audit Stage 3 security findings",
        2_000_000,
    )
    audit_stage3_reject_secret_values(report, "Audit Stage 3 security findings")

    source = _audit_source_subject(project_path, "Stage 3")
    failures: list[str] = []

    def exact_object(
        container: dict[str, Any],
        field: str,
        keys: set[str],
    ) -> dict[str, Any]:
        value = container.get(field)
        if not isinstance(value, dict) or set(value) != keys:
            raise ToolError(
                f"Audit Stage 3 security findings {field} has unsupported or missing fields."
            )
        return value

    def exact_list(field: str, maximum: int = AUDIT_STAGE3_MAX_ITEMS) -> list[Any]:
        value = report.get(field)
        if not isinstance(value, list) or len(value) > maximum:
            raise ToolError(
                f"Audit Stage 3 security findings {field} must be an array with at most {maximum} items."
            )
        return value

    def valid_id(value: Any) -> bool:
        return bool(
            isinstance(value, str)
            and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,127}", value)
        )

    def valid_text(value: Any, maximum: int = 1000) -> bool:
        return bool(isinstance(value, str) and value.strip() and len(value) <= maximum)

    def text_list(value: Any, field: str, *, allow_empty: bool = False) -> list[str]:
        valid = (
            isinstance(value, list)
            and len(value) <= 32
            and (allow_empty or bool(value))
            and all(valid_text(item) for item in value)
        )
        if not valid:
            failures.append(field)
            return []
        return [str(item) for item in value]

    def identifier_refs(
        value: Any,
        field: str,
        *,
        allow_empty: bool = False,
    ) -> list[str]:
        valid = (
            isinstance(value, list)
            and len(value) <= 32
            and (allow_empty or bool(value))
            and all(valid_id(item) for item in value)
        )
        if not valid:
            failures.append(field)
            return []
        if len(value) != len(set(value)):
            failures.append(field + ".duplicate")
        return [str(item) for item in value]

    def evidence_refs(
        value: Any,
        field: str,
        known: set[str],
        referenced: set[str],
        *,
        allow_empty: bool = False,
    ) -> list[str]:
        refs = identifier_refs(value, field, allow_empty=allow_empty)
        for item in refs:
            if item not in known:
                failures.append(field + ".unknown")
            else:
                referenced.add(item)
        return refs

    def collect_id(
        item: dict[str, Any],
        prefix: str,
        known: set[str],
    ) -> str:
        value = item.get("id")
        if not valid_id(value):
            failures.append(prefix + ".id")
            return ""
        normalized = str(value)
        if normalized in known:
            failures.append(prefix + ".id.duplicate")
        else:
            known.add(normalized)
        return normalized

    if report.get("schemaVersion") != AUDIT_STAGE3_SECURITY_FINDINGS_SCHEMA:
        failures.append("schemaVersion")

    subject = exact_object(report, "subject", {"gitHead", "gitTree"})
    for field in ("gitHead", "gitTree"):
        if not isinstance(subject.get(field), str) or subject.get(field) != source[field]:
            failures.append("subject." + field)

    boundary = exact_object(
        report,
        "assessmentBoundary",
        set(AUDIT_STAGE3_ASSESSMENT_BOUNDARY),
    )
    for field, expected in AUDIT_STAGE3_ASSESSMENT_BOUNDARY.items():
        if type(boundary.get(field)) is not type(expected) or boundary.get(field) != expected:
            failures.append("assessmentBoundary." + field)

    methodology = exact_object(
        report,
        "methodology",
        set(AUDIT_STAGE3_METHODOLOGY),
    )
    for field, expected in AUDIT_STAGE3_METHODOLOGY.items():
        if methodology.get(field) != expected:
            failures.append("methodology." + field)

    limitations = report.get("limitations")
    if (
        not isinstance(limitations, list)
        or not all(isinstance(item, str) for item in limitations)
        or limitations != AUDIT_STAGE3_LIMITATIONS
    ):
        failures.append("limitations")

    bindings = exact_object(
        report,
        "artifactBindings",
        {"threatModel", "abuseCases"},
    )
    for binding_name, artifact_name in (
        ("threatModel", "threat-model.md"),
        ("abuseCases", "abuse-cases.md"),
    ):
        binding = bindings.get(binding_name)
        if not isinstance(binding, dict) or set(binding) != {"path", "sha256"}:
            raise ToolError(
                "Audit Stage 3 artifactBindings entries have unsupported or missing fields."
            )
        artifact = artifacts.get(artifact_name) or {}
        if binding.get("path") != artifact.get("path"):
            failures.append("artifactBindings." + binding_name + ".path")
        if binding.get("sha256") != artifact.get("sha256"):
            failures.append("artifactBindings." + binding_name + ".sha256")
        validate_mastery_text_artifact(
            project_path,
            artifact,
            "Audit Stage 3 " + artifact_name,
            max_bytes=2_000_000,
        )

    evidence_items = exact_list("evidence")
    if not evidence_items:
        failures.append("evidence.empty")
    evidence_ids: set[str] = set()
    file_cache: dict[str, bytes] = {}
    total_evidence_bytes = 0
    for index, item in enumerate(evidence_items):
        prefix = f"evidence[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "path",
            "lineStart",
            "lineEnd",
            "sha256",
        }:
            raise ToolError(
                "Audit Stage 3 evidence entries have unsupported or missing fields."
            )
        collect_id(item, prefix, evidence_ids)
        path = item.get("path")
        if not _audit_stage1_safe_relative_path(path):
            failures.append(prefix + ".path")
            continue
        assert isinstance(path, str)
        if source["tracked"].get(path) not in {"100644", "100755"}:
            failures.append(prefix + ".path.untracked-or-nonregular")
            continue
        start = item.get("lineStart")
        end = item.get("lineEnd")
        if (
            not isinstance(start, int)
            or isinstance(start, bool)
            or not isinstance(end, int)
            or isinstance(end, bool)
            or start < 1
            or end < start
        ):
            failures.append(prefix + ".lines")
        try:
            if path not in file_cache:
                content = audit_core.read_repository_file(
                    source["_root"],
                    path,
                    max_bytes=AUDIT_STAGE3_MAX_EVIDENCE_FILE_BYTES,
                    max_seconds=30,
                )
                total_evidence_bytes += len(content)
                if total_evidence_bytes > AUDIT_STAGE3_MAX_EVIDENCE_TOTAL_BYTES:
                    raise ToolError(
                        "Audit Stage 3 evidence exceeds the bounded total read limit."
                    )
                file_cache[path] = content
            content = file_cache[path]
        except audit_core.AuditError:
            failures.append(prefix + ".path.unreadable")
            continue
        expected_digest = hashlib.sha256(content).hexdigest()
        if not isinstance(item.get("sha256"), str) or item.get("sha256") != expected_digest:
            failures.append(prefix + ".sha256")
        line_count = len(content.splitlines())
        if isinstance(end, int) and not isinstance(end, bool) and end > line_count:
            failures.append(prefix + ".lines")

    referenced_evidence: set[str] = set()
    coverage_items = exact_list(
        "coverage",
        len(AUDIT_STAGE3_REQUIRED_CATEGORIES),
    )
    coverage_status: dict[str, str] = {}
    for index, item in enumerate(coverage_items):
        prefix = f"coverage[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "status",
            "reason",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 3 coverage entries have unsupported or missing fields."
            )
        category = item.get("id")
        status = item.get("status")
        if category not in AUDIT_STAGE3_REQUIRED_CATEGORIES:
            failures.append(prefix + ".id")
        elif category in coverage_status:
            failures.append(prefix + ".id.duplicate")
        else:
            coverage_status[str(category)] = str(status)
        if status not in AUDIT_STAGE3_CATEGORY_STATUSES:
            failures.append(prefix + ".status")
        elif status == "unsupported":
            failures.append(prefix + ".unsupported")
        if not valid_text(item.get("reason"), 500):
            failures.append(prefix + ".reason")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )
    if set(coverage_status) != set(AUDIT_STAGE3_REQUIRED_CATEGORIES):
        failures.append("coverage.categories")

    asset_items = exact_list("assets")
    if not asset_items:
        failures.append("assets.empty")
    asset_ids: set[str] = set()
    referenced_assets: set[str] = set()
    for index, item in enumerate(asset_items):
        prefix = f"assets[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "name",
            "type",
            "securityObjectives",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 3 asset entries have unsupported or missing fields."
            )
        collect_id(item, prefix, asset_ids)
        if not valid_text(item.get("name"), 200):
            failures.append(prefix + ".name")
        if item.get("type") not in {
            "credential",
            "identity",
            "personal-data",
            "financial-data",
            "business-data",
            "service-availability",
            "security-boundary",
            "software-integrity",
            "audit-data",
            "other",
        }:
            failures.append(prefix + ".type")
        objectives = item.get("securityObjectives")
        if (
            not isinstance(objectives, list)
            or not objectives
            or len(objectives) > 3
            or len(objectives) != len(set(objectives))
            or not set(objectives).issubset(
                {"confidentiality", "integrity", "availability"}
            )
        ):
            failures.append(prefix + ".securityObjectives")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )

    adversary_items = exact_list("adversaries")
    if not adversary_items:
        failures.append("adversaries.empty")
    adversary_ids: set[str] = set()
    referenced_adversaries: set[str] = set()
    for index, item in enumerate(adversary_items):
        prefix = f"adversaries[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "name",
            "type",
            "access",
            "capabilities",
            "constraints",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 3 adversary entries have unsupported or missing fields."
            )
        collect_id(item, prefix, adversary_ids)
        if not valid_text(item.get("name"), 200):
            failures.append(prefix + ".name")
        if item.get("type") not in {
            "external",
            "insider",
            "compromised-service",
            "supply-chain",
        }:
            failures.append(prefix + ".type")
        if item.get("access") not in {
            "unauthenticated",
            "authenticated",
            "privileged",
            "repository-write",
            "dependency-publisher",
        }:
            failures.append(prefix + ".access")
        text_list(item.get("capabilities"), prefix + ".capabilities")
        text_list(item.get("constraints"), prefix + ".constraints")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )

    control_items = exact_list("controls")
    if not control_items:
        failures.append("controls.empty")
    control_ids: set[str] = set()
    control_status: dict[str, str] = {}
    referenced_controls: set[str] = set()
    for index, item in enumerate(control_items):
        prefix = f"controls[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "name",
            "type",
            "implementationStatus",
            "effectiveness",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 3 control entries have unsupported or missing fields."
            )
        control_id = collect_id(item, prefix, control_ids)
        if not valid_text(item.get("name"), 200):
            failures.append(prefix + ".name")
        if item.get("type") not in {
            "preventive",
            "detective",
            "corrective",
            "recovery",
        }:
            failures.append(prefix + ".type")
        if item.get("implementationStatus") not in {
            "implemented",
            "partial",
            "absent",
            "unverified",
        }:
            failures.append(prefix + ".implementationStatus")
        if item.get("effectiveness") not in {
            "effective",
            "partial",
            "ineffective",
            "unverified",
        }:
            failures.append(prefix + ".effectiveness")
        if control_id:
            control_status[control_id] = str(item.get("implementationStatus"))
        if (
            item.get("implementationStatus") == "absent"
            and item.get("effectiveness") != "ineffective"
        ):
            failures.append(prefix + ".absent-effectiveness")
        if (
            item.get("implementationStatus") == "unverified"
            and item.get("effectiveness") != "unverified"
        ):
            failures.append(prefix + ".unverified-effectiveness")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )

    boundary_items = exact_list("trustBoundaries")
    if not boundary_items:
        failures.append("trustBoundaries.empty")
    boundary_ids: set[str] = set()
    referenced_boundaries: set[str] = set()
    for index, item in enumerate(boundary_items):
        prefix = f"trustBoundaries[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "name",
            "fromZone",
            "toZone",
            "dataFlows",
            "authentication",
            "authorization",
            "authenticationControlIds",
            "authorizationControlIds",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 3 trust-boundary entries have unsupported or missing fields."
            )
        boundary_id = collect_id(item, prefix, boundary_ids)
        for field in ("name", "fromZone", "toZone"):
            if not valid_text(item.get(field), 200):
                failures.append(prefix + "." + field)
        if item.get("fromZone") == item.get("toZone"):
            failures.append(prefix + ".zones.same")
        text_list(item.get("dataFlows"), prefix + ".dataFlows")
        for field in ("authentication", "authorization"):
            if item.get(field) not in {"present", "absent", "unverified"}:
                failures.append(prefix + "." + field)
        for status_field, controls_field in (
            ("authentication", "authenticationControlIds"),
            ("authorization", "authorizationControlIds"),
        ):
            refs = identifier_refs(
                item.get(controls_field),
                prefix + "." + controls_field,
            )
            for control_id in refs:
                if control_id not in control_ids:
                    failures.append(prefix + "." + controls_field + ".unknown")
                else:
                    referenced_controls.add(control_id)
            if item.get(status_field) == "present" and not any(
                control_status.get(control_id) == "implemented"
                for control_id in refs
            ):
                failures.append(prefix + "." + controls_field + ".not-implemented")
            if item.get(status_field) == "absent" and not any(
                control_status.get(control_id) == "absent"
                for control_id in refs
            ):
                failures.append(prefix + "." + controls_field + ".not-absent")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )

    abuse_items = exact_list("abuseCases")
    if not abuse_items:
        failures.append("abuseCases.empty")
    abuse_ids: set[str] = set()
    abuse_paths: dict[str, list[str]] = {}
    referenced_abuse_cases: set[str] = set()
    for index, item in enumerate(abuse_items):
        prefix = f"abuseCases[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "title",
            "adversaryIds",
            "assetIds",
            "goal",
            "preconditions",
            "boundaryIds",
            "controlIds",
            "attackPathIds",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 3 abuse-case entries have unsupported or missing fields."
            )
        abuse_id = collect_id(item, prefix, abuse_ids)
        if not valid_text(item.get("title"), 200):
            failures.append(prefix + ".title")
        if not valid_text(item.get("goal")):
            failures.append(prefix + ".goal")
        text_list(item.get("preconditions"), prefix + ".preconditions")
        adversary_refs = identifier_refs(
            item.get("adversaryIds"), prefix + ".adversaryIds"
        )
        asset_refs = identifier_refs(item.get("assetIds"), prefix + ".assetIds")
        boundary_refs = identifier_refs(
            item.get("boundaryIds"), prefix + ".boundaryIds"
        )
        control_refs = identifier_refs(
            item.get("controlIds"), prefix + ".controlIds"
        )
        path_refs = identifier_refs(
            item.get("attackPathIds"), prefix + ".attackPathIds"
        )
        if abuse_id:
            abuse_paths[abuse_id] = path_refs
        for reference, known, referenced, field in (
            (adversary_refs, adversary_ids, referenced_adversaries, "adversaryIds"),
            (asset_refs, asset_ids, referenced_assets, "assetIds"),
            (boundary_refs, boundary_ids, referenced_boundaries, "boundaryIds"),
            (control_refs, control_ids, referenced_controls, "controlIds"),
        ):
            for identifier in reference:
                if identifier not in known:
                    failures.append(prefix + "." + field + ".unknown")
                else:
                    referenced.add(identifier)
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )

    path_items = exact_list("attackPaths")
    if not path_items:
        failures.append("attackPaths.empty")
    path_ids: set[str] = set()
    path_categories: dict[str, str] = {}
    path_reachability: dict[str, str] = {}
    path_verification: dict[str, str] = {}
    path_abuse_cases: dict[str, list[str]] = {}
    referenced_paths: set[str] = set()
    for index, item in enumerate(path_items):
        prefix = f"attackPaths[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "title",
            "category",
            "adversaryId",
            "assetIds",
            "abuseCaseIds",
            "source",
            "sink",
            "preconditions",
            "impact",
            "boundaryIds",
            "controlIds",
            "controlAssessment",
            "reachability",
            "verificationStatus",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 3 attack-path entries have unsupported or missing fields."
            )
        path_id = collect_id(item, prefix, path_ids)
        if not valid_text(item.get("title"), 200):
            failures.append(prefix + ".title")
        category = item.get("category")
        if category not in AUDIT_STAGE3_REQUIRED_CATEGORIES:
            failures.append(prefix + ".category")
        elif path_id:
            path_categories[path_id] = str(category)
        if category in AUDIT_STAGE3_REQUIRED_CATEGORIES and coverage_status.get(
            str(category)
        ) != "assessed":
            failures.append(prefix + ".category.not-assessed")
        adversary_id = item.get("adversaryId")
        if not valid_id(adversary_id) or adversary_id not in adversary_ids:
            failures.append(prefix + ".adversaryId")
        else:
            referenced_adversaries.add(str(adversary_id))
        asset_refs = identifier_refs(item.get("assetIds"), prefix + ".assetIds")
        abuse_refs = identifier_refs(
            item.get("abuseCaseIds"), prefix + ".abuseCaseIds"
        )
        boundary_refs = identifier_refs(
            item.get("boundaryIds"), prefix + ".boundaryIds"
        )
        control_refs = identifier_refs(
            item.get("controlIds"), prefix + ".controlIds"
        )
        if path_id:
            path_abuse_cases[path_id] = abuse_refs
        for reference, known, referenced, field in (
            (asset_refs, asset_ids, referenced_assets, "assetIds"),
            (abuse_refs, abuse_ids, referenced_abuse_cases, "abuseCaseIds"),
            (boundary_refs, boundary_ids, referenced_boundaries, "boundaryIds"),
            (control_refs, control_ids, referenced_controls, "controlIds"),
        ):
            for identifier in reference:
                if identifier not in known:
                    failures.append(prefix + "." + field + ".unknown")
                else:
                    referenced.add(identifier)
        for field in ("source", "sink", "impact", "controlAssessment"):
            if not valid_text(item.get(field)):
                failures.append(prefix + "." + field)
        if item.get("source") == item.get("sink"):
            failures.append(prefix + ".source-sink.same")
        text_list(item.get("preconditions"), prefix + ".preconditions")
        reachability = item.get("reachability")
        verification = item.get("verificationStatus")
        if reachability not in {"reachable", "conditional", "unproven"}:
            failures.append(prefix + ".reachability")
        if verification not in {"verified", "unverified"}:
            failures.append(prefix + ".verificationStatus")
        if verification == "verified" and reachability == "unproven":
            failures.append(prefix + ".verified-unproven")
        if path_id:
            path_reachability[path_id] = str(reachability)
            path_verification[path_id] = str(verification)
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )

    for abuse_id, path_refs in abuse_paths.items():
        for path_id in path_refs:
            if path_id not in path_ids:
                failures.append("abuseCases.attackPathIds.unknown")
            elif abuse_id not in path_abuse_cases.get(path_id, []):
                failures.append("abuseCases.attackPathIds.not-reciprocal")
    for path_id, abuse_refs in path_abuse_cases.items():
        for abuse_id in abuse_refs:
            if path_id not in abuse_paths.get(abuse_id, []):
                failures.append("attackPaths.abuseCaseIds.not-reciprocal")

    mapping_items = exact_list("standardsMappings")
    if not mapping_items:
        failures.append("standardsMappings.empty")
    mapping_ids: set[str] = set()
    mapping_findings: dict[str, list[str]] = {}
    mapping_paths: dict[str, list[str]] = {}
    referenced_mappings: set[str] = set()
    for index, item in enumerate(mapping_items):
        prefix = f"standardsMappings[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "standard",
            "version",
            "controlId",
            "applicability",
            "rationale",
            "findingIds",
            "attackPathIds",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 3 standards-mapping entries have unsupported or missing fields."
            )
        mapping_id = collect_id(item, prefix, mapping_ids)
        standard = item.get("standard")
        registry = AUDIT_STAGE3_STANDARD_REGISTRY.get(str(standard))
        if registry is None:
            failures.append(prefix + ".standard")
        else:
            if item.get("version") != registry["version"]:
                failures.append(prefix + ".version")
            control_id = item.get("controlId")
            if not isinstance(control_id, str) or not re.fullmatch(
                str(registry["controlPattern"]), control_id
            ):
                failures.append(prefix + ".controlId")
        if item.get("applicability") != "applicable":
            failures.append(prefix + ".applicability")
        if not valid_text(item.get("rationale")):
            failures.append(prefix + ".rationale")
        finding_refs = identifier_refs(
            item.get("findingIds"), prefix + ".findingIds"
        )
        path_refs = identifier_refs(
            item.get("attackPathIds"), prefix + ".attackPathIds"
        )
        if mapping_id:
            mapping_findings[mapping_id] = finding_refs
            mapping_paths[mapping_id] = path_refs
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )

    finding_items = exact_list("findings")
    if not finding_items:
        failures.append("findings.empty")
    finding_ids: set[str] = set()
    finding_mappings: dict[str, list[str]] = {}
    finding_paths: dict[str, list[str]] = {}
    finding_abuse_cases: dict[str, list[str]] = {}
    blocker_ids: set[str] = set()
    critical_blocker_ids: set[str] = set()
    verified_finding_ids: set[str] = set()
    hypothesis_ids: set[str] = set()
    for index, item in enumerate(finding_items):
        prefix = f"findings[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "title",
            "category",
            "severity",
            "confidence",
            "disposition",
            "verificationStatus",
            "rootCause",
            "preconditions",
            "impact",
            "residualRisk",
            "assetIds",
            "abuseCaseIds",
            "attackPathIds",
            "controlIds",
            "standardMappingIds",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 3 finding entries have unsupported or missing fields."
            )
        finding_id = collect_id(item, prefix, finding_ids)
        if not valid_text(item.get("title"), 200):
            failures.append(prefix + ".title")
        category = item.get("category")
        if category not in AUDIT_STAGE3_REQUIRED_CATEGORIES:
            failures.append(prefix + ".category")
        elif coverage_status.get(str(category)) != "assessed":
            failures.append(prefix + ".category.not-assessed")
        severity = item.get("severity")
        confidence = item.get("confidence")
        disposition = item.get("disposition")
        verification = item.get("verificationStatus")
        if severity not in AUDIT_STAGE3_SEVERITIES:
            failures.append(prefix + ".severity")
        if confidence not in {"low", "medium", "high"}:
            failures.append(prefix + ".confidence")
        if disposition not in {"blocker", "non-blocking", "hypothesis"}:
            failures.append(prefix + ".disposition")
        if verification not in {"verified", "unverified"}:
            failures.append(prefix + ".verificationStatus")
        for field in ("rootCause", "impact", "residualRisk"):
            if not valid_text(item.get(field)):
                failures.append(prefix + "." + field)
        text_list(item.get("preconditions"), prefix + ".preconditions")
        asset_refs = identifier_refs(item.get("assetIds"), prefix + ".assetIds")
        abuse_refs = identifier_refs(
            item.get("abuseCaseIds"), prefix + ".abuseCaseIds"
        )
        path_refs = identifier_refs(
            item.get("attackPathIds"), prefix + ".attackPathIds"
        )
        control_refs = identifier_refs(
            item.get("controlIds"), prefix + ".controlIds"
        )
        mapping_refs = identifier_refs(
            item.get("standardMappingIds"), prefix + ".standardMappingIds"
        )
        if finding_id:
            finding_mappings[finding_id] = mapping_refs
            finding_paths[finding_id] = path_refs
            finding_abuse_cases[finding_id] = abuse_refs
        for reference, known, referenced, field in (
            (asset_refs, asset_ids, referenced_assets, "assetIds"),
            (abuse_refs, abuse_ids, referenced_abuse_cases, "abuseCaseIds"),
            (path_refs, path_ids, referenced_paths, "attackPathIds"),
            (control_refs, control_ids, referenced_controls, "controlIds"),
            (mapping_refs, mapping_ids, referenced_mappings, "standardMappingIds"),
        ):
            for identifier in reference:
                if identifier not in known:
                    failures.append(prefix + "." + field + ".unknown")
                else:
                    referenced.add(identifier)
        if any(path_categories.get(path_id) != category for path_id in path_refs):
            failures.append(prefix + ".attackPathIds.category")
        strong_claim = disposition == "blocker" or severity in {"high", "critical"}
        if strong_claim:
            if verification != "verified":
                failures.append(prefix + ".strong-claim-unverified")
            if confidence != "high":
                failures.append(prefix + ".strong-claim-confidence")
        if disposition == "blocker":
            if severity not in {"high", "critical"}:
                failures.append(prefix + ".blocker-severity")
            if not any(
                path_verification.get(path_id) == "verified"
                and path_reachability.get(path_id) == "reachable"
                for path_id in path_refs
            ):
                failures.append(prefix + ".blocker-reachable-path")
            if finding_id:
                blocker_ids.add(finding_id)
                if severity == "critical":
                    critical_blocker_ids.add(finding_id)
        if verification == "verified" and finding_id:
            verified_finding_ids.add(finding_id)
        if verification == "unverified" and disposition != "hypothesis":
            failures.append(prefix + ".unverified-disposition")
        if disposition == "hypothesis":
            if verification != "unverified":
                failures.append(prefix + ".hypothesis-verification")
            if severity in {"high", "critical"}:
                failures.append(prefix + ".speculative-high-severity")
            if finding_id:
                hypothesis_ids.add(finding_id)
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )
    if not blocker_ids:
        failures.append("blockers.empty")
    if not critical_blocker_ids:
        failures.append("criticalBlockers.empty")

    for finding_id, path_refs in finding_paths.items():
        abuse_refs = set(finding_abuse_cases.get(finding_id, []))
        for path_id in path_refs:
            if path_id in path_ids and not abuse_refs.intersection(
                path_abuse_cases.get(path_id, [])
            ):
                failures.append("findings.attackPathIds.abuseCaseIds")
        for abuse_id in abuse_refs:
            if abuse_id in abuse_ids and not any(
                abuse_id in path_abuse_cases.get(path_id, [])
                for path_id in path_refs
            ):
                failures.append("findings.abuseCaseIds.attackPathIds")

    for mapping_id, finding_refs in mapping_findings.items():
        for finding_id in finding_refs:
            if finding_id not in finding_ids:
                failures.append("standardsMappings.findingIds.unknown")
            elif mapping_id not in finding_mappings.get(finding_id, []):
                failures.append("standardsMappings.findingIds.not-reciprocal")
    for mapping_id, path_refs in mapping_paths.items():
        mapped_paths = {
            path_id
            for finding_id in mapping_findings.get(mapping_id, [])
            for path_id in finding_paths.get(finding_id, [])
        }
        for path_id in path_refs:
            if path_id not in path_ids:
                failures.append("standardsMappings.attackPathIds.unknown")
            elif path_id not in mapped_paths:
                failures.append(
                    "standardsMappings.attackPathIds.not-linked-to-finding"
                )
    for finding_id, mapping_refs in finding_mappings.items():
        for mapping_id in mapping_refs:
            if finding_id not in mapping_findings.get(mapping_id, []):
                failures.append("findings.standardMappingIds.not-reciprocal")
    if verified_finding_ids - set(finding_mappings):
        failures.append("standardsMappings.missing")

    gap_items = exact_list("gaps")
    gap_ids: set[str] = set()
    for index, item in enumerate(gap_items):
        prefix = f"gaps[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "category",
            "description",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 3 gap entries have unsupported or missing fields."
            )
        collect_id(item, prefix, gap_ids)
        if item.get("category") not in AUDIT_STAGE3_REQUIRED_CATEGORIES:
            failures.append(prefix + ".category")
        if not valid_text(item.get("description")):
            failures.append(prefix + ".description")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
            allow_empty=True,
        )
    if gap_items:
        failures.append("gaps.present")

    if asset_ids - referenced_assets:
        failures.append("assets.unused")
    if adversary_ids - referenced_adversaries:
        failures.append("adversaries.unused")
    if boundary_ids - referenced_boundaries:
        failures.append("trustBoundaries.unused")
    if control_ids - referenced_controls:
        failures.append("controls.unused")
    if abuse_ids - referenced_abuse_cases:
        failures.append("abuseCases.unused")
    if path_ids - referenced_paths:
        failures.append("attackPaths.unused")
    if mapping_ids - referenced_mappings:
        failures.append("standardsMappings.unused")
    if evidence_ids - referenced_evidence:
        failures.append("evidence.unused")
    if not isinstance(report.get("complete"), bool) or report.get("complete") is not True:
        failures.append("complete")

    result = {
        "schemaVersion": AUDIT_STAGE3_SECURITY_FINDINGS_SCHEMA,
        "sourceSubject": {
            "gitHead": source["gitHead"],
            "gitTree": source["gitTree"],
        },
        "categoryCount": len(coverage_status),
        "assessedCategoryCount": sum(
            status == "assessed" for status in coverage_status.values()
        ),
        "notApplicableCategoryCount": sum(
            status == "not-applicable" for status in coverage_status.values()
        ),
        "unsupportedCategoryCount": sum(
            status == "unsupported" for status in coverage_status.values()
        ),
        "evidenceCount": len(evidence_ids),
        "assetCount": len(asset_ids),
        "adversaryCount": len(adversary_ids),
        "trustBoundaryCount": len(boundary_ids),
        "controlCount": len(control_ids),
        "abuseCaseCount": len(abuse_ids),
        "attackPathCount": len(path_ids),
        "verifiedAttackPathCount": sum(
            status == "verified" for status in path_verification.values()
        ),
        "findingCount": len(finding_ids),
        "verifiedFindingCount": len(verified_finding_ids),
        "blockerCount": len(blocker_ids),
        "criticalBlockerCount": len(critical_blocker_ids),
        "hypothesisCount": len(hypothesis_ids),
        "standardsMappingCount": len(mapping_ids),
        "gapCount": len(gap_ids),
        "passed": not failures,
        "failureCodes": sorted(set(failures)),
    }
    return {**result, "evaluationDigest": audit_json_digest(result)}


def _audit_stage4_resolve_revision(
    root: Path, raw_revision: Any
) -> Optional[dict[str, str]]:
    if not isinstance(raw_revision, str) or not re.fullmatch(
        r"[0-9a-f]{40,64}", raw_revision
    ):
        return None
    commit_result = run_complete(
        ["git", "rev-parse", "--verify", f"{raw_revision}^{{commit}}"],
        root,
        timeout=8,
    )
    if not commit_result["ok"]:
        return None
    commit = _git_text(commit_result).strip()
    if commit != raw_revision:
        return None
    tree_result = run_complete(
        ["git", "rev-parse", "--verify", f"{commit}^{{tree}}"],
        root,
        timeout=8,
    )
    if not tree_result["ok"]:
        return None
    tree = _git_text(tree_result).strip()
    if not re.fullmatch(r"[0-9a-f]{40,64}", tree):
        return None
    return {"gitHead": commit, "gitTree": tree}


def _audit_stage4_changed_paths(
    root: Path, baseline: str, candidate: str
) -> Optional[list[str]]:
    result = run_complete(
        ["git", "diff", "--name-only", "-z", baseline, candidate, "--"],
        root,
        timeout=20,
        max_bytes=20_000_000,
    )
    if not result["ok"]:
        return None
    paths: list[str] = []
    for raw_path in result["stdout"].split(b"\0"):
        if not raw_path:
            continue
        try:
            path = decode_git_relative_path(raw_path, "Stage 4 changed path")
        except ToolError:
            return None
        if not _audit_stage1_safe_relative_path(path):
            return None
        paths.append(path)
    return paths


def _audit_stage4_revision_file(
    root: Path,
    revision: str,
    relative: str,
    *,
    max_bytes: int,
) -> Optional[bytes]:
    tree_result = run_complete(
        ["git", "ls-tree", "-z", revision, "--", relative],
        root,
        timeout=8,
        max_bytes=100_000,
    )
    if not tree_result["ok"]:
        return None
    entries = [item for item in tree_result["stdout"].split(b"\0") if item]
    if len(entries) != 1:
        return None
    try:
        metadata, raw_path = entries[0].split(b"\t", 1)
        mode, kind, object_id = metadata.decode("ascii").split()
        decoded_path = decode_git_relative_path(raw_path, "Stage 4 evidence path")
    except (UnicodeError, ValueError, ToolError):
        return None
    if (
        decoded_path != relative
        or mode not in {"100644", "100755"}
        or kind != "blob"
        or not re.fullmatch(r"[0-9a-f]{40,64}", object_id)
    ):
        return None
    blob_result = run_complete(
        ["git", "cat-file", "blob", object_id],
        root,
        timeout=30,
        max_bytes=max_bytes,
    )
    if not blob_result["ok"]:
        return None
    return blob_result["stdout"]


def evaluate_audit_stage4_architecture(
    report: Any,
    project_path: Path,
    artifacts: dict[str, dict[str, Any]],
    qa_verifications: list[dict[str, Any]],
    drill_id: str,
) -> dict[str, Any]:
    """Validate one exact-revision Stage 4 architecture evidence package."""

    report_fields = {
        "schemaVersion",
        "subject",
        "exercise",
        "assessmentBoundary",
        "artifactBindings",
        "coverage",
        "evidence",
        "components",
        "dependencies",
        "contracts",
        "changeScenarios",
        "findings",
        "remediations",
        "compatibilityAssessments",
        "qaBindings",
        "gaps",
        "complete",
        "limitations",
    }
    if not isinstance(report, dict) or set(report) != report_fields:
        raise ToolError(
            "Audit Stage 4 maintainability-report.json has unsupported or missing fields."
        )
    audit_enforce_json_limit(
        report,
        "Audit Stage 4 maintainability report",
        2_000_000,
    )
    audit_reject_secret_values(report, "Audit Stage 4 maintainability report")
    source = _audit_source_subject(project_path, "Stage 4")
    failures: list[str] = []

    def exact_object(field: str, keys: set[str]) -> dict[str, Any]:
        value = report.get(field)
        if not isinstance(value, dict) or set(value) != keys:
            raise ToolError(
                f"Audit Stage 4 maintainability report {field} has unsupported or missing fields."
            )
        return value

    def exact_list(field: str, maximum: int = AUDIT_STAGE4_MAX_ITEMS) -> list[Any]:
        value = report.get(field)
        if not isinstance(value, list) or len(value) > maximum:
            raise ToolError(
                f"Audit Stage 4 maintainability report {field} must be an array with at most {maximum} items."
            )
        return value

    def valid_id(value: Any) -> bool:
        return bool(
            isinstance(value, str)
            and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,127}", value)
        )

    def valid_text(value: Any, maximum: int = 1000) -> bool:
        return bool(
            isinstance(value, str) and value.strip() and len(value) <= maximum
        )

    def collect_id(item: dict[str, Any], prefix: str, known: set[str]) -> str:
        raw = item.get("id")
        if not valid_id(raw):
            failures.append(prefix + ".id")
            return ""
        identifier = str(raw)
        if identifier in known:
            failures.append(prefix + ".id.duplicate")
        else:
            known.add(identifier)
        return identifier

    def identifier_refs(
        value: Any,
        field: str,
        *,
        allow_empty: bool = False,
    ) -> list[str]:
        if (
            not isinstance(value, list)
            or len(value) > 32
            or (not allow_empty and not value)
            or not all(valid_id(item) for item in value)
        ):
            failures.append(field)
            return []
        refs = [str(item) for item in value]
        if len(refs) != len(set(refs)):
            failures.append(field + ".duplicate")
        return refs

    def text_list(value: Any, field: str, *, allow_empty: bool = False) -> list[str]:
        if (
            not isinstance(value, list)
            or len(value) > 32
            or (not allow_empty and not value)
            or not all(valid_text(item) for item in value)
        ):
            failures.append(field)
            return []
        return [str(item) for item in value]

    def evidence_refs(
        value: Any,
        field: str,
        known: set[str],
        referenced: set[str],
        *,
        allow_empty: bool = False,
    ) -> list[str]:
        refs = identifier_refs(value, field, allow_empty=allow_empty)
        for identifier in refs:
            if identifier not in known:
                failures.append(field + ".unknown")
            else:
                referenced.add(identifier)
        return refs

    if report.get("schemaVersion") != AUDIT_STAGE4_MAINTAINABILITY_SCHEMA:
        failures.append("schemaVersion")

    subject = exact_object(
        "subject",
        {
            "baselineGitHead",
            "baselineGitTree",
            "candidateGitHead",
            "candidateGitTree",
        },
    )
    for field, source_field in (
        ("candidateGitHead", "gitHead"),
        ("candidateGitTree", "gitTree"),
    ):
        if subject.get(field) != source[source_field]:
            failures.append("subject." + field)
    baseline = _audit_stage4_resolve_revision(
        source["_root"], subject.get("baselineGitHead")
    )
    if baseline is None:
        failures.append("subject.baselineGitHead")
    elif subject.get("baselineGitTree") != baseline["gitTree"]:
        failures.append("subject.baselineGitTree")

    exercise = exact_object("exercise", {"drillId", "type"})
    expected_type = AUDIT_STAGE4_DRILL_TYPES.get(drill_id)
    exercise_type = exercise.get("type")
    if exercise.get("drillId") != drill_id:
        failures.append("exercise.drillId")
    if expected_type is None or exercise_type != expected_type:
        failures.append("exercise.type")
    if exercise_type not in {"audit", "implementation"}:
        failures.append("exercise.type.unsupported")

    candidate_head = source["gitHead"]
    baseline_head = baseline["gitHead"] if baseline else ""
    changed_paths: Optional[list[str]] = None
    if baseline:
        changed_paths = _audit_stage4_changed_paths(
            source["_root"], baseline_head, candidate_head
        )
        if changed_paths is None or len(changed_paths) > AUDIT_STAGE4_MAX_ITEMS:
            failures.append("subject.changedPaths")
        if exercise_type == "audit":
            if baseline_head != candidate_head or baseline["gitTree"] != source["gitTree"]:
                failures.append("subject.audit-baseline")
        elif exercise_type == "implementation":
            ancestry = run_complete(
                ["git", "merge-base", "--is-ancestor", baseline_head, candidate_head],
                source["_root"],
                timeout=8,
            )
            if baseline_head == candidate_head:
                failures.append("subject.implementation-distinct-commit")
            if not ancestry["ok"]:
                failures.append("subject.baseline-not-ancestor")
            if changed_paths == []:
                failures.append("subject.implementation-empty-diff")

    boundary = exact_object(
        "assessmentBoundary",
        set(AUDIT_STAGE4_ASSESSMENT_BOUNDARY),
    )
    for field, expected in AUDIT_STAGE4_ASSESSMENT_BOUNDARY.items():
        if type(boundary.get(field)) is not type(expected) or boundary.get(field) != expected:
            failures.append("assessmentBoundary." + field)

    limitations = report.get("limitations")
    if (
        not isinstance(limitations, list)
        or not all(isinstance(item, str) for item in limitations)
        or limitations != AUDIT_STAGE4_LIMITATIONS
    ):
        failures.append("limitations")

    bindings = exact_object(
        "artifactBindings",
        {"architectureMap", "migrationOutline"},
    )
    for binding_name, artifact_name in (
        ("architectureMap", "architecture-map.md"),
        ("migrationOutline", "migration-outline.md"),
    ):
        binding = bindings.get(binding_name)
        if not isinstance(binding, dict) or set(binding) != {"path", "sha256"}:
            raise ToolError(
                "Audit Stage 4 artifactBindings entries have unsupported or missing fields."
            )
        artifact = artifacts.get(artifact_name) or {}
        if binding.get("path") != artifact.get("path"):
            failures.append("artifactBindings." + binding_name + ".path")
        if binding.get("sha256") != artifact.get("sha256"):
            failures.append("artifactBindings." + binding_name + ".sha256")
        validate_mastery_text_artifact(
            project_path,
            artifact,
            "Audit Stage 4 " + artifact_name,
        )

    evidence_items = exact_list("evidence")
    if not evidence_items:
        failures.append("evidence.empty")
    evidence_ids: set[str] = set()
    evidence_revision: dict[str, str] = {}
    total_evidence_bytes = 0
    for index, item in enumerate(evidence_items):
        prefix = f"evidence[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "revision",
            "path",
            "lineStart",
            "lineEnd",
            "sha256",
        }:
            raise ToolError(
                "Audit Stage 4 evidence entries have unsupported or missing fields."
            )
        evidence_id = collect_id(item, prefix, evidence_ids)
        revision_kind = item.get("revision")
        if revision_kind not in {"baseline", "candidate"}:
            failures.append(prefix + ".revision")
            revision = ""
        elif revision_kind == "baseline":
            revision = baseline_head
        else:
            revision = candidate_head
        if evidence_id and isinstance(revision_kind, str):
            evidence_revision[evidence_id] = revision_kind
        path = item.get("path")
        if not _audit_stage1_safe_relative_path(path):
            failures.append(prefix + ".path")
            continue
        assert isinstance(path, str)
        start = item.get("lineStart")
        end = item.get("lineEnd")
        if (
            not isinstance(start, int)
            or isinstance(start, bool)
            or not isinstance(end, int)
            or isinstance(end, bool)
            or start < 1
            or end < start
        ):
            failures.append(prefix + ".lines")
        content = (
            _audit_stage4_revision_file(
                source["_root"],
                revision,
                path,
                max_bytes=AUDIT_STAGE4_MAX_EVIDENCE_FILE_BYTES,
            )
            if revision
            else None
        )
        if content is None:
            failures.append(prefix + ".path.untracked-or-nonregular")
            continue
        total_evidence_bytes += len(content)
        if total_evidence_bytes > AUDIT_STAGE4_MAX_EVIDENCE_TOTAL_BYTES:
            raise ToolError(
                "Audit Stage 4 evidence exceeds the bounded total read limit."
            )
        if item.get("sha256") != hashlib.sha256(content).hexdigest():
            failures.append(prefix + ".sha256")
        line_count = len(content.splitlines())
        if isinstance(end, int) and not isinstance(end, bool) and end > line_count:
            failures.append(prefix + ".lines")

    referenced_evidence: set[str] = set()
    coverage_items = exact_list("coverage", len(AUDIT_STAGE4_REQUIRED_SURFACES))
    coverage_status: dict[str, str] = {}
    for index, item in enumerate(coverage_items):
        prefix = f"coverage[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "status",
            "reason",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 4 coverage entries have unsupported or missing fields."
            )
        surface = item.get("id")
        status = item.get("status")
        if surface not in AUDIT_STAGE4_REQUIRED_SURFACES:
            failures.append(prefix + ".id")
        elif surface in coverage_status:
            failures.append(prefix + ".id.duplicate")
        else:
            coverage_status[str(surface)] = str(status)
        if status not in AUDIT_STAGE4_SURFACE_STATUSES:
            failures.append(prefix + ".status")
        elif status == "unsupported":
            failures.append(prefix + ".unsupported")
        if not valid_text(item.get("reason"), 500):
            failures.append(prefix + ".reason")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )
    if set(coverage_status) != set(AUDIT_STAGE4_REQUIRED_SURFACES):
        failures.append("coverage.surfaces")

    component_items = exact_list("components")
    if not component_items:
        failures.append("components.empty")
    component_ids: set[str] = set()
    referenced_components: set[str] = set()
    for index, item in enumerate(component_items):
        prefix = f"components[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "name",
            "kind",
            "responsibility",
            "boundary",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 4 component entries have unsupported or missing fields."
            )
        collect_id(item, prefix, component_ids)
        if not valid_text(item.get("name"), 200):
            failures.append(prefix + ".name")
        if item.get("kind") not in AUDIT_STAGE4_COMPONENT_KINDS:
            failures.append(prefix + ".kind")
        for field in ("responsibility", "boundary"):
            if not valid_text(item.get(field)):
                failures.append(prefix + "." + field)
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )

    dependency_items = exact_list("dependencies")
    if not dependency_items:
        failures.append("dependencies.empty")
    dependency_ids: set[str] = set()
    dependency_endpoints: dict[str, tuple[str, str]] = {}
    violating_dependencies: set[str] = set()
    referenced_dependencies: set[str] = set()
    dependency_contracts: dict[str, list[str]] = {}
    for index, item in enumerate(dependency_items):
        prefix = f"dependencies[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "fromComponentId",
            "toComponentId",
            "kind",
            "directionPolicy",
            "contractIds",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 4 dependency entries have unsupported or missing fields."
            )
        dependency_id = collect_id(item, prefix, dependency_ids)
        from_id = item.get("fromComponentId")
        to_id = item.get("toComponentId")
        for field, value in (("fromComponentId", from_id), ("toComponentId", to_id)):
            if not valid_id(value):
                failures.append(prefix + "." + field)
            elif value not in component_ids:
                failures.append(prefix + "." + field + ".unknown")
            else:
                referenced_components.add(str(value))
        if from_id == to_id:
            failures.append(prefix + ".self-reference")
        if dependency_id and isinstance(from_id, str) and isinstance(to_id, str):
            dependency_endpoints[dependency_id] = (from_id, to_id)
        if item.get("kind") not in AUDIT_STAGE4_DEPENDENCY_KINDS:
            failures.append(prefix + ".kind")
        direction = item.get("directionPolicy")
        if direction not in {"allowed", "violating"}:
            failures.append(prefix + ".directionPolicy")
        elif direction == "violating" and dependency_id:
            violating_dependencies.add(dependency_id)
        refs = identifier_refs(
            item.get("contractIds"),
            prefix + ".contractIds",
            allow_empty=True,
        )
        if dependency_id:
            dependency_contracts[dependency_id] = refs
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )

    contract_items = exact_list("contracts")
    if not contract_items:
        failures.append("contracts.empty")
    contract_ids: set[str] = set()
    referenced_contracts: set[str] = set()
    for index, item in enumerate(contract_items):
        prefix = f"contracts[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "name",
            "type",
            "stability",
            "providerComponentId",
            "consumerComponentIds",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 4 contract entries have unsupported or missing fields."
            )
        collect_id(item, prefix, contract_ids)
        if not valid_text(item.get("name"), 200):
            failures.append(prefix + ".name")
        if item.get("type") not in AUDIT_STAGE4_CONTRACT_TYPES:
            failures.append(prefix + ".type")
        if item.get("stability") not in {"stable", "internal", "experimental"}:
            failures.append(prefix + ".stability")
        provider = item.get("providerComponentId")
        if not valid_id(provider) or provider not in component_ids:
            failures.append(prefix + ".providerComponentId")
        else:
            referenced_components.add(str(provider))
        consumers = identifier_refs(
            item.get("consumerComponentIds"),
            prefix + ".consumerComponentIds",
        )
        for consumer in consumers:
            if consumer not in component_ids:
                failures.append(prefix + ".consumerComponentIds.unknown")
            else:
                referenced_components.add(consumer)
        if provider in consumers:
            failures.append(prefix + ".consumerComponentIds.self")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )

    for dependency_id, refs in dependency_contracts.items():
        for contract_id in refs:
            if contract_id not in contract_ids:
                failures.append("dependencies.contractIds.unknown")
            else:
                referenced_contracts.add(contract_id)

    scenario_items = exact_list("changeScenarios")
    if not scenario_items:
        failures.append("changeScenarios.empty")
    scenario_ids: set[str] = set()
    scenario_components: dict[str, list[str]] = {}
    scenario_dependencies: dict[str, list[str]] = {}
    scenario_contracts: dict[str, list[str]] = {}
    scenario_touch_points: dict[str, int] = {}
    referenced_scenarios: set[str] = set()
    for index, item in enumerate(scenario_items):
        prefix = f"changeScenarios[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "trigger",
            "originComponentId",
            "affectedComponentIds",
            "dependencyIds",
            "contractIds",
            "touchPointCount",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 4 change-scenario entries have unsupported or missing fields."
            )
        scenario_id = collect_id(item, prefix, scenario_ids)
        if not valid_text(item.get("trigger")):
            failures.append(prefix + ".trigger")
        origin = item.get("originComponentId")
        if not valid_id(origin) or origin not in component_ids:
            failures.append(prefix + ".originComponentId")
        else:
            referenced_components.add(str(origin))
        components = identifier_refs(
            item.get("affectedComponentIds"),
            prefix + ".affectedComponentIds",
        )
        dependencies = identifier_refs(
            item.get("dependencyIds"), prefix + ".dependencyIds"
        )
        contracts = identifier_refs(
            item.get("contractIds"), prefix + ".contractIds"
        )
        touch_points = item.get("touchPointCount")
        if (
            not isinstance(touch_points, int)
            or isinstance(touch_points, bool)
            or touch_points != len(components)
            or touch_points < 1
        ):
            failures.append(prefix + ".touchPointCount")
        if origin not in components:
            failures.append(prefix + ".originComponentId.not-affected")
        for component_id in components:
            if component_id not in component_ids:
                failures.append(prefix + ".affectedComponentIds.unknown")
            else:
                referenced_components.add(component_id)
        for dependency_id in dependencies:
            if dependency_id not in dependency_ids:
                failures.append(prefix + ".dependencyIds.unknown")
                continue
            referenced_dependencies.add(dependency_id)
            endpoints = dependency_endpoints.get(dependency_id, ("", ""))
            if not set(endpoints).issubset(set(components)):
                failures.append(prefix + ".dependencyIds.outside-affected")
        for contract_id in contracts:
            if contract_id not in contract_ids:
                failures.append(prefix + ".contractIds.unknown")
            else:
                referenced_contracts.add(contract_id)
        if scenario_id:
            scenario_components[scenario_id] = components
            scenario_dependencies[scenario_id] = dependencies
            scenario_contracts[scenario_id] = contracts
            if isinstance(touch_points, int) and not isinstance(touch_points, bool):
                scenario_touch_points[scenario_id] = touch_points
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )

    finding_items = exact_list("findings")
    if not finding_items:
        failures.append("findings.empty")
    finding_ids: set[str] = set()
    verified_findings: set[str] = set()
    open_findings: set[str] = set()
    resolved_findings: set[str] = set()
    hypothesis_findings: set[str] = set()
    finding_states: dict[str, str] = {}
    finding_contracts: dict[str, list[str]] = {}
    finding_dependencies: dict[str, list[str]] = {}
    for index, item in enumerate(finding_items):
        prefix = f"findings[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "category",
            "title",
            "severity",
            "confidence",
            "priority",
            "state",
            "verificationStatus",
            "styleOnly",
            "materialImpacts",
            "rootCause",
            "changeTrigger",
            "impact",
            "componentIds",
            "dependencyIds",
            "contractIds",
            "changeScenarioIds",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 4 finding entries have unsupported or missing fields."
            )
        finding_id = collect_id(item, prefix, finding_ids)
        category = item.get("category")
        if category not in AUDIT_STAGE4_FINDING_CATEGORIES:
            failures.append(prefix + ".category")
        elif coverage_status.get(str(category)) != "assessed":
            failures.append(prefix + ".category.not-assessed")
        if not valid_text(item.get("title"), 200):
            failures.append(prefix + ".title")
        severity = item.get("severity")
        confidence = item.get("confidence")
        priority = item.get("priority")
        state_value = item.get("state")
        verification = item.get("verificationStatus")
        if severity not in AUDIT_STAGE4_SEVERITIES:
            failures.append(prefix + ".severity")
        if confidence not in {"low", "medium", "high"}:
            failures.append(prefix + ".confidence")
        if priority not in {"blocker", "non-blocking"}:
            failures.append(prefix + ".priority")
        if state_value not in {"open", "resolved", "hypothesis"}:
            failures.append(prefix + ".state")
        if verification not in {"verified", "unverified"}:
            failures.append(prefix + ".verificationStatus")
        if not isinstance(item.get("styleOnly"), bool) or item.get("styleOnly") is not False:
            failures.append(prefix + ".styleOnly")
        impacts = identifier_refs(
            item.get("materialImpacts"), prefix + ".materialImpacts"
        )
        if any(impact not in AUDIT_STAGE4_MATERIAL_IMPACTS for impact in impacts):
            failures.append(prefix + ".materialImpacts.unsupported")
        for field in ("rootCause", "changeTrigger", "impact"):
            if not valid_text(item.get(field)):
                failures.append(prefix + "." + field)
        component_refs = identifier_refs(
            item.get("componentIds"), prefix + ".componentIds"
        )
        dependency_refs = identifier_refs(
            item.get("dependencyIds"), prefix + ".dependencyIds"
        )
        contract_refs = identifier_refs(
            item.get("contractIds"), prefix + ".contractIds"
        )
        scenario_refs = identifier_refs(
            item.get("changeScenarioIds"), prefix + ".changeScenarioIds"
        )
        for component_id in component_refs:
            if component_id not in component_ids:
                failures.append(prefix + ".componentIds.unknown")
            else:
                referenced_components.add(component_id)
        for dependency_id in dependency_refs:
            if dependency_id not in dependency_ids:
                failures.append(prefix + ".dependencyIds.unknown")
            else:
                referenced_dependencies.add(dependency_id)
        for contract_id in contract_refs:
            if contract_id not in contract_ids:
                failures.append(prefix + ".contractIds.unknown")
            else:
                referenced_contracts.add(contract_id)
        for scenario_id in scenario_refs:
            if scenario_id not in scenario_ids:
                failures.append(prefix + ".changeScenarioIds.unknown")
            else:
                referenced_scenarios.add(scenario_id)
                if not set(dependency_refs).intersection(
                    scenario_dependencies.get(scenario_id, [])
                ):
                    failures.append(prefix + ".changeScenarioIds.no-dependency-link")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )
        if finding_id:
            finding_states[finding_id] = str(state_value)
            finding_contracts[finding_id] = contract_refs
            finding_dependencies[finding_id] = dependency_refs
            if verification == "verified":
                verified_findings.add(finding_id)
            if state_value == "open":
                open_findings.add(finding_id)
            elif state_value == "resolved":
                resolved_findings.add(finding_id)
            elif state_value == "hypothesis":
                hypothesis_findings.add(finding_id)
        strong_claim = priority == "blocker" or severity in {"high", "critical"}
        if strong_claim:
            if verification != "verified":
                failures.append(prefix + ".strong-claim-unverified")
            if confidence != "high":
                failures.append(prefix + ".strong-claim-confidence")
        if priority == "blocker" and severity in {"info", "low"}:
            failures.append(prefix + ".blocker-severity")
        if state_value == "hypothesis":
            if verification != "unverified":
                failures.append(prefix + ".hypothesis-verification")
            if priority != "non-blocking" or severity in {"high", "critical"}:
                failures.append(prefix + ".speculative-high-severity")
        elif verification != "verified":
            failures.append(prefix + ".unverified-state")
        if state_value == "resolved" and exercise_type != "implementation":
            failures.append(prefix + ".resolved-outside-implementation")
    if not verified_findings:
        failures.append("verifiedFindings.empty")
    if exercise_type == "audit" and not open_findings:
        failures.append("openFindings.empty")
    if exercise_type == "implementation" and not resolved_findings:
        failures.append("resolvedFindings.empty")

    valid_qa_payloads = [
        item.get("payload") or {}
        for item in qa_verifications
        if item.get("valid") is True and (item.get("payload") or {}).get("passed") is True
    ]
    qa_items = exact_list("qaBindings")
    qa_ids: set[str] = set()
    matched_qa_ids: set[str] = set()
    referenced_qa_ids: set[str] = set()
    for index, item in enumerate(qa_items):
        prefix = f"qaBindings[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "commandKey",
            "commandFingerprint",
            "executionProfile",
            "returncode",
        }:
            raise ToolError(
                "Audit Stage 4 QA-binding entries have unsupported or missing fields."
            )
        qa_id = collect_id(item, prefix, qa_ids)
        if not valid_text(item.get("commandKey"), 200):
            failures.append(prefix + ".commandKey")
        if not isinstance(item.get("commandFingerprint"), str) or not re.fullmatch(
            r"[0-9a-f]{64}", str(item.get("commandFingerprint") or "")
        ):
            failures.append(prefix + ".commandFingerprint")
        if item.get("executionProfile") != "local-scrubbed-no-os-sandbox-v1":
            failures.append(prefix + ".executionProfile")
        if (
            not isinstance(item.get("returncode"), int)
            or isinstance(item.get("returncode"), bool)
            or item.get("returncode") != 0
        ):
            failures.append(prefix + ".returncode")
        matched = next(
            (
                payload
                for payload in valid_qa_payloads
                if payload.get("commandKey") == item.get("commandKey")
                and payload.get("commandFingerprint") == item.get("commandFingerprint")
                and payload.get("executionProfile") == item.get("executionProfile")
                and payload.get("returncode") == item.get("returncode")
            ),
            None,
        )
        if matched is None:
            failures.append(prefix + ".unverified")
        elif qa_id:
            matched_qa_ids.add(qa_id)
    if exercise_type == "audit" and qa_items:
        failures.append("qaBindings.unexpected")
    if exercise_type == "implementation" and not qa_items:
        failures.append("qaBindings.empty")

    compatibility_items = exact_list("compatibilityAssessments")
    if not compatibility_items:
        failures.append("compatibilityAssessments.empty")
    compatibility_ids: set[str] = set()
    compatibility_contracts: dict[str, str] = {}
    compatibility_status: dict[str, str] = {}
    for index, item in enumerate(compatibility_items):
        prefix = f"compatibilityAssessments[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "contractId",
            "status",
            "rationale",
            "baselineEvidence",
            "candidateEvidence",
            "qaBindingIds",
        }:
            raise ToolError(
                "Audit Stage 4 compatibility-assessment entries have unsupported or missing fields."
            )
        compatibility_id = collect_id(item, prefix, compatibility_ids)
        contract_id = item.get("contractId")
        if not valid_id(contract_id) or contract_id not in contract_ids:
            failures.append(prefix + ".contractId")
        elif contract_id in compatibility_contracts:
            failures.append(prefix + ".contractId.duplicate")
        elif compatibility_id:
            compatibility_contracts[str(contract_id)] = compatibility_id
            referenced_contracts.add(str(contract_id))
        status = item.get("status")
        if status not in AUDIT_STAGE4_COMPATIBILITY_STATUSES:
            failures.append(prefix + ".status")
        if isinstance(contract_id, str):
            compatibility_status[contract_id] = str(status)
        if status in {"breaking", "unsupported"}:
            failures.append(prefix + ".status.blocking")
        if exercise_type == "audit" and status != "unchanged":
            failures.append(prefix + ".status.audit")
        if exercise_type == "implementation" and status not in {
            "unchanged",
            "preserved",
            "changed-compatible",
        }:
            failures.append(prefix + ".status.implementation")
        if not valid_text(item.get("rationale")):
            failures.append(prefix + ".rationale")
        baseline_refs = evidence_refs(
            item.get("baselineEvidence"),
            prefix + ".baselineEvidence",
            evidence_ids,
            referenced_evidence,
        )
        candidate_refs = evidence_refs(
            item.get("candidateEvidence"),
            prefix + ".candidateEvidence",
            evidence_ids,
            referenced_evidence,
        )
        if any(evidence_revision.get(ref) != "baseline" for ref in baseline_refs):
            failures.append(prefix + ".baselineEvidence.revision")
        if any(evidence_revision.get(ref) != "candidate" for ref in candidate_refs):
            failures.append(prefix + ".candidateEvidence.revision")
        qa_refs = identifier_refs(
            item.get("qaBindingIds"),
            prefix + ".qaBindingIds",
            allow_empty=exercise_type == "audit",
        )
        for qa_id in qa_refs:
            if qa_id not in qa_ids:
                failures.append(prefix + ".qaBindingIds.unknown")
            else:
                referenced_qa_ids.add(qa_id)
        if exercise_type == "audit" and qa_refs:
            failures.append(prefix + ".qaBindingIds.unexpected")
    if contract_ids - set(compatibility_contracts):
        failures.append("compatibilityAssessments.missing")

    remediation_items = exact_list("remediations")
    if not remediation_items:
        failures.append("remediations.empty")
    remediation_findings: set[str] = set()
    implemented_count = 0
    for index, item in enumerate(remediation_items):
        prefix = f"remediations[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "findingId",
            "status",
            "targetState",
            "compatibilityStrategy",
            "migrationSteps",
            "rollbackStrategy",
            "changedPaths",
            "contractIds",
            "qaBindingIds",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 4 remediation entries have unsupported or missing fields."
            )
        finding_id = item.get("findingId")
        if not valid_id(finding_id):
            failures.append(prefix + ".findingId")
        elif finding_id in remediation_findings:
            failures.append(prefix + ".findingId.duplicate")
        else:
            remediation_findings.add(str(finding_id))
        if finding_id not in finding_ids:
            failures.append(prefix + ".findingId.unknown")
        elif finding_id not in verified_findings:
            failures.append(prefix + ".findingId.unverified")
        status = item.get("status")
        if status not in {"proposed", "implemented-verified"}:
            failures.append(prefix + ".status")
        for field in ("targetState", "compatibilityStrategy", "rollbackStrategy"):
            if not valid_text(item.get(field)):
                failures.append(prefix + "." + field)
        text_list(item.get("migrationSteps"), prefix + ".migrationSteps")
        changed = item.get("changedPaths")
        if (
            not isinstance(changed, list)
            or len(changed) > AUDIT_STAGE4_MAX_ITEMS
            or not all(_audit_stage1_safe_relative_path(path) for path in changed)
        ):
            failures.append(prefix + ".changedPaths")
            normalized_changed: list[str] = []
        else:
            normalized_changed = [str(path) for path in changed]
            if len(normalized_changed) != len(set(normalized_changed)):
                failures.append(prefix + ".changedPaths.duplicate")
        contract_refs = identifier_refs(
            item.get("contractIds"), prefix + ".contractIds"
        )
        for contract_id in contract_refs:
            if contract_id not in contract_ids:
                failures.append(prefix + ".contractIds.unknown")
            else:
                referenced_contracts.add(contract_id)
        qa_refs = identifier_refs(
            item.get("qaBindingIds"),
            prefix + ".qaBindingIds",
            allow_empty=status == "proposed",
        )
        for qa_id in qa_refs:
            if qa_id not in qa_ids:
                failures.append(prefix + ".qaBindingIds.unknown")
            else:
                referenced_qa_ids.add(qa_id)
        remediation_evidence = evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
        )
        if status == "proposed":
            if normalized_changed:
                failures.append(prefix + ".changedPaths.unexpected")
            if qa_refs:
                failures.append(prefix + ".qaBindingIds.unexpected")
            if finding_id in resolved_findings:
                failures.append(prefix + ".findingId.resolved-with-proposal")
        elif status == "implemented-verified":
            implemented_count += 1
            if exercise_type != "implementation":
                failures.append(prefix + ".status.outside-implementation")
            if finding_id not in resolved_findings:
                failures.append(prefix + ".findingId.not-resolved")
            if changed_paths is None or set(normalized_changed) != set(changed_paths):
                failures.append(prefix + ".changedPaths.diff-mismatch")
            if not normalized_changed:
                failures.append(prefix + ".changedPaths.empty")
            if not qa_refs:
                failures.append(prefix + ".qaBindingIds.empty")
            if not any(
                evidence_revision.get(ref) == "baseline"
                for ref in remediation_evidence
            ):
                failures.append(prefix + ".evidence.baseline-missing")
            if not any(
                evidence_revision.get(ref) == "candidate"
                for ref in remediation_evidence
            ):
                failures.append(prefix + ".evidence.candidate-missing")
            if any(
                compatibility_status.get(contract_id)
                not in {"unchanged", "preserved", "changed-compatible"}
                for contract_id in contract_refs
            ):
                failures.append(prefix + ".contractIds.compatibility")
    if verified_findings - remediation_findings:
        failures.append("remediations.missing")
    if remediation_findings - verified_findings:
        failures.append("remediations.unexpected")
    if exercise_type == "audit" and implemented_count:
        failures.append("remediations.implemented-unexpected")
    if exercise_type == "implementation" and implemented_count != 1:
        failures.append("remediations.implemented-count")

    for dependency_id in violating_dependencies:
        linked_findings = {
            finding_id
            for finding_id, refs in finding_dependencies.items()
            if dependency_id in refs
        }
        if not linked_findings.intersection(verified_findings):
            failures.append("dependencies.violating-without-verified-finding")

    gap_items = exact_list("gaps")
    gap_ids: set[str] = set()
    for index, item in enumerate(gap_items):
        prefix = f"gaps[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "surface",
            "description",
            "evidence",
        }:
            raise ToolError(
                "Audit Stage 4 gap entries have unsupported or missing fields."
            )
        collect_id(item, prefix, gap_ids)
        if item.get("surface") not in AUDIT_STAGE4_REQUIRED_SURFACES:
            failures.append(prefix + ".surface")
        if not valid_text(item.get("description")):
            failures.append(prefix + ".description")
        evidence_refs(
            item.get("evidence"),
            prefix + ".evidence",
            evidence_ids,
            referenced_evidence,
            allow_empty=True,
        )
    if gap_items:
        failures.append("gaps.present")

    if component_ids - referenced_components:
        failures.append("components.unused")
    if dependency_ids - referenced_dependencies:
        failures.append("dependencies.unused")
    if contract_ids - referenced_contracts:
        failures.append("contracts.unused")
    if scenario_ids - referenced_scenarios:
        failures.append("changeScenarios.unused")
    if qa_ids - referenced_qa_ids:
        failures.append("qaBindings.unused")
    if qa_ids - matched_qa_ids:
        failures.append("qaBindings.unverified")
    if evidence_ids - referenced_evidence:
        failures.append("evidence.unused")
    if not isinstance(report.get("complete"), bool) or report.get("complete") is not True:
        failures.append("complete")

    result = {
        "schemaVersion": AUDIT_STAGE4_MAINTAINABILITY_SCHEMA,
        "sourceSubject": {
            "baselineGitHead": baseline_head or None,
            "baselineGitTree": baseline["gitTree"] if baseline else None,
            "candidateGitHead": source["gitHead"],
            "candidateGitTree": source["gitTree"],
        },
        "drillId": drill_id,
        "exerciseType": exercise_type,
        "surfaceCount": len(coverage_status),
        "assessedSurfaceCount": sum(
            status == "assessed" for status in coverage_status.values()
        ),
        "notApplicableSurfaceCount": sum(
            status == "not-applicable" for status in coverage_status.values()
        ),
        "unsupportedSurfaceCount": sum(
            status == "unsupported" for status in coverage_status.values()
        ),
        "evidenceCount": len(evidence_ids),
        "componentCount": len(component_ids),
        "dependencyCount": len(dependency_ids),
        "violatingDependencyCount": len(violating_dependencies),
        "contractCount": len(contract_ids),
        "changeScenarioCount": len(scenario_ids),
        "maximumTouchPointCount": max(scenario_touch_points.values(), default=0),
        "findingCount": len(finding_ids),
        "verifiedFindingCount": len(verified_findings),
        "openFindingCount": len(open_findings),
        "resolvedFindingCount": len(resolved_findings),
        "hypothesisCount": len(hypothesis_findings),
        "remediationCount": len(remediation_findings),
        "implementedRemediationCount": implemented_count,
        "compatibilityAssessmentCount": len(compatibility_ids),
        "qaBindingCount": len(qa_ids),
        "matchedQaBindingCount": len(matched_qa_ids),
        "changedPathCount": len(changed_paths or []),
        "gapCount": len(gap_ids),
        "passed": not failures,
        "failureCodes": sorted(set(failures)),
    }
    return {**result, "evaluationDigest": audit_json_digest(result)}


def _verify_performance_receipt_for_revision(
    receipt: str,
    root: Path,
    expected: dict[str, Any],
) -> dict[str, Any]:
    """Verify a current-session receipt while permitting an immutable historical revision."""

    try:
        encoded, supplied_signature = receipt.split(".", 1)
        expected_signature = _b64encode(
            hmac.new(_RECEIPT_SECRET, encoded.encode("ascii"), hashlib.sha256).digest()
        )
        if not hmac.compare_digest(supplied_signature, expected_signature):
            raise ValueError("signature mismatch")
        payload = json.loads(_b64decode(encoded).decode("utf-8"))
        issued = _dt.datetime.fromisoformat(str(payload["issuedAt"]))
        if issued.tzinfo is None:
            raise ValueError("timezone-aware issuedAt required")
    except Exception as exc:
        raise ToolError(
            "Performance receipt is malformed, stale, or was not issued by this JStack server session."
        ) from exc
    age = (_dt.datetime.now(_dt.timezone.utc) - issued).total_seconds()
    checks = {
        "kind": payload.get("kind") == "performance",
        "session": payload.get("serverSession") == SERVER_SESSION_ID,
        "projectPath": payload.get("projectPath") == str(root),
        "gitHead": payload.get("gitHead") == expected.get("gitHead"),
        "gitTree": payload.get("gitTree") == expected.get("gitTree"),
        "policyDigest": payload.get("policyDigest") == expected.get("policyDigest"),
        "toolVersion": payload.get("toolVersion") == SERVER_VERSION,
        "commandKey": payload.get("commandKey") == expected.get("commandKey"),
        "commandFingerprint": payload.get("commandFingerprint")
        == expected.get("commandFingerprint"),
        "workloadId": payload.get("workloadId") == expected.get("workloadId"),
        "workloadDigest": payload.get("workloadDigest") == expected.get("workloadDigest"),
        "environmentDigest": payload.get("environmentDigest")
        == expected.get("environmentDigest"),
        "captureDigest": payload.get("captureDigest") == expected.get("captureDigest"),
        "metricCount": payload.get("metricCount") == expected.get("metricCount"),
        "measurementIterations": payload.get("measurementIterations")
        == expected.get("measurementIterations"),
        "executionProfile": payload.get("executionProfile")
        == "local-scrubbed-no-os-sandbox-v1",
        "passed": payload.get("passed") is True,
        "mutationDetected": payload.get("mutationDetected") is False,
        "fresh": 0 <= age <= RECEIPT_MAX_AGE_SECONDS,
    }
    return {"valid": all(checks.values()), "checks": checks, "payload": payload}


def evaluate_audit_stage5_performance(
    results: Any,
    report: Any,
    project_path: Path,
    artifacts: dict[str, dict[str, Any]],
    qa_verifications: list[dict[str, Any]],
    performance_receipts: list[str],
    drill_id: str,
) -> dict[str, Any]:
    """Validate one exact-revision Stage 5 performance evidence package."""

    results_fields = {
        "schemaVersion",
        "subject",
        "exercise",
        "benchmarkPlanSha256",
        "workload",
        "comparisonPolicy",
        "captures",
        "limitations",
    }
    report_fields = {
        "schemaVersion",
        "subject",
        "exercise",
        "assessmentBoundary",
        "artifactBindings",
        "coverage",
        "evidence",
        "bottlenecks",
        "findings",
        "remediations",
        "regressionGuards",
        "qaBindings",
        "gaps",
        "complete",
        "limitations",
    }
    if not isinstance(results, dict) or set(results) != results_fields:
        raise ToolError(
            "Audit Stage 5 baseline-results.json has unsupported or missing fields."
        )
    if not isinstance(report, dict) or set(report) != report_fields:
        raise ToolError(
            "Audit Stage 5 performance-findings.json has unsupported or missing fields."
        )
    audit_enforce_json_limit(results, "Audit Stage 5 performance results", 10_000_000)
    audit_enforce_json_limit(report, "Audit Stage 5 performance findings", 2_000_000)
    audit_reject_secret_values(results, "Audit Stage 5 performance results")
    audit_reject_secret_values(report, "Audit Stage 5 performance findings")
    source = _audit_source_subject(project_path, "Stage 5")
    root = source["_root"]
    current_policy_digest = evidence_subject(project_path)["policyDigest"]
    failures: list[str] = []

    def exact_object(
        container: dict[str, Any], field: str, keys: set[str], label: str
    ) -> dict[str, Any]:
        value = container.get(field)
        if not isinstance(value, dict) or set(value) != keys:
            raise ToolError(
                f"Audit Stage 5 {label} {field} has unsupported or missing fields."
            )
        return value

    def exact_list(
        container: dict[str, Any], field: str, label: str, maximum: int = AUDIT_STAGE5_MAX_ITEMS
    ) -> list[Any]:
        value = container.get(field)
        if not isinstance(value, list) or len(value) > maximum:
            raise ToolError(
                f"Audit Stage 5 {label} {field} must be an array with at most {maximum} items."
            )
        return value

    def valid_id(value: Any) -> bool:
        return bool(
            isinstance(value, str)
            and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,127}", value)
        )

    def valid_text(value: Any, maximum: int = 1000) -> bool:
        return bool(isinstance(value, str) and value.strip() and len(value) <= maximum)

    if results.get("schemaVersion") != AUDIT_STAGE5_RESULTS_SCHEMA:
        failures.append("results.schemaVersion")
    if report.get("schemaVersion") != AUDIT_STAGE5_FINDINGS_SCHEMA:
        failures.append("report.schemaVersion")
    expected_type = AUDIT_STAGE5_DRILL_TYPES.get(drill_id)
    if expected_type is None:
        raise ToolError(f"Unsupported Audit Stage 5 drill: {drill_id}")
    for container, label in ((results, "results"), (report, "report")):
        exercise = exact_object(container, "exercise", {"drillId", "type"}, label)
        if exercise.get("drillId") != drill_id:
            failures.append(label + ".exercise.drillId")
        if exercise.get("type") != expected_type:
            failures.append(label + ".exercise.type")

    subject_keys = {
        "baselineGitHead",
        "baselineGitTree",
        "candidateGitHead",
        "candidateGitTree",
    }
    results_subject = exact_object(results, "subject", subject_keys, "results")
    report_subject = exact_object(report, "subject", subject_keys, "report")
    if report_subject != results_subject:
        failures.append("subject.report-results-mismatch")
    baseline = _audit_stage4_resolve_revision(root, results_subject.get("baselineGitHead"))
    candidate = _audit_stage4_resolve_revision(root, results_subject.get("candidateGitHead"))
    if baseline is None:
        failures.append("subject.baseline")
    if candidate is None:
        failures.append("subject.candidate")
    if baseline and results_subject.get("baselineGitTree") != baseline["gitTree"]:
        failures.append("subject.baselineGitTree")
    if candidate and results_subject.get("candidateGitTree") != candidate["gitTree"]:
        failures.append("subject.candidateGitTree")
    if candidate and (
        candidate["gitHead"] != source["gitHead"] or candidate["gitTree"] != source["gitTree"]
    ):
        failures.append("subject.candidate-not-current")
    changed_paths: Optional[list[str]] = None
    if baseline and candidate:
        if expected_type == "audit":
            if baseline != candidate:
                failures.append("subject.audit-baseline-candidate")
        else:
            ancestry = run_complete(
                ["git", "merge-base", "--is-ancestor", baseline["gitHead"], candidate["gitHead"]],
                root,
                timeout=8,
            )
            changed_paths = _audit_stage4_changed_paths(
                root, baseline["gitHead"], candidate["gitHead"]
            )
            if baseline["gitHead"] == candidate["gitHead"]:
                failures.append("subject.implementation-distinct-commit")
            if not ancestry["ok"]:
                failures.append("subject.baseline-not-ancestor")
            if not changed_paths:
                failures.append("subject.implementation-empty-diff")

    plan_artifact = artifacts.get("benchmark-plan.md") or {}
    results_artifact = artifacts.get("baseline-results.json") or {}
    plan_metadata = validate_mastery_text_artifact(
        project_path, plan_artifact, "Audit Stage 5 benchmark-plan.md"
    )
    if results.get("benchmarkPlanSha256") != plan_metadata["sha256"]:
        failures.append("results.benchmarkPlanSha256")
    bindings = exact_object(
        report, "artifactBindings", {"benchmarkPlan", "baselineResults"}, "report"
    )
    for binding_name, artifact_name in (
        ("benchmarkPlan", "benchmark-plan.md"),
        ("baselineResults", "baseline-results.json"),
    ):
        binding = bindings.get(binding_name)
        if not isinstance(binding, dict) or set(binding) != {"path", "sha256"}:
            raise ToolError("Audit Stage 5 artifact binding is malformed.")
        artifact = artifacts.get(artifact_name) or {}
        if binding.get("path") != artifact.get("path"):
            failures.append(f"artifactBindings.{binding_name}.path")
        if binding.get("sha256") != artifact.get("sha256"):
            failures.append(f"artifactBindings.{binding_name}.sha256")

    boundary = exact_object(
        report,
        "assessmentBoundary",
        set(AUDIT_STAGE5_ASSESSMENT_BOUNDARY),
        "report",
    )
    for field, expected in AUDIT_STAGE5_ASSESSMENT_BOUNDARY.items():
        if type(boundary.get(field)) is not type(expected) or boundary.get(field) != expected:
            failures.append("assessmentBoundary." + field)
    if results.get("limitations") != AUDIT_STAGE5_RESULTS_LIMITATIONS:
        failures.append("results.limitations")
    if report.get("limitations") != AUDIT_STAGE5_LIMITATIONS:
        failures.append("report.limitations")

    workload_keys = {
        "id",
        "name",
        "criticalPath",
        "inputDigest",
        "deterministicSeed",
        "concurrency",
        "warmupIterations",
        "measurementIterations",
        "timeoutSeconds",
        "realisticRationale",
    }
    workload = exact_object(results, "workload", workload_keys, "results")
    if not valid_id(workload.get("id")):
        failures.append("workload.id")
    for field in ("name", "criticalPath", "realisticRationale"):
        if not valid_text(workload.get(field)):
            failures.append("workload." + field)
    if not re.fullmatch(r"[0-9a-f]{64}", str(workload.get("inputDigest") or "")):
        failures.append("workload.inputDigest")
    for field, minimum, maximum in (
        ("deterministicSeed", 0, 2**63 - 1),
        ("concurrency", 1, 100_000),
        ("warmupIterations", 0, 10_000),
        ("measurementIterations", 5, 10_000),
        ("timeoutSeconds", 1, 1800),
    ):
        value = workload.get(field)
        if not isinstance(value, int) or isinstance(value, bool) or not minimum <= value <= maximum:
            failures.append("workload." + field)
    workload_digest = audit_core.performance_canonical_sha256(workload)
    comparison = exact_object(
        results,
        "comparisonPolicy",
        {
            "percentileMethod",
            "outlierPolicy",
            "environmentPolicy",
            "commandPolicy",
            "warmupsExcluded",
        },
        "results",
    )
    expected_comparison = {
        "percentileMethod": "nearest-rank",
        "outlierPolicy": "none",
        "environmentPolicy": "same-signed-environment",
        "commandPolicy": "same-command-fingerprint",
        "warmupsExcluded": True,
    }
    if comparison != expected_comparison:
        failures.append("comparisonPolicy")

    if not isinstance(performance_receipts, list) or not all(
        isinstance(item, str) for item in performance_receipts
    ):
        raise ToolError("performance_receipts must be an array of JStack performance receipts.")
    if len(performance_receipts) > PERFORMANCE_MAX_RECEIPTS:
        raise ToolError("performance_receipts exceeds the bounded Stage 5 limit.")
    if any(len(receipt) > PERFORMANCE_MAX_RECEIPT_CHARS for receipt in performance_receipts):
        raise ToolError("performance_receipts contains an oversized receipt.")
    receipts_by_digest: dict[str, str] = {}
    for receipt in performance_receipts:
        digest = hashlib.sha256(receipt.encode("utf-8")).hexdigest()
        if digest in receipts_by_digest:
            failures.append("performanceReceipts.duplicate")
        receipts_by_digest[digest] = receipt

    capture_items = exact_list(results, "captures", "results", 2)
    expected_capture_count = 1 if expected_type == "audit" else 2
    if len(capture_items) != expected_capture_count:
        failures.append("captures.count")
    capture_by_revision: dict[str, dict[str, Any]] = {}
    summaries_by_revision: dict[str, dict[str, dict[str, Any]]] = {}
    matched_receipts: set[str] = set()
    environment_digests: set[str] = set()
    command_fingerprints: set[str] = set()
    metric_contracts: list[list[tuple[Any, ...]]] = []
    capture_fields = {
        "id",
        "revision",
        "receiptDigest",
        "environmentDigest",
        "commandKey",
        "commandFingerprint",
        "captureDigest",
        "capture",
        "summary",
    }
    for index, item in enumerate(capture_items):
        prefix = f"captures[{index}]"
        if not isinstance(item, dict) or set(item) != capture_fields:
            raise ToolError(f"Audit Stage 5 {prefix} has unsupported or missing fields.")
        if not valid_id(item.get("id")):
            failures.append(prefix + ".id")
        revision_kind = item.get("revision")
        if revision_kind not in {"baseline", "candidate"} or revision_kind in capture_by_revision:
            failures.append(prefix + ".revision")
            continue
        capture_by_revision[revision_kind] = item
        expected_revision = baseline if revision_kind == "baseline" else candidate
        try:
            capture = audit_core.normalize_performance_capture(item.get("capture"))
        except audit_core.PerformanceProtocolError as exc:
            raise ToolError(f"Audit Stage 5 {prefix}.capture is invalid: {exc}") from exc
        capture_digest = audit_core.performance_canonical_sha256(capture)
        summaries = audit_core.summarize_performance_capture(capture)
        if item.get("captureDigest") != capture_digest:
            failures.append(prefix + ".captureDigest")
        if item.get("summary") != summaries:
            failures.append(prefix + ".summary")
        if capture.get("workloadId") != workload.get("id"):
            failures.append(prefix + ".workloadId")
        if capture.get("workloadDigest") != workload_digest:
            failures.append(prefix + ".workloadDigest")
        if capture.get("warmupIterations") != workload.get("warmupIterations"):
            failures.append(prefix + ".warmupIterations")
        if capture.get("measurementIterations") != workload.get("measurementIterations"):
            failures.append(prefix + ".measurementIterations")
        summary_map = {entry["id"]: entry for entry in summaries}
        summaries_by_revision[revision_kind] = summary_map
        metric_contracts.append(
            [
                (
                    entry["id"],
                    entry["surface"],
                    entry["unit"],
                    entry["direction"],
                    entry["role"],
                )
                for entry in summaries
            ]
        )
        environment_digest = item.get("environmentDigest")
        command_key = item.get("commandKey")
        command_fingerprint = item.get("commandFingerprint")
        receipt_digest = item.get("receiptDigest")
        if not re.fullmatch(r"[0-9a-f]{64}", str(environment_digest or "")):
            failures.append(prefix + ".environmentDigest")
        else:
            environment_digests.add(str(environment_digest))
        if not valid_id(command_key):
            failures.append(prefix + ".commandKey")
        if not re.fullmatch(r"[0-9a-f]{64}", str(command_fingerprint or "")):
            failures.append(prefix + ".commandFingerprint")
        else:
            command_fingerprints.add(str(command_fingerprint))
        if not re.fullmatch(r"[0-9a-f]{64}", str(receipt_digest or "")):
            failures.append(prefix + ".receiptDigest")
        receipt = receipts_by_digest.get(str(receipt_digest))
        if receipt is None or expected_revision is None:
            failures.append(prefix + ".receipt.missing")
        else:
            verification = _verify_performance_receipt_for_revision(
                receipt,
                root,
                {
                    "gitHead": expected_revision["gitHead"],
                    "gitTree": expected_revision["gitTree"],
                    "policyDigest": current_policy_digest,
                    "commandKey": command_key,
                    "commandFingerprint": command_fingerprint,
                    "workloadId": workload.get("id"),
                    "workloadDigest": workload_digest,
                    "environmentDigest": environment_digest,
                    "captureDigest": capture_digest,
                    "metricCount": len(capture["metrics"]),
                    "measurementIterations": capture["measurementIterations"],
                },
            )
            if not verification["valid"]:
                failures.append(prefix + ".receipt.invalid")
            else:
                matched_receipts.add(str(receipt_digest))
    expected_revisions = {"baseline"} if expected_type == "audit" else {"baseline", "candidate"}
    if set(capture_by_revision) != expected_revisions:
        failures.append("captures.revisions")
    if len(environment_digests) > 1:
        failures.append("captures.environment-mismatch")
    if len(command_fingerprints) > 1:
        failures.append("captures.command-mismatch")
    if len(metric_contracts) == 2 and metric_contracts[0] != metric_contracts[1]:
        failures.append("captures.metric-contract-mismatch")
    if set(receipts_by_digest) != matched_receipts:
        failures.append("performanceReceipts.unused-or-unverified")

    evidence_items = exact_list(report, "evidence", "report")
    if not evidence_items:
        failures.append("evidence.empty")
    evidence_ids: set[str] = set()
    referenced_evidence: set[str] = set()
    total_evidence_bytes = 0
    for index, item in enumerate(evidence_items):
        prefix = f"evidence[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "revision",
            "path",
            "lineStart",
            "lineEnd",
            "sha256",
        }:
            raise ToolError("Audit Stage 5 evidence entry is malformed.")
        evidence_id = item.get("id")
        if not valid_id(evidence_id) or evidence_id in evidence_ids:
            failures.append(prefix + ".id")
        else:
            evidence_ids.add(str(evidence_id))
        revision_kind = item.get("revision")
        revision = (
            baseline["gitHead"]
            if revision_kind == "baseline" and baseline
            else candidate["gitHead"]
            if revision_kind == "candidate" and candidate
            else ""
        )
        if not revision:
            failures.append(prefix + ".revision")
        path = item.get("path")
        start = item.get("lineStart")
        end = item.get("lineEnd")
        if not _audit_stage1_safe_relative_path(path):
            failures.append(prefix + ".path")
            continue
        if (
            not isinstance(start, int)
            or isinstance(start, bool)
            or not isinstance(end, int)
            or isinstance(end, bool)
            or start < 1
            or end < start
        ):
            failures.append(prefix + ".lines")
        content = (
            _audit_stage4_revision_file(
                root,
                revision,
                str(path),
                max_bytes=AUDIT_STAGE4_MAX_EVIDENCE_FILE_BYTES,
            )
            if revision
            else None
        )
        if content is None:
            failures.append(prefix + ".path.untracked-or-nonregular")
            continue
        total_evidence_bytes += len(content)
        if total_evidence_bytes > AUDIT_STAGE4_MAX_EVIDENCE_TOTAL_BYTES:
            raise ToolError("Audit Stage 5 evidence exceeds the bounded total read limit.")
        if item.get("sha256") != hashlib.sha256(content).hexdigest():
            failures.append(prefix + ".sha256")
        if isinstance(end, int) and not isinstance(end, bool) and end > len(content.splitlines()):
            failures.append(prefix + ".lines")

    def evidence_refs(value: Any, prefix: str, allow_empty: bool = False) -> list[str]:
        if (
            not isinstance(value, list)
            or (not allow_empty and not value)
            or len(value) > 32
            or not all(valid_id(item) for item in value)
            or len(set(value)) != len(value)
        ):
            failures.append(prefix)
            return []
        refs = [str(item) for item in value]
        if any(item not in evidence_ids for item in refs):
            failures.append(prefix + ".unknown")
        referenced_evidence.update(item for item in refs if item in evidence_ids)
        return refs

    baseline_summaries = summaries_by_revision.get("baseline", {})
    candidate_summaries = summaries_by_revision.get("candidate", {})
    all_summaries = baseline_summaries
    metric_ids = set(all_summaries)
    coverage_items = exact_list(
        report, "coverage", "report", len(AUDIT_STAGE5_REQUIRED_SURFACES)
    )
    coverage_status: dict[str, str] = {}
    covered_metrics: set[str] = set()
    for index, item in enumerate(coverage_items):
        prefix = f"coverage[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "status",
            "reason",
            "metricIds",
            "evidence",
        }:
            raise ToolError("Audit Stage 5 coverage entry is malformed.")
        surface = item.get("id")
        status = item.get("status")
        if surface not in AUDIT_STAGE5_REQUIRED_SURFACES or surface in coverage_status:
            failures.append(prefix + ".id")
        else:
            coverage_status[str(surface)] = str(status)
        if status not in AUDIT_STAGE5_SURFACE_STATUSES:
            failures.append(prefix + ".status")
        if not valid_text(item.get("reason"), 500):
            failures.append(prefix + ".reason")
        refs = item.get("metricIds")
        if (
            not isinstance(refs, list)
            or len(refs) > 32
            or not all(valid_id(ref) for ref in refs)
            or len(set(refs)) != len(refs)
        ):
            failures.append(prefix + ".metricIds")
            refs = []
        expected_metrics = {
            metric_id
            for metric_id, summary in all_summaries.items()
            if summary.get("surface") == surface
        }
        if status == "measured" and set(refs) != expected_metrics:
            failures.append(prefix + ".metricIds")
        if status != "measured" and refs:
            failures.append(prefix + ".metricIds.unexpected")
        covered_metrics.update(item for item in refs if item in metric_ids)
        evidence_refs(item.get("evidence"), prefix + ".evidence")
    if set(coverage_status) != set(AUDIT_STAGE5_REQUIRED_SURFACES):
        failures.append("coverage.surfaces")
    if any(status == "unsupported" for status in coverage_status.values()):
        failures.append("coverage.unsupported")
    if covered_metrics != metric_ids:
        failures.append("coverage.metrics")

    bottleneck_items = exact_list(report, "bottlenecks", "report")
    if len(bottleneck_items) != 1:
        failures.append("bottlenecks.count")
    bottleneck_ids: set[str] = set()
    bottleneck_metrics: dict[str, str] = {}
    for index, item in enumerate(bottleneck_items):
        prefix = f"bottlenecks[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "surface",
            "description",
            "metricId",
            "evidence",
        }:
            raise ToolError("Audit Stage 5 bottleneck entry is malformed.")
        identifier = item.get("id")
        if not valid_id(identifier) or identifier in bottleneck_ids:
            failures.append(prefix + ".id")
        else:
            bottleneck_ids.add(str(identifier))
        metric_id = str(item.get("metricId") or "")
        summary = baseline_summaries.get(metric_id)
        if summary is None or summary.get("role") != "primary":
            failures.append(prefix + ".metricId")
        elif item.get("surface") != summary.get("surface"):
            failures.append(prefix + ".surface")
        if identifier:
            bottleneck_metrics[str(identifier)] = metric_id
        if not valid_text(item.get("description")):
            failures.append(prefix + ".description")
        evidence_refs(item.get("evidence"), prefix + ".evidence")

    finding_items = exact_list(report, "findings", "report")
    if len(finding_items) != 1:
        failures.append("findings.count")
    finding_ids: set[str] = set()
    finding_remediations: dict[str, str] = {}
    for index, item in enumerate(finding_items):
        prefix = f"findings[{index}]"
        expected_fields = {
            "id",
            "surface",
            "severity",
            "status",
            "confidence",
            "verification",
            "summary",
            "metricId",
            "bottleneckId",
            "statistic",
            "comparator",
            "budget",
            "baselineValue",
            "candidateValue",
            "relativeImprovementPercent",
            "evidence",
            "remediationId",
        }
        if not isinstance(item, dict) or set(item) != expected_fields:
            raise ToolError("Audit Stage 5 finding entry is malformed.")
        finding_id = item.get("id")
        if not valid_id(finding_id) or finding_id in finding_ids:
            failures.append(prefix + ".id")
        else:
            finding_ids.add(str(finding_id))
        metric_id = str(item.get("metricId") or "")
        baseline_summary = baseline_summaries.get(metric_id)
        candidate_summary = candidate_summaries.get(metric_id)
        if baseline_summary is None or baseline_summary.get("role") != "primary":
            failures.append(prefix + ".metricId")
            continue
        if item.get("surface") != baseline_summary.get("surface"):
            failures.append(prefix + ".surface")
        if item.get("severity") not in AUDIT_STAGE5_SEVERITIES:
            failures.append(prefix + ".severity")
        if item.get("confidence") != "high" or item.get("verification") != "measured":
            failures.append(prefix + ".verification")
        if not valid_text(item.get("summary")):
            failures.append(prefix + ".summary")
        bottleneck_id = str(item.get("bottleneckId") or "")
        if bottleneck_metrics.get(bottleneck_id) != metric_id:
            failures.append(prefix + ".bottleneckId")
        statistic = str(item.get("statistic") or "")
        comparator = item.get("comparator")
        if statistic not in AUDIT_STAGE5_STATISTICS:
            failures.append(prefix + ".statistic")
            continue
        expected_comparator = "<=" if baseline_summary["direction"] == "lower-is-better" else ">="
        if comparator != expected_comparator:
            failures.append(prefix + ".comparator")
        budget = item.get("budget")
        if isinstance(budget, bool) or not isinstance(budget, (int, float)) or not float(budget) >= 0:
            failures.append(prefix + ".budget")
            continue
        baseline_value = audit_core.performance_statistic_value(baseline_summary, statistic)
        if item.get("baselineValue") != baseline_value:
            failures.append(prefix + ".baselineValue")
        violates = baseline_value > float(budget) if comparator == "<=" else baseline_value < float(budget)
        if not violates:
            failures.append(prefix + ".baseline-budget-not-violated")
        remediation_id = str(item.get("remediationId") or "")
        if finding_id:
            finding_remediations[str(finding_id)] = remediation_id
        evidence_refs(item.get("evidence"), prefix + ".evidence")
        if expected_type == "audit":
            if (
                item.get("status") != "open"
                or item.get("candidateValue") is not None
                or item.get("relativeImprovementPercent") is not None
            ):
                failures.append(prefix + ".audit-semantics")
        else:
            if item.get("status") != "resolved" or candidate_summary is None:
                failures.append(prefix + ".implementation-semantics")
            else:
                candidate_value = audit_core.performance_statistic_value(candidate_summary, statistic)
                if item.get("candidateValue") != candidate_value:
                    failures.append(prefix + ".candidateValue")
                meets = candidate_value <= float(budget) if comparator == "<=" else candidate_value >= float(budget)
                if not meets:
                    failures.append(prefix + ".candidate-budget")
                try:
                    improvement = audit_core.performance_relative_improvement(
                        baseline_summary["direction"], baseline_value, candidate_value
                    )
                except audit_core.PerformanceProtocolError:
                    failures.append(prefix + ".relativeImprovementPercent")
                else:
                    if item.get("relativeImprovementPercent") != improvement or improvement <= 0:
                        failures.append(prefix + ".relativeImprovementPercent")

    remediation_items = exact_list(report, "remediations", "report")
    if len(remediation_items) != 1:
        failures.append("remediations.count")
    remediation_ids: set[str] = set()
    for index, item in enumerate(remediation_items):
        prefix = f"remediations[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "findingId",
            "status",
            "description",
            "changedPaths",
            "evidence",
        }:
            raise ToolError("Audit Stage 5 remediation entry is malformed.")
        remediation_id = item.get("id")
        finding_id = str(item.get("findingId") or "")
        if not valid_id(remediation_id) or remediation_id in remediation_ids:
            failures.append(prefix + ".id")
        else:
            remediation_ids.add(str(remediation_id))
        if finding_id not in finding_ids or finding_remediations.get(finding_id) != remediation_id:
            failures.append(prefix + ".findingId")
        if not valid_text(item.get("description")):
            failures.append(prefix + ".description")
        paths = item.get("changedPaths")
        if (
            not isinstance(paths, list)
            or len(paths) > AUDIT_STAGE5_MAX_ITEMS
            or not all(isinstance(path, str) for path in paths)
            or len(set(paths)) != len(paths)
        ):
            failures.append(prefix + ".changedPaths")
            paths = []
        if any(not _audit_stage1_safe_relative_path(path) for path in paths):
            failures.append(prefix + ".changedPaths")
        evidence_refs(item.get("evidence"), prefix + ".evidence")
        if expected_type == "audit":
            if item.get("status") != "proposed" or paths:
                failures.append(prefix + ".audit-semantics")
        else:
            if item.get("status") != "implemented-verified":
                failures.append(prefix + ".implementation-status")
            if sorted(paths) != sorted(changed_paths or []):
                failures.append(prefix + ".changedPaths.diff")
    if finding_ids != set(finding_remediations) or remediation_ids != set(finding_remediations.values()):
        failures.append("remediations.reciprocity")

    guard_items = exact_list(report, "regressionGuards", "report")
    guardrail_metric_ids = {
        metric_id
        for metric_id, summary in baseline_summaries.items()
        if summary.get("role") == "guardrail"
    }
    guarded_metrics: set[str] = set()
    for index, item in enumerate(guard_items):
        prefix = f"regressionGuards[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "metricId",
            "statistic",
            "maxRegressionPercent",
            "baselineValue",
            "candidateValue",
            "status",
        }:
            raise ToolError("Audit Stage 5 regression guard entry is malformed.")
        if not valid_id(item.get("id")):
            failures.append(prefix + ".id")
        metric_id = str(item.get("metricId") or "")
        baseline_summary = baseline_summaries.get(metric_id)
        if metric_id not in guardrail_metric_ids or metric_id in guarded_metrics:
            failures.append(prefix + ".metricId")
            continue
        guarded_metrics.add(metric_id)
        statistic = str(item.get("statistic") or "")
        if statistic not in AUDIT_STAGE5_STATISTICS:
            failures.append(prefix + ".statistic")
            continue
        tolerance = item.get("maxRegressionPercent")
        if isinstance(tolerance, bool) or not isinstance(tolerance, (int, float)) or not 0 <= float(tolerance) <= 25:
            failures.append(prefix + ".maxRegressionPercent")
            continue
        baseline_value = audit_core.performance_statistic_value(baseline_summary, statistic)
        if item.get("baselineValue") != baseline_value:
            failures.append(prefix + ".baselineValue")
        if expected_type == "audit":
            if item.get("candidateValue") is not None or item.get("status") != "planned":
                failures.append(prefix + ".audit-semantics")
        else:
            candidate_summary = candidate_summaries.get(metric_id)
            if candidate_summary is None:
                failures.append(prefix + ".candidateMetric")
                continue
            candidate_value = audit_core.performance_statistic_value(candidate_summary, statistic)
            if item.get("candidateValue") != candidate_value or item.get("status") != "passed":
                failures.append(prefix + ".candidateValue")
            regression = audit_core.performance_regression_percent(
                baseline_summary["direction"], baseline_value, candidate_value
            )
            if regression > float(tolerance):
                failures.append(prefix + ".regressed")
    if guarded_metrics != guardrail_metric_ids or not guardrail_metric_ids:
        failures.append("regressionGuards.coverage")

    qa_items = exact_list(report, "qaBindings", "report")
    matched_qa_ids: set[str] = set()
    qa_ids: set[str] = set()
    for index, item in enumerate(qa_items):
        prefix = f"qaBindings[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "commandKey",
            "commandFingerprint",
            "executionProfile",
            "returncode",
        }:
            raise ToolError("Audit Stage 5 QA binding is malformed.")
        binding_id = item.get("id")
        if not valid_id(binding_id) or binding_id in qa_ids:
            failures.append(prefix + ".id")
        else:
            qa_ids.add(str(binding_id))
        matched = False
        for verification in qa_verifications:
            payload = verification.get("payload") or {}
            if (
                verification.get("valid")
                and item.get("commandKey") == payload.get("commandKey")
                and item.get("commandFingerprint") == payload.get("commandFingerprint")
                and item.get("executionProfile") == payload.get("executionProfile")
                and item.get("returncode") == payload.get("returncode")
            ):
                matched = True
                matched_qa_ids.add(str(binding_id))
                break
        if not matched:
            failures.append(prefix + ".unverified")
    if not qa_items:
        failures.append("qaBindings.required")

    gap_items = exact_list(report, "gaps", "report")
    for index, item in enumerate(gap_items):
        prefix = f"gaps[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "surface",
            "description",
            "evidence",
        }:
            raise ToolError("Audit Stage 5 gap entry is malformed.")
        if not valid_id(item.get("id")):
            failures.append(prefix + ".id")
        if item.get("surface") not in AUDIT_STAGE5_REQUIRED_SURFACES:
            failures.append(prefix + ".surface")
        if not valid_text(item.get("description")):
            failures.append(prefix + ".description")
        evidence_refs(item.get("evidence"), prefix + ".evidence", allow_empty=True)
    if gap_items:
        failures.append("gaps.present")
    if evidence_ids - referenced_evidence:
        failures.append("evidence.unused")
    if report.get("complete") is not True:
        failures.append("complete")

    result = {
        "schemaVersion": AUDIT_STAGE5_FINDINGS_SCHEMA,
        "sourceSubject": {
            "baselineGitHead": baseline["gitHead"] if baseline else None,
            "baselineGitTree": baseline["gitTree"] if baseline else None,
            "candidateGitHead": source["gitHead"],
            "candidateGitTree": source["gitTree"],
        },
        "drillId": drill_id,
        "exerciseType": expected_type,
        "workloadDigest": workload_digest,
        "captureCount": len(capture_items),
        "matchedPerformanceReceiptCount": len(matched_receipts),
        "metricCount": len(metric_ids),
        "primaryMetricCount": sum(
            summary.get("role") == "primary" for summary in baseline_summaries.values()
        ),
        "guardrailMetricCount": len(guardrail_metric_ids),
        "measuredSurfaceCount": sum(
            status == "measured" for status in coverage_status.values()
        ),
        "notApplicableSurfaceCount": sum(
            status == "not-applicable" for status in coverage_status.values()
        ),
        "unsupportedSurfaceCount": sum(
            status == "unsupported" for status in coverage_status.values()
        ),
        "findingCount": len(finding_ids),
        "bottleneckCount": len(bottleneck_ids),
        "remediationCount": len(remediation_ids),
        "regressionGuardCount": len(guard_items),
        "qaBindingCount": len(qa_ids),
        "matchedQaBindingCount": len(matched_qa_ids),
        "changedPathCount": len(changed_paths or []),
        "gapCount": len(gap_items),
        "passed": not failures,
        "failureCodes": sorted(set(failures)),
    }
    return {**result, "evaluationDigest": audit_json_digest(result)}


def _audit_stage6_revision_paths(root: Path, revision: str) -> Optional[list[str]]:
    result = run_complete(
        ["git", "ls-tree", "-r", "-z", "--name-only", revision],
        root,
        timeout=30,
        max_bytes=20_000_000,
    )
    if not result["ok"]:
        return None
    paths: list[str] = []
    for raw_path in result["stdout"].split(b"\0"):
        if not raw_path:
            continue
        try:
            relative = decode_git_relative_path(raw_path, "Stage 6 tracked path")
        except ToolError:
            return None
        if not _audit_stage1_safe_relative_path(relative):
            return None
        paths.append(relative)
        if len(paths) > 100_000:
            return None
    return paths


def evaluate_audit_stage6_supply_chain(
    inventory: Any,
    report: Any,
    project_path: Path,
    artifacts: dict[str, dict[str, Any]],
    qa_verifications: list[dict[str, Any]],
    audit_verification: Optional[dict[str, Any]],
    drill_id: str,
) -> dict[str, Any]:
    """Validate one exact-revision Stage 6 supply-chain evidence package."""

    inventory_fields = {
        "schemaVersion",
        "subject",
        "assessmentBoundary",
        "inputs",
        "relationships",
        "coverage",
        "gaps",
        "complete",
        "limitations",
    }
    report_fields = {
        "schemaVersion",
        "subject",
        "exercise",
        "assessmentBoundary",
        "artifactBindings",
        "coverage",
        "evidence",
        "workflowActions",
        "ciPermissions",
        "buildGraph",
        "provenance",
        "generatedArtifacts",
        "scannerBindings",
        "findings",
        "remediations",
        "qaBindings",
        "gaps",
        "complete",
        "limitations",
    }
    if not isinstance(inventory, dict) or set(inventory) != inventory_fields:
        raise ToolError(
            "Audit Stage 6 dependency-inventory.json has unsupported or missing fields."
        )
    if not isinstance(report, dict) or set(report) != report_fields:
        raise ToolError(
            "Audit Stage 6 supply-chain-report.json has unsupported or missing fields."
        )
    audit_enforce_json_limit(inventory, "Audit Stage 6 dependency inventory", 10_000_000)
    audit_enforce_json_limit(report, "Audit Stage 6 supply-chain report", 10_000_000)
    audit_reject_secret_values(inventory, "Audit Stage 6 dependency inventory")
    audit_reject_secret_values(report, "Audit Stage 6 supply-chain report")
    source = _audit_source_subject(project_path, "Stage 6")
    root = source["_root"]
    failures: list[str] = []

    def valid_id(value: Any) -> bool:
        return bool(
            isinstance(value, str)
            and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,127}", value)
        )

    def valid_text(value: Any, maximum: int = 1000) -> bool:
        return bool(isinstance(value, str) and value.strip() and len(value) <= maximum)

    def exact_object(
        container: dict[str, Any], field: str, keys: set[str], label: str
    ) -> dict[str, Any]:
        value = container.get(field)
        if not isinstance(value, dict) or set(value) != keys:
            raise ToolError(
                f"Audit Stage 6 {label} {field} has unsupported or missing fields."
            )
        return value

    def exact_list(
        container: dict[str, Any],
        field: str,
        label: str,
        maximum: int = AUDIT_STAGE6_MAX_ITEMS,
    ) -> list[Any]:
        value = container.get(field)
        if not isinstance(value, list) or len(value) > maximum:
            raise ToolError(
                f"Audit Stage 6 {label} {field} must be an array with at most {maximum} items."
            )
        return value

    def collect_id(item: dict[str, Any], prefix: str, known: set[str]) -> str:
        value = item.get("id")
        if not valid_id(value):
            failures.append(prefix + ".id")
            return ""
        identifier = str(value)
        if identifier in known:
            failures.append(prefix + ".id.duplicate")
        else:
            known.add(identifier)
        return identifier

    def id_refs(
        value: Any,
        prefix: str,
        known: set[str],
        referenced: Optional[set[str]] = None,
        *,
        allow_empty: bool = False,
        maximum: int = 64,
    ) -> list[str]:
        if (
            not isinstance(value, list)
            or len(value) > maximum
            or (not allow_empty and not value)
            or not all(valid_id(item) for item in value)
        ):
            failures.append(prefix)
            return []
        refs = [str(item) for item in value]
        if len(refs) != len(set(refs)):
            failures.append(prefix + ".duplicate")
        for ref in refs:
            if ref not in known:
                failures.append(prefix + ".unknown")
            elif referenced is not None:
                referenced.add(ref)
        return refs

    if inventory.get("schemaVersion") != AUDIT_STAGE6_INVENTORY_SCHEMA:
        failures.append("inventory.schemaVersion")
    if report.get("schemaVersion") != AUDIT_STAGE6_REPORT_SCHEMA:
        failures.append("report.schemaVersion")
    if inventory.get("assessmentBoundary") != AUDIT_STAGE6_ASSESSMENT_BOUNDARY:
        failures.append("inventory.assessmentBoundary")
    if report.get("assessmentBoundary") != AUDIT_STAGE6_ASSESSMENT_BOUNDARY:
        failures.append("report.assessmentBoundary")
    if inventory.get("limitations") != AUDIT_STAGE6_INVENTORY_LIMITATIONS:
        failures.append("inventory.limitations")
    if report.get("limitations") != AUDIT_STAGE6_REPORT_LIMITATIONS:
        failures.append("report.limitations")

    expected_type = AUDIT_STAGE6_DRILL_TYPES.get(drill_id)
    if expected_type is None:
        raise ToolError(f"Unsupported Audit Stage 6 drill: {drill_id}")
    exercise = exact_object(report, "exercise", {"drillId", "type"}, "report")
    if exercise.get("drillId") != drill_id:
        failures.append("exercise.drillId")
    if exercise.get("type") != expected_type:
        failures.append("exercise.type")

    subject_keys = {
        "baselineGitHead",
        "baselineGitTree",
        "candidateGitHead",
        "candidateGitTree",
    }
    inventory_subject = exact_object(inventory, "subject", subject_keys, "inventory")
    report_subject = exact_object(report, "subject", subject_keys, "report")
    if report_subject != inventory_subject:
        failures.append("subject.report-inventory-mismatch")
    baseline = _audit_stage4_resolve_revision(
        root, inventory_subject.get("baselineGitHead")
    )
    candidate = _audit_stage4_resolve_revision(
        root, inventory_subject.get("candidateGitHead")
    )
    if baseline is None:
        failures.append("subject.baseline")
    if candidate is None:
        failures.append("subject.candidate")
    if baseline and inventory_subject.get("baselineGitTree") != baseline["gitTree"]:
        failures.append("subject.baselineGitTree")
    if candidate and inventory_subject.get("candidateGitTree") != candidate["gitTree"]:
        failures.append("subject.candidateGitTree")
    if candidate and (
        candidate["gitHead"] != source["gitHead"]
        or candidate["gitTree"] != source["gitTree"]
    ):
        failures.append("subject.candidate-not-current")
    changed_paths: Optional[list[str]] = None
    if baseline and candidate:
        if expected_type == "audit":
            if baseline != candidate:
                failures.append("subject.audit-baseline-candidate")
        else:
            ancestry = run_complete(
                [
                    "git",
                    "merge-base",
                    "--is-ancestor",
                    baseline["gitHead"],
                    candidate["gitHead"],
                ],
                root,
                timeout=8,
            )
            changed_paths = _audit_stage4_changed_paths(
                root, baseline["gitHead"], candidate["gitHead"]
            )
            if baseline["gitHead"] == candidate["gitHead"]:
                failures.append("subject.implementation-distinct-commit")
            if not ancestry["ok"]:
                failures.append("subject.baseline-not-ancestor")
            if not changed_paths:
                failures.append("subject.implementation-empty-diff")

    build_trace = validate_mastery_text_artifact(
        project_path,
        artifacts.get("build-trace.md") or {},
        "Audit Stage 6 build-trace.md",
    )
    bindings = exact_object(
        report,
        "artifactBindings",
        {"dependencyInventory", "buildTrace"},
        "report",
    )
    for binding_name, artifact_name in (
        ("dependencyInventory", "dependency-inventory.json"),
        ("buildTrace", "build-trace.md"),
    ):
        binding = bindings.get(binding_name)
        if not isinstance(binding, dict) or set(binding) != {"path", "sha256"}:
            raise ToolError("Audit Stage 6 artifact binding is malformed.")
        artifact = artifacts.get(artifact_name) or {}
        if binding.get("path") != artifact.get("path"):
            failures.append(f"artifactBindings.{binding_name}.path")
        if binding.get("sha256") != artifact.get("sha256"):
            failures.append(f"artifactBindings.{binding_name}.sha256")
    if bindings.get("buildTrace", {}).get("sha256") != build_trace.get("sha256"):
        failures.append("artifactBindings.buildTrace.sha256")

    revision_heads = {
        "baseline": baseline["gitHead"] if baseline else "",
        "candidate": candidate["gitHead"] if candidate else "",
    }
    expected_inputs: dict[tuple[str, str], dict[str, Any]] = {}
    revision_blobs: dict[tuple[str, str], bytes] = {}
    immutable_blob_cache: dict[tuple[str, str], bytes] = {}
    total_input_bytes = 0
    for revision_kind, revision in revision_heads.items():
        if not revision:
            continue
        paths = _audit_stage6_revision_paths(root, revision)
        if paths is None:
            failures.append(f"inventory.{revision_kind}.tracked-paths")
            continue
        try:
            discovered = audit_core.discover_supply_chain_inputs(paths)
        except audit_core.SupplyChainProtocolError:
            failures.append(f"inventory.{revision_kind}.discovery")
            continue
        for classified in discovered:
            path = classified["path"]
            immutable_key = (revision, path)
            content = immutable_blob_cache.get(immutable_key)
            if content is None:
                content = _audit_stage4_revision_file(
                    root,
                    revision,
                    path,
                    max_bytes=AUDIT_STAGE6_MAX_INPUT_FILE_BYTES,
                )
                if content is not None:
                    total_input_bytes += len(content)
                    if total_input_bytes > AUDIT_STAGE6_MAX_INPUT_TOTAL_BYTES:
                        raise ToolError(
                            "Audit Stage 6 classified inputs exceed the bounded total read limit."
                        )
                    immutable_blob_cache[immutable_key] = content
            if content is None:
                failures.append(f"inventory.{revision_kind}.unreadable")
                continue
            revision_blobs[(revision_kind, path)] = content
            expected_inputs[(revision_kind, path)] = {
                "revision": revision_kind,
                "path": path,
                "kind": classified["kind"],
                "ecosystem": classified["ecosystem"],
                "sha256": hashlib.sha256(content).hexdigest(),
                "sizeBytes": len(content),
            }

    input_items = exact_list(inventory, "inputs", "inventory")
    input_ids: set[str] = set()
    input_by_id: dict[str, dict[str, Any]] = {}
    actual_input_keys: set[tuple[str, str]] = set()
    required_input_fields = {
        "id",
        "revision",
        "path",
        "kind",
        "ecosystem",
        "sha256",
        "sizeBytes",
    }
    for index, item in enumerate(input_items):
        prefix = f"inputs[{index}]"
        if not isinstance(item, dict) or set(item) != required_input_fields:
            raise ToolError("Audit Stage 6 inventory input entry is malformed.")
        identifier = collect_id(item, prefix, input_ids)
        key = (str(item.get("revision")), str(item.get("path")))
        if key in actual_input_keys:
            failures.append(prefix + ".duplicate-subject")
        actual_input_keys.add(key)
        expected = expected_inputs.get(key)
        if expected is None:
            failures.append(prefix + ".undiscovered")
        else:
            for field, value in expected.items():
                if type(item.get(field)) is not type(value) or item.get(field) != value:
                    failures.append(prefix + "." + field)
        if identifier:
            input_by_id[identifier] = item
    if actual_input_keys != set(expected_inputs):
        failures.append("inputs.discovery-set")
    if not input_items:
        failures.append("inputs.empty")

    inventory_coverage = exact_list(
        inventory,
        "coverage",
        "inventory",
        len(AUDIT_STAGE6_INVENTORY_SURFACES),
    )
    coverage_kind_map = {
        "dependency-inputs": {"manifest", "policy"},
        "lockfiles": {"lockfile"},
        "build-configs": {"build-config"},
        "ci-workflows": {"ci-workflow"},
        "provenance": {"provenance"},
        "generated-artifacts": {"generated-artifact"},
    }
    inventory_coverage_ids: set[str] = set()
    for index, item in enumerate(inventory_coverage):
        prefix = f"inventory.coverage[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "status",
            "reason",
            "inputIds",
        }:
            raise ToolError("Audit Stage 6 inventory coverage entry is malformed.")
        surface = item.get("id")
        if surface not in AUDIT_STAGE6_INVENTORY_SURFACES:
            failures.append(prefix + ".id")
            expected_ids: set[str] = set()
        elif surface in inventory_coverage_ids:
            failures.append(prefix + ".id.duplicate")
            expected_ids = set()
        else:
            inventory_coverage_ids.add(str(surface))
            expected_ids = {
                identifier
                for identifier, input_item in input_by_id.items()
                if input_item.get("kind") in coverage_kind_map[str(surface)]
            }
        supplied_ids = id_refs(
            item.get("inputIds"),
            prefix + ".inputIds",
            input_ids,
            allow_empty=True,
            maximum=AUDIT_STAGE6_MAX_ITEMS,
        )
        if set(supplied_ids) != expected_ids:
            failures.append(prefix + ".inputIds.coverage")
        expected_status = "inventoried" if expected_ids else "not-applicable"
        if item.get("status") != expected_status:
            failures.append(prefix + ".status")
        if not valid_text(item.get("reason"), 500):
            failures.append(prefix + ".reason")
    if inventory_coverage_ids != set(AUDIT_STAGE6_INVENTORY_SURFACES):
        failures.append("inventory.coverage.surfaces")

    relationship_items = exact_list(inventory, "relationships", "inventory")
    relationship_ids: set[str] = set()
    lock_relationships: set[str] = set()
    for index, item in enumerate(relationship_items):
        prefix = f"relationships[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "revision",
            "fromInputId",
            "toInputId",
            "type",
            "evidence",
        }:
            raise ToolError("Audit Stage 6 inventory relationship entry is malformed.")
        collect_id(item, prefix, relationship_ids)
        from_id = str(item.get("fromInputId") or "")
        to_id = str(item.get("toInputId") or "")
        if from_id not in input_by_id:
            failures.append(prefix + ".fromInputId")
        if to_id not in input_by_id:
            failures.append(prefix + ".toInputId")
        if from_id in input_by_id and to_id in input_by_id:
            if item.get("revision") != input_by_id[from_id].get("revision") or item.get(
                "revision"
            ) != input_by_id[to_id].get("revision"):
                failures.append(prefix + ".revision")
        if item.get("type") not in {
            "locked-by",
            "configured-by",
            "built-by",
            "attested-by",
            "generated-by",
        }:
            failures.append(prefix + ".type")
        id_refs(item.get("evidence"), prefix + ".evidence", input_ids)
        if item.get("type") == "locked-by" and to_id in input_by_id:
            lock_relationships.add(to_id)
            if input_by_id[to_id].get("kind") != "lockfile":
                failures.append(prefix + ".locked-by.target")
    for identifier, item in input_by_id.items():
        if item.get("kind") != "lockfile":
            continue
        matching_manifest = any(
            candidate_item.get("revision") == item.get("revision")
            and candidate_item.get("ecosystem") == item.get("ecosystem")
            and candidate_item.get("kind") == "manifest"
            for candidate_item in input_by_id.values()
        )
        if matching_manifest and identifier not in lock_relationships:
            failures.append("relationships.lockfile-missing")
    inventory_gaps = exact_list(inventory, "gaps", "inventory", 256)
    if inventory_gaps:
        failures.append("inventory.gaps")
    if inventory.get("complete") is not True:
        failures.append("inventory.complete")

    evidence_items = exact_list(report, "evidence", "report", 1024)
    evidence_ids: set[str] = set()
    evidence_by_id: dict[str, dict[str, Any]] = {}
    evidence_revision: dict[str, str] = {}
    evidence_content_by_subject: dict[tuple[str, str], bytes] = {}
    referenced_evidence: set[str] = set()
    total_evidence_bytes = 0
    for index, item in enumerate(evidence_items):
        prefix = f"evidence[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "revision",
            "path",
            "lineStart",
            "lineEnd",
            "sha256",
        }:
            raise ToolError("Audit Stage 6 evidence entry is malformed.")
        identifier = collect_id(item, prefix, evidence_ids)
        revision_kind = item.get("revision")
        revision = revision_heads.get(str(revision_kind), "")
        path = item.get("path")
        if not _audit_stage1_safe_relative_path(path):
            failures.append(prefix + ".path")
            continue
        assert isinstance(path, str)
        start = item.get("lineStart")
        end = item.get("lineEnd")
        if (
            not isinstance(start, int)
            or isinstance(start, bool)
            or not isinstance(end, int)
            or isinstance(end, bool)
            or start < 1
            or end < start
        ):
            failures.append(prefix + ".lines")
        content = (
            _audit_stage4_revision_file(
                root,
                revision,
                path,
                max_bytes=AUDIT_STAGE6_MAX_EVIDENCE_FILE_BYTES,
            )
            if revision
            else None
        )
        if content is None:
            failures.append(prefix + ".path.untracked-or-nonregular")
            continue
        total_evidence_bytes += len(content)
        if total_evidence_bytes > AUDIT_STAGE6_MAX_EVIDENCE_TOTAL_BYTES:
            raise ToolError("Audit Stage 6 evidence exceeds the bounded total read limit.")
        if item.get("sha256") != hashlib.sha256(content).hexdigest():
            failures.append(prefix + ".sha256")
        evidence_content_by_subject[(str(revision_kind), path)] = content
        line_count = max(1, len(content.splitlines()))
        if isinstance(end, int) and not isinstance(end, bool) and end > line_count:
            failures.append(prefix + ".lines")
        if identifier:
            evidence_by_id[identifier] = item
            evidence_revision[identifier] = str(revision_kind)

    def evidence_refs(value: Any, prefix: str, *, allow_empty: bool = False) -> list[str]:
        return id_refs(
            value,
            prefix,
            evidence_ids,
            referenced_evidence,
            allow_empty=allow_empty,
        )

    report_coverage = exact_list(
        report, "coverage", "report", len(AUDIT_STAGE6_REQUIRED_SURFACES)
    )
    report_coverage_ids: set[str] = set()
    report_coverage_statuses: dict[str, str] = {}
    for index, item in enumerate(report_coverage):
        prefix = f"coverage[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "status",
            "reason",
            "evidence",
        }:
            raise ToolError("Audit Stage 6 report coverage entry is malformed.")
        surface = item.get("id")
        if surface not in AUDIT_STAGE6_REQUIRED_SURFACES:
            failures.append(prefix + ".id")
        elif surface in report_coverage_ids:
            failures.append(prefix + ".id.duplicate")
        else:
            report_coverage_ids.add(str(surface))
            report_coverage_statuses[str(surface)] = str(item.get("status"))
        if item.get("status") not in {"assessed", "not-applicable"}:
            failures.append(prefix + ".status")
        if not valid_text(item.get("reason"), 500):
            failures.append(prefix + ".reason")
        evidence_refs(item.get("evidence"), prefix + ".evidence")
    if report_coverage_ids != set(AUDIT_STAGE6_REQUIRED_SURFACES):
        failures.append("coverage.surfaces")

    finding_items = exact_list(report, "findings", "report", 256)
    finding_ids: set[str] = set()
    finding_by_id: dict[str, dict[str, Any]] = {}
    finding_remediations: dict[str, str] = {}
    for index, item in enumerate(finding_items):
        prefix = f"findings[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "category",
            "severity",
            "status",
            "confidence",
            "verification",
            "summary",
            "evidence",
            "remediationId",
        }:
            raise ToolError("Audit Stage 6 finding entry is malformed.")
        identifier = collect_id(item, prefix, finding_ids)
        if item.get("category") not in set(AUDIT_STAGE6_REQUIRED_SURFACES) - {
            "dependency-inventory"
        }:
            failures.append(prefix + ".category")
        if item.get("severity") not in {"info", "low", "medium", "high", "critical"}:
            failures.append(prefix + ".severity")
        if item.get("status") not in {"open", "resolved"}:
            failures.append(prefix + ".status")
        if item.get("confidence") != "high":
            failures.append(prefix + ".confidence")
        if item.get("verification") not in {"source-proven", "tool-confirmed"}:
            failures.append(prefix + ".verification")
        if not valid_text(item.get("summary")):
            failures.append(prefix + ".summary")
        evidence_refs(item.get("evidence"), prefix + ".evidence")
        remediation_id = item.get("remediationId")
        if not valid_id(remediation_id):
            failures.append(prefix + ".remediationId")
        elif identifier:
            finding_remediations[identifier] = str(remediation_id)
        if identifier:
            finding_by_id[identifier] = item
    if not finding_items:
        failures.append("findings.empty")

    qa_items = exact_list(report, "qaBindings", "report", 64)
    qa_ids: set[str] = set()
    qa_command_keys: set[str] = set()
    matched_qa_ids: set[str] = set()
    valid_qa_by_key = {
        str(item.get("payload", {}).get("commandKey")): item
        for item in qa_verifications
        if item.get("valid") is True
    }
    for index, item in enumerate(qa_items):
        prefix = f"qaBindings[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "commandKey",
            "commandFingerprint",
            "executionProfile",
            "returncode",
        }:
            raise ToolError("Audit Stage 6 QA binding is malformed.")
        identifier = collect_id(item, prefix, qa_ids)
        command_key = str(item.get("commandKey") or "")
        if command_key in qa_command_keys:
            failures.append(prefix + ".commandKey.duplicate")
        else:
            qa_command_keys.add(command_key)
        verification = valid_qa_by_key.get(command_key)
        payload = verification.get("payload", {}) if verification else {}
        if (
            verification is None
            or item.get("commandFingerprint") != payload.get("commandFingerprint")
            or item.get("executionProfile") != payload.get("executionProfile")
            or item.get("returncode") != payload.get("returncode")
            or payload.get("mutationDetected") is not False
        ):
            failures.append(prefix + ".receipt-mismatch")
        elif identifier:
            matched_qa_ids.add(identifier)
    discovered_qa_keys = {item["key"] for item in discover_test_commands(project_path)}
    if {str(item.get("commandKey")) for item in qa_items} != discovered_qa_keys:
        failures.append("qaBindings.discovered-command-coverage")

    remediation_items = exact_list(report, "remediations", "report", 256)
    remediation_ids: set[str] = set()
    remediation_by_id: dict[str, dict[str, Any]] = {}
    implemented_ids: list[str] = []
    for index, item in enumerate(remediation_items):
        prefix = f"remediations[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "findingId",
            "status",
            "description",
            "changedPaths",
            "evidence",
            "qaBindingIds",
        }:
            raise ToolError("Audit Stage 6 remediation entry is malformed.")
        identifier = collect_id(item, prefix, remediation_ids)
        finding_id = str(item.get("findingId") or "")
        if finding_id not in finding_by_id:
            failures.append(prefix + ".findingId")
        elif finding_remediations.get(finding_id) != identifier:
            failures.append(prefix + ".findingId.reciprocal")
        if not valid_text(item.get("description")):
            failures.append(prefix + ".description")
        changed = item.get("changedPaths")
        if (
            not isinstance(changed, list)
            or len(changed) > 256
            or len(changed) != len(set(changed))
            or not all(_audit_stage1_safe_relative_path(path) for path in changed)
        ):
            failures.append(prefix + ".changedPaths")
            changed_values: list[str] = []
        else:
            changed_values = [str(path) for path in changed]
        evidence_refs(item.get("evidence"), prefix + ".evidence")
        qa_refs = id_refs(
            item.get("qaBindingIds"),
            prefix + ".qaBindingIds",
            qa_ids,
            allow_empty=True,
        )
        status = item.get("status")
        if status not in {"proposed", "implemented-verified"}:
            failures.append(prefix + ".status")
        if expected_type == "audit":
            if status != "proposed" or changed_values or qa_refs:
                failures.append(prefix + ".audit-authority")
        elif status == "implemented-verified":
            implemented_ids.append(identifier)
            if finding_by_id.get(finding_id, {}).get("status") != "resolved":
                failures.append(prefix + ".finding-not-resolved")
            if changed_paths is None or set(changed_values) != set(changed_paths):
                failures.append(prefix + ".changedPaths.diff-mismatch")
            if not qa_refs or not set(qa_refs).issubset(matched_qa_ids):
                failures.append(prefix + ".qaBindingIds.unverified")
            refs = item.get("evidence") if isinstance(item.get("evidence"), list) else []
            if not any(evidence_revision.get(str(ref)) == "baseline" for ref in refs):
                failures.append(prefix + ".evidence.baseline-missing")
            if not any(evidence_revision.get(str(ref)) == "candidate" for ref in refs):
                failures.append(prefix + ".evidence.candidate-missing")
        else:
            if changed_values or qa_refs:
                failures.append(prefix + ".proposal-evidence")
        if identifier:
            remediation_by_id[identifier] = item
    if set(remediation_by_id) != set(finding_remediations.values()):
        failures.append("remediations.reciprocal-set")
    if expected_type == "audit":
        if any(item.get("status") != "open" for item in finding_items):
            failures.append("findings.audit-status")
    else:
        resolved = [item for item in finding_items if item.get("status") == "resolved"]
        if len(resolved) != 1 or len(implemented_ids) != 1:
            failures.append("remediations.implementation-count")

    def linked_finding(
        raw_id: Any, category: str, prefix: str, *, required: bool
    ) -> None:
        if raw_id is None:
            if required:
                failures.append(prefix + ".findingId.missing")
            return
        finding = finding_by_id.get(str(raw_id))
        if finding is None:
            failures.append(prefix + ".findingId.unknown")
        elif finding.get("category") != category:
            failures.append(prefix + ".findingId.category")

    expected_actions: dict[tuple[str, str, int, str], dict[str, Any]] = {}
    expected_permissions: dict[tuple[str, str], dict[str, Any]] = {}
    for key, input_item in expected_inputs.items():
        revision_kind, path = key
        if input_item["kind"] != "ci-workflow":
            continue
        content = revision_blobs[key]
        try:
            for action in audit_core.parse_github_actions(path, content):
                expected_actions[(revision_kind, path, action["line"], action["locator"])] = {
                    **action,
                    "revision": revision_kind,
                }
            permission = audit_core.parse_github_permissions(path, content)
        except audit_core.SupplyChainProtocolError:
            failures.append(f"workflow.{revision_kind}.{path}.parse")
            continue
        if permission["mode"] != "not-applicable":
            expected_permissions[(revision_kind, path)] = {
                **permission,
                "revision": revision_kind,
            }

    action_items = exact_list(report, "workflowActions", "report", 1024)
    action_ids: set[str] = set()
    actual_action_keys: set[tuple[str, str, int, str]] = set()
    for index, item in enumerate(action_items):
        prefix = f"workflowActions[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "revision",
            "path",
            "line",
            "locator",
            "reference",
            "referenceType",
            "immutable",
            "evidence",
            "findingId",
        }:
            raise ToolError("Audit Stage 6 workflow action entry is malformed.")
        collect_id(item, prefix, action_ids)
        key = (
            str(item.get("revision")),
            str(item.get("path")),
            int(item.get("line")) if isinstance(item.get("line"), int) else -1,
            str(item.get("locator")),
        )
        if key in actual_action_keys:
            failures.append(prefix + ".duplicate-subject")
        actual_action_keys.add(key)
        expected = expected_actions.get(key)
        if expected is None:
            failures.append(prefix + ".undiscovered")
        else:
            for field in ("revision", "path", "line", "locator", "reference", "referenceType", "immutable"):
                if type(item.get(field)) is not type(expected[field]) or item.get(field) != expected[field]:
                    failures.append(prefix + "." + field)
        refs = evidence_refs(item.get("evidence"), prefix + ".evidence")
        if not any(
            evidence_by_id.get(ref, {}).get("revision") == item.get("revision")
            and evidence_by_id.get(ref, {}).get("path") == item.get("path")
            for ref in refs
        ):
            failures.append(prefix + ".evidence.subject")
        linked_finding(
            item.get("findingId"),
            "automation-pinning",
            prefix,
            required=item.get("immutable") is False,
        )
        if item.get("immutable") is True and item.get("findingId") is not None:
            failures.append(prefix + ".findingId.unexpected")
    if actual_action_keys != set(expected_actions):
        failures.append("workflowActions.discovery-set")

    permission_items = exact_list(report, "ciPermissions", "report", 512)
    permission_ids: set[str] = set()
    actual_permission_keys: set[tuple[str, str]] = set()
    for index, item in enumerate(permission_items):
        prefix = f"ciPermissions[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "revision",
            "path",
            "mode",
            "scopes",
            "writeScopes",
            "justification",
            "evidence",
            "findingId",
        }:
            raise ToolError("Audit Stage 6 CI permission entry is malformed.")
        collect_id(item, prefix, permission_ids)
        key = (str(item.get("revision")), str(item.get("path")))
        if key in actual_permission_keys:
            failures.append(prefix + ".duplicate-subject")
        actual_permission_keys.add(key)
        expected = expected_permissions.get(key)
        if expected is None:
            failures.append(prefix + ".undiscovered")
        else:
            for field in ("revision", "path", "mode", "scopes", "writeScopes"):
                if item.get(field) != expected[field]:
                    failures.append(prefix + "." + field)
        refs = evidence_refs(item.get("evidence"), prefix + ".evidence")
        if not any(
            evidence_by_id.get(ref, {}).get("revision") == item.get("revision")
            and evidence_by_id.get(ref, {}).get("path") == item.get("path")
            for ref in refs
        ):
            failures.append(prefix + ".evidence.subject")
        mode = item.get("mode")
        write_scopes = item.get("writeScopes")
        risky = mode in {"implicit", "explicit-write-all", "unsupported"}
        if isinstance(write_scopes, list) and write_scopes:
            risky = risky or not valid_text(item.get("justification"))
        elif item.get("justification") is not None:
            failures.append(prefix + ".justification.unexpected")
        linked_finding(
            item.get("findingId"),
            "ci-least-privilege",
            prefix,
            required=risky,
        )
        if not risky and item.get("findingId") is not None:
            failures.append(prefix + ".findingId.unexpected")
    if actual_permission_keys != set(expected_permissions):
        failures.append("ciPermissions.discovery-set")

    graph = exact_object(report, "buildGraph", {"nodes", "edges"}, "report")
    node_items = exact_list(graph, "nodes", "buildGraph", 1024)
    edge_items = exact_list(graph, "edges", "buildGraph", 2048)
    node_ids: set[str] = set()
    node_by_id: dict[str, dict[str, Any]] = {}
    for index, item in enumerate(node_items):
        prefix = f"buildGraph.nodes[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "revision",
            "path",
            "role",
            "evidence",
        }:
            raise ToolError("Audit Stage 6 build graph node is malformed.")
        identifier = collect_id(item, prefix, node_ids)
        if item.get("revision") not in {"baseline", "candidate"}:
            failures.append(prefix + ".revision")
        if item.get("role") not in {
            "source",
            "configuration",
            "dependency",
            "artifact",
            "attestation",
        }:
            failures.append(prefix + ".role")
        path = item.get("path")
        if not _audit_stage1_safe_relative_path(path):
            failures.append(prefix + ".path")
        refs = evidence_refs(item.get("evidence"), prefix + ".evidence")
        if not any(
            evidence_by_id.get(ref, {}).get("revision") == item.get("revision")
            and evidence_by_id.get(ref, {}).get("path") == item.get("path")
            for ref in refs
        ):
            failures.append(prefix + ".evidence.subject")
        if identifier:
            node_by_id[identifier] = item
    edge_ids: set[str] = set()
    traced_artifacts: set[str] = set()
    edges_by_artifact: dict[str, list[tuple[str, str]]] = {}
    for index, item in enumerate(edge_items):
        prefix = f"buildGraph.edges[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "fromNodeId",
            "toNodeId",
            "type",
            "evidence",
        }:
            raise ToolError("Audit Stage 6 build graph edge is malformed.")
        collect_id(item, prefix, edge_ids)
        from_id = str(item.get("fromNodeId") or "")
        to_id = str(item.get("toNodeId") or "")
        if from_id not in node_by_id:
            failures.append(prefix + ".fromNodeId")
        if to_id not in node_by_id:
            failures.append(prefix + ".toNodeId")
        if from_id in node_by_id and to_id in node_by_id:
            if node_by_id[from_id].get("revision") != node_by_id[to_id].get("revision"):
                failures.append(prefix + ".revision")
            if node_by_id[to_id].get("role") == "artifact":
                edge_type = str(item.get("type") or "")
                edges_by_artifact.setdefault(to_id, []).append((from_id, edge_type))
                if node_by_id[from_id].get("role") in {
                    "source",
                    "configuration",
                    "dependency",
                }:
                    traced_artifacts.add(to_id)
        if item.get("type") not in {"declares", "configures", "builds", "generates", "attests"}:
            failures.append(prefix + ".type")
        evidence_refs(item.get("evidence"), prefix + ".evidence")
    candidate_artifacts = {
        identifier
        for identifier, item in node_by_id.items()
        if item.get("revision") == "candidate" and item.get("role") == "artifact"
    }
    if not candidate_artifacts or not candidate_artifacts.issubset(traced_artifacts):
        failures.append("buildGraph.candidate-artifact-trace")

    provenance_items = exact_list(report, "provenance", "report", 256)
    provenance_ids: set[str] = set()
    provenance_artifacts: set[str] = set()
    for index, item in enumerate(provenance_items):
        prefix = f"provenance[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "revision",
            "artifactNodeId",
            "materialNodeIds",
            "builderId",
            "attestationStatus",
            "evidence",
            "findingId",
        }:
            raise ToolError("Audit Stage 6 provenance entry is malformed.")
        collect_id(item, prefix, provenance_ids)
        artifact_id = str(item.get("artifactNodeId") or "")
        if artifact_id not in node_by_id or node_by_id[artifact_id].get("role") != "artifact":
            failures.append(prefix + ".artifactNodeId")
        else:
            if artifact_id in provenance_artifacts:
                failures.append(prefix + ".artifactNodeId.duplicate")
            provenance_artifacts.add(artifact_id)
            if item.get("revision") != node_by_id[artifact_id].get("revision"):
                failures.append(prefix + ".revision")
        material_ids = id_refs(
            item.get("materialNodeIds"), prefix + ".materialNodeIds", node_ids
        )
        for material_id in material_ids:
            material = node_by_id.get(material_id)
            if material is None:
                continue
            if material.get("revision") != item.get("revision"):
                failures.append(prefix + ".materialNodeIds.revision")
            if material.get("role") not in {"source", "configuration", "dependency"}:
                failures.append(prefix + ".materialNodeIds.role")
        if not valid_text(item.get("builderId"), 500):
            failures.append(prefix + ".builderId")
        status = item.get("attestationStatus")
        if status not in {"verified", "missing", "unsupported"}:
            failures.append(prefix + ".attestationStatus")
        evidence_refs(item.get("evidence"), prefix + ".evidence")
        linked_finding(
            item.get("findingId"),
            "build-trace-provenance",
            prefix,
            required=status in {"missing", "unsupported"},
        )
        if status == "verified" and not any(
            node_by_id.get(from_id, {}).get("role") == "attestation"
            and edge_type == "attests"
            for from_id, edge_type in edges_by_artifact.get(artifact_id, [])
        ):
            failures.append(prefix + ".attestation-evidence")
        if status == "verified" and item.get("findingId") is not None:
            failures.append(prefix + ".findingId.unexpected")
    if not candidate_artifacts.issubset(provenance_artifacts):
        failures.append("provenance.candidate-artifacts")

    generated_items = exact_list(report, "generatedArtifacts", "report", 512)
    generated_ids: set[str] = set()
    actual_generated_keys: set[tuple[str, str]] = set()
    expected_generated_keys = {
        key for key, item in expected_inputs.items() if item["kind"] == "generated-artifact"
    }
    for index, item in enumerate(generated_items):
        prefix = f"generatedArtifacts[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "revision",
            "path",
            "artifactNodeId",
            "sourcePaths",
            "status",
            "evidence",
            "findingId",
        }:
            raise ToolError("Audit Stage 6 generated artifact entry is malformed.")
        collect_id(item, prefix, generated_ids)
        key = (str(item.get("revision")), str(item.get("path")))
        if key in actual_generated_keys:
            failures.append(prefix + ".duplicate-subject")
        actual_generated_keys.add(key)
        if key not in expected_generated_keys:
            failures.append(prefix + ".undiscovered")
        artifact_id = str(item.get("artifactNodeId") or "")
        if (
            artifact_id not in node_by_id
            or node_by_id[artifact_id].get("role") != "artifact"
            or node_by_id[artifact_id].get("revision") != item.get("revision")
            or node_by_id[artifact_id].get("path") != item.get("path")
        ):
            failures.append(prefix + ".artifactNodeId")
        refs = evidence_refs(item.get("evidence"), prefix + ".evidence")
        evidence_subjects = {
            (
                str(evidence_by_id.get(ref, {}).get("revision")),
                str(evidence_by_id.get(ref, {}).get("path")),
            )
            for ref in refs
        }
        source_paths = item.get("sourcePaths")
        if (
            not isinstance(source_paths, list)
            or len(source_paths) > 64
            or len(source_paths) != len(set(source_paths))
            or not all(_audit_stage1_safe_relative_path(path) for path in source_paths)
        ):
            failures.append(prefix + ".sourcePaths")
            source_contents: list[bytes] = []
        else:
            source_contents = []
            for source_path in source_paths:
                source_key = (str(item.get("revision")), str(source_path))
                if source_path == item.get("path"):
                    failures.append(prefix + ".sourcePaths.self")
                try:
                    source_classification = audit_core.classify_supply_chain_path(
                        str(source_path)
                    )
                except audit_core.SupplyChainProtocolError:
                    source_classification = None
                if (
                    source_classification is not None
                    and source_classification.get("kind") == "generated-artifact"
                ):
                    failures.append(prefix + ".sourcePaths.generated")
                source_nodes = [
                    node_id
                    for node_id, node in node_by_id.items()
                    if node.get("revision") == item.get("revision")
                    and node.get("path") == source_path
                    and node.get("role") == "source"
                ]
                if not source_nodes or not any(
                    from_id in source_nodes and edge_type in {"builds", "generates"}
                    for from_id, edge_type in edges_by_artifact.get(artifact_id, [])
                ):
                    failures.append(prefix + ".sourcePaths.build-edge")
                if source_key not in evidence_subjects:
                    failures.append(prefix + ".sourcePaths.evidence")
                content = evidence_content_by_subject.get(source_key)
                if content is None:
                    failures.append(prefix + ".sourcePaths.untracked")
                else:
                    source_contents.append(content)
        artifact_content = revision_blobs.get(key)
        if not source_contents:
            expected_status = "unverifiable"
        elif artifact_content is not None and any(
            hashlib.sha256(content).digest() == hashlib.sha256(artifact_content).digest()
            for content in source_contents
        ):
            expected_status = "in-sync"
        else:
            expected_status = "drift"
        if item.get("status") != expected_status:
            failures.append(prefix + ".status")
        if not any(
            evidence_by_id.get(ref, {}).get("revision") == item.get("revision")
            and evidence_by_id.get(ref, {}).get("path") == item.get("path")
            for ref in refs
        ):
            failures.append(prefix + ".evidence.subject")
        linked_finding(
            item.get("findingId"),
            "generated-artifact-integrity",
            prefix,
            required=expected_status != "in-sync",
        )
        if expected_status == "in-sync" and item.get("findingId") is not None:
            failures.append(prefix + ".findingId.unexpected")
    if actual_generated_keys != expected_generated_keys:
        failures.append("generatedArtifacts.discovery-set")

    scanner_items = exact_list(report, "scannerBindings", "report", 16)
    scanner_ids: set[str] = set()
    payload = audit_verification.get("payload", {}) if audit_verification else {}
    receipt_valid = bool(audit_verification and audit_verification.get("valid"))
    required_domains = payload.get("requiredDomains")
    if (
        not receipt_valid
        or payload.get("complete") is not True
        or payload.get("resultStatus") not in {"pass", "fail"}
        or not isinstance(required_domains, list)
        or not all(isinstance(item, str) for item in required_domains)
        or "supply-chain" not in required_domains
    ):
        failures.append("scannerBindings.audit-receipt")
    expected_scanners: dict[str, dict[str, Any]] = {}
    adapter_results = payload.get("adapterResults")
    if not isinstance(adapter_results, list):
        failures.append("scannerBindings.audit-receipt-adapters")
        adapter_results = []
    dependency_adapter_ids: set[str] = set()
    for index, adapter in enumerate(adapter_results):
        if not isinstance(adapter, dict):
            failures.append(f"scannerBindings.audit-receipt-adapters[{index}]")
            continue
        if adapter.get("capability") != "dependency-analysis":
            continue
        adapter_id = str(adapter.get("adapterId") or "")
        if not valid_id(adapter_id):
            failures.append(f"scannerBindings.audit-receipt-adapters[{index}].adapterId")
            continue
        if adapter_id in dependency_adapter_ids:
            failures.append(f"scannerBindings.audit-receipt-adapters[{index}].duplicate")
        dependency_adapter_ids.add(adapter_id)
        valid_dependency_result = (
            adapter.get("status") == "passed"
            and adapter.get("subjectValidated") is True
            and isinstance(adapter.get("returnCode"), int)
            and not isinstance(adapter.get("returnCode"), bool)
            and adapter.get("returnCode") == 0
            and adapter.get("mutationDetected") is False
            and all(
                valid_text(adapter.get(field), 200)
                for field in (
                    "adapterVersion",
                    "approvalSubjectDigest",
                    "evidenceFingerprint",
                    "outputFingerprint",
                )
            )
        )
        if not valid_dependency_result:
            failures.append(
                f"scannerBindings.audit-receipt-adapters[{index}].not-passed-exact-subject"
            )
            continue
        expected_scanners[adapter_id] = adapter
    actual_scanner_ids: set[str] = set()
    scanner_fields = (
        "adapterId",
        "capability",
        "status",
        "subjectValidated",
        "adapterVersion",
        "approvalSubjectDigest",
        "evidenceFingerprint",
        "returnCode",
        "outputFingerprint",
        "mutationDetected",
    )
    for index, item in enumerate(scanner_items):
        prefix = f"scannerBindings[{index}]"
        if not isinstance(item, dict) or set(item) != {"id", *scanner_fields}:
            raise ToolError("Audit Stage 6 scanner binding is malformed.")
        collect_id(item, prefix, scanner_ids)
        adapter_id = str(item.get("adapterId") or "")
        if adapter_id in actual_scanner_ids:
            failures.append(prefix + ".adapterId.duplicate")
        actual_scanner_ids.add(adapter_id)
        expected = expected_scanners.get(adapter_id)
        if expected is None:
            failures.append(prefix + ".receipt-mismatch")
        else:
            for field in scanner_fields:
                if item.get(field) != expected.get(field):
                    failures.append(prefix + "." + field)
    if not expected_scanners or actual_scanner_ids != set(expected_scanners):
        failures.append("scannerBindings.complete-passed-dependency-analysis")

    has_lockfile = any(
        item.get("kind") == "lockfile" for item in expected_inputs.values()
    )
    has_ci_workflow = any(
        item.get("kind") == "ci-workflow" for item in expected_inputs.values()
    )
    expected_coverage_statuses = {
        "dependency-inventory": "assessed",
        "lockfile-integrity": "assessed" if has_lockfile else "not-applicable",
        "ci-least-privilege": "assessed" if has_ci_workflow else "not-applicable",
        "automation-pinning": "assessed" if has_ci_workflow else "not-applicable",
        "build-trace-provenance": "assessed",
        "generated-artifact-integrity": (
            "assessed" if expected_generated_keys else "not-applicable"
        ),
        "advisory-coverage": "assessed",
    }
    for surface, expected_status in expected_coverage_statuses.items():
        if report_coverage_statuses.get(surface) != expected_status:
            failures.append(f"coverage.{surface}.status")

    report_gaps = exact_list(report, "gaps", "report", 256)
    if report_gaps:
        failures.append("report.gaps")
    if report.get("complete") is not True:
        failures.append("report.complete")
    if evidence_ids - referenced_evidence:
        failures.append("evidence.unused")

    result = {
        "schemaVersion": "jstack.audit.stage6-evaluation.v1",
        "exerciseType": expected_type,
        "drillId": drill_id,
        "baselineGitHead": baseline["gitHead"] if baseline else None,
        "baselineGitTree": baseline["gitTree"] if baseline else None,
        "candidateGitHead": candidate["gitHead"] if candidate else None,
        "candidateGitTree": candidate["gitTree"] if candidate else None,
        "inputCount": len(input_items),
        "relationshipCount": len(relationship_items),
        "evidenceCount": len(evidence_items),
        "workflowActionCount": len(action_items),
        "immutableWorkflowActionCount": sum(
            item.get("immutable") is True for item in action_items if isinstance(item, dict)
        ),
        "ciPermissionCount": len(permission_items),
        "buildNodeCount": len(node_items),
        "buildEdgeCount": len(edge_items),
        "provenanceCount": len(provenance_items),
        "generatedArtifactCount": len(generated_items),
        "scannerBindingCount": len(scanner_items),
        "matchedQaBindingCount": len(matched_qa_ids),
        "findingCount": len(finding_items),
        "resolvedFindingCount": sum(
            item.get("status") == "resolved" for item in finding_items if isinstance(item, dict)
        ),
        "implementedRemediationCount": len(implemented_ids),
        "changedPathCount": len(changed_paths or []),
        "gapCount": len(inventory_gaps) + len(report_gaps),
        "passed": not failures,
        "failureCodes": sorted(set(failures)),
    }
    return {**result, "evaluationDigest": audit_json_digest(result)}


def _verify_adversarial_receipt_for_revision(
    receipt: str,
    root: Path,
    expected: dict[str, Any],
) -> dict[str, Any]:
    """Verify a current-session Stage 7 receipt for an immutable revision."""

    try:
        encoded, supplied_signature = receipt.split(".", 1)
        expected_signature = _b64encode(
            hmac.new(_RECEIPT_SECRET, encoded.encode("ascii"), hashlib.sha256).digest()
        )
        if not hmac.compare_digest(supplied_signature, expected_signature):
            raise ValueError("signature mismatch")
        payload = json.loads(_b64decode(encoded).decode("utf-8"))
        issued = _dt.datetime.fromisoformat(str(payload["issuedAt"]))
        if issued.tzinfo is None:
            raise ValueError("timezone-aware issuedAt required")
    except Exception as exc:
        raise ToolError(
            "Adversarial receipt is malformed, stale, or was not issued by this JStack server session."
        ) from exc
    age = (_dt.datetime.now(_dt.timezone.utc) - issued).total_seconds()
    exact_fields = (
        "gitHead",
        "gitTree",
        "policyDigest",
        "commandKey",
        "commandFingerprint",
        "campaignId",
        "campaignDigest",
        "planDigest",
        "deterministicSeed",
        "inputCorpusDigest",
        "targetScopeDigest",
        "environmentDigest",
        "captureDigest",
        "caseSetDigest",
        "outcomeSetDigest",
        "caseCount",
        "testedCategoryCount",
    )
    checks = {
        "kind": payload.get("kind") == "adversarial",
        "session": payload.get("serverSession") == SERVER_SESSION_ID,
        "projectPath": payload.get("projectPath") == str(root),
        "toolVersion": payload.get("toolVersion") == SERVER_VERSION,
        "executionProfile": payload.get("executionProfile")
        == "local-scrubbed-no-os-sandbox-v1",
        "networkIsolationEnforced": payload.get("networkIsolationEnforced") is False,
        "returncode": payload.get("returncode") == 0,
        "passed": payload.get("passed") is True,
        "mutationDetected": payload.get("mutationDetected") is False,
        "fresh": 0 <= age <= RECEIPT_MAX_AGE_SECONDS,
    }
    for field in exact_fields:
        checks[field] = payload.get(field) == expected.get(field)
    return {"valid": all(checks.values()), "checks": checks, "payload": payload}


def evaluate_audit_stage7_adversarial(
    report: Any,
    project_path: Path,
    artifacts: dict[str, dict[str, Any]],
    qa_verifications: list[dict[str, Any]],
    security_verification: Optional[dict[str, Any]],
    adversarial_receipts: list[str],
    drill_id: str,
) -> dict[str, Any]:
    """Validate one exact-revision Stage 7 adversarial evidence package."""

    report_fields = {
        "schemaVersion",
        "subject",
        "exercise",
        "assessmentBoundary",
        "artifactBindings",
        "campaign",
        "captures",
        "coverage",
        "evidence",
        "hypotheses",
        "falsePositiveAssessments",
        "harness",
        "comparison",
        "qaBindings",
        "securityBinding",
        "gaps",
        "complete",
        "limitations",
    }
    if not isinstance(report, dict) or set(report) != report_fields:
        raise ToolError(
            "Audit Stage 7 verification-results.json has unsupported or missing fields."
        )
    audit_enforce_json_limit(report, "Audit Stage 7 verification results", 10_000_000)
    audit_reject_secret_values(report, "Audit Stage 7 verification results")
    source = _audit_source_subject(project_path, "Stage 7")
    root = source["_root"]
    current_policy_digest = evidence_subject(project_path)["policyDigest"]
    failures: list[str] = []

    def exact_object(field: str, keys: set[str]) -> dict[str, Any]:
        value = report.get(field)
        if not isinstance(value, dict) or set(value) != keys:
            raise ToolError(
                f"Audit Stage 7 {field} has unsupported or missing fields."
            )
        return value

    def exact_list(field: str, maximum: int = AUDIT_STAGE7_MAX_ITEMS) -> list[Any]:
        value = report.get(field)
        if not isinstance(value, list) or len(value) > maximum:
            raise ToolError(
                f"Audit Stage 7 {field} must be an array with at most {maximum} items."
            )
        return value

    def valid_id(value: Any) -> bool:
        return bool(
            isinstance(value, str)
            and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,127}", value)
        )

    def valid_digest(value: Any) -> bool:
        return bool(isinstance(value, str) and re.fullmatch(r"[0-9a-f]{64}", value))

    def valid_text(value: Any, maximum: int = 1000) -> bool:
        return bool(isinstance(value, str) and value.strip() and len(value) <= maximum)

    def collect_id(item: dict[str, Any], prefix: str, seen: set[str]) -> Optional[str]:
        identifier = item.get("id")
        if not valid_id(identifier) or identifier in seen:
            failures.append(prefix + ".id")
            return None
        seen.add(str(identifier))
        return str(identifier)

    if report.get("schemaVersion") != AUDIT_STAGE7_RESULTS_SCHEMA:
        failures.append("schemaVersion")
    expected_type = AUDIT_STAGE7_DRILL_TYPES.get(drill_id)
    if expected_type is None:
        raise ToolError(f"Unsupported Audit Stage 7 drill: {drill_id}")
    exercise = exact_object("exercise", {"drillId", "type"})
    if exercise.get("drillId") != drill_id:
        failures.append("exercise.drillId")
    if exercise.get("type") != expected_type:
        failures.append("exercise.type")

    subject = exact_object(
        "subject",
        {
            "baselineGitHead",
            "baselineGitTree",
            "candidateGitHead",
            "candidateGitTree",
        },
    )
    baseline = _audit_stage4_resolve_revision(root, subject.get("baselineGitHead"))
    candidate = _audit_stage4_resolve_revision(root, subject.get("candidateGitHead"))
    if baseline is None:
        failures.append("subject.baseline")
    if candidate is None:
        failures.append("subject.candidate")
    if baseline and subject.get("baselineGitTree") != baseline["gitTree"]:
        failures.append("subject.baselineGitTree")
    if candidate and subject.get("candidateGitTree") != candidate["gitTree"]:
        failures.append("subject.candidateGitTree")
    if candidate and (
        candidate["gitHead"] != source["gitHead"]
        or candidate["gitTree"] != source["gitTree"]
    ):
        failures.append("subject.candidate-not-current")
    changed_paths: Optional[list[str]] = None
    if baseline and candidate:
        if expected_type == "audit":
            if baseline != candidate:
                failures.append("subject.audit-baseline-candidate")
        else:
            ancestry = run_complete(
                ["git", "merge-base", "--is-ancestor", baseline["gitHead"], candidate["gitHead"]],
                root,
                timeout=8,
            )
            changed_paths = _audit_stage4_changed_paths(
                root, baseline["gitHead"], candidate["gitHead"]
            )
            if baseline["gitHead"] == candidate["gitHead"]:
                failures.append("subject.implementation-distinct-commit")
            if not ancestry["ok"]:
                failures.append("subject.baseline-not-ancestor")
            if not changed_paths:
                failures.append("subject.implementation-empty-diff")

    boundary = exact_object(
        "assessmentBoundary", set(AUDIT_STAGE7_ASSESSMENT_BOUNDARY)
    )
    for field, expected in AUDIT_STAGE7_ASSESSMENT_BOUNDARY.items():
        if type(boundary.get(field)) is not type(expected) or boundary.get(field) != expected:
            failures.append("assessmentBoundary." + field)
    if report.get("limitations") != AUDIT_STAGE7_LIMITATIONS:
        failures.append("limitations")

    bindings = exact_object(
        "artifactBindings", {"adversarialPlan", "falsePositiveAnalysis"}
    )
    for binding_name, artifact_name in (
        ("adversarialPlan", "adversarial-plan.md"),
        ("falsePositiveAnalysis", "false-positive-analysis.md"),
    ):
        binding = bindings.get(binding_name)
        if not isinstance(binding, dict) or set(binding) != {"path", "sha256"}:
            raise ToolError("Audit Stage 7 artifact binding is malformed.")
        artifact = artifacts.get(artifact_name) or {}
        if binding.get("path") != artifact.get("path"):
            failures.append(f"artifactBindings.{binding_name}.path")
        if binding.get("sha256") != artifact.get("sha256"):
            failures.append(f"artifactBindings.{binding_name}.sha256")
        validate_mastery_text_artifact(
            project_path, artifact, "Audit Stage 7 " + artifact_name
        )

    campaign_keys = {
        "id",
        "name",
        "planDigest",
        "deterministicSeed",
        "inputCorpusDigest",
        "targetScopeDigest",
        "timeoutSeconds",
        "maximumCases",
        "rerunsPerCase",
        "externalEffectPolicy",
        "isolationPolicy",
    }
    campaign = exact_object("campaign", campaign_keys)
    if not valid_id(campaign.get("id")):
        failures.append("campaign.id")
    if not valid_text(campaign.get("name")):
        failures.append("campaign.name")
    if campaign.get("planDigest") != (artifacts.get("adversarial-plan.md") or {}).get("sha256"):
        failures.append("campaign.planDigest")
    for field in ("planDigest", "inputCorpusDigest", "targetScopeDigest"):
        if not valid_digest(campaign.get(field)):
            failures.append("campaign." + field)
    seed = campaign.get("deterministicSeed")
    if (
        not isinstance(seed, int)
        or isinstance(seed, bool)
        or not 0 <= seed <= 2**63 - 1
    ):
        failures.append("campaign.deterministicSeed")
    for field, minimum, maximum in (
        ("timeoutSeconds", 1, 1800),
        ("maximumCases", audit_core.ADVERSARIAL_MIN_CASES, audit_core.ADVERSARIAL_MAX_CASES),
    ):
        value = campaign.get(field)
        if (
            not isinstance(value, int)
            or isinstance(value, bool)
            or not minimum <= value <= maximum
        ):
            failures.append("campaign." + field)
    if campaign.get("rerunsPerCase") != audit_core.ADVERSARIAL_RERUNS_PER_CASE:
        failures.append("campaign.rerunsPerCase")
    if campaign.get("externalEffectPolicy") != "none-observed-required-not-enforced":
        failures.append("campaign.externalEffectPolicy")
    if campaign.get("isolationPolicy") != "local-scrubbed-requires-external-isolation-for-untrusted-targets":
        failures.append("campaign.isolationPolicy")
    campaign_digest = audit_core.adversarial_canonical_sha256(campaign)

    if not isinstance(adversarial_receipts, list) or not all(
        isinstance(item, str) for item in adversarial_receipts
    ):
        raise ToolError(
            "adversarial_receipts must be an array of JStack adversarial receipts."
        )
    if len(adversarial_receipts) > ADVERSARIAL_MAX_RECEIPTS:
        raise ToolError("adversarial_receipts exceeds the bounded Stage 7 limit.")
    if any(len(item) > ADVERSARIAL_MAX_RECEIPT_CHARS for item in adversarial_receipts):
        raise ToolError("adversarial_receipts contains an oversized receipt.")
    receipts_by_digest: dict[str, str] = {}
    for receipt in adversarial_receipts:
        digest = hashlib.sha256(receipt.encode("utf-8")).hexdigest()
        if digest in receipts_by_digest:
            failures.append("adversarialReceipts.duplicate")
        receipts_by_digest[digest] = receipt

    capture_items = exact_list("captures", 2)
    expected_capture_count = 1 if expected_type == "audit" else 2
    if len(capture_items) != expected_capture_count:
        failures.append("captures.count")
    capture_fields = {
        "id",
        "revision",
        "receiptDigest",
        "environmentDigest",
        "commandKey",
        "commandFingerprint",
        "captureDigest",
        "capture",
        "summary",
    }
    capture_by_revision: dict[str, dict[str, Any]] = {}
    normalized_by_revision: dict[str, dict[str, Any]] = {}
    matched_receipts: set[str] = set()
    environment_digests: set[str] = set()
    command_fingerprints: set[str] = set()
    for index, item in enumerate(capture_items):
        prefix = f"captures[{index}]"
        if not isinstance(item, dict) or set(item) != capture_fields:
            raise ToolError(f"Audit Stage 7 {prefix} is malformed.")
        if not valid_id(item.get("id")):
            failures.append(prefix + ".id")
        revision_kind = item.get("revision")
        if revision_kind not in {"baseline", "candidate"} or revision_kind in capture_by_revision:
            failures.append(prefix + ".revision")
            continue
        capture_by_revision[str(revision_kind)] = item
        expected_revision = baseline if revision_kind == "baseline" else candidate
        try:
            capture = audit_core.normalize_adversarial_capture(item.get("capture"))
        except audit_core.AdversarialProtocolError as exc:
            raise ToolError(f"Audit Stage 7 {prefix}.capture is invalid: {exc}") from exc
        normalized_by_revision[str(revision_kind)] = capture
        capture_digest = audit_core.adversarial_canonical_sha256(capture)
        summary = audit_core.summarize_adversarial_capture(capture)
        if item.get("captureDigest") != capture_digest:
            failures.append(prefix + ".captureDigest")
        if item.get("summary") != summary:
            failures.append(prefix + ".summary")
        if capture.get("campaignId") != campaign.get("id"):
            failures.append(prefix + ".campaignId")
        if capture.get("campaignDigest") != campaign_digest:
            failures.append(prefix + ".campaignDigest")
        for capture_field, campaign_field in (
            ("planDigest", "planDigest"),
            ("deterministicSeed", "deterministicSeed"),
            ("inputCorpusDigest", "inputCorpusDigest"),
            ("targetScopeDigest", "targetScopeDigest"),
        ):
            if capture.get(capture_field) != campaign.get(campaign_field):
                failures.append(prefix + "." + capture_field)
        maximum_cases = campaign.get("maximumCases")
        if isinstance(maximum_cases, int) and len(capture["cases"]) > maximum_cases:
            failures.append(prefix + ".caseCount")
        environment_digest = item.get("environmentDigest")
        command_key = item.get("commandKey")
        command_fingerprint = item.get("commandFingerprint")
        receipt_digest = item.get("receiptDigest")
        if valid_digest(environment_digest):
            environment_digests.add(str(environment_digest))
        else:
            failures.append(prefix + ".environmentDigest")
        if not valid_id(command_key):
            failures.append(prefix + ".commandKey")
        if valid_digest(command_fingerprint):
            command_fingerprints.add(str(command_fingerprint))
        else:
            failures.append(prefix + ".commandFingerprint")
        if not valid_digest(receipt_digest):
            failures.append(prefix + ".receiptDigest")
        receipt = receipts_by_digest.get(str(receipt_digest))
        if receipt is None or expected_revision is None:
            failures.append(prefix + ".receipt.missing")
        else:
            verification = _verify_adversarial_receipt_for_revision(
                receipt,
                root,
                {
                    "gitHead": expected_revision["gitHead"],
                    "gitTree": expected_revision["gitTree"],
                    "policyDigest": current_policy_digest,
                    "commandKey": command_key,
                    "commandFingerprint": command_fingerprint,
                    "campaignId": campaign.get("id"),
                    "campaignDigest": campaign_digest,
                    "planDigest": campaign.get("planDigest"),
                    "deterministicSeed": campaign.get("deterministicSeed"),
                    "inputCorpusDigest": campaign.get("inputCorpusDigest"),
                    "targetScopeDigest": campaign.get("targetScopeDigest"),
                    "environmentDigest": environment_digest,
                    "captureDigest": capture_digest,
                    "caseSetDigest": summary["caseSetDigest"],
                    "outcomeSetDigest": summary["outcomeSetDigest"],
                    "caseCount": summary["caseCount"],
                    "testedCategoryCount": summary["testedCategoryCount"],
                },
            )
            if verification["valid"]:
                matched_receipts.add(str(receipt_digest))
            else:
                failures.append(prefix + ".receipt.invalid")
    expected_revisions = {"candidate"} if expected_type == "audit" else {"baseline", "candidate"}
    if expected_type == "audit" and "baseline" in capture_by_revision and "candidate" not in capture_by_revision:
        # A single current capture may be labelled baseline for parity with earlier stages.
        capture_by_revision["candidate"] = capture_by_revision.pop("baseline")
        normalized_by_revision["candidate"] = normalized_by_revision.pop("baseline")
    if set(capture_by_revision) != expected_revisions:
        failures.append("captures.revisions")
    if len(environment_digests) > 1:
        failures.append("captures.environment-mismatch")
    if len(command_fingerprints) > 1:
        failures.append("captures.command-mismatch")
    if set(receipts_by_digest) != matched_receipts:
        failures.append("adversarialReceipts.unused-or-unverified")

    candidate_capture = normalized_by_revision.get("candidate")
    baseline_capture = normalized_by_revision.get("baseline")
    candidate_cases = {
        case["id"]: case for case in (candidate_capture or {}).get("cases", [])
    }
    baseline_cases = {
        case["id"]: case for case in (baseline_capture or {}).get("cases", [])
    }
    if not candidate_cases:
        failures.append("captures.candidate-required")

    evidence_items = exact_list("evidence")
    if not evidence_items:
        failures.append("evidence.empty")
    evidence_ids: set[str] = set()
    evidence_revision: dict[str, str] = {}
    total_evidence_bytes = 0
    for index, item in enumerate(evidence_items):
        prefix = f"evidence[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "revision",
            "path",
            "lineStart",
            "lineEnd",
            "sha256",
        }:
            raise ToolError("Audit Stage 7 evidence entry is malformed.")
        evidence_id = collect_id(item, prefix, evidence_ids)
        revision_kind = item.get("revision")
        revision = (
            baseline["gitHead"]
            if revision_kind == "baseline" and baseline
            else candidate["gitHead"]
            if revision_kind == "candidate" and candidate
            else ""
        )
        if not revision:
            failures.append(prefix + ".revision")
        if evidence_id and isinstance(revision_kind, str):
            evidence_revision[evidence_id] = revision_kind
        path = item.get("path")
        if not _audit_stage1_safe_relative_path(path):
            failures.append(prefix + ".path")
            continue
        assert isinstance(path, str)
        start = item.get("lineStart")
        end = item.get("lineEnd")
        if (
            not isinstance(start, int)
            or isinstance(start, bool)
            or not isinstance(end, int)
            or isinstance(end, bool)
            or start < 1
            or end < start
        ):
            failures.append(prefix + ".lines")
        content = (
            _audit_stage4_revision_file(
                root,
                revision,
                path,
                max_bytes=AUDIT_STAGE7_MAX_EVIDENCE_FILE_BYTES,
            )
            if revision
            else None
        )
        if content is None:
            failures.append(prefix + ".path.untracked-or-nonregular")
            continue
        total_evidence_bytes += len(content)
        if total_evidence_bytes > AUDIT_STAGE7_MAX_EVIDENCE_TOTAL_BYTES:
            raise ToolError("Audit Stage 7 evidence exceeds the bounded total read limit.")
        if item.get("sha256") != hashlib.sha256(content).hexdigest():
            failures.append(prefix + ".sha256")
        if isinstance(end, int) and not isinstance(end, bool) and end > len(content.splitlines()):
            failures.append(prefix + ".lines")

    referenced_evidence: set[str] = set()

    def evidence_refs(value: Any, prefix: str, *, allow_empty: bool = False) -> list[str]:
        if (
            not isinstance(value, list)
            or len(value) > AUDIT_STAGE7_MAX_ITEMS
            or not all(valid_id(item) for item in value)
            or len(set(value)) != len(value)
            or (not allow_empty and not value)
        ):
            failures.append(prefix)
            return []
        for identifier in value:
            if identifier not in evidence_ids:
                failures.append(prefix + ".unknown")
            else:
                referenced_evidence.add(str(identifier))
        return [str(item) for item in value]

    coverage_items = exact_list("coverage", len(audit_core.ADVERSARIAL_CATEGORIES))
    coverage_status: dict[str, str] = {}
    covered_case_ids: set[str] = set()
    for index, item in enumerate(coverage_items):
        prefix = f"coverage[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "status",
            "reason",
            "caseIds",
            "evidence",
        }:
            raise ToolError("Audit Stage 7 coverage entry is malformed.")
        category = item.get("id")
        status = item.get("status")
        if category not in audit_core.ADVERSARIAL_CATEGORIES or category in coverage_status:
            failures.append(prefix + ".id")
            continue
        coverage_status[str(category)] = str(status)
        if status not in AUDIT_STAGE7_COVERAGE_STATUSES:
            failures.append(prefix + ".status")
        if not valid_text(item.get("reason")):
            failures.append(prefix + ".reason")
        case_ids = item.get("caseIds")
        if (
            not isinstance(case_ids, list)
            or len(case_ids) > AUDIT_STAGE7_MAX_ITEMS
            or not all(valid_id(case_id) for case_id in case_ids)
            or len(set(case_ids)) != len(case_ids)
        ):
            failures.append(prefix + ".caseIds")
            case_ids = []
        expected_case_ids = {
            case_id
            for case_id, case in candidate_cases.items()
            if case.get("category") == category
        }
        if status == "tested":
            if set(case_ids) != expected_case_ids or not expected_case_ids:
                failures.append(prefix + ".caseIds")
        elif case_ids:
            failures.append(prefix + ".caseIds.unexpected")
        if status == "not-applicable" and expected_case_ids:
            failures.append(prefix + ".not-applicable-with-cases")
        covered_case_ids.update(case_id for case_id in case_ids if case_id in candidate_cases)
        evidence_refs(item.get("evidence"), prefix + ".evidence")
    if set(coverage_status) != set(audit_core.ADVERSARIAL_CATEGORIES):
        failures.append("coverage.categories")
    if any(status == "unsupported" for status in coverage_status.values()):
        failures.append("coverage.unsupported")
    if covered_case_ids != set(candidate_cases):
        failures.append("coverage.cases")

    hypothesis_items = exact_list("hypotheses")
    if len(hypothesis_items) < 2:
        failures.append("hypotheses.count")
    hypothesis_ids: set[str] = set()
    hypothesis_dispositions: dict[str, str] = {}
    hypothesis_cases: dict[str, set[str]] = {}
    origins: set[str] = set()
    candidate_case_owners: set[str] = set()
    for index, item in enumerate(hypothesis_items):
        prefix = f"hypotheses[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "origin",
            "findingFingerprint",
            "severity",
            "disposition",
            "caseIds",
            "evidence",
        }:
            raise ToolError("Audit Stage 7 hypothesis entry is malformed.")
        hypothesis_id = collect_id(item, prefix, hypothesis_ids)
        origin = item.get("origin")
        if origin not in {"static-finding", "dynamic-observation"}:
            failures.append(prefix + ".origin")
        else:
            origins.add(str(origin))
        if not valid_digest(item.get("findingFingerprint")):
            failures.append(prefix + ".findingFingerprint")
        if item.get("severity") not in AUDIT_STAGE7_SEVERITIES:
            failures.append(prefix + ".severity")
        disposition = item.get("disposition")
        if disposition not in audit_core.ADVERSARIAL_STATUSES:
            failures.append(prefix + ".disposition")
        case_ids = item.get("caseIds")
        if (
            not isinstance(case_ids, list)
            or not case_ids
            or len(case_ids) > AUDIT_STAGE7_MAX_ITEMS
            or not all(valid_id(case_id) for case_id in case_ids)
            or len(set(case_ids)) != len(case_ids)
        ):
            failures.append(prefix + ".caseIds")
            case_ids = []
        actual = {
            case_id
            for case_id, case in candidate_cases.items()
            if case.get("hypothesisId") == hypothesis_id
        }
        if set(case_ids) != actual:
            failures.append(prefix + ".caseIds")
        statuses = {
            candidate_cases[case_id]["runs"][0]["status"]
            for case_id in case_ids
            if case_id in candidate_cases
        }
        if len(statuses) != 1 or disposition not in statuses:
            failures.append(prefix + ".disposition")
        candidate_case_owners.update(case_ids)
        if hypothesis_id:
            hypothesis_dispositions[hypothesis_id] = str(disposition)
            hypothesis_cases[hypothesis_id] = set(case_ids)
        evidence_refs(item.get("evidence"), prefix + ".evidence")
    if candidate_case_owners != set(candidate_cases):
        failures.append("hypotheses.case-coverage")
    if not {"static-finding", "dynamic-observation"}.issubset(origins):
        failures.append("hypotheses.origins")
    dispositions = set(hypothesis_dispositions.values())
    if not {"confirmed", "refuted"}.issubset(dispositions):
        failures.append("hypotheses.dispositions")
    dynamic_confirmed = sum(
        item.get("origin") == "dynamic-observation" and item.get("disposition") == "confirmed"
        for item in hypothesis_items
        if isinstance(item, dict)
    )
    if dynamic_confirmed < 1:
        failures.append("hypotheses.dynamic-confirmed")

    assessment_items = exact_list("falsePositiveAssessments")
    assessment_ids: set[str] = set()
    assessed_hypotheses: set[str] = set()
    for index, item in enumerate(assessment_items):
        prefix = f"falsePositiveAssessments[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "hypothesisId",
            "classification",
            "caseIds",
            "evidence",
        }:
            raise ToolError("Audit Stage 7 false-positive assessment is malformed.")
        collect_id(item, prefix, assessment_ids)
        hypothesis_id = str(item.get("hypothesisId") or "")
        if hypothesis_id not in hypothesis_ids or hypothesis_id in assessed_hypotheses:
            failures.append(prefix + ".hypothesisId")
        else:
            assessed_hypotheses.add(hypothesis_id)
        expected_classification = (
            "supported"
            if hypothesis_dispositions.get(hypothesis_id) == "confirmed"
            else "false-positive"
        )
        if item.get("classification") != expected_classification:
            failures.append(prefix + ".classification")
        case_ids = item.get("caseIds")
        if not isinstance(case_ids, list) or set(case_ids) != hypothesis_cases.get(hypothesis_id, set()):
            failures.append(prefix + ".caseIds")
        evidence_refs(item.get("evidence"), prefix + ".evidence")
    if assessed_hypotheses != hypothesis_ids or len(assessment_items) != len(hypothesis_items):
        failures.append("falsePositiveAssessments.reciprocity")

    harness = exact_object("harness", {"status", "changedPaths", "evidence"})
    harness_paths = harness.get("changedPaths")
    if (
        not isinstance(harness_paths, list)
        or len(harness_paths) > AUDIT_STAGE7_MAX_ITEMS
        or not all(_audit_stage1_safe_relative_path(path) for path in harness_paths)
        or len(set(harness_paths)) != len(harness_paths)
    ):
        failures.append("harness.changedPaths")
        harness_paths = []
    harness_evidence = evidence_refs(harness.get("evidence"), "harness.evidence")
    if expected_type == "audit":
        if harness.get("status") != "existing-observed" or harness_paths:
            failures.append("harness.audit-semantics")
    else:
        if harness.get("status") != "implemented-verified":
            failures.append("harness.implementation-status")
        if sorted(harness_paths) != sorted(changed_paths or []):
            failures.append("harness.changedPaths.diff")
        if not any(evidence_revision.get(item) == "candidate" for item in harness_evidence):
            failures.append("harness.candidate-evidence")

    comparison = exact_object(
        "comparison",
        {
            "policy",
            "sharedCaseIds",
            "addedCaseIds",
            "removedCaseIds",
            "sharedOutcomesStable",
        },
    )
    if expected_type == "audit":
        expected_comparison = {
            "policy": "single-current-capture",
            "sharedCaseIds": [],
            "addedCaseIds": [],
            "removedCaseIds": [],
            "sharedOutcomesStable": True,
        }
        if comparison != expected_comparison:
            failures.append("comparison.audit")
        shared_case_ids: set[str] = set()
        added_case_ids: set[str] = set()
        removed_case_ids: set[str] = set()
        shared_outcomes_stable = True
    else:
        shared_case_ids = set(baseline_cases) & set(candidate_cases)
        added_case_ids = set(candidate_cases) - set(baseline_cases)
        removed_case_ids = set(baseline_cases) - set(candidate_cases)
        shared_outcomes_stable = all(
            audit_core.adversarial_case_contract(baseline_cases[case_id])
            == audit_core.adversarial_case_contract(candidate_cases[case_id])
            and audit_core.adversarial_case_outcome(baseline_cases[case_id])
            == audit_core.adversarial_case_outcome(candidate_cases[case_id])
            for case_id in shared_case_ids
        )
        expected_comparison = {
            "policy": "baseline-subset-candidate-superset",
            "sharedCaseIds": sorted(shared_case_ids),
            "addedCaseIds": sorted(added_case_ids),
            "removedCaseIds": sorted(removed_case_ids),
            "sharedOutcomesStable": shared_outcomes_stable,
        }
        if comparison != expected_comparison:
            failures.append("comparison.implementation")
        if not shared_case_ids:
            failures.append("comparison.shared-required")
        if not added_case_ids:
            failures.append("comparison.added-required")
        if removed_case_ids:
            failures.append("comparison.removed")
        if not shared_outcomes_stable:
            failures.append("comparison.shared-outcomes")

    qa_items = exact_list("qaBindings", 64)
    qa_ids: set[str] = set()
    matched_qa_keys: set[str] = set()
    expected_qa_keys = {item["key"] for item in discover_test_commands(project_path)}
    for index, item in enumerate(qa_items):
        prefix = f"qaBindings[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "commandKey",
            "commandFingerprint",
            "executionProfile",
            "returncode",
        }:
            raise ToolError("Audit Stage 7 QA binding is malformed.")
        collect_id(item, prefix, qa_ids)
        matches = [
            verification
            for verification in qa_verifications
            if verification.get("valid")
            and item.get("commandKey") == (verification.get("payload") or {}).get("commandKey")
            and item.get("commandFingerprint")
            == (verification.get("payload") or {}).get("commandFingerprint")
            and item.get("executionProfile")
            == (verification.get("payload") or {}).get("executionProfile")
            and item.get("returncode") == (verification.get("payload") or {}).get("returncode")
        ]
        if len(matches) != 1:
            failures.append(prefix + ".unverified")
        else:
            matched_qa_keys.add(str(item.get("commandKey")))
    if matched_qa_keys != expected_qa_keys:
        failures.append("qaBindings.complete")

    security = exact_object(
        "securityBinding", {"complete", "passed", "findingCount"}
    )
    security_payload = (
        security_verification.get("payload", {}) if security_verification else {}
    )
    if not security_verification or not security_verification.get("valid"):
        failures.append("securityBinding.receipt")
    for field in ("complete", "passed", "findingCount"):
        if security.get(field) != security_payload.get(field):
            failures.append("securityBinding." + field)
    if security.get("complete") is not True or security.get("passed") is not True:
        failures.append("securityBinding.not-passing")

    gap_items = exact_list("gaps")
    for index, item in enumerate(gap_items):
        prefix = f"gaps[{index}]"
        if not isinstance(item, dict) or set(item) != {
            "id",
            "category",
            "description",
            "evidence",
        }:
            raise ToolError("Audit Stage 7 gap entry is malformed.")
        if not valid_id(item.get("id")):
            failures.append(prefix + ".id")
        if item.get("category") not in audit_core.ADVERSARIAL_CATEGORIES:
            failures.append(prefix + ".category")
        if not valid_text(item.get("description")):
            failures.append(prefix + ".description")
        evidence_refs(item.get("evidence"), prefix + ".evidence", allow_empty=True)
    if gap_items:
        failures.append("gaps.present")
    if report.get("complete") is not True:
        failures.append("complete")
    if evidence_ids - referenced_evidence:
        failures.append("evidence.unused")

    result = {
        "schemaVersion": "jstack.audit.stage7-evaluation.v1",
        "exerciseType": expected_type,
        "drillId": drill_id,
        "baselineGitHead": baseline["gitHead"] if baseline else None,
        "baselineGitTree": baseline["gitTree"] if baseline else None,
        "candidateGitHead": candidate["gitHead"] if candidate else None,
        "candidateGitTree": candidate["gitTree"] if candidate else None,
        "campaignDigest": campaign_digest,
        "captureCount": len(capture_items),
        "matchedAdversarialReceiptCount": len(matched_receipts),
        "candidateCaseCount": len(candidate_cases),
        "baselineCaseCount": len(baseline_cases),
        "testedCategoryCount": sum(
            status == "tested" for status in coverage_status.values()
        ),
        "notApplicableCategoryCount": sum(
            status == "not-applicable" for status in coverage_status.values()
        ),
        "unsupportedCategoryCount": sum(
            status == "unsupported" for status in coverage_status.values()
        ),
        "hypothesisCount": len(hypothesis_ids),
        "confirmedHypothesisCount": sum(
            value == "confirmed" for value in hypothesis_dispositions.values()
        ),
        "refutedHypothesisCount": sum(
            value == "refuted" for value in hypothesis_dispositions.values()
        ),
        "dynamicConfirmedHypothesisCount": dynamic_confirmed,
        "falsePositiveAssessmentCount": len(assessment_items),
        "sharedCaseCount": len(shared_case_ids),
        "addedCaseCount": len(added_case_ids),
        "removedCaseCount": len(removed_case_ids),
        "sharedOutcomesStable": shared_outcomes_stable,
        "evidenceCount": len(evidence_ids),
        "qaBindingCount": len(qa_ids),
        "matchedQaBindingCount": len(matched_qa_keys),
        "changedPathCount": len(changed_paths or []),
        "gapCount": len(gap_items),
        "passed": not failures,
        "failureCodes": sorted(set(failures)),
    }
    return {**result, "evaluationDigest": audit_json_digest(result)}


def _audit_stage8_timestamp(value: Any, label: str) -> _dt.datetime:
    if not isinstance(value, str) or not value.strip():
        raise ToolError(f"Audit Stage 8 {label} must be an ISO-8601 date or timestamp.")
    raw = value.strip()
    try:
        if len(raw) == 10:
            parsed = _dt.datetime.combine(
                _dt.date.fromisoformat(raw), _dt.time(), tzinfo=_dt.timezone.utc
            )
        else:
            parsed = _dt.datetime.fromisoformat(raw.replace("Z", "+00:00"))
            if parsed.tzinfo is None:
                raise ValueError("timezone required")
            parsed = parsed.astimezone(_dt.timezone.utc)
    except ValueError as exc:
        raise ToolError(
            f"Audit Stage 8 {label} must include an unambiguous date or timezone."
        ) from exc
    return parsed.replace(microsecond=0)


def _audit_stage8_plain_text(value: Any, label: str, *, minimum: int = 1) -> str:
    if (
        not isinstance(value, str)
        or len(value.strip()) < minimum
        or len(value) > 2000
        or "\n" in value
        or "\r" in value
        or any(ord(character) < 32 and character != "\t" for character in value)
    ):
        raise ToolError(f"Audit Stage 8 {label} must be bounded single-line text.")
    return value.strip()


def _audit_stage8_markdown_text(value: Any) -> str:
    """Render one already-redacted value without allowing Markdown structure injection."""

    return " ".join(str(value or "").replace("`", "'").split())


def _audit_stage8_result_semantics(
    raw: Any, label: str
) -> tuple[dict[str, Any], dict[str, Any], list[str]]:
    """Validate one finalized release-audit result without re-running the audit."""

    result_fields = {
        "schemaVersion",
        "profile",
        "status",
        "passed",
        "evaluatedAt",
        "failOn",
        "coverage",
        "findings",
        "findingCounts",
        "blockingFindingIds",
        "suppressionDecisions",
        "errors",
    }
    if not isinstance(raw, dict) or set(raw) != result_fields:
        raise ToolError(f"Audit Stage 8 {label} has unsupported or missing fields.")
    audit_enforce_json_limit(raw, f"Audit Stage 8 {label}", 10_000_000)
    audit_reject_secret_values(raw, f"Audit Stage 8 {label}")
    failures: list[str] = []
    if raw.get("schemaVersion") != audit_core.RESULT_SCHEMA_VERSION:
        failures.append(label + ".schemaVersion")
    if raw.get("profile") != "release":
        failures.append(label + ".profile")
    if raw.get("failOn") not in AUDIT_STAGE8_SEVERITY_RANK:
        failures.append(label + ".failOn")
    try:
        evaluated_at = _audit_stage8_timestamp(raw.get("evaluatedAt"), label + ".evaluatedAt")
    except ToolError:
        failures.append(label + ".evaluatedAt")
        evaluated_at = _dt.datetime.min.replace(tzinfo=_dt.timezone.utc)

    coverage = raw.get("coverage")
    if not isinstance(coverage, dict):
        raise ToolError(f"Audit Stage 8 {label}.coverage must be an object.")
    if coverage.get("schemaVersion") != audit_core.COVERAGE_SCHEMA_VERSION:
        failures.append(label + ".coverage.schemaVersion")
    if coverage.get("profile") != "release":
        failures.append(label + ".coverage.profile")
    if coverage.get("complete") is not True:
        failures.append(label + ".coverage.incomplete")
    if coverage.get("gaps") != []:
        failures.append(label + ".coverage.gaps")

    findings = raw.get("findings")
    if not isinstance(findings, list) or len(findings) > AUDIT_STAGE8_MAX_ITEMS:
        raise ToolError(
            f"Audit Stage 8 {label}.findings must contain at most {AUDIT_STAGE8_MAX_ITEMS} entries."
        )
    finding_by_id: dict[str, dict[str, Any]] = {}
    finding_by_fingerprint: dict[str, dict[str, Any]] = {}
    for index, finding in enumerate(findings):
        try:
            normalized = audit_core.validate_normalized_finding(finding)
        except audit_core.AuditError as exc:
            raise ToolError(
                f"Audit Stage 8 {label}.findings[{index}] is not a core-generated finding: {exc}"
            ) from exc
        finding_id = str(normalized.get("findingId") or "")
        fingerprint = str(normalized.get("fingerprint") or "")
        if finding_id in finding_by_id or fingerprint in finding_by_fingerprint:
            failures.append(label + ".findings.duplicate")
        finding_by_id[finding_id] = normalized
        finding_by_fingerprint[fingerprint] = normalized
        status = normalized.get("status")
        suppression = normalized.get("suppression")
        if status == "suppressed":
            if not isinstance(suppression, dict) or suppression.get("state") != "accepted":
                failures.append(label + f".findings[{index}].suppression")
            else:
                assessment = audit_core.assess_suppression(
                    {key: value for key, value in suppression.items() if key != "state"},
                    normalized,
                    raw.get("evaluatedAt"),
                )
                if assessment.get("accepted") is not True:
                    failures.append(label + f".findings[{index}].suppression")
            if normalized.get("blocking") is not False:
                failures.append(label + f".findings[{index}].blocking")
        elif status == "open":
            if suppression != {"state": "none"}:
                failures.append(label + f".findings[{index}].suppression")
        else:
            failures.append(label + f".findings[{index}].status")

    expected_order = sorted(
        findings,
        key=lambda item: (
            -AUDIT_STAGE8_SEVERITY_RANK.get(str(item.get("severity")), -1),
            AUDIT_STAGE8_PRIORITY_RANK.get(str(item.get("priority")), 99),
            str((item.get("location") or {}).get("path") or ""),
            int((item.get("location") or {}).get("startLine") or 0),
            str(item.get("findingId") or ""),
        ),
    )
    if findings != expected_order:
        failures.append(label + ".findings.order")

    threshold_rank = AUDIT_STAGE8_SEVERITY_RANK.get(str(raw.get("failOn")), 99)
    blockers = [
        item
        for item in findings
        if item.get("status") == "open"
        and item.get("blocking") is True
        and item.get("verificationState") != "unverified-hypothesis"
        and AUDIT_STAGE8_SEVERITY_RANK.get(str(item.get("severity")), -1)
        >= threshold_rank
    ]
    blocking_ids = [str(item["findingId"]) for item in blockers]
    by_severity = {
        severity: sum(item.get("severity") == severity for item in findings)
        for severity in ("critical", "high", "medium", "low", "info")
    }
    expected_counts = {
        "total": len(findings),
        "blocking": len(blockers),
        "suppressed": sum(item.get("status") == "suppressed" for item in findings),
        "bySeverity": by_severity,
    }
    if raw.get("findingCounts") != expected_counts:
        failures.append(label + ".findingCounts")
    if raw.get("blockingFindingIds") != blocking_ids:
        failures.append(label + ".blockingFindingIds")
    errors = raw.get("errors")
    if not isinstance(errors, list) or errors:
        failures.append(label + ".errors")
    expected_status = "fail" if blockers else "pass"
    if raw.get("status") != expected_status:
        failures.append(label + ".status")
    if raw.get("passed") is not (expected_status == "pass"):
        failures.append(label + ".passed")

    expected_decisions = sorted(
        [
            {
                "fingerprint": item["fingerprint"],
                "findingId": item["findingId"],
                "status": "applied",
                "reason": "accepted",
            }
            for item in findings
            if item.get("status") == "suppressed"
        ],
        key=lambda item: (
            item["fingerprint"],
            item["findingId"],
            item["status"],
            item["reason"],
        ),
    )
    if raw.get("suppressionDecisions") != expected_decisions:
        failures.append(label + ".suppressionDecisions")
    return (
        raw,
        {
            "evaluatedAt": evaluated_at,
            "findingById": finding_by_id,
            "findingByFingerprint": finding_by_fingerprint,
            "blockingFindingIds": blocking_ids,
            "findingCounts": expected_counts,
        },
        failures,
    )


def _audit_stage8_revision_json(
    root: Path, revision: str, path: str
) -> tuple[dict[str, Any], str]:
    content = _audit_stage4_revision_file(
        root, revision, path, max_bytes=10_000_000
    )
    if content is None:
        raise ToolError(
            "Audit Stage 8 controls baseline does not contain the declared audit-result artifact."
        )

    def reject_duplicates(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        value: dict[str, Any] = {}
        for key, item in pairs:
            if key in value:
                raise ToolError(
                    "Audit Stage 8 controls baseline audit result contains a duplicate JSON key."
                )
            value[key] = item
        return value

    try:
        parsed = json.loads(content.decode("utf-8"), object_pairs_hook=reject_duplicates)
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ToolError(
            "Audit Stage 8 controls baseline audit result must be valid UTF-8 JSON."
        ) from exc
    if not isinstance(parsed, dict):
        raise ToolError("Audit Stage 8 controls baseline audit result must be an object.")
    # Bind baseline meaning to a stable canonical JSON digest. Git still pins
    # the exact immutable blob through the declared revision, while canonical
    # hashing prevents checkout newline conversion (for example CRLF on
    # Windows) from changing the prior-validation identity.
    return parsed, audit_json_digest(parsed)


def _audit_stage8_expected_decision(
    result: dict[str, Any], summary: dict[str, Any]
) -> dict[str, Any]:
    passed = result.get("status") == "pass"
    return {
        "decision": "go" if passed else "no-go",
        "reasonCodes": [
            "complete-release-audit-pass" if passed else "open-release-blockers"
        ],
        "openBlockingFindingIds": list(summary["blockingFindingIds"]),
        "coverageComplete": result.get("coverage", {}).get("complete") is True,
        "auditStatus": result.get("status"),
    }


def render_audit_stage8_report(
    risk_register: dict[str, Any], audit_result: dict[str, Any]
) -> str:
    """Render the one canonical Stage 8 engineering/executive Markdown report."""

    subject = risk_register["subject"]
    decision = risk_register["releaseDecision"]
    control = risk_register["controlChange"]
    finding_by_fingerprint = {
        str(item.get("fingerprint") or ""): item
        for item in audit_result.get("findings", [])
        if isinstance(item, dict)
    }
    counts = audit_result.get("findingCounts") or {}
    lines = [
        "# JStack Enterprise Audit Lead Report",
        "",
        "## Executive Decision",
        "",
        f"- Decision: `{decision['decision']}`",
        f"- Audit status: `{decision['auditStatus']}`",
        f"- Coverage complete: `{str(decision['coverageComplete']).lower()}`",
        f"- Candidate commit: `{subject['candidateGitHead']}`",
        f"- Current findings: `{counts.get('total', 0)}`",
        f"- Open release blockers: `{counts.get('blocking', 0)}`",
        f"- Accepted-risk findings: `{counts.get('suppressed', 0)}`",
        "- Reason codes: " + ", ".join(
            f"`{item}`" for item in decision["reasonCodes"]
        ),
        "",
        "## Prioritized Risk Register",
        "",
    ]
    entries = risk_register["entries"]
    if not entries:
        lines.append("No findings remain in the current complete release audit.")
    for entry in entries:
        finding = finding_by_fingerprint.get(str(entry.get("fingerprint") or ""), {})
        location = finding.get("location") or {}
        location_text = (
            f"{location.get('path', 'unknown')}:"
            f"{location.get('startLine', 'unknown')}-"
            f"{location.get('endLine', 'unknown')}"
        )
        remediation = finding.get("remediation") or {}
        lines.extend(
            [
                (
                    f"### {entry['priority']} · {entry['findingId']} · "
                    f"{_audit_stage8_markdown_text(finding.get('title') or 'Untitled finding')}"
                ),
                "",
                f"- Domain: `{_audit_stage8_markdown_text(finding.get('domain') or 'unknown')}`",
                f"- Severity: `{entry['severity']}`",
                f"- Confidence: `{_audit_stage8_markdown_text(finding.get('confidence') or 'unknown')}`",
                f"- Verification state: `{entry['verificationState']}`",
                f"- Audit status: `{entry['auditStatus']}`",
                f"- Source: {_audit_stage8_markdown_text(location_text)}",
                f"- Claim: {_audit_stage8_markdown_text(finding.get('claim'))}",
                f"- Impact: {_audit_stage8_markdown_text(finding.get('impact'))}",
                f"- Disposition: `{entry['disposition']}`",
                f"- Owner: {_audit_stage8_markdown_text(entry['owner'])}",
                f"- Reason: {_audit_stage8_markdown_text(entry['reason'])}",
                f"- Target date: {_audit_stage8_markdown_text(entry['targetDate'] or 'not-applicable')}",
                f"- Accepted-risk approval: {_audit_stage8_markdown_text(entry['approvalReference'] or 'not-applicable')}",
                f"- Accepted-risk expiry: {_audit_stage8_markdown_text(entry['expiresAt'] or 'not-applicable')}",
                f"- Compensating control: {_audit_stage8_markdown_text(entry['compensatingControl'] or 'not-applicable')}",
                f"- Recommended change: {_audit_stage8_markdown_text(remediation.get('recommendedChange'))}",
                f"- Residual risk: {_audit_stage8_markdown_text(entry['residualRisk'])}",
                f"- Verification: {_audit_stage8_markdown_text(entry['verificationPlan'])}",
                "",
            ]
        )
    lines.extend(
        [
            "## Control And Remediation Comparison",
            "",
            f"- Status: `{control['status']}`",
            f"- Changed paths: `{len(control['changedPaths'])}`",
            f"- Shared stable fingerprints: `{len(control['sharedFingerprints'])}`",
            f"- Verified remediated fingerprints: `{len(control['remediatedFingerprints'])}`",
            f"- Introduced fingerprints: `{len(control['introducedFingerprints'])}`",
            f"- Regressions absent: `{str(control['regressionsAbsent']).lower()}`",
            "",
            "## Residual Boundary",
            "",
        ]
    )
    lines.extend(f"- {item}" for item in risk_register["limitations"])
    return "\n".join(lines).rstrip() + "\n"


def evaluate_audit_stage8_enterprise_lead(
    risk_register: Any,
    audit_result: Any,
    sarif: Any,
    project_path: Path,
    artifacts: dict[str, dict[str, Any]],
    qa_verifications: list[dict[str, Any]],
    security_verification: Optional[dict[str, Any]],
    audit_verification: Optional[dict[str, Any]],
    drill_id: str,
    prior_attempts: list[dict[str, Any]],
) -> dict[str, Any]:
    """Reconcile one exact-revision Stage 8 enterprise audit-lead package."""

    expected_type = AUDIT_STAGE8_DRILL_TYPES.get(drill_id)
    if expected_type is None:
        raise ToolError(f"Unsupported Audit Stage 8 drill: {drill_id}")
    risk_fields = {
        "schemaVersion",
        "subject",
        "exercise",
        "assessmentBoundary",
        "artifactBindings",
        "auditReceipt",
        "triagePolicy",
        "entries",
        "controlChange",
        "releaseDecision",
        "complete",
        "limitations",
    }
    if not isinstance(risk_register, dict) or set(risk_register) != risk_fields:
        raise ToolError(
            "Audit Stage 8 risk-register.json has unsupported or missing fields."
        )
    audit_enforce_json_limit(risk_register, "Audit Stage 8 risk register", 10_000_000)
    audit_reject_secret_values(risk_register, "Audit Stage 8 risk register")
    result, result_summary, failures = _audit_stage8_result_semantics(
        audit_result, "auditResult"
    )
    source = _audit_source_subject(project_path, "Stage 8")
    root = source["_root"]

    def exact_object(container: dict[str, Any], field: str, keys: set[str]) -> dict[str, Any]:
        value = container.get(field)
        if not isinstance(value, dict) or set(value) != keys:
            raise ToolError(
                f"Audit Stage 8 {field} has unsupported or missing fields."
            )
        return value

    if risk_register.get("schemaVersion") != AUDIT_STAGE8_RISK_SCHEMA:
        failures.append("schemaVersion")
    exercise = exact_object(risk_register, "exercise", {"drillId", "type"})
    if exercise != {"drillId": drill_id, "type": expected_type}:
        failures.append("exercise")
    boundary = exact_object(
        risk_register, "assessmentBoundary", set(AUDIT_STAGE8_ASSESSMENT_BOUNDARY)
    )
    if boundary != AUDIT_STAGE8_ASSESSMENT_BOUNDARY:
        failures.append("assessmentBoundary")
    if risk_register.get("triagePolicy") != AUDIT_STAGE8_TRIAGE_POLICY:
        failures.append("triagePolicy")
    if risk_register.get("limitations") != AUDIT_STAGE8_LIMITATIONS:
        failures.append("limitations")
    if risk_register.get("complete") is not True:
        failures.append("complete")

    subject = exact_object(
        risk_register,
        "subject",
        {
            "baselineGitHead",
            "baselineGitTree",
            "candidateGitHead",
            "candidateGitTree",
        },
    )
    baseline = _audit_stage4_resolve_revision(root, subject.get("baselineGitHead"))
    candidate = _audit_stage4_resolve_revision(root, subject.get("candidateGitHead"))
    if baseline is None:
        failures.append("subject.baseline")
    if candidate is None:
        failures.append("subject.candidate")
    if baseline and subject.get("baselineGitTree") != baseline["gitTree"]:
        failures.append("subject.baselineGitTree")
    if candidate and subject.get("candidateGitTree") != candidate["gitTree"]:
        failures.append("subject.candidateGitTree")
    if candidate and (
        candidate["gitHead"] != source["gitHead"]
        or candidate["gitTree"] != source["gitTree"]
    ):
        failures.append("subject.candidate-not-current")
    changed_paths: list[str] = []
    if baseline and candidate:
        if expected_type == "audit":
            if baseline != candidate:
                failures.append("subject.audit-baseline-candidate")
        else:
            ancestry = run_complete(
                [
                    "git",
                    "merge-base",
                    "--is-ancestor",
                    baseline["gitHead"],
                    candidate["gitHead"],
                ],
                root,
                timeout=8,
            )
            diff = _audit_stage4_changed_paths(
                root, baseline["gitHead"], candidate["gitHead"]
            )
            if baseline["gitHead"] == candidate["gitHead"]:
                failures.append("subject.implementation-distinct-commit")
            if not ancestry["ok"]:
                failures.append("subject.baseline-not-ancestor")
            if not diff:
                failures.append("subject.implementation-empty-diff")
            changed_paths = diff or []

    bindings = exact_object(
        risk_register, "artifactBindings", {"auditResult", "auditReport", "sarif"}
    )
    for binding_name, artifact_name in (
        ("auditResult", "audit-result.json"),
        ("auditReport", "audit-report.md"),
        ("sarif", "audit.sarif"),
    ):
        binding = bindings.get(binding_name)
        if not isinstance(binding, dict) or set(binding) != {"path", "sha256"}:
            raise ToolError("Audit Stage 8 artifact binding is malformed.")
        artifact = artifacts.get(artifact_name) or {}
        if binding.get("path") != artifact.get("path"):
            failures.append(f"artifactBindings.{binding_name}.path")
        if binding.get("sha256") != artifact.get("sha256"):
            failures.append(f"artifactBindings.{binding_name}.sha256")

    expected_sarif = audit_core.to_sarif(result)
    if sarif != expected_sarif:
        failures.append("sarif.equivalence")

    permitted_dirty = set(AUDIT_STAGE8_ARTIFACT_PATHS.values())
    dirty_paths = set(git_changed_files(project_path))
    receipt_payload = (
        audit_verification.get("payload", {}) if audit_verification else {}
    )
    receipt_checks = (
        audit_verification.get("checks", {}) if audit_verification else {}
    )
    required_receipt_checks = {
        "kind",
        "session",
        "projectPath",
        "gitHead",
        "projectFingerprint",
        "fresh",
        "notExpired",
        "boundedExpiry",
    }
    receipt_valid_except_training_artifacts = bool(
        audit_verification
        and required_receipt_checks.issubset(receipt_checks)
        and all(
            value is True
            for key, value in receipt_checks.items()
            if key != "projectFingerprint"
        )
        and dirty_paths.issubset(permitted_dirty)
    )
    if not receipt_valid_except_training_artifacts:
        failures.append("auditReceipt.signature-subject-or-freshness")
    receipt_binding = exact_object(
        risk_register,
        "auditReceipt",
        {
            "receiptDigest",
            "schemaVersion",
            "gitHead",
            "projectFingerprint",
            "profile",
            "scopeMode",
            "releaseScopeCovered",
            "complete",
            "resultStatus",
            "failureThreshold",
            "coverageDigest",
            "findingDigest",
            "evaluatedAt",
        },
    )
    expected_receipt_binding = {
        "receiptDigest": (
            audit_verification.get("receiptDigest") if audit_verification else None
        ),
        "schemaVersion": receipt_payload.get("schemaVersion"),
        "gitHead": receipt_payload.get("gitHead"),
        "projectFingerprint": receipt_payload.get("projectFingerprint"),
        "profile": receipt_payload.get("profile"),
        "scopeMode": receipt_payload.get("scopeMode"),
        "releaseScopeCovered": receipt_payload.get("releaseScopeCovered"),
        "complete": receipt_payload.get("complete"),
        "resultStatus": receipt_payload.get("resultStatus"),
        "failureThreshold": receipt_payload.get("failureThreshold"),
        "coverageDigest": receipt_payload.get("coverageDigest"),
        "findingDigest": receipt_payload.get("findingDigest"),
        "evaluatedAt": receipt_payload.get("evaluatedAt"),
    }
    if receipt_binding != expected_receipt_binding:
        failures.append("auditReceipt.binding")
    expected_receipt_semantics = {
        "schemaVersion": "jstack.audit.receipt.v1",
        "gitHead": source["gitHead"],
        "profile": "release",
        "scopeMode": "repository",
        "releaseScopeCovered": True,
        "complete": True,
        "resultStatus": result.get("status"),
        "failureThreshold": result.get("failOn"),
        "coverageDigest": audit_json_digest(result.get("coverage")),
        "findingDigest": audit_json_digest(result.get("findings")),
        "evaluatedAt": result.get("evaluatedAt"),
    }
    for field, expected in expected_receipt_semantics.items():
        if receipt_payload.get(field) != expected:
            failures.append("auditReceipt." + field)
    if receipt_payload.get("findingCounts") != result.get("findingCounts"):
        failures.append("auditReceipt.findingCounts")
    expected_active_suppressions = sorted(
        [
            {
                "fingerprint": finding["fingerprint"],
                "expiresAt": finding["suppression"]["expiresAt"],
            }
            for finding in result["findings"]
            if finding.get("status") == "suppressed"
        ],
        key=lambda item: (item["expiresAt"], item["fingerprint"]),
    )
    if receipt_payload.get("activeSuppressions") != expected_active_suppressions:
        failures.append("auditReceipt.activeSuppressions")

    entries = risk_register.get("entries")
    if not isinstance(entries, list) or len(entries) > AUDIT_STAGE8_MAX_ITEMS:
        raise ToolError(
            f"Audit Stage 8 entries must contain at most {AUDIT_STAGE8_MAX_ITEMS} items."
        )
    entry_fields = {
        "findingId",
        "fingerprint",
        "severity",
        "priority",
        "verificationState",
        "auditStatus",
        "blocking",
        "disposition",
        "owner",
        "reason",
        "targetDate",
        "approvalReference",
        "expiresAt",
        "compensatingControl",
        "residualRisk",
        "verificationPlan",
    }
    seen_fingerprints: set[str] = set()
    for index, entry in enumerate(entries):
        prefix = f"entries[{index}]"
        if not isinstance(entry, dict) or set(entry) != entry_fields:
            raise ToolError(f"Audit Stage 8 {prefix} is malformed.")
        fingerprint = str(entry.get("fingerprint") or "")
        finding = result_summary["findingByFingerprint"].get(fingerprint)
        if finding is None or fingerprint in seen_fingerprints:
            failures.append(prefix + ".fingerprint")
            continue
        seen_fingerprints.add(fingerprint)
        for field in (
            "findingId",
            "fingerprint",
            "severity",
            "priority",
            "verificationState",
            "blocking",
        ):
            if entry.get(field) != finding.get(field):
                failures.append(prefix + "." + field)
        if entry.get("auditStatus") != finding.get("status"):
            failures.append(prefix + ".auditStatus")
        if entry.get("residualRisk") != finding.get("residualRisk"):
            failures.append(prefix + ".residualRisk")
        if entry.get("verificationPlan") != finding.get("verificationPlan"):
            failures.append(prefix + ".verificationPlan")
        if finding.get("status") == "suppressed":
            suppression = finding["suppression"]
            expected_values = {
                "disposition": "accepted-risk",
                "owner": suppression["owner"],
                "reason": suppression["reason"],
                "targetDate": None,
                "approvalReference": suppression["approvalReference"],
                "expiresAt": suppression["expiresAt"],
                "compensatingControl": suppression["compensatingControl"],
            }
            for field, expected in expected_values.items():
                if entry.get(field) != expected:
                    failures.append(prefix + "." + field)
            try:
                expires = _audit_stage8_timestamp(
                    suppression["expiresAt"], prefix + ".expiresAt"
                )
                if expires <= _dt.datetime.now(_dt.timezone.utc):
                    failures.append(prefix + ".expired")
            except ToolError:
                failures.append(prefix + ".expiresAt")
        else:
            expected_disposition = (
                "investigate"
                if finding.get("verificationState") == "unverified-hypothesis"
                else "remediate"
            )
            if entry.get("disposition") != expected_disposition:
                failures.append(prefix + ".disposition")
            try:
                _audit_stage8_plain_text(entry.get("owner"), prefix + ".owner", minimum=2)
                _audit_stage8_plain_text(entry.get("reason"), prefix + ".reason", minimum=12)
            except ToolError:
                failures.append(prefix + ".ownership")
            if any(
                entry.get(field) is not None
                for field in ("approvalReference", "expiresAt", "compensatingControl")
            ):
                failures.append(prefix + ".open-risk-fields")
            try:
                target = _audit_stage8_timestamp(
                    entry.get("targetDate"), prefix + ".targetDate"
                )
                if target <= result_summary["evaluatedAt"]:
                    failures.append(prefix + ".targetDate")
            except ToolError:
                failures.append(prefix + ".targetDate")
    if seen_fingerprints != set(result_summary["findingByFingerprint"]):
        failures.append("entries.finding-coverage")
    expected_entry_order = sorted(
        entries,
        key=lambda item: (
            AUDIT_STAGE8_PRIORITY_RANK.get(str(item.get("priority")), 99),
            -AUDIT_STAGE8_SEVERITY_RANK.get(str(item.get("severity")), -1),
            str(item.get("findingId") or ""),
        ),
    )
    if entries != expected_entry_order:
        failures.append("entries.order")

    candidate_findings = result_summary["findingByFingerprint"]
    baseline_findings = candidate_findings
    baseline_result_sha: Optional[str] = None
    if expected_type == "implementation" and baseline:
        baseline_raw, baseline_result_sha = _audit_stage8_revision_json(
            root,
            baseline["gitHead"],
            AUDIT_STAGE8_ARTIFACT_PATHS["audit-result.json"],
        )
        _, baseline_summary, baseline_failures = _audit_stage8_result_semantics(
            baseline_raw, "baselineAuditResult"
        )
        failures.extend(baseline_failures)
        baseline_findings = baseline_summary["findingByFingerprint"]
        prior_baseline_validated = any(
            isinstance(item, dict)
            and item.get("stage") == 8
            and item.get("track") == "audit"
            and (item.get("stage8EnterpriseLeadEvaluation") or {}).get("passed") is True
            and (item.get("stage8EnterpriseLeadEvaluation") or {}).get(
                "candidateGitHead"
            )
            == baseline["gitHead"]
            and (item.get("stage8EnterpriseLeadEvaluation") or {}).get(
                "auditResultDigest"
            )
            == baseline_result_sha
            for item in prior_attempts
        )
        if not prior_baseline_validated:
            failures.append("controlChange.baseline-not-prior-validated")
    shared = sorted(set(baseline_findings) & set(candidate_findings))
    remediated = sorted(set(baseline_findings) - set(candidate_findings))
    introduced = sorted(set(candidate_findings) - set(baseline_findings))
    changed_triage = sorted(
        [
            {
                "fingerprint": fingerprint,
                "baselineSeverity": baseline_findings[fingerprint]["severity"],
                "candidateSeverity": candidate_findings[fingerprint]["severity"],
                "baselinePriority": baseline_findings[fingerprint]["priority"],
                "candidatePriority": candidate_findings[fingerprint]["priority"],
                "baselineStatus": baseline_findings[fingerprint]["status"],
                "candidateStatus": candidate_findings[fingerprint]["status"],
            }
            for fingerprint in shared
            if any(
                baseline_findings[fingerprint].get(field)
                != candidate_findings[fingerprint].get(field)
                for field in ("severity", "priority", "status")
            )
        ],
        key=lambda item: item["fingerprint"],
    )
    regressions_absent = not any(
        candidate_findings[fingerprint].get("blocking") is True
        for fingerprint in introduced
    ) and not any(
        AUDIT_STAGE8_SEVERITY_RANK[candidate_findings[fingerprint]["severity"]]
        > AUDIT_STAGE8_SEVERITY_RANK[baseline_findings[fingerprint]["severity"]]
        or AUDIT_STAGE8_PRIORITY_RANK[candidate_findings[fingerprint]["priority"]]
        < AUDIT_STAGE8_PRIORITY_RANK[baseline_findings[fingerprint]["priority"]]
        for fingerprint in shared
    )
    control = exact_object(
        risk_register,
        "controlChange",
        {
            "status",
            "changedPaths",
            "baselineAuditResultPath",
            "baselineAuditResultSha256",
            "sharedFingerprints",
            "remediatedFingerprints",
            "introducedFingerprints",
            "changedTriage",
            "regressionsAbsent",
        },
    )
    expected_control = {
        "status": "implemented-verified" if expected_type == "implementation" else "existing-observed",
        "changedPaths": sorted(changed_paths),
        "baselineAuditResultPath": (
            AUDIT_STAGE8_ARTIFACT_PATHS["audit-result.json"]
            if expected_type == "implementation"
            else None
        ),
        "baselineAuditResultSha256": (
            baseline_result_sha if expected_type == "implementation" else None
        ),
        "sharedFingerprints": shared,
        "remediatedFingerprints": remediated,
        "introducedFingerprints": introduced,
        "changedTriage": changed_triage,
        "regressionsAbsent": regressions_absent,
    }
    if control != expected_control:
        failures.append("controlChange")
    if expected_type == "implementation":
        verified_remediated = [
            fingerprint
            for fingerprint in remediated
            if baseline_findings[fingerprint].get("verificationState")
            != "unverified-hypothesis"
        ]
        if not verified_remediated:
            failures.append("controlChange.verified-remediation-required")
        if not regressions_absent:
            failures.append("controlChange.regression")
        if result.get("status") != "pass":
            failures.append("controlChange.candidate-release-pass")

    expected_decision = _audit_stage8_expected_decision(result, result_summary)
    if risk_register.get("releaseDecision") != expected_decision:
        failures.append("releaseDecision")

    report_artifact = artifacts.get("audit-report.md") or {}
    validate_mastery_text_artifact(
        project_path, report_artifact, "Audit Stage 8 audit-report.md"
    )
    try:
        report_bytes = audit_core.read_repository_file(
            project_path,
            str(report_artifact.get("path") or ""),
            max_bytes=2_000_000,
            max_seconds=30,
        )
        report_text = report_bytes.decode("utf-8")
    except (audit_core.AuditError, UnicodeError) as exc:
        raise ToolError("Audit Stage 8 audit-report.md could not be read safely.") from exc
    # Markdown written through Windows text mode uses CRLF even though the
    # canonical renderer is platform-independent LF. Treat those encodings as
    # the same report while leaving the exact artifact byte digest bound in
    # artifactBindings.
    normalized_report_text = report_text.replace("\r\n", "\n")
    if normalized_report_text != render_audit_stage8_report(risk_register, result):
        failures.append("auditReport.equivalence")

    expected_qa_keys = {item["key"] for item in discover_test_commands(project_path)}
    valid_qa_keys = {
        str((item.get("payload") or {}).get("commandKey"))
        for item in qa_verifications
        if item.get("valid")
    }
    if valid_qa_keys != expected_qa_keys:
        failures.append("qaEvidence.complete")
    security_payload = (
        security_verification.get("payload", {}) if security_verification else {}
    )
    if (
        not security_verification
        or security_verification.get("valid") is not True
        or security_payload.get("complete") is not True
        or security_payload.get("passed") is not True
    ):
        failures.append("securityEvidence")

    evaluation = {
        "schemaVersion": "jstack.audit.stage8-evaluation.v1",
        "exerciseType": expected_type,
        "drillId": drill_id,
        "baselineGitHead": baseline["gitHead"] if baseline else None,
        "baselineGitTree": baseline["gitTree"] if baseline else None,
        "candidateGitHead": candidate["gitHead"] if candidate else None,
        "candidateGitTree": candidate["gitTree"] if candidate else None,
        "auditReceiptDigest": (
            audit_verification.get("receiptDigest") if audit_verification else None
        ),
        # This semantic SHA-256 is stable across checkout newline policies;
        # exact current artifact bytes remain separately bound by the artifact
        # record and the candidate commit remains the immutable Git boundary.
        "auditResultDigest": audit_json_digest(result),
        "auditReportDigest": artifacts.get("audit-report.md", {}).get("sha256"),
        "sarifDigest": artifacts.get("audit.sarif", {}).get("sha256"),
        "riskRegisterDigest": artifacts.get("risk-register.json", {}).get("sha256"),
        "releaseDecision": expected_decision["decision"],
        "findingCount": len(candidate_findings),
        "blockingFindingCount": len(result_summary["blockingFindingIds"]),
        "suppressedFindingCount": result_summary["findingCounts"]["suppressed"],
        "sharedFingerprintCount": len(shared),
        "remediatedFingerprintCount": len(remediated),
        "introducedFingerprintCount": len(introduced),
        "changedTriageCount": len(changed_triage),
        "changedPathCount": len(changed_paths),
        "qaEvidenceCount": len(valid_qa_keys),
        "regressionsAbsent": regressions_absent,
        "passed": not failures,
        "failureCodes": sorted(set(failures)),
    }
    return {**evaluation, "evaluationDigest": audit_json_digest(evaluation)}


def score_level(score: float) -> int:
    if score < 50:
        return 0
    if score < 65:
        return 1
    if score < 80:
        return 2
    if score < 90:
        return 3
    return 4


def mastery_attempt_evidence_digest(
    track: str,
    stage_number: int,
    drill_id: str,
    assistance: str,
    assessor: str,
    citations: list[str],
    component_scores: dict[str, float],
    artifacts: dict[str, dict[str, Any]],
    state: dict[str, Any],
    benchmark_evaluation: Optional[dict[str, Any]],
) -> str:
    return audit_json_digest(
        {
            "track": track,
            "stage": stage_number,
            "drillId": drill_id,
            "assistanceLevel": assistance,
            "assessor": assessor,
            "assessorCitations": citations,
            "assessment": component_scores,
            "artifacts": artifacts,
            "projectState": {
                "gitRoot": state.get("gitRoot"),
                "gitHead": state.get("gitHead"),
                "projectFingerprint": state.get("projectFingerprint"),
            },
            "benchmarkEvaluationDigest": (
                benchmark_evaluation.get("evaluationDigest")
                if benchmark_evaluation is not None
                else None
            ),
        }
    )


def verify_capstone_attestation(
    raw_attestation: Any,
    expected_assessor: str,
    expected_attempt_digest: str,
    expected_evaluation_digest: str,
    *,
    expected_schema: str,
    assessor_key_env: str,
) -> dict[str, Any]:
    required = {
        "schemaVersion",
        "assessorId",
        "challengeId",
        "challengeDigest",
        "attemptEvidenceDigest",
        "evaluationDigest",
        "issuedAt",
        "expiresAt",
        "blind",
        "independent",
        "signature",
    }
    if not isinstance(raw_attestation, dict) or set(raw_attestation) != required:
        return {"valid": False, "reason": "malformed"}
    body = {key: raw_attestation[key] for key in sorted(required - {"signature"})}
    signature = str(raw_attestation.get("signature") or "")
    key_value = os.environ.get(assessor_key_env, "")
    checks: dict[str, bool] = {
        "schema": body.get("schemaVersion") == expected_schema,
        "assessor": body.get("assessorId") == expected_assessor,
        "challengeId": bool(
            re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,127}", str(body.get("challengeId") or ""))
        ),
        "challengeDigest": bool(
            re.fullmatch(r"sha256:[0-9a-f]{64}", str(body.get("challengeDigest") or ""))
        ),
        "attemptEvidenceDigest": body.get("attemptEvidenceDigest") == expected_attempt_digest,
        "evaluationDigest": body.get("evaluationDigest") == expected_evaluation_digest,
        "blind": body.get("blind") is True,
        "independent": body.get("independent") is True,
        "keyConfigured": len(key_value.encode("utf-8")) >= 32,
        "signatureFormat": bool(re.fullmatch(r"sha256:[0-9a-f]{64}", signature)),
    }
    try:
        issued = _dt.datetime.fromisoformat(str(body["issuedAt"]).replace("Z", "+00:00"))
        expires = _dt.datetime.fromisoformat(str(body["expiresAt"]).replace("Z", "+00:00"))
        if issued.tzinfo is None or expires.tzinfo is None:
            raise ValueError("timezone required")
        issued = issued.astimezone(_dt.timezone.utc)
        expires = expires.astimezone(_dt.timezone.utc)
        now = _dt.datetime.now(_dt.timezone.utc)
        checks["timeWindow"] = (
            issued <= now < expires
            and 0 < (expires - issued).total_seconds()
            <= AUDIT_CAPSTONE_ATTESTATION_MAX_AGE_SECONDS
        )
    except (KeyError, TypeError, ValueError):
        checks["timeWindow"] = False
    if checks["keyConfigured"] and checks["signatureFormat"]:
        message = json.dumps(
            body,
            ensure_ascii=True,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
        expected_signature = "sha256:" + hmac.new(
            key_value.encode("utf-8"), message, hashlib.sha256
        ).hexdigest()
        checks["signature"] = hmac.compare_digest(signature, expected_signature)
    else:
        checks["signature"] = False
    valid = all(checks.values())
    return {
        "valid": valid,
        "reason": "verified" if valid else "attestation-check-failed",
        "schemaVersion": body.get("schemaVersion"),
        "assessorId": body.get("assessorId"),
        "challengeId": body.get("challengeId"),
        "challengeDigest": body.get("challengeDigest"),
        "attemptEvidenceDigest": body.get("attemptEvidenceDigest"),
        "evaluationDigest": body.get("evaluationDigest"),
        "issuedAt": body.get("issuedAt"),
        "expiresAt": body.get("expiresAt"),
        "blind": body.get("blind") is True,
        "independent": body.get("independent") is True,
        "attestationDigest": audit_json_digest(body),
        "checks": checks,
    }


def verify_audit_capstone_attestation(
    raw_attestation: Any,
    expected_assessor: str,
    expected_attempt_digest: str,
    expected_evaluation_digest: str,
) -> dict[str, Any]:
    return verify_capstone_attestation(
        raw_attestation,
        expected_assessor,
        expected_attempt_digest,
        expected_evaluation_digest,
        expected_schema=AUDIT_CAPSTONE_ATTESTATION_SCHEMA,
        assessor_key_env=AUDIT_CAPSTONE_ASSESSOR_KEY_ENV,
    )


def verify_loop_capstone_attestation(
    raw_attestation: Any,
    expected_assessor: str,
    expected_attempt_digest: str,
    expected_evaluation_digest: str,
) -> dict[str, Any]:
    return verify_capstone_attestation(
        raw_attestation,
        expected_assessor,
        expected_attempt_digest,
        expected_evaluation_digest,
        expected_schema=LOOP_CAPSTONE_ATTESTATION_SCHEMA,
        assessor_key_env=LOOP_CAPSTONE_ASSESSOR_KEY_ENV,
    )


def evaluate_loop_capstone(raw: Any) -> dict[str, Any]:
    required = {
        "schemaVersion",
        "p0Total",
        "p0Found",
        "p1Total",
        "p1Found",
        "continuationDecisionCorrect",
        "releaseDecisionCorrect",
        "recoveryVerified",
        "evidenceComplete",
    }
    if not isinstance(raw, dict) or set(raw) != required:
        raise ToolError(
            "Loop Stage 9 capstone-evaluation.json has unsupported or missing fields."
        )
    if raw.get("schemaVersion") != "jstack.loop.capstone-evaluation.v1":
        raise ToolError("Loop Stage 9 capstone evaluation schema is unsupported.")
    metrics: dict[str, Any] = {"schemaVersion": raw["schemaVersion"]}
    for field in ("p0Total", "p0Found", "p1Total", "p1Found"):
        value = raw.get(field)
        if not isinstance(value, int) or isinstance(value, bool) or value < 0:
            raise ToolError(f"Loop Stage 9 capstone evaluation {field} must be a non-negative integer.")
        metrics[field] = value
    if metrics["p0Found"] > metrics["p0Total"] or metrics["p1Found"] > metrics["p1Total"]:
        raise ToolError("Loop Stage 9 capstone findings found cannot exceed seeded totals.")
    for field in (
        "continuationDecisionCorrect",
        "releaseDecisionCorrect",
        "recoveryVerified",
        "evidenceComplete",
    ):
        if not isinstance(raw.get(field), bool):
            raise ToolError(f"Loop Stage 9 capstone evaluation {field} must be a boolean.")
        metrics[field] = raw[field]
    return {**metrics, "evaluationDigest": audit_json_digest(metrics)}


def tool_mastery_record(args: dict[str, Any]) -> dict[str, Any]:
    if not mastery_profile_path().exists():
        raise ToolError("Start the mastery system with jstack_mastery_start before recording an attempt.")
    project_path = require_project_path(args.get("project_path"))
    track = normalize_mastery_track(args.get("track"))
    profile = load_mastery_profile()
    track_state = mastery_track_state(profile, track)
    stage_number = int(args.get("stage", -1))
    if stage_number != track_state["currentStage"]:
        raise ToolError(f"Attempt stage must match current {track} learner stage {track_state['currentStage']}.")
    stage = curriculum_stage(stage_number, track)
    drill_id = str(args.get("drill_id") or "").strip()
    drill = next((item for item in stage.get("drills", []) if item.get("id") == drill_id), None)
    if not drill:
        raise ToolError(f"Unknown drill_id for stage {stage_number}: {drill_id}")
    assistance = str(args.get("assistance_level") or "").strip()
    curriculum = load_mastery_curriculum(track)
    caps = curriculum["scoring"]["assistanceCaps"]
    if assistance not in caps:
        raise ToolError("assistance_level must be observed, guided, checklist, independent, or independent_teach.")
    assessor = str(args.get("assessor") or "").strip()
    citations = args.get("assessor_citations") or []
    if not assessor or not isinstance(citations, list) or not all(isinstance(item, str) and item.strip() for item in citations):
        raise ToolError("assessor and at least one assessor_citation are required.")
    assessment = args.get("assessment") or {}
    weights = curriculum["scoring"]["weights"]
    if not isinstance(assessment, dict):
        raise ToolError("assessment must be an object with the five rubric scores.")
    component_scores: dict[str, float] = {}
    for component in weights:
        try:
            value = float(assessment[component])
        except (KeyError, TypeError, ValueError) as exc:
            raise ToolError(f"assessment.{component} must be a number from 0 to 100.") from exc
        if not 0 <= value <= 100:
            raise ToolError(f"assessment.{component} must be between 0 and 100.")
        component_scores[component] = value
    score = round(sum(component_scores[key] * float(weight) / 100 for key, weight in weights.items()), 2)
    raw_level = score_level(score)
    demonstrated_level = min(raw_level, int(caps[assistance]))

    artifacts_arg = args.get("artifacts") or {}
    if not isinstance(artifacts_arg, dict):
        raise ToolError("artifacts must map each required artifact name to a project-relative path.")
    missing_artifacts = [name for name in stage.get("requiredArtifacts", []) if not artifacts_arg.get(name)]
    if missing_artifacts:
        raise ToolError("Missing required mastery artifacts: " + ", ".join(missing_artifacts))
    artifacts = {
        requirement: hash_mastery_artifact(project_path, str(artifacts_arg[requirement]))
        for requirement in stage.get("requiredArtifacts", [])
    }
    stage0_security_evaluation = None
    stage1_repository_map_evaluation = None
    stage2_correctness_report = None
    stage2_reproduction_manifest = None
    stage2_correctness_evaluation = None
    stage3_security_findings = None
    stage3_threat_model_evaluation = None
    stage4_maintainability_report = None
    stage4_architecture_evaluation = None
    stage5_performance_results = None
    stage5_performance_findings = None
    stage5_performance_evaluation = None
    stage6_dependency_inventory = None
    stage6_supply_chain_report = None
    stage6_supply_chain_evaluation = None
    stage7_verification_results = None
    stage7_adversarial_evaluation = None
    stage8_audit_result = None
    stage8_sarif = None
    stage8_risk_register = None
    stage8_enterprise_lead_evaluation = None
    performance_evidence: list[dict[str, Any]] = []
    adversarial_evidence: list[dict[str, Any]] = []
    audit_verification = None
    benchmark_evaluation = None
    loop_capstone_evaluation = None
    if track == "audit" and stage_number == 0:
        orientation = load_mastery_json_artifact(
            project_path,
            artifacts["security-orientation.json"],
        )
        stage0_security_evaluation = evaluate_audit_stage0_security_orientation(
            orientation,
            drill_id,
        )
    elif track == "audit" and stage_number == 1:
        repository_map = load_mastery_json_artifact(
            project_path,
            artifacts["coverage-matrix.json"],
        )
        stage1_repository_map_evaluation = evaluate_audit_stage1_repository_map(
            repository_map,
            project_path,
        )
    elif track == "audit" and stage_number == 2:
        stage2_correctness_report = load_mastery_json_artifact(
            project_path,
            artifacts["correctness-report.json"],
        )
        stage2_reproduction_manifest = load_mastery_directory_json_artifact(
            project_path,
            artifacts["reproductions"],
            "manifest.json",
        )
    elif track == "audit" and stage_number == 3:
        stage3_security_findings = load_mastery_json_artifact(
            project_path,
            artifacts["security-findings.json"],
        )
    elif track == "audit" and stage_number == 4:
        stage4_maintainability_report = load_mastery_json_artifact(
            project_path,
            artifacts["maintainability-report.json"],
        )
    elif track == "audit" and stage_number == 5:
        stage5_performance_results = load_mastery_json_artifact(
            project_path,
            artifacts["baseline-results.json"],
        )
        stage5_performance_findings = load_mastery_json_artifact(
            project_path,
            artifacts["performance-findings.json"],
        )
    elif track == "audit" and stage_number == 6:
        stage6_dependency_inventory = load_mastery_json_artifact(
            project_path,
            artifacts["dependency-inventory.json"],
        )
        stage6_supply_chain_report = load_mastery_json_artifact(
            project_path,
            artifacts["supply-chain-report.json"],
        )
    elif track == "audit" and stage_number == 7:
        stage7_verification_results = load_mastery_json_artifact(
            project_path,
            artifacts["verification-results.json"],
        )
    elif track == "audit" and stage_number == 8:
        stage8_audit_result = load_mastery_json_artifact(
            project_path,
            artifacts["audit-result.json"],
        )
        stage8_sarif = load_mastery_json_artifact(
            project_path,
            artifacts["audit.sarif"],
        )
        stage8_risk_register = load_mastery_json_artifact(
            project_path,
            artifacts["risk-register.json"],
        )
    elif track == "audit" and stage_number == 9:
        if args.get("capstone_results") not in (None, {}):
            raise ToolError(
                "Audit Stage 9 does not accept caller-supplied aggregate capstone_results; "
                "metrics are derived from the evaluation-results.json benchmark submissions."
            )
        evaluation = load_mastery_json_artifact(
            project_path,
            artifacts["evaluation-results.json"],
        )
        try:
            benchmark_evaluation = audit_core.score_benchmark_evaluation(evaluation)
        except audit_core.AuditError as exc:
            raise ToolError(f"Audit Stage 9 benchmark evaluation is invalid: {exc}") from exc
    elif track == "loop" and stage_number == 9:
        if args.get("capstone_results") not in (None, {}):
            raise ToolError(
                "Loop Stage 9 does not accept caller-supplied capstone_results; "
                "metrics come from the hashed capstone-evaluation.json artifact."
            )
        evaluation = load_mastery_json_artifact(
            project_path,
            artifacts["capstone-evaluation.json"],
        )
        loop_capstone_evaluation = evaluate_loop_capstone(evaluation)

    state = project_state(project_path)
    capstone_attestation = None
    if track == "audit" and stage_number == 9:
        assert benchmark_evaluation is not None
        attempt_digest = mastery_attempt_evidence_digest(
            track,
            stage_number,
            drill_id,
            assistance,
            assessor,
            citations,
            component_scores,
            artifacts,
            state,
            benchmark_evaluation,
        )
        capstone_attestation = verify_audit_capstone_attestation(
            args.get("assessor_attestation"),
            assessor,
            attempt_digest,
            str(benchmark_evaluation["evaluationDigest"]),
        )
    elif track == "loop" and stage_number == 9:
        assert loop_capstone_evaluation is not None
        attempt_digest = mastery_attempt_evidence_digest(
            track,
            stage_number,
            drill_id,
            assistance,
            assessor,
            citations,
            component_scores,
            artifacts,
            state,
            loop_capstone_evaluation,
        )
        capstone_attestation = verify_loop_capstone_attestation(
            args.get("assessor_attestation"),
            assessor,
            attempt_digest,
            str(loop_capstone_evaluation["evaluationDigest"]),
        )
    hard_blocks = [str(item) for item in (args.get("hard_gate_failures") or []) if str(item).strip()]
    if stage_number == 0:
        artifact_paths = [item["path"] for item in artifacts.values()]
        if any(not path.startswith(".jstack-training/") for path in artifact_paths):
            hard_blocks.append("Stage 0 artifacts must live under .jstack-training/.")
        disallowed_changes = [
            path for path in git_changed_files(project_path) if not path.startswith(".jstack-training/")
        ]
        if disallowed_changes:
            hard_blocks.append(
                "Stage 0 project state contains non-training changes: " + ", ".join(disallowed_changes)
            )
        if track == "audit":
            assert stage0_security_evaluation is not None
            for code in stage0_security_evaluation["failureCodes"]:
                hard_blocks.append(
                    f"Audit Stage 0 security orientation gate failed: {code}."
                )
    if track == "audit" and stage_number == 1:
        artifact_paths = [item["path"] for item in artifacts.values()]
        if any(not path.startswith(".jstack-training/") for path in artifact_paths):
            hard_blocks.append(
                "Audit Stage 1 artifacts must live under .jstack-training/."
            )
        disallowed_changes = [
            path
            for path in git_changed_files(project_path)
            if not path.startswith(".jstack-training/")
        ]
        if disallowed_changes:
            hard_blocks.append(
                "Audit Stage 1 project state contains non-training changes: "
                + ", ".join(disallowed_changes)
            )
        assert stage1_repository_map_evaluation is not None
        for code in stage1_repository_map_evaluation["failureCodes"]:
            hard_blocks.append(
                f"Audit Stage 1 repository-map gate failed: {code}."
            )
    if track == "audit" and stage_number == 2:
        for artifact_name, expected_path in AUDIT_STAGE2_ARTIFACT_PATHS.items():
            if artifacts.get(artifact_name, {}).get("path") != expected_path:
                hard_blocks.append(
                    f"Audit Stage 2 {artifact_name} must use {expected_path}."
                )
        permitted_changes = {
            AUDIT_STAGE2_ARTIFACT_PATHS["correctness-report.json"],
            AUDIT_STAGE2_ARTIFACT_PATHS["invariants.md"],
            AUDIT_STAGE2_ARTIFACT_PATHS["reproductions"] + "/manifest.json",
        }
        disallowed_changes = [
            path for path in git_changed_files(project_path) if path not in permitted_changes
        ]
        if disallowed_changes:
            hard_blocks.append(
                "Audit Stage 2 project state contains non-training changes: "
                + ", ".join(disallowed_changes)
            )
    if track == "audit" and stage_number == 3:
        for artifact_name, expected_path in AUDIT_STAGE3_ARTIFACT_PATHS.items():
            if artifacts.get(artifact_name, {}).get("path") != expected_path:
                hard_blocks.append(
                    f"Audit Stage 3 {artifact_name} must use {expected_path}."
                )
        permitted_changes = set(AUDIT_STAGE3_ARTIFACT_PATHS.values())
        disallowed_changes = [
            path for path in git_changed_files(project_path) if path not in permitted_changes
        ]
        if disallowed_changes:
            hard_blocks.append(
                "Audit Stage 3 project state contains non-training changes: "
                + ", ".join(disallowed_changes)
            )
    if track == "audit" and stage_number == 4:
        for artifact_name, expected_path in AUDIT_STAGE4_ARTIFACT_PATHS.items():
            if artifacts.get(artifact_name, {}).get("path") != expected_path:
                hard_blocks.append(
                    f"Audit Stage 4 {artifact_name} must use {expected_path}."
                )
        permitted_changes = set(AUDIT_STAGE4_ARTIFACT_PATHS.values())
        disallowed_changes = [
            path for path in git_changed_files(project_path) if path not in permitted_changes
        ]
        if disallowed_changes:
            hard_blocks.append(
                "Audit Stage 4 project state contains non-training changes: "
                + ", ".join(disallowed_changes)
            )
    if track == "audit" and stage_number == 5:
        for artifact_name, expected_path in AUDIT_STAGE5_ARTIFACT_PATHS.items():
            if artifacts.get(artifact_name, {}).get("path") != expected_path:
                hard_blocks.append(
                    f"Audit Stage 5 {artifact_name} must use {expected_path}."
                )
        permitted_changes = set(AUDIT_STAGE5_ARTIFACT_PATHS.values())
        disallowed_changes = [
            path for path in git_changed_files(project_path) if path not in permitted_changes
        ]
        if disallowed_changes:
            hard_blocks.append(
                "Audit Stage 5 project state contains non-training changes: "
                + ", ".join(disallowed_changes)
            )
    if track == "audit" and stage_number == 6:
        for artifact_name, expected_path in AUDIT_STAGE6_ARTIFACT_PATHS.items():
            if artifacts.get(artifact_name, {}).get("path") != expected_path:
                hard_blocks.append(
                    f"Audit Stage 6 {artifact_name} must use {expected_path}."
                )
        permitted_changes = set(AUDIT_STAGE6_ARTIFACT_PATHS.values())
        disallowed_changes = [
            path for path in git_changed_files(project_path) if path not in permitted_changes
        ]
        if disallowed_changes:
            hard_blocks.append(
                "Audit Stage 6 project state contains non-training changes: "
                + ", ".join(disallowed_changes)
            )
    if track == "audit" and stage_number == 7:
        for artifact_name, expected_path in AUDIT_STAGE7_ARTIFACT_PATHS.items():
            if artifacts.get(artifact_name, {}).get("path") != expected_path:
                hard_blocks.append(
                    f"Audit Stage 7 {artifact_name} must use {expected_path}."
                )
        permitted_changes = set(AUDIT_STAGE7_ARTIFACT_PATHS.values())
        disallowed_changes = [
            path for path in git_changed_files(project_path) if path not in permitted_changes
        ]
        if disallowed_changes:
            hard_blocks.append(
                "Audit Stage 7 project state contains non-training changes: "
                + ", ".join(disallowed_changes)
            )
    if track == "audit" and stage_number == 8:
        for artifact_name, expected_path in AUDIT_STAGE8_ARTIFACT_PATHS.items():
            if artifacts.get(artifact_name, {}).get("path") != expected_path:
                hard_blocks.append(
                    f"Audit Stage 8 {artifact_name} must use {expected_path}."
                )
        permitted_changes = set(AUDIT_STAGE8_ARTIFACT_PATHS.values())
        disallowed_changes = [
            path for path in git_changed_files(project_path) if path not in permitted_changes
        ]
        if disallowed_changes:
            hard_blocks.append(
                "Audit Stage 8 project state contains non-training changes: "
                + ", ".join(disallowed_changes)
            )
    if (
        stage_number >= 2
        and not (track == "audit" and stage_number in {2, 3, 4, 5, 6, 7, 8})
        and not state["clean"]
    ):
        hard_blocks.append("Stage 2+ evidence must be recorded from a clean committed project state.")
    qa_receipts = args.get("qa_receipts") or []
    if not isinstance(qa_receipts, list) or not all(isinstance(item, str) for item in qa_receipts):
        raise ToolError("qa_receipts must be an array.")
    qa_verifications = []
    for receipt in qa_receipts:
        verification = verify_receipt(receipt, "qa", state)
        verification["receiptDigest"] = hashlib.sha256(
            receipt.encode("utf-8")
        ).hexdigest()
        qa_verifications.append(verification)
    valid_qa = [item for item in qa_verifications if item["valid"]]
    if track == "audit" and stage_number == 2:
        assert stage2_correctness_report is not None
        assert stage2_reproduction_manifest is not None
        stage2_correctness_evaluation = evaluate_audit_stage2_correctness(
            stage2_correctness_report,
            stage2_reproduction_manifest,
            project_path,
            artifacts,
            qa_verifications,
        )
        for code in stage2_correctness_evaluation["failureCodes"]:
            hard_blocks.append(
                f"Audit Stage 2 correctness gate failed: {code}."
            )
    if track == "audit" and stage_number == 3:
        assert stage3_security_findings is not None
        stage3_threat_model_evaluation = evaluate_audit_stage3_threat_model(
            stage3_security_findings,
            project_path,
            artifacts,
        )
        for code in stage3_threat_model_evaluation["failureCodes"]:
            hard_blocks.append(
                f"Audit Stage 3 threat-model gate failed: {code}."
            )
    if track == "audit" and stage_number == 4:
        assert stage4_maintainability_report is not None
        stage4_architecture_evaluation = evaluate_audit_stage4_architecture(
            stage4_maintainability_report,
            project_path,
            artifacts,
            qa_verifications,
            drill_id,
        )
        for code in stage4_architecture_evaluation["failureCodes"]:
            hard_blocks.append(
                f"Audit Stage 4 architecture gate failed: {code}."
            )
    if track == "audit" and stage_number == 5:
        performance_receipts = args.get("performance_receipts") or []
        if not isinstance(performance_receipts, list) or not all(
            isinstance(item, str) for item in performance_receipts
        ):
            raise ToolError("performance_receipts must be an array.")
        if len(performance_receipts) > PERFORMANCE_MAX_RECEIPTS:
            raise ToolError("performance_receipts exceeds the bounded Stage 5 limit.")
        if any(
            len(receipt) > PERFORMANCE_MAX_RECEIPT_CHARS
            for receipt in performance_receipts
        ):
            raise ToolError("performance_receipts contains an oversized receipt.")
        performance_evidence = [
            {
                "kind": "performance",
                "receiptDigest": hashlib.sha256(receipt.encode("utf-8")).hexdigest(),
            }
            for receipt in performance_receipts
        ]
        assert stage5_performance_results is not None
        assert stage5_performance_findings is not None
        stage5_performance_evaluation = evaluate_audit_stage5_performance(
            stage5_performance_results,
            stage5_performance_findings,
            project_path,
            artifacts,
            qa_verifications,
            performance_receipts,
            drill_id,
        )
        for code in stage5_performance_evaluation["failureCodes"]:
            hard_blocks.append(
                f"Audit Stage 5 performance gate failed: {code}."
            )
    if track == "audit" and stage_number == 6:
        audit_receipt = str(args.get("audit_receipt") or "").strip()
        if not audit_receipt:
            hard_blocks.append(
                "Audit Stage 6 requires a current complete audit receipt with passed dependency-analysis adapter evidence."
            )
        else:
            audit_verification = verify_receipt(
                audit_receipt,
                "audit",
                state,
                require_passed=False,
            )
        assert stage6_dependency_inventory is not None
        assert stage6_supply_chain_report is not None
        stage6_supply_chain_evaluation = evaluate_audit_stage6_supply_chain(
            stage6_dependency_inventory,
            stage6_supply_chain_report,
            project_path,
            artifacts,
            qa_verifications,
            audit_verification,
            drill_id,
        )
        for code in stage6_supply_chain_evaluation["failureCodes"]:
            hard_blocks.append(
                f"Audit Stage 6 supply-chain gate failed: {code}."
            )
    qa_required = stage_number >= 2 and not (
        track == "audit"
        and (
            (
                stage_number == 2
                and stage2_correctness_evaluation is not None
                and stage2_correctness_evaluation["qaReproductionCount"] == 0
            )
            or stage_number == 3
            or (stage_number == 4 and drill.get("type") == "audit")
        )
    )
    if qa_required and not valid_qa:
        hard_blocks.append("Stage 2+ attempt requires a current passing QA evidence receipt.")
    if stage_number >= 6:
        valid_keys = {item["payload"].get("commandKey") for item in valid_qa}
        missing_checks = [item["key"] for item in discover_test_commands(project_path) if item["key"] not in valid_keys]
        if missing_checks:
            hard_blocks.append("Stage 6+ attempt is missing QA receipts for: " + ", ".join(missing_checks))
    security_verification = None
    if stage_number >= 7:
        security_receipt = str(args.get("security_receipt") or "").strip()
        if not security_receipt:
            hard_blocks.append("Stage 7+ attempt requires a current complete security receipt.")
        else:
            security_verification = verify_receipt(security_receipt, "security", state)
            security_verification["receiptDigest"] = hashlib.sha256(
                security_receipt.encode("utf-8")
            ).hexdigest()
            if not security_verification["valid"]:
                hard_blocks.append("Stage 7+ security receipt is invalid or stale.")
    if track == "audit" and stage_number == 7:
        adversarial_receipts = args.get("adversarial_receipts") or []
        if not isinstance(adversarial_receipts, list) or not all(
            isinstance(item, str) for item in adversarial_receipts
        ):
            raise ToolError("adversarial_receipts must be an array.")
        if len(adversarial_receipts) > ADVERSARIAL_MAX_RECEIPTS:
            raise ToolError("adversarial_receipts exceeds the bounded Stage 7 limit.")
        if any(
            len(receipt) > ADVERSARIAL_MAX_RECEIPT_CHARS
            for receipt in adversarial_receipts
        ):
            raise ToolError("adversarial_receipts contains an oversized receipt.")
        adversarial_evidence = [
            {
                "kind": "adversarial",
                "receiptDigest": hashlib.sha256(receipt.encode("utf-8")).hexdigest(),
            }
            for receipt in adversarial_receipts
        ]
        assert stage7_verification_results is not None
        stage7_adversarial_evaluation = evaluate_audit_stage7_adversarial(
            stage7_verification_results,
            project_path,
            artifacts,
            qa_verifications,
            security_verification,
            adversarial_receipts,
            drill_id,
        )
        for code in stage7_adversarial_evaluation["failureCodes"]:
            hard_blocks.append(
                f"Audit Stage 7 adversarial-verification gate failed: {code}."
            )
    if track == "audit" and stage_number >= 8:
        audit_receipt = str(args.get("audit_receipt") or "").strip()
        if not audit_receipt:
            hard_blocks.append("Audit Stage 8+ attempt requires a current complete audit receipt.")
        else:
            audit_verification = verify_receipt(
                audit_receipt,
                "audit",
                state,
                require_passed=False,
            )
            audit_verification["receiptDigest"] = hashlib.sha256(
                audit_receipt.encode("utf-8")
            ).hexdigest()
            if stage_number > 8:
                payload = audit_verification.get("payload") or {}
                if (
                    not audit_verification["valid"]
                    or payload.get("complete") is not True
                    or payload.get("resultStatus") not in {"pass", "fail"}
                ):
                    hard_blocks.append("Audit Stage 8+ receipt is invalid, stale, or incomplete.")
        if stage_number == 8:
            assert stage8_audit_result is not None
            assert stage8_sarif is not None
            assert stage8_risk_register is not None
            stage8_enterprise_lead_evaluation = evaluate_audit_stage8_enterprise_lead(
                stage8_risk_register,
                stage8_audit_result,
                stage8_sarif,
                project_path,
                artifacts,
                qa_verifications,
                security_verification,
                audit_verification,
                drill_id,
                list(track_state.get("attempts") or []),
            )
            for code in stage8_enterprise_lead_evaluation["failureCodes"]:
                hard_blocks.append(
                    f"Audit Stage 8 enterprise-lead gate failed: {code}."
                )
    elif track == "loop" and stage_number >= 8:
        audit_receipt = str(args.get("audit_receipt") or "").strip()
        if not audit_receipt:
            hard_blocks.append("Loop Stage 8+ attempt requires a current passing audit receipt.")
        else:
            audit_verification = verify_receipt(
                audit_receipt,
                "audit",
                state,
                require_passed=True,
            )
            payload = audit_verification.get("payload") or {}
            if (
                not audit_verification["valid"]
                or payload.get("complete") is not True
                or payload.get("resultStatus") != "pass"
            ):
                hard_blocks.append("Loop Stage 8+ audit receipt is invalid, stale, incomplete, or not passing.")
    blind_capstone = (
        capstone_attestation is not None
        and capstone_attestation.get("valid") is True
        and capstone_attestation.get("blind") is True
        if track in {"audit", "loop"} and stage_number == 9
        else bool(args.get("blind_capstone") or False)
    )
    if stage_number == 9:
        if track == "audit":
            assert benchmark_evaluation is not None
            metrics = benchmark_evaluation["primary"]["metrics"]
            if capstone_attestation is None or capstone_attestation.get("valid") is not True:
                hard_blocks.append(
                    "Audit Stage 9 requires a current independently signed assessor attestation bound to the exact attempt and unseen challenge subject."
                )
            if not blind_capstone or metrics["p0Total"] <= 0 or metrics["p0Found"] != metrics["p0Total"]:
                hard_blocks.append("Stage 9 capstone must be blind and catch every seeded P0 finding.")
            if metrics["p1Total"] <= 0 or metrics["p1Found"] / metrics["p1Total"] < 0.8:
                hard_blocks.append("Stage 9 capstone must catch at least 80 percent of seeded P1 findings.")
            if metrics["releaseDecisionCorrect"] is not True:
                hard_blocks.append("Stage 9 capstone requires the correct release go/no-go decision.")
            if metrics["coverage"] != 1.0:
                hard_blocks.append("Audit Stage 9 capstone requires 100 percent scored fixture coverage.")
            if metrics["coverageClassificationCorrect"] is not True:
                hard_blocks.append(
                    "Audit Stage 9 capstone must report unsupported and complete coverage classifications exactly."
                )
            if metrics["severityUnderRanked"] != 0 or metrics["priorityMiscalibrated"] != 0:
                hard_blocks.append(
                    "Audit Stage 9 capstone may not under-rank seeded severity or miscalibrate seeded priority."
                )
            if metrics["precision"] < 0.8:
                hard_blocks.append("Audit Stage 9 capstone requires precision of at least 80 percent.")
            if metrics["duplicateRate"] > 0.05:
                hard_blocks.append("Audit Stage 9 capstone duplicate rate may not exceed 5 percent.")
            if metrics["falseP0"] != 0:
                hard_blocks.append("Audit Stage 9 capstone permits no false-P0 findings.")
            if benchmark_evaluation["deterministicEquivalent"] is not True:
                hard_blocks.append("Audit Stage 9 capstone requires deterministic repeated results.")
            for code in benchmark_evaluation["failureCodes"]:
                hard_blocks.append(f"Audit Stage 9 benchmark gate failed: {code}.")
        elif track == "loop":
            assert loop_capstone_evaluation is not None
            metrics = loop_capstone_evaluation
            if capstone_attestation is None or capstone_attestation.get("valid") is not True:
                hard_blocks.append(
                    "Loop Stage 9 requires a current independently signed assessor attestation bound to the exact attempt and unseen challenge subject."
                )
            if not blind_capstone or metrics["p0Total"] <= 0 or metrics["p0Found"] != metrics["p0Total"]:
                hard_blocks.append("Loop Stage 9 capstone must be blind and catch every seeded P0 finding.")
            if metrics["p1Total"] <= 0 or metrics["p1Found"] / metrics["p1Total"] < 0.8:
                hard_blocks.append("Loop Stage 9 capstone must catch at least 80 percent of seeded P1 findings.")
            if metrics["continuationDecisionCorrect"] is not True:
                hard_blocks.append("Loop Stage 9 capstone requires the correct continuation decision.")
            if metrics["releaseDecisionCorrect"] is not True:
                hard_blocks.append("Loop Stage 9 capstone requires the correct release go/no-go decision.")
            if metrics["recoveryVerified"] is not True:
                hard_blocks.append("Loop Stage 9 capstone requires independently verified recovery.")
            if metrics["evidenceComplete"] is not True:
                hard_blocks.append("Loop Stage 9 capstone requires a complete evidence dossier.")
        else:
            capstone = args.get("capstone_results") or {}
            p0_total = int(capstone.get("p0_total") or 0)
            p0_found = int(capstone.get("p0_found") or 0)
            p1_total = int(capstone.get("p1_total") or 0)
            p1_found = int(capstone.get("p1_found") or 0)
            if not blind_capstone or p0_total <= 0 or p0_found != p0_total:
                hard_blocks.append("Stage 9 capstone must be blind and catch every seeded P0 finding.")
            if p1_total <= 0 or p1_found / p1_total < 0.8:
                hard_blocks.append("Stage 9 capstone must catch at least 80 percent of seeded P1 findings.")
            if capstone.get("release_decision_correct") is not True:
                hard_blocks.append("Stage 9 capstone requires the correct release go/no-go decision.")

    eligible = (
        not hard_blocks
        and assistance in {"independent", "independent_teach"}
        and score >= (90 if stage_number == 9 else 80)
        and demonstrated_level >= 3
    )
    attempt = {
        "attemptedAt": now_iso(),
        "track": track,
        "stage": stage_number,
        "drillId": drill_id,
        "exerciseType": drill["type"],
        "assistanceLevel": assistance,
        "assessor": assessor,
        "assessorCitations": citations,
        "assessment": component_scores,
        "score": score,
        "rawLevel": raw_level,
        "demonstratedLevel": demonstrated_level,
        "artifacts": artifacts,
        "projectState": state,
        "qaEvidence": qa_verifications,
        "performanceEvidence": performance_evidence,
        "adversarialEvidence": adversarial_evidence,
        "securityEvidence": security_verification,
        "auditEvidence": audit_verification,
        "stage0SecurityEvaluation": stage0_security_evaluation,
        "stage1RepositoryMapEvaluation": stage1_repository_map_evaluation,
        "stage2CorrectnessEvaluation": stage2_correctness_evaluation,
        "stage3ThreatModelEvaluation": stage3_threat_model_evaluation,
        "stage4ArchitectureEvaluation": stage4_architecture_evaluation,
        "stage5PerformanceEvaluation": stage5_performance_evaluation,
        "stage6SupplyChainEvaluation": stage6_supply_chain_evaluation,
        "stage7AdversarialEvaluation": stage7_adversarial_evaluation,
        "stage8EnterpriseLeadEvaluation": stage8_enterprise_lead_evaluation,
        "curriculumDigest": mastery_curriculum_digest(curriculum),
        "capstoneResults": args.get("capstone_results") if stage_number == 9 and track == "engineering" else None,
        "benchmarkEvaluation": benchmark_evaluation,
        "loopCapstoneEvaluation": loop_capstone_evaluation,
        "capstoneAttestation": capstone_attestation,
        "hardGateFailures": list(dict.fromkeys(hard_blocks)),
        "blindCapstone": blind_capstone,
        "eligibleForAdvancement": eligible,
    }
    track_state["attempts"].append(attempt)
    track_state["attempts"] = track_state["attempts"][-500:]
    advancement = advancement_status(profile, stage_number, track)
    if advancement["passed"] and stage_number not in track_state["completedStages"]:
        track_state["completedStages"].append(stage_number)
        if stage_number < 9:
            track_state["currentStage"] = stage_number + 1
        else:
            track_state["masteredAt"] = now_iso()
    profile["activeTrack"] = track
    profile["updatedAt"] = now_iso()
    atomic_write_json(mastery_profile_path(), profile)
    return {
        "recorded": True,
        "attempt": attempt,
        "advanced": advancement["passed"],
        "status": tool_mastery_status({"track": track}),
        "recordType": "Local deliberate-practice record; advancement is only as trustworthy as the independent assessor evidence.",
    }


def tool_runtime_status(args: dict[str, Any]) -> dict[str, Any]:
    project_path = args.get("project_path")
    if project_path:
        binding = resolve_project_binding(str(project_path))
    else:
        binding = {
            "mode": "unbound",
            "evidenceMode": "unbound",
            "requestedPath": None,
            "projectPath": None,
            "gitRoot": None,
            "gitEvidenceAvailable": False,
            "gitEvidenceToolsAvailable": False,
            "releaseReadinessToolAvailable": False,
            "gitRequiredTools": GIT_REQUIRED_TOOLS,
            "blockedTools": [],
            "limitations": [],
            "diagnostic": "MCP mounted; no project binding was requested.",
        }
    return {
        "mcpMounted": True,
        "serverName": SERVER_NAME,
        "serverVersion": SERVER_VERSION,
        "transport": "stdio-jsonl",
        "sessionId": SERVER_SESSION_ID,
        "projectBinding": binding,
        "actionSafety": {
            "mode": "host-native",
            "customApprovalProtocol": False,
            "approvalTokenRequired": False,
            "terminalApprovalRequired": False,
            "rule": "JStack relies on explicit user scope and the host/provider's normal permissions; it never asks the user to generate or paste an approval token or terminal command.",
        },
        "diagnostic": binding["diagnostic"],
    }


def tool_detect_project(args: dict[str, Any]) -> dict[str, Any]:
    binding = resolve_project_binding(args.get("project_path"))
    project_path = Path(binding["projectPath"])
    g_root = find_gstack_root()
    j_root = find_jstack_root()
    bin_dir = gstack_bin()
    project_config_paths = [
        project_path / ".jstack" / "project.yaml",
        project_path / ".jstack" / "project.yml",
        project_path / ".jstack" / "project.json",
        project_path / "jstack.yaml",
        project_path / "jstack.yml",
        project_path / ".gstack" / "project.yaml",
        project_path / ".gstack" / "project.yml",
        project_path / ".gstack" / "project.json",
        project_path / "gstack.yaml",
        project_path / "gstack.yml",
    ]
    project_config = [str(path) for path in project_config_paths if path.exists()]
    product_interface = (
        _ui_applicability(project_path)
        if binding["evidenceMode"] == "git"
        else {
            "schemaVersion": "jstack.ui.applicability.v1",
            "state": "unavailable",
            "reason": "git-required",
            "detection": None,
        }
    )
    return {
        **binding,
        "jstackRoot": str(j_root) if j_root else None,
        "jstackInstalled": bool(j_root),
        "gstackRoot": str(g_root) if g_root else None,
        "gstackBin": str(bin_dir) if bin_dir else None,
        "gstackInstalled": bool(g_root),
        "upstreamGstackOptional": True,
        "skillCount": len(skill_files()),
        "projectConfig": project_config,
        "testCommands": discover_test_commands(project_path),
        "productInterface": product_interface,
    }


def tool_list_skills(args: dict[str, Any]) -> dict[str, Any]:
    query = str(args.get("query") or "").lower().strip()
    limit = int(args.get("limit") or 40)
    skills = [parse_skill(path) for path in skill_files()]
    if query:
        skills = [
            skill
            for skill in skills
            if query in skill["name"].lower()
            or query in skill["directory"].lower()
            or query in skill["description"].lower()
        ]
    return {"count": len(skills), "skills": skills[: max(1, min(limit, 100))]}


def tool_read_skill(args: dict[str, Any]) -> dict[str, Any]:
    skill_name = str(args.get("skill_name") or "").strip()
    if not skill_name:
        raise ToolError("skill_name is required, for example 'qa' or 'review'.")
    for path in skill_files():
        parsed = parse_skill(path)
        names = {parsed["name"].lower(), parsed["directory"].lower()}
        if skill_name.lower() in names:
            text = path.read_text(encoding="utf-8", errors="replace")
            return {
                "skill": parsed,
                "content": truncate(text, int(args.get("max_chars") or 20_000)),
            }
    raise ToolError(f"Unknown upstream gstack skill: {skill_name}. Use jstack_list_skills first.")


def context_goal_digest(goal: str) -> str:
    normalized = " ".join(goal.split())
    return context_readiness_core.canonical_digest({"goal": normalized})


def context_workflow_for_team_mode(team_mode: str) -> str:
    return {
        "single-lead": "j-stack-dev",
        "smart-subagents": "jstack-subagents",
        "full-team": "jstack-full-team",
    }.get(team_mode, "j-stack-dev")


def context_risk_tier(goal: str, requested: Any = None) -> str:
    value = str(requested or "").strip().lower()
    if value:
        if value not in {"low", "medium", "high", "critical"}:
            raise ToolError("risk_tier must be low, medium, high, or critical.")
    requested_tier = value or "low"
    classification_ids = {str(item["id"]) for item in classify_work(goal)}
    if classification_ids & {"security_compliance", "data_financial", "production_release"}:
        derived_tier = "high"
    elif classification_ids & {"architecture", "ui_product"}:
        derived_tier = "medium"
    else:
        derived_tier = "low"
    tiers = list(context_readiness_core.RISK_TIERS)
    return tiers[max(tiers.index(requested_tier), tiers.index(derived_tier))]


def context_payload(args: dict[str, Any]) -> dict[str, Any]:
    value = args.get("context") or {}
    if not isinstance(value, dict):
        raise ToolError("context must be an object.")
    return value


def context_project_inspection(binding: dict[str, Any]) -> dict[str, Any]:
    detected = tool_detect_project({"project_path": binding["requestedPath"]})
    return {
        "projectPath": detected.get("projectPath"),
        "gitRoot": detected.get("gitRoot"),
        "evidenceMode": detected.get("evidenceMode"),
        "projectConfig": detected.get("projectConfig") or [],
        "testCommands": detected.get("testCommands") or [],
        "jstackInstalled": bool(detected.get("jstackInstalled")),
        "inspectionRule": "Inspect repository instructions, configuration, stack, and relevant files before asking the user.",
    }


PROMPT_COMPILER_WORKFLOW_MODES = prompt_compiler_core.WORKFLOW_MODES


def _prompt_context_workflow(workflow_mode: str) -> str:
    return "j-stack-dev" if workflow_mode == "jstack-evidence-builder" else workflow_mode


def _prompt_mode() -> str:
    try:
        return prompt_compiler_core.compiler_mode()
    except ValueError as exc:
        raise ToolError(str(exc)) from exc


def _prompt_binding(binding: dict[str, Any]) -> dict[str, Any]:
    result: dict[str, Any] = {
        "evidenceMode": binding["evidenceMode"],
        "projectPath": binding["projectPath"],
        "toolVersion": SERVER_VERSION,
    }
    if binding["evidenceMode"] == "git":
        subject = evidence_subject(Path(binding["gitRoot"]))
        result.update(
            {
                "gitHead": subject["gitHead"],
                "projectFingerprint": subject["projectFingerprint"],
                "policyDigest": subject["policyDigest"],
            }
        )
    else:
        result["policyDigest"] = None
    return result


def _prompt_source_kind(value: str) -> str:
    return {
        "user": "explicit-user",
        "repository": "repository",
        "policy": "policy",
        "external-evidence": "external-evidence",
        "inferred": "inference",
    }.get(value, "inference")


def _prompt_grounding_from_readiness(
    intent: dict[str, Any], readiness: dict[str, Any]
) -> dict[str, Any]:
    sources = [
        {
            "field": item["field"],
            "value": item["value"],
            "source_kind": _prompt_source_kind(item["sourceKind"]),
            "source_reference": item["sourceReference"],
        }
        for item in readiness.get("sourceMap") or []
    ]
    sources.extend(
        {
            "field": item["field"],
            "value": item["value"],
            "source_kind": "recommended-assumption",
            "source_reference": item.get("rationale")
            or "Adaptive Context Gate disclosed assumption",
        }
        for item in readiness.get("assumptions") or []
    )
    requirements = [
        {
            "id": "user-goal",
            "category": "scope",
            "statement": intent["normalizedGoal"],
            "material": True,
            "status": "required",
            "source_kind": "explicit-user",
            "source_reference": "raw-prompt-sha256:" + intent["rawPromptDigest"],
        }
    ]
    for index, constraint in enumerate(intent.get("explicitConstraints") or []):
        requirements.append(
            {
                "id": "user-constraint-%02d" % (index + 1),
                "category": "scope",
                "statement": constraint,
                "material": True,
                "status": "required",
                "source_kind": "explicit-user",
                "source_reference": "raw-prompt-sha256:" + intent["rawPromptDigest"],
            }
        )
    facts = {str(item["field"]): str(item["value"]) for item in readiness.get("sourceMap") or []}
    acceptance = [facts["acceptance_criteria"]] if facts.get("acceptance_criteria") else []
    verification = [facts["verification_requirements"]] if facts.get("verification_requirements") else []
    rollback = [facts["rollback_requirements"]] if facts.get("rollback_requirements") else []
    return {
        "sources": sources,
        "requirements": requirements,
        "unknowns": [str(item.get("question") or "") for item in readiness.get("questions") or [] if item.get("question")],
        "contradictions": [],
        "acceptance_criteria": acceptance,
        "verification_requirements": verification,
        "rollback_requirements": rollback,
        "likely_in_scope": list((intent.get("namedReferences") or {}).get("paths") or []),
        "explicitly_out_of_scope": list(intent.get("explicitNonGoals") or []),
        "recommended_defaults": [str(item.get("value") or "") for item in readiness.get("defaultsApplied") or [] if item.get("value")],
    }


def _prompt_intent_questions(intent: dict[str, Any]) -> list[dict[str, Any]]:
    questions: list[dict[str, Any]] = []
    for ambiguity in intent.get("materialAmbiguities") or []:
        ambiguity_id = str(ambiguity.get("id") or "")
        if ambiguity_id == "task-mode":
            questions.append(
                {
                    "id": "task_mode",
                    "question": "What action should JStack perform: explain, plan, diagnose, implement, review, or another explicitly named mode?",
                    "why": "Different task modes grant materially different repository and external-action authority.",
                    "recommended_default": "Explain or research only without repository changes.",
                    "material": True,
                }
            )
        elif ambiguity_id == "deployment-contradiction":
            questions.append(
                {
                    "id": "deployment_authority",
                    "question": "Should deployment remain prohibited or is deployment explicitly authorized after implementation succeeds?",
                    "why": "The request contains contradictory deployment authority.",
                    "recommended_default": "Keep deployment prohibited.",
                    "material": True,
                }
            )
    return questions


def _assess_prompt_context(
    *,
    goal: str,
    workflow_mode: str,
    risk_tier: str,
    context: dict[str, Any],
    workflow_parameters: Any,
    use_recommended_defaults: bool,
    confirm_material_inferences: bool,
    intent: dict[str, Any],
) -> dict[str, Any]:
    supplied_questions = list(context.get("open_questions") or [])
    supplied_questions.extend(_prompt_intent_questions(intent))
    try:
        return context_readiness_core.assess_context(
            goal=goal,
            workflow_mode=workflow_mode,
            risk_tier=risk_tier,
            facts=context.get("facts") or [],
            assumptions=context.get("assumptions") or [],
            open_questions=supplied_questions,
            workflow_parameters=workflow_parameters or {},
            use_recommended_defaults=use_recommended_defaults,
            confirm_material_inferences=confirm_material_inferences,
        )
    except ValueError as exc:
        raise ToolError(str(exc)) from exc


def _issue_context_readiness(
    *,
    result: dict[str, Any],
    goal: str,
    workflow_mode: str,
    binding: dict[str, Any],
    compilation: Optional[dict[str, Any]],
) -> None:
    expires = (
        _dt.datetime.now(_dt.timezone.utc)
        + _dt.timedelta(seconds=GOAL_READINESS_RECEIPT_MAX_AGE_SECONDS)
    ).replace(microsecond=0)
    binding_metadata = _prompt_binding(binding)
    receipt_payload: dict[str, Any] = {
        "kind": "context-readiness",
        "schemaVersion": context_readiness_core.CONTEXT_READINESS_SCHEMA,
        "expiresAt": expires.isoformat(),
        "goalDigest": context_goal_digest(goal),
        "briefDigest": result["briefDigest"],
        "workflowMode": workflow_mode,
        "riskTier": result["riskTier"],
        "state": result["state"],
        **binding_metadata,
        "promptCompilerMode": _prompt_mode(),
    }
    if compilation is not None:
        receipt_payload.update(
            {
                "promptCompilationDigest": compilation["compilationDigest"],
                "rawPromptDigest": compilation["rawPromptDigest"],
                "requestedTaskMode": compilation["requestedTaskMode"],
                "compilerVersion": compilation["compilerVersion"],
                "promptTemplateVersion": compilation["templateVersion"],
                "materialExternalEvidenceDigest": compilation.get(
                    "materialExternalEvidenceDigest"
                ),
            }
        )
    result["readinessReceipt"] = issue_receipt(receipt_payload)


def _issue_prompt_intent_receipt(intent: dict[str, Any]) -> str:
    expires = (
        _dt.datetime.now(_dt.timezone.utc)
        + _dt.timedelta(seconds=GOAL_READINESS_RECEIPT_MAX_AGE_SECONDS)
    ).replace(microsecond=0)
    return issue_receipt(
        {
            "kind": "prompt-intent",
            "schemaVersion": prompt_compiler_core.INTENT_SCHEMA,
            "expiresAt": expires.isoformat(),
            "intentDigest": intent["intentDigest"],
            "rawPromptDigest": intent["rawPromptDigest"],
            "workflowMode": intent["workflowMode"],
            "requestedTaskMode": intent["requestedTaskMode"],
            "compilerMode": intent["compilerMode"],
            "compilerVersion": intent["compilerVersion"],
            "templateVersion": intent["templateVersion"],
        }
    )


def _verify_prompt_intent_receipt(receipt: Any, intent: Any) -> dict[str, Any]:
    if not isinstance(receipt, str) or not receipt or len(receipt) > 100_000:
        raise ToolError("A bounded intent_receipt from Prompt Compiler Stage A is required.")
    if not isinstance(intent, dict):
        raise ToolError("intent_contract from Prompt Compiler Stage A is required.")
    payload = verify_signed_session_token(receipt, "prompt-intent")
    without_digest = {key: value for key, value in intent.items() if key != "intentDigest"}
    checks = {
        "schemaVersion": payload.get("schemaVersion")
        == prompt_compiler_core.INTENT_SCHEMA
        == intent.get("schemaVersion"),
        "intentDigest": payload.get("intentDigest")
        == intent.get("intentDigest")
        == prompt_compiler_core.canonical_digest(without_digest),
        "rawPromptDigest": payload.get("rawPromptDigest")
        == intent.get("rawPromptDigest"),
        "workflowMode": payload.get("workflowMode") == intent.get("workflowMode"),
        "requestedTaskMode": payload.get("requestedTaskMode")
        == intent.get("requestedTaskMode"),
        "compilerMode": payload.get("compilerMode") == intent.get("compilerMode") == _prompt_mode(),
        "compilerVersion": payload.get("compilerVersion")
        == prompt_compiler_core.COMPILER_VERSION,
        "templateVersion": payload.get("templateVersion")
        == prompt_compiler_core.TEMPLATE_VERSION,
    }
    if not all(checks.values()):
        raise ToolError(
            "Prompt Compiler intent receipt is stale or does not match the supplied intent contract and current compiler configuration."
        )
    return {"verified": True, "checks": checks, "payload": payload}


def _prompt_compilation_core(contract: dict[str, Any]) -> dict[str, Any]:
    return {
        key: value
        for key, value in contract.items()
        if key
        not in {
            "compilationDigest",
            "compilationReceipt",
            "promptPreviewReceipt",
            "contextReadiness",
        }
    }


def _verify_prompt_compilation_receipt(
    receipt: Any,
    contract: Any,
    *,
    workflow_mode: str,
    binding: dict[str, Any],
    expected_goal: str,
) -> dict[str, Any]:
    if not isinstance(receipt, str) or not receipt or len(receipt) > 250_000:
        raise ToolError(
            "A bounded prompt_compilation_receipt from Prompt Compiler Stage B is required."
        )
    if not isinstance(contract, dict):
        raise ToolError(
            "prompt_contract must be the exact approved jstack.prompt-compilation.v2 object returned by Stage B."
        )
    payload = verify_signed_session_token(receipt, "prompt-compilation")
    binding_metadata = _prompt_binding(binding)
    compilation_digest = prompt_compiler_core.canonical_digest(
        _prompt_compilation_core(contract)
    )
    rendered_prompt = contract.get("renderedCodexPrompt")
    rendered_digest = (
        hashlib.sha256(rendered_prompt.encode("utf-8")).hexdigest()
        if isinstance(rendered_prompt, str)
        else None
    )
    checks = {
        "schemaVersion": payload.get("schemaVersion")
        == contract.get("schemaVersion")
        == prompt_compiler_core.PROMPT_COMPILATION_SCHEMA,
        "compilationDigest": payload.get("compilationDigest")
        == contract.get("compilationDigest")
        == compilation_digest,
        "rawPromptDigest": payload.get("rawPromptDigest")
        == contract.get("rawPromptDigest"),
        "intentDigest": payload.get("intentDigest") == contract.get("intentDigest"),
        "renderedPromptSha256": payload.get("renderedPromptSha256")
        == contract.get("renderedPromptSha256")
        == rendered_digest,
        "workflowMode": payload.get("workflowMode")
        == contract.get("workflowMode")
        == workflow_mode,
        "goal": contract.get("normalizedGoal") == " ".join(expected_goal.split()),
        "requestedTaskMode": payload.get("requestedTaskMode")
        == contract.get("requestedTaskMode")
        and payload.get("requestedTaskMode") in prompt_compiler_core.TASK_MODES,
        "compilerMode": payload.get("compilerMode")
        == contract.get("compilerMode")
        == _prompt_mode(),
        "compilerVersion": payload.get("compilerVersion")
        == contract.get("compilerVersion")
        == prompt_compiler_core.COMPILER_VERSION,
        "templateVersion": payload.get("templateVersion")
        == contract.get("templateVersion")
        == prompt_compiler_core.TEMPLATE_VERSION,
        "ready": contract.get("readiness", {}).get("readyForPlanning") is True,
        "approval": contract.get("approval")
        == {
            "protocolVersion": prompt_compiler_core.PROMPT_APPROVAL_VERSION,
            "required": True,
            "state": "approved",
            "approved": True,
            "renderedPromptSha256": rendered_digest,
            "source": "active-conversation",
            "rule": (
                "Display the complete rendered prompt and wait for explicit approval "
                "in the active conversation before planning or implementation."
            ),
        },
        "approvedPromptSha256": payload.get("approvedPromptSha256")
        == rendered_digest,
        "promptApprovalSource": payload.get("promptApprovalSource")
        == "active-conversation",
    }
    for field, value in binding_metadata.items():
        checks[field] = payload.get(field) == value
    if not all(checks.values()):
        raise ToolError(
            "Prompt compilation receipt is stale or does not match the compiled contract, goal, workflow, project, policy, or compiler version."
        )
    return {
        "bound": True,
        "source": "explicit-stage-b",
        "compilationDigest": compilation_digest,
        "rawPromptDigest": contract["rawPromptDigest"],
        "requestedTaskMode": contract["requestedTaskMode"],
        "compilerVersion": contract["compilerVersion"],
        "templateVersion": contract["templateVersion"],
    }


def _prompt_orchestration_binding(
    args: dict[str, Any],
    *,
    goal: str,
    workflow_mode: str,
    binding: dict[str, Any],
) -> Optional[dict[str, Any]]:
    mode = _prompt_mode()
    if mode == "disabled":
        return None
    receipt = args.get("prompt_compilation_receipt")
    contract = args.get("prompt_contract")
    if receipt is not None or contract is not None:
        if receipt is None or contract is None:
            raise ToolError(
                "prompt_compilation_receipt and prompt_contract must be supplied together."
            )
        return _verify_prompt_compilation_receipt(
            receipt,
            contract,
            workflow_mode=workflow_mode,
            binding=binding,
            expected_goal=goal,
        )

    # Backward-compatible direct callers still pass through the same
    # deterministic compiler. The explicit two-stage path is what can prove
    # pre-inspection ordering; this bridge can bind intent but cannot claim it.
    try:
        intent = prompt_compiler_core.compile_intent(
            raw_request=goal,
            workflow_mode=workflow_mode,
            compiler_mode_value=mode,
        )
        readiness = {
            "state": "ready",
            "readyForPlanning": True,
            "briefDigest": hashlib.sha256(goal.encode("utf-8")).hexdigest(),
            "questionCount": 0,
            "materialGapCount": 0,
        }
        compilation = prompt_compiler_core.compile_grounded(
            intent=intent,
            workflow_mode=workflow_mode,
            risk_tier=context_risk_tier(goal, args.get("risk_tier")),
            grounding=_with_required_prompt_requirements(intent, {}),
            readiness=readiness,
            compiler_mode_value=mode,
        )
    except ValueError as exc:
        raise ToolError(str(exc)) from exc
    return {
        "bound": True,
        "source": "legacy-compatibility-bridge",
        "preInspectionOrderingProven": False,
        "compilationDigest": compilation["compilationDigest"],
        "rawPromptDigest": compilation["rawPromptDigest"],
        "requestedTaskMode": compilation["requestedTaskMode"],
        "compilerVersion": compilation["compilerVersion"],
        "templateVersion": compilation["templateVersion"],
    }


def _prompt_receipt_binding_fields(
    binding: Optional[dict[str, Any]],
) -> dict[str, Any]:
    result: dict[str, Any] = {"promptCompilerMode": _prompt_mode()}
    if binding is not None:
        result.update(
            {
                "promptCompilationDigest": binding["compilationDigest"],
                "rawPromptDigest": binding["rawPromptDigest"],
                "requestedTaskMode": binding["requestedTaskMode"],
                "compilerVersion": binding["compilerVersion"],
                "promptTemplateVersion": binding["templateVersion"],
                "promptCompilationSource": binding["source"],
            }
        )
    return result


def _prompt_receipt_binding_valid(payload: dict[str, Any]) -> bool:
    mode = _prompt_mode()
    if payload.get("promptCompilerMode") != mode:
        return False
    if mode == "disabled":
        return payload.get("promptCompilationDigest") is None
    return bool(
        re.fullmatch(
            r"[0-9a-f]{64}", str(payload.get("promptCompilationDigest") or "")
        )
        and re.fullmatch(
            r"[0-9a-f]{64}", str(payload.get("rawPromptDigest") or "")
        )
        and payload.get("requestedTaskMode") in prompt_compiler_core.TASK_MODES
        and payload.get("compilerVersion") == prompt_compiler_core.COMPILER_VERSION
        and payload.get("promptTemplateVersion")
        == prompt_compiler_core.TEMPLATE_VERSION
        and payload.get("promptCompilationSource")
        in {"explicit-stage-b", "legacy-compatibility-bridge"}
    )


def _grounding_context(grounding: Any, supplied: dict[str, Any]) -> dict[str, Any]:
    result = {
        "facts": list(supplied.get("facts") or []),
        "assumptions": list(supplied.get("assumptions") or []),
        "open_questions": list(supplied.get("open_questions") or []),
    }
    if not isinstance(grounding, dict):
        return result
    for source in grounding.get("sources") or []:
        if not isinstance(source, dict):
            continue
        kind = str(source.get("source_kind") or source.get("sourceKind") or "")
        mapped = {
            "explicit-user": "user",
            "repository": "repository",
            "policy": "policy",
            "external-evidence": "external-evidence",
            "inference": "inferred",
        }.get(kind)
        if mapped:
            result["facts"].append(
                {
                    "field": source.get("field"),
                    "value": source.get("value"),
                    "source_kind": mapped,
                    "source_reference": source.get("source_reference")
                    or source.get("sourceReference"),
                }
            )
        elif kind == "recommended-assumption":
            result["assumptions"].append(
                {
                    "field": source.get("field"),
                    "value": source.get("value"),
                    "rationale": source.get("source_reference")
                    or source.get("sourceReference")
                    or "Prompt Compiler recommended assumption",
                    "material": True,
                }
            )
    return result


def _with_required_prompt_requirements(
    intent: dict[str, Any], grounding: Any
) -> dict[str, Any]:
    value = dict(grounding) if isinstance(grounding, dict) else {}
    requirements = list(value.get("requirements") or [])
    existing_ids = {
        str(item.get("id") or "") for item in requirements if isinstance(item, dict)
    }
    if "user-goal" not in existing_ids:
        requirements.insert(
            0,
            {
                "id": "user-goal",
                "category": "scope",
                "statement": intent["normalizedGoal"],
                "material": True,
                "status": "required",
                "source_kind": "explicit-user",
                "source_reference": "raw-prompt-sha256:" + intent["rawPromptDigest"],
            },
        )
    value["requirements"] = requirements
    return value


def _issue_prompt_preview_receipt(
    *,
    compilation: dict[str, Any],
    binding: dict[str, Any],
    context_workflow: str,
) -> str:
    expires = (
        _dt.datetime.now(_dt.timezone.utc)
        + _dt.timedelta(seconds=GOAL_READINESS_RECEIPT_MAX_AGE_SECONDS)
    ).replace(microsecond=0)
    return issue_receipt(
        {
            "kind": "prompt-preview",
            "schemaVersion": prompt_compiler_core.PROMPT_COMPILATION_SCHEMA,
            "expiresAt": expires.isoformat(),
            "draftCompilationDigest": compilation["compilationDigest"],
            "rawPromptDigest": compilation["rawPromptDigest"],
            "intentDigest": compilation["intentDigest"],
            "renderedPromptSha256": compilation["renderedPromptSha256"],
            "requestedTaskMode": compilation["requestedTaskMode"],
            "workflowMode": compilation["workflowMode"],
            "contextWorkflowMode": context_workflow,
            "riskTier": compilation["riskTier"],
            "briefDigest": compilation["readiness"]["briefDigest"],
            "compilerMode": compilation["compilerMode"],
            "compilerVersion": compilation["compilerVersion"],
            "templateVersion": compilation["templateVersion"],
            **_prompt_binding(binding),
        }
    )


def _verify_prompt_preview_receipt(
    receipt: Any,
    compilation: dict[str, Any],
    *,
    binding: dict[str, Any],
    context_workflow: str,
) -> None:
    if not isinstance(receipt, str) or not receipt or len(receipt) > 250_000:
        raise ToolError(
            "A bounded prompt_preview_receipt from the prior final-prompt preview is required."
        )
    payload = verify_signed_session_token(receipt, "prompt-preview")
    checks = {
        "schemaVersion": payload.get("schemaVersion")
        == compilation.get("schemaVersion")
        == prompt_compiler_core.PROMPT_COMPILATION_SCHEMA,
        "draftCompilationDigest": payload.get("draftCompilationDigest")
        == compilation.get("compilationDigest"),
        "rawPromptDigest": payload.get("rawPromptDigest")
        == compilation.get("rawPromptDigest"),
        "intentDigest": payload.get("intentDigest")
        == compilation.get("intentDigest"),
        "renderedPromptSha256": payload.get("renderedPromptSha256")
        == compilation.get("renderedPromptSha256"),
        "requestedTaskMode": payload.get("requestedTaskMode")
        == compilation.get("requestedTaskMode"),
        "workflowMode": payload.get("workflowMode")
        == compilation.get("workflowMode"),
        "contextWorkflowMode": payload.get("contextWorkflowMode")
        == context_workflow,
        "riskTier": payload.get("riskTier") == compilation.get("riskTier"),
        "briefDigest": payload.get("briefDigest")
        == compilation.get("readiness", {}).get("briefDigest"),
        "compilerMode": payload.get("compilerMode")
        == compilation.get("compilerMode")
        == _prompt_mode(),
        "compilerVersion": payload.get("compilerVersion")
        == compilation.get("compilerVersion")
        == prompt_compiler_core.COMPILER_VERSION,
        "templateVersion": payload.get("templateVersion")
        == compilation.get("templateVersion")
        == prompt_compiler_core.TEMPLATE_VERSION,
        "awaitingApproval": compilation.get("approval", {}).get("state")
        == "awaiting-user",
    }
    for field, value in _prompt_binding(binding).items():
        checks[field] = payload.get(field) == value
    if not all(checks.values()):
        raise ToolError(
            "Prompt preview receipt is stale or does not match the exact rendered prompt, task, workflow, project, policy, or compiler configuration. Display the new prompt and request approval again."
        )


def _apply_prompt_approval(
    compilation: dict[str, Any],
    readiness: dict[str, Any],
    approval: Any,
) -> None:
    if not isinstance(approval, dict) or set(approval) != {
        "approved",
        "rendered_prompt_sha256",
        "source",
    }:
        raise ToolError(
            "prompt_approval must contain only approved, rendered_prompt_sha256, and source."
        )
    if approval.get("approved") is not True:
        raise ToolError(
            "prompt_approval.approved must be true only after explicit approval in the active conversation."
        )
    if approval.get("source") != "active-conversation":
        raise ToolError(
            "prompt_approval.source must be active-conversation; approval cannot be inferred from a receipt, default, or tool result."
        )
    approved_digest = str(approval.get("rendered_prompt_sha256") or "")
    if approved_digest != compilation.get("renderedPromptSha256"):
        raise ToolError(
            "The approved prompt digest does not match the current rendered prompt. Display the new prompt and request approval again."
        )
    if not readiness.get("readyForPlanning"):
        raise ToolError(
            "The compiled prompt cannot be approved until all material context questions and confirmations are resolved."
        )
    compilation["approval"] = {
        "protocolVersion": prompt_compiler_core.PROMPT_APPROVAL_VERSION,
        "required": True,
        "state": "approved",
        "approved": True,
        "renderedPromptSha256": approved_digest,
        "source": "active-conversation",
        "rule": (
            "Display the complete rendered prompt and wait for explicit approval "
            "in the active conversation before planning or implementation."
        ),
    }
    compilation["readiness"] = {
        "state": readiness.get("state"),
        "readyForPlanning": True,
        "briefDigest": readiness.get("briefDigest"),
        "questionCount": int(readiness.get("questionCount") or 0),
        "materialGapCount": int(readiness.get("materialGapCount") or 0),
    }
    compilation["compilationDigest"] = prompt_compiler_core.canonical_digest(
        _prompt_compilation_core(compilation)
    )


def tool_prompt_compile(args: dict[str, Any]) -> dict[str, Any]:
    stage = str(args.get("stage") or "").strip().lower()
    workflow_mode = str(args.get("workflow_mode") or "").strip()
    if workflow_mode not in PROMPT_COMPILER_WORKFLOW_MODES:
        raise ToolError(
            "workflow_mode must identify one of the six public JStack workflows."
        )
    if stage == "intent":
        try:
            intent = prompt_compiler_core.compile_intent(
                raw_request=args.get("raw_request"),
                workflow_mode=workflow_mode,
                compiler_mode_value=_prompt_mode(),
            )
        except ValueError as exc:
            raise ToolError(str(exc)) from exc
        return {
            "stage": "intent",
            "intentContract": intent,
            "intentReceipt": _issue_prompt_intent_receipt(intent),
            "receiptMeaning": (
                "Digest-only session proof of pre-inspection intent normalization; it grants no repository read, write, Git, external, release, deployment, or production authority."
            ),
        }
    if stage != "grounded":
        raise ToolError("stage must be intent or grounded.")
    intent = args.get("intent_contract")
    _verify_prompt_intent_receipt(args.get("intent_receipt"), intent)
    if intent.get("workflowMode") != workflow_mode:
        raise ToolError("workflow_mode must match the Stage A intent contract.")
    binding = resolve_project_binding(args.get("project_path"))
    grounding = _with_required_prompt_requirements(intent, args.get("grounding"))
    context = _grounding_context(grounding, context_payload(args))
    context_workflow = _prompt_context_workflow(workflow_mode)
    risk_tier = context_risk_tier(intent["normalizedGoal"], args.get("risk_tier"))
    readiness = _assess_prompt_context(
        goal=intent["normalizedGoal"],
        workflow_mode=context_workflow,
        risk_tier=risk_tier,
        context=context,
        workflow_parameters=args.get("workflow_parameters") or {},
        use_recommended_defaults=bool(args.get("use_recommended_defaults", False)),
        confirm_material_inferences=bool(args.get("confirm_material_inferences", False)),
        intent=intent,
    )
    readiness["projectBinding"] = binding
    readiness["projectInspection"] = context_project_inspection(binding)
    try:
        compilation = prompt_compiler_core.compile_grounded(
            intent=intent,
            workflow_mode=workflow_mode,
            risk_tier=readiness["riskTier"],
            grounding=grounding,
            readiness=readiness,
            compiler_mode_value=_prompt_mode(),
        )
    except ValueError as exc:
        raise ToolError(str(exc)) from exc
    approval = args.get("prompt_approval")
    preview_receipt = args.get("prompt_preview_receipt")
    if approval is None and preview_receipt is not None:
        raise ToolError(
            "prompt_preview_receipt is accepted only with prompt_approval after the user approves the displayed prompt."
        )
    if approval is not None and not readiness["readyForPlanning"]:
        raise ToolError(
            "The compiled prompt cannot be approved until all material context questions and confirmations are resolved."
        )
    if readiness["readyForPlanning"]:
        binding_before = _prompt_binding(binding)
        if approval is None:
            compilation["promptPreviewReceipt"] = _issue_prompt_preview_receipt(
                compilation=compilation,
                binding=binding,
                context_workflow=context_workflow,
            )
        else:
            _verify_prompt_preview_receipt(
                preview_receipt,
                compilation,
                binding=binding,
                context_workflow=context_workflow,
            )
            _apply_prompt_approval(compilation, readiness, approval)
            _issue_context_readiness(
                result=readiness,
                goal=intent["normalizedGoal"],
                workflow_mode=context_workflow,
                binding=binding,
                compilation=compilation,
            )
        binding_after = _prompt_binding(binding)
        if binding_after != binding_before:
            raise ToolError(
                "The project or policy changed during prompt compilation. Re-run both compilation stages."
            )
        if approval is not None:
            expires = (
                _dt.datetime.now(_dt.timezone.utc)
                + _dt.timedelta(seconds=GOAL_READINESS_RECEIPT_MAX_AGE_SECONDS)
            ).replace(microsecond=0)
            compilation["compilationReceipt"] = issue_receipt(
                {
                    "kind": "prompt-compilation",
                    "schemaVersion": prompt_compiler_core.PROMPT_COMPILATION_SCHEMA,
                    "expiresAt": expires.isoformat(),
                    "compilationDigest": compilation["compilationDigest"],
                    "rawPromptDigest": compilation["rawPromptDigest"],
                    "intentDigest": compilation["intentDigest"],
                    "renderedPromptSha256": compilation["renderedPromptSha256"],
                    "approvedPromptSha256": compilation["renderedPromptSha256"],
                    "promptApprovalSource": "active-conversation",
                    "requestedTaskMode": compilation["requestedTaskMode"],
                    "workflowMode": workflow_mode,
                    "contextWorkflowMode": context_workflow,
                    "riskTier": compilation["riskTier"],
                    "briefDigest": readiness["briefDigest"],
                    "compilerMode": compilation["compilerMode"],
                    "compilerVersion": compilation["compilerVersion"],
                    "templateVersion": compilation["templateVersion"],
                    **binding_after,
                }
            )
    compilation["contextReadiness"] = readiness
    return compilation


def tool_context_readiness(args: dict[str, Any]) -> dict[str, Any]:
    goal = str(args.get("goal") or "").strip()
    if not goal:
        raise ToolError("goal is required.")
    workflow_mode = str(args.get("workflow_mode") or "j-stack-dev").strip()
    if workflow_mode not in context_readiness_core.WORKFLOW_MODES:
        raise ToolError(
            "workflow_mode must be j-stack-dev, jstack-subagents, jstack-full-team, jstack-audit, or jstack-loop."
        )
    try:
        intent = prompt_compiler_core.compile_intent(
            raw_request=goal,
            workflow_mode=workflow_mode,
            compiler_mode_value=_prompt_mode(),
        )
    except ValueError as exc:
        raise ToolError(str(exc)) from exc
    binding = resolve_project_binding(args.get("project_path"))
    context = context_payload(args)
    result = _assess_prompt_context(
        goal=goal,
        workflow_mode=workflow_mode,
        risk_tier=context_risk_tier(goal, args.get("risk_tier")),
        context=context,
        workflow_parameters=args.get("workflow_parameters") or {},
        use_recommended_defaults=bool(args.get("use_recommended_defaults", False)),
        confirm_material_inferences=bool(args.get("confirm_material_inferences", False)),
        intent=intent,
    )
    result["projectBinding"] = binding
    result["projectInspection"] = context_project_inspection(binding)
    if result["readyForPlanning"]:
        compilation = None
        if _prompt_mode() != "disabled":
            try:
                compilation = prompt_compiler_core.compile_grounded(
                    intent=intent,
                    workflow_mode=workflow_mode,
                    risk_tier=result["riskTier"],
                    grounding=_prompt_grounding_from_readiness(intent, result),
                    readiness=result,
                    compiler_mode_value=_prompt_mode(),
                )
            except ValueError as exc:
                raise ToolError(str(exc)) from exc
        _issue_context_readiness(
            result=result,
            goal=goal,
            workflow_mode=workflow_mode,
            binding=binding,
            compilation=compilation,
        )
    return result


def verify_context_readiness_receipt(
    receipt: str,
    *,
    goal: str,
    workflow_mode: str,
    binding: dict[str, Any],
    context_brief: Any,
) -> dict[str, Any]:
    if not isinstance(context_brief, dict):
        raise ToolError(
            "context_brief returned by jstack_context_readiness is required with a context readiness receipt."
        )
    try:
        validate_schema_value(context_brief, CONTEXT_NORMALIZED_BRIEF_SCHEMA)
    except InputError as exc:
        raise ToolError(f"context_brief is invalid: {exc}") from exc
    payload = verify_signed_session_token(receipt, "context-readiness")
    current_prompt_mode = _prompt_mode()
    checks = {
        "schemaVersion": payload.get("schemaVersion")
        == context_readiness_core.CONTEXT_READINESS_SCHEMA,
        "goalDigest": payload.get("goalDigest") == context_goal_digest(goal),
        "workflowMode": payload.get("workflowMode") == workflow_mode,
        "evidenceMode": payload.get("evidenceMode") == binding["evidenceMode"],
        "projectPath": payload.get("projectPath") == binding["projectPath"],
        "toolVersion": payload.get("toolVersion") == SERVER_VERSION,
        "readyState": payload.get("state") in {"ready", "proceed_with_assumptions"},
        "briefDigest": payload.get("briefDigest")
        == context_readiness_core.canonical_digest(context_brief),
        "briefGoal": context_brief.get("goal") == " ".join(goal.split()),
        "briefWorkflowMode": context_brief.get("workflowMode") == workflow_mode,
        "briefRiskTier": context_brief.get("riskTier") == payload.get("riskTier"),
        "promptCompilerMode": payload.get("promptCompilerMode")
        == current_prompt_mode,
    }
    if current_prompt_mode != "disabled":
        checks.update(
            {
                "promptCompilationDigest": bool(
                    re.fullmatch(
                        r"[0-9a-f]{64}",
                        str(payload.get("promptCompilationDigest") or ""),
                    )
                ),
                "rawPromptDigest": bool(
                    re.fullmatch(
                        r"[0-9a-f]{64}",
                        str(payload.get("rawPromptDigest") or ""),
                    )
                ),
                "requestedTaskMode": payload.get("requestedTaskMode")
                in prompt_compiler_core.TASK_MODES,
                "compilerVersion": payload.get("compilerVersion")
                == prompt_compiler_core.COMPILER_VERSION,
                "promptTemplateVersion": payload.get("promptTemplateVersion")
                == prompt_compiler_core.TEMPLATE_VERSION,
            }
        )
    if binding["evidenceMode"] == "git":
        subject = evidence_subject(Path(binding["gitRoot"]))
        checks["gitHead"] = payload.get("gitHead") == subject["gitHead"]
        checks["projectFingerprint"] = (
            payload.get("projectFingerprint") == subject["projectFingerprint"]
        )
        checks["policyDigest"] = payload.get("policyDigest") == subject["policyDigest"]
    if not all(checks.values()):
        raise ToolError(
            "Context readiness receipt is stale or does not match the current goal, workflow, project, or repository state. Re-run jstack_context_readiness."
        )
    return {
        "verified": True,
        "schemaVersion": payload["schemaVersion"],
        "state": payload["state"],
        "briefDigest": payload["briefDigest"],
        "riskTier": payload["riskTier"],
        "workflowMode": payload["workflowMode"],
        "normalizedBrief": context_brief,
        "promptCompilation": {
            "bound": current_prompt_mode != "disabled",
            "mode": current_prompt_mode,
            "compilationDigest": payload.get("promptCompilationDigest"),
            "rawPromptDigest": payload.get("rawPromptDigest"),
            "requestedTaskMode": payload.get("requestedTaskMode"),
            "compilerVersion": payload.get("compilerVersion"),
            "templateVersion": payload.get("promptTemplateVersion"),
        },
        "checks": checks,
    }


def audit_context_workflow_parameters(args: dict[str, Any]) -> dict[str, Any]:
    raw: dict[str, Any] = {}
    profile = str(args.get("profile") or "").strip()
    if profile:
        raw["profile"] = profile
    scope = args.get("scope")
    if isinstance(scope, list) and scope:
        raw["scope"] = scope
    focus = str(args.get("focus") or "").strip()
    if focus:
        raw["focus"] = focus
    base_ref = str(args.get("base_ref") or "").strip()
    if base_ref:
        raw["base_ref"] = base_ref
    try:
        return context_readiness_core.normalize_workflow_parameters(
            "jstack-audit", raw
        )
    except ValueError as exc:
        raise ToolError(str(exc)) from exc


def tool_plan(args: dict[str, Any]) -> dict[str, Any]:
    goal = str(args.get("goal") or "").strip()
    if not goal:
        raise ToolError("goal is required.")
    binding = resolve_project_binding(args.get("project_path"))
    quality_level = str(args.get("quality_level") or "enterprise").strip().lower()
    if quality_level not in {"standard", "enterprise"}:
        raise ToolError("quality_level must be 'standard' or 'enterprise'.")
    mastery_mode = bool(args.get("mastery_mode", True))
    learning_mode = str(args.get("learning_mode") or ("embedded" if mastery_mode else "off")).strip().lower()
    if learning_mode not in {"off", "embedded", "coach", "assessment"}:
        raise ToolError("learning_mode must be off, embedded, coach, or assessment.")
    if not mastery_mode:
        learning_mode = "off"
    team_mode = normalize_team_mode(args.get("team_mode") or "single-lead")
    workflow_mode = str(
        args.get("context_workflow_mode") or context_workflow_for_team_mode(team_mode)
    ).strip()
    if workflow_mode not in context_readiness_core.WORKFLOW_MODES:
        raise ToolError("context_workflow_mode is not supported.")
    context_readiness = None
    if args.get("context_readiness_receipt"):
        context_readiness = verify_context_readiness_receipt(
            str(args["context_readiness_receipt"]),
            goal=goal,
            workflow_mode=workflow_mode,
            binding=binding,
            context_brief=args.get("context_brief"),
        )
    capability_ids = args.get("capability_ids") or []
    classifications = classify_work(goal)
    detected = tool_detect_project({"project_path": binding["requestedPath"]})
    if binding["evidenceMode"] == "git":
        ui_change_evidence = git_change_evidence(
            Path(binding["gitRoot"]),
            str(args.get("base_ref") or "").strip() or None,
        )
        changed_ui_scope = ui_change_evidence["files"]
        ui_applicability = _ui_applicability(
            Path(binding["gitRoot"]),
            goal=goal,
            paths=changed_ui_scope if changed_ui_scope else None,
            baseline_head=(
                str(ui_change_evidence.get("baseCommit") or "").strip() or None
            ),
        )
    else:
        ui_applicability = {
            "schemaVersion": "jstack.ui.applicability.v1",
            "state": "unavailable",
            "reason": "git-required",
            "detection": None,
        }
    classifications = classifications_with_product_interface(
        classifications,
        required=ui_applicability["state"] == "required",
    )
    selected = skills_with_classifications(
        goal, classifications, quality_level=quality_level
    )
    team_plan = choose_agent_team(
        goal,
        classifications,
        quality_level=quality_level,
        team_mode=team_mode,
        capability_ids=capability_ids,
    )
    steps = [
        {
            "gate": "Classify",
            "skill": "jstack_plan",
            "purpose": "Classify the work by risk and select the strictest matching workflow.",
            "doneWhen": "The plan names the applicable risk classes and required gates.",
        },
        {
            "gate": "Context",
            "skill": "jstack_detect_project -> context-restore",
            "purpose": "Read project instructions, restore prior context, detect repo boundaries, and load project memory where relevant.",
            "doneWhen": "Project path, repo instructions, stack, test commands, and relevant memory/docs are known.",
        },
        {
            "gate": "Planning",
            "skill": "spec -> autoplan -> plan-eng-review -> plan-ceo-review -> plan-design-review -> plan-devex-review",
            "purpose": "Convert unclear intent into acceptance criteria and review architecture/product/design/devex risk before coding.",
            "doneWhen": "The execution plan is scoped, sequenced, and matched to the risk class.",
        },
        {
            "gate": "Safety",
            "skill": "guard -> freeze -> careful",
            "purpose": "Set edit boundaries and avoid destructive or production-affecting operations without explicit approval.",
            "doneWhen": "Risky filesystem/git/production actions are either avoided or explicitly approved.",
        },
        {
            "gate": "Build",
            "skill": "normal Codex implementation tools",
            "purpose": "Make the smallest coherent change using existing architecture and proportional tests.",
            "doneWhen": "The implementation is scoped, coherent, and avoids unrelated refactors.",
        },
        {
            "gate": "Quality",
            "skill": "jstack_health -> jstack_review -> investigate -> jstack_qa",
            "purpose": "Check repo health, review diffs, run focused verification, and investigate root causes for defects.",
            "doneWhen": "Relevant lint/typecheck/test/build checks pass or failures are clearly reported.",
        },
        {
            "gate": "Security/compliance",
            "skill": "jstack_security_audit -> cso",
            "purpose": "Review auth, secrets, RBAC, PII, payment, public endpoints, webhooks, infra, and external integration boundaries.",
            "doneWhen": "Sensitive-surface risks are reviewed and release blockers are resolved or documented.",
        },
        {
            "gate": "Product/UI/QA",
            "skill": "design-review -> design-consultation -> qa -> qa-only -> browse -> benchmark",
            "purpose": "Verify user-facing behavior, visual quality, browser flows, and performance where applicable.",
            "doneWhen": "Relevant UI/product/browser/performance evidence exists for changed surfaces.",
        },
        {
            "gate": "Release",
            "skill": "jstack_ship_check -> ship -> land-and-deploy -> canary",
            "purpose": "Prepare, release, deploy, and monitor only when the user explicitly asks for release/deploy work.",
            "doneWhen": "Release work has explicit approval and ship/deploy/canary checks are complete.",
        },
        {
            "gate": "Handoff",
            "skill": "jstack_context_save -> document-release -> learn",
            "purpose": "Save decisions, files changed, checks run, risks, open items, and durable memory.",
            "doneWhen": "The handoff states what changed, what was checked, remaining risk, and next steps.",
        },
    ]
    if binding["evidenceMode"] == "artifact-only":
        artifact_replacements = {
            "Context": {
                "skill": "jstack_detect_project -> direct context inspection",
                "purpose": "Read project instructions, restore relevant durable memory, identify the authoritative source and deployment boundary, and record that Git evidence is unavailable.",
                "doneWhen": "The orchestration path, authoritative source, stack, test commands, deployment boundary, and evidence limitation are known.",
            },
            "Quality": {
                "skill": "normal Codex test/build tools + direct evidence capture",
                "purpose": "Inspect and run authorized checks directly, recording exact commands, statuses, timestamps, output, and artifact hashes without claiming JStack receipts.",
                "doneWhen": "Relevant checks pass with reviewable direct evidence, or failures and missing evidence are clearly reported.",
            },
            "Security/compliance": {
                "skill": "normal Codex security review + direct scanners",
                "purpose": "Review sensitive boundaries directly and record findings without claiming a commit-bound JStack security receipt.",
                "doneWhen": "Relevant security risks are reviewed and unresolved findings are explicit release blockers.",
            },
            "Release": {
                "skill": "artifact-only release boundary",
                "purpose": "Prepare local release artifacts and direct evidence only; commit-bound JStack release readiness is unavailable without an exact Git subject.",
                "doneWhen": "Direct release evidence is complete and the handoff states that JStack release readiness remains unavailable without Git.",
            },
            "Handoff": {
                "skill": "direct handoff + durable memory",
                "purpose": "Save decisions, artifact hashes, checks, backup and rollback evidence, runtime identity, smoke results, risks, and open items outside JStack Git-bound context receipts.",
                "doneWhen": "The handoff distinguishes direct artifact evidence from unavailable Git-backed JStack certification.",
            },
        }
        for step in steps:
            replacement = artifact_replacements.get(step["gate"])
            if replacement:
                step.update(replacement)
        steps.insert(
            4,
            {
                "gate": "Artifact evidence",
                "skill": "direct hashes, tests, backup, runtime identity, rollback, monitoring, and smoke checks",
                "purpose": "Establish a reviewable evidence chain for work whose authoritative source is not bound to Git.",
                "doneWhen": "Every required artifact-only evidence item is captured, failures are explicit, and no commit-bound receipt is claimed.",
            },
        )
    if ui_applicability["state"] == "required":
        for step in steps:
            if step["gate"] == "Product/UI/QA":
                step.update(
                    {
                        "skill": "product-ui-design -> design-review -> qa -> browse",
                        "purpose": (
                            "Apply the Product Interface System automatically, preserve and extend any established design system, "
                            "and gather profile-aware visual, interaction, accessibility, and runtime evidence."
                        ),
                        "doneWhen": (
                            "The scoped UI has a baseline contract and the exact candidate has a current passing Product Interface finalization receipt."
                        ),
                    }
                )
                break
    release_blockers: list[str] = []
    required_gates: list[str] = []
    for classification in classifications:
        for blocker in classification.get("releaseBlockers", []):
            if blocker not in release_blockers:
                release_blockers.append(blocker)
        for gate in classification.get("requiredGates", []):
            if gate not in required_gates:
                required_gates.append(gate)
    if binding["evidenceMode"] == "artifact-only":
        release_blockers.insert(0, ARTIFACT_ONLY_RELEASE_BLOCKER)
        if "artifact-evidence" not in required_gates:
            required_gates.append("artifact-evidence")
    task_training = (
        build_task_training(goal, classifications, required_gates, learning_mode)
        if learning_mode != "off"
        else None
    )
    return {
        "goal": goal,
        "qualityLevel": quality_level,
        "masteryMode": mastery_mode,
        "learningMode": learning_mode,
        "teamMode": team_mode,
        "contextGate": {
            "requiredByJStackWorkflow": True,
            "receiptBound": context_readiness is not None,
            "readiness": context_readiness,
            "instruction": "Run jstack_context_readiness after inspecting project context, or use the stronger loop/program goal-readiness contract when it owns orchestration, before executing this plan.",
        },
        "classifications": classifications,
        "productInterface": ui_applicability,
        "project": detected,
        "projectBinding": binding,
        "gitRequiredTools": GIT_REQUIRED_TOOLS,
        "blockedTools": binding["blockedTools"],
        "artifactEvidenceRequirements": ARTIFACT_EVIDENCE_REQUIREMENTS if binding["evidenceMode"] == "artifact-only" else [],
        "workflowProfile": WORKFLOW_PROFILE,
        "masterySystem": mastery_system(),
        "taskTraining": task_training,
        "agentTeam": team_plan,
        "specialistCapabilityCatalog": _capability_call(
            lambda: capability_core.catalog_summary()
        ),
        "antiSlopChecklist": task_training["antiSlopChecklist"] if task_training else ANTI_SLOP_BASE,
        "recommendedSkills": selected,
        "availableWorkflowSkills": workflow_skill_names(),
        "requiredGates": required_gates,
        "releaseBlockers": release_blockers,
        "plan": steps,
        "policy": {
            "intent": "Use gstack as an enterprise workflow router and quality gate.",
            "noArbitraryShell": "Do not execute arbitrary shell commands through this MCP.",
            "actionSafety": "JStack adds no custom approval tokens or terminal ceremony. Perform repository, Git, provider, deployment, and production actions only within explicit user scope and the host/provider's normal permissions.",
            "productionBar": "Do not call work production-ready if required tests, security, QA, or docs for the risk class are missing.",
            "antiSlopStandard": "No fake data, fake test results, hidden assumptions, unverifiable completion claims, unrelated churn, or unapproved production mutation.",
            "masteryStandard": "For non-trivial work, include the skill stage, learning objective, expert mental model, benchmarks, review rubric, and next drill.",
            "projectBindingBoundary": "Artifact-only planning is advisory evidence capture, not commit-bound JStack QA, security, policy, context, or release certification.",
        },
    }


def tool_team_plan(args: dict[str, Any]) -> dict[str, Any]:
    goal = str(args.get("goal") or "").strip()
    if not goal:
        raise ToolError("goal is required.")
    quality_level = str(args.get("quality_level") or "enterprise").strip().lower()
    if quality_level not in {"standard", "enterprise"}:
        raise ToolError("quality_level must be 'standard' or 'enterprise'.")
    team_mode = normalize_team_mode(args.get("team_mode"))
    binding = resolve_project_binding(args.get("project_path"))
    workflow_mode = str(
        args.get("context_workflow_mode") or context_workflow_for_team_mode(team_mode)
    ).strip()
    if workflow_mode not in context_readiness_core.WORKFLOW_MODES:
        raise ToolError("context_workflow_mode is not supported.")
    context_readiness = None
    if args.get("context_readiness_receipt"):
        context_readiness = verify_context_readiness_receipt(
            str(args["context_readiness_receipt"]),
            goal=goal,
            workflow_mode=workflow_mode,
            binding=binding,
            context_brief=args.get("context_brief"),
        )
    capability_ids = args.get("capability_ids") or []
    classifications = classify_work(goal)
    team_change_evidence = (
        git_change_evidence(Path(binding["gitRoot"]))
        if binding["evidenceMode"] == "git"
        else None
    )
    ui_applicability = (
        _ui_applicability(
            Path(binding["gitRoot"]),
            goal=goal,
            paths=(team_change_evidence["files"] or None),
            baseline_head=(
                str(team_change_evidence.get("baseCommit") or "").strip() or None
            ),
        )
        if binding["evidenceMode"] == "git"
        else {
            "schemaVersion": "jstack.ui.applicability.v1",
            "state": "unavailable",
            "reason": "git-required",
            "detection": None,
        }
    )
    classifications = classifications_with_product_interface(
        classifications,
        required=ui_applicability["state"] == "required",
    )
    return {
        "goal": goal,
        "qualityLevel": quality_level,
        "teamMode": team_mode,
        "contextGate": {
            "requiredByJStackWorkflow": True,
            "receiptBound": context_readiness is not None,
            "readiness": context_readiness,
            "instruction": "Run jstack_context_readiness after inspecting project context and before dispatching this team.",
        },
        "classifications": classifications,
        "productInterface": ui_applicability,
        "team": choose_agent_team(
            goal,
            classifications,
            quality_level=quality_level,
            team_mode=team_mode,
            capability_ids=capability_ids,
        ),
        "capabilityCatalog": _capability_call(lambda: capability_core.catalog_summary()),
        "availableRoster": AGENT_ROSTER,
        "policy": TEAM_DISPATCH_POLICY,
        "coordinationProtocol": TEAM_COORDINATION_PROTOCOL,
    }


def tool_capability_catalog(args: dict[str, Any]) -> dict[str, Any]:
    include_details = bool(args.get("include_details", False))
    catalog = _capability_call(lambda: capability_core.load_catalog())
    summary = _capability_call(
        lambda: capability_core.catalog_summary(catalog, include_details=include_details)
    )
    role_ids = args.get("role_ids") or []
    capability_ids = args.get("capability_ids") or []
    query = str(args.get("query") or "").strip().lower()
    if role_ids:
        unknown_roles = sorted(set(str(item) for item in role_ids) - capability_core.ROSTER_ROLE_IDS)
        if unknown_roles:
            raise ToolError("Unknown role ids: " + ", ".join(unknown_roles))
    if capability_ids:
        indexed = _capability_call(lambda: capability_core.capability_by_id(catalog))
        unknown_capabilities = sorted(set(str(item) for item in capability_ids) - set(indexed))
        if unknown_capabilities:
            raise ToolError("Unknown capability ids: " + ", ".join(unknown_capabilities))
    filtered = []
    for capability in summary["capabilities"]:
        if role_ids and not set(str(item) for item in role_ids) & set(capability["allowedRoles"]):
            continue
        if capability_ids and capability["id"] not in capability_ids:
            continue
        if query and query not in " ".join(
            [
                str(capability["id"]),
                str(capability["name"]),
                str(capability["summary"]),
                " ".join(str(item) for item in capability.get("auditDomains") or []),
            ]
        ).lower():
            continue
        filtered.append(capability)
    summary["capabilities"] = filtered
    summary["resultCount"] = len(filtered)
    goal = str(args.get("goal") or "").strip()
    if goal:
        selected_roles = [str(item) for item in role_ids] or ["lead"]
        classifications = classify_work(goal)
        summary["selection"] = specialist_capability_plan(
            goal,
            classifications,
            selected_roles,
            [str(item) for item in capability_ids],
        )
    return summary


def normalize_agent_plan(agent: Any) -> dict[str, Any]:
    if not isinstance(agent, dict):
        return {}
    agent_id = str(agent.get("id") or agent.get("agent_id") or "").strip()
    read_only = bool(agent.get("readOnly", agent.get("read_only", not bool(agent.get("mayEdit", agent.get("may_edit", False))))))
    write_scope = agent.get("writeScope", agent.get("write_scope", []))
    if isinstance(write_scope, str):
        write_scope = [write_scope]
    if not isinstance(write_scope, list):
        write_scope = []
    capability_ids = agent.get("capabilityIds", agent.get("capability_ids"))
    capabilities_provided = capability_ids is not None
    if isinstance(capability_ids, str):
        capability_ids = [capability_ids]
    if not isinstance(capability_ids, list):
        capability_ids = []
    return {
        "id": agent_id,
        "readOnly": read_only,
        "mayEdit": not read_only,
        "writeScope": [str(item).replace("\\", "/") for item in write_scope],
        "task": str(agent.get("task") or ""),
        "capabilityIds": [str(item).strip() for item in capability_ids if str(item).strip()],
        "capabilitiesProvided": capabilities_provided,
    }


def normalize_write_scope(scope: str) -> str:
    normalized = scope.strip().replace("\\", "/")
    if not normalized or normalized.startswith("/") or re.match(r"^[A-Za-z]:", normalized):
        raise ToolError(f"Write scope must be a non-empty repository-relative path: {scope!r}")
    parts = [part for part in normalized.split("/") if part not in {"", "."}]
    if any(part == ".." for part in parts):
        raise ToolError(f"Write scope may not escape the repository root: {scope!r}")
    result = "/".join(parts).rstrip("/")
    if not result:
        raise ToolError(f"Write scope must identify a repository path, not the repository root: {scope!r}")
    return result


def scope_static_prefix(scope: str) -> str:
    wildcard = min([index for index in (scope.find("*"), scope.find("?"), scope.find("[")) if index >= 0] or [len(scope)])
    return scope[:wildcard].rstrip("/")


def scopes_overlap(left: str, right: str) -> bool:
    left = normalize_write_scope(left).casefold()
    right = normalize_write_scope(right).casefold()
    if left == right or fnmatch.fnmatch(left, right) or fnmatch.fnmatch(right, left):
        return True
    left_prefix = scope_static_prefix(left)
    right_prefix = scope_static_prefix(right)
    if not left_prefix or not right_prefix:
        return True
    return (
        left_prefix == right_prefix
        or left_prefix.startswith(right_prefix + "/")
        or right_prefix.startswith(left_prefix + "/")
    )


def coordination_packet_errors(
    packet: Any,
    goal: str,
    team_mode: str,
    agent_ids: list[str],
    expected_capability_plan: Optional[dict[str, Any]] = None,
) -> list[str]:
    if not isinstance(packet, dict):
        return ["Specialist dispatch requires the actual coordination_packet object, not a boolean assertion."]
    errors: list[str] = []
    required = TEAM_COORDINATION_PROTOCOL["requiredFields"]
    for field in required:
        if field == "rolesNotUsed" and team_mode == "full-team":
            continue
        value = packet.get(field)
        if value in (None, "", [], {}):
            errors.append(f"Coordination packet field '{field}' is required and must be non-empty.")
    packet_mode = normalize_team_mode(str(packet.get("mode") or team_mode))
    if packet_mode != team_mode:
        errors.append(f"Coordination packet mode '{packet_mode}' does not match dispatch mode '{team_mode}'.")
    if goal and str(packet.get("goal") or "").strip() != goal:
        errors.append("Coordination packet goal must exactly match the dispatch goal.")
    roles_used = packet.get("rolesUsed") or []
    used_ids: set[str] = set()
    if isinstance(roles_used, list):
        for role in roles_used:
            role_id = str(role.get("id") if isinstance(role, dict) else role).strip()
            if role_id:
                used_ids.add(role_id)
    if used_ids != set(agent_ids):
        errors.append("Coordination packet rolesUsed must exactly match the proposed agent ids.")
    packet_capability_plan = packet.get("capabilityPlan")
    if expected_capability_plan is not None:
        if not isinstance(packet_capability_plan, dict):
            errors.append("Coordination packet capabilityPlan must be the actual capability plan object.")
        else:
            for field in ("catalogDigest", "selectionDigest"):
                if packet_capability_plan.get(field) != expected_capability_plan.get(field):
                    errors.append(
                        f"Coordination packet capabilityPlan.{field} does not match deterministic routing."
                    )
            expected_by_role = capability_assignments_by_role(expected_capability_plan)
            for role in roles_used if isinstance(roles_used, list) else []:
                if not isinstance(role, dict):
                    continue
                role_id = str(role.get("id") or "")
                expected_ids = [
                    str(item["capabilityId"])
                    for item in expected_by_role.get(role_id, [])
                ]
                supplied_ids = role.get("capabilityIds") or []
                if supplied_ids != expected_ids:
                    errors.append(
                        f"Coordination packet role '{role_id}' capabilityIds do not match deterministic routing."
                    )
    ownership = packet.get("fileOwnershipMap")
    if not isinstance(ownership, dict):
        errors.append("Coordination packet fileOwnershipMap must be an object keyed by editing agent id.")
    return errors


def tool_dispatch_check(args: dict[str, Any]) -> dict[str, Any]:
    goal = str(args.get("goal") or "").strip()
    team_mode = normalize_team_mode(args.get("team_mode"))
    proposed = args.get("team") or args.get("agents") or {}
    if isinstance(proposed, dict):
        raw_agents = proposed.get("agents") or []
    elif isinstance(proposed, list):
        raw_agents = proposed
    else:
        raw_agents = []
    agents = [normalize_agent_plan(agent) for agent in raw_agents]
    agents = [agent for agent in agents if agent.get("id")]
    if args.get("max_specialists") is not None:
        max_specialists = int(args["max_specialists"])
    elif team_mode == "full-team":
        max_specialists = int(TEAM_DISPATCH_POLICY["fullTeamMaxSpecialists"])
    else:
        max_specialists = int(TEAM_DISPATCH_POLICY["defaultMaxSpecialists"])
    explicit_justification = str(args.get("lead_justification") or "").strip()
    explicit_release_requested = bool(args.get("explicit_release_requested") or False)
    coordination_packet = args.get("coordination_packet")
    classifications = classify_work(goal) if goal else []
    blockers: list[str] = []
    warnings: list[str] = []

    ids = [agent["id"] for agent in agents]
    allowed_ids = {agent["id"] for agent in AGENT_ROSTER}
    unknown_ids = sorted(set(ids) - allowed_ids)
    if unknown_ids:
        blockers.append("Unknown agent ids are not allowed: " + ", ".join(unknown_ids))
    if "lead" not in ids:
        blockers.append("Agent plan must include the Lead Engineer with id 'lead'.")
    expected_capability_plan: Optional[dict[str, Any]] = None
    if not goal:
        blockers.append("A non-empty goal is required for deterministic capability validation.")
    else:
        known_role_ids = [agent_id for agent_id in ids if agent_id in allowed_ids]
        if known_role_ids:
            explicit_capability_ids = [
                str(item) for item in (args.get("capability_ids") or [])
            ]
            candidate_classifications = [
                classifications,
                classifications_with_product_interface(
                    classifications, required=True
                ),
            ]
            candidate_plans = [
                specialist_capability_plan(
                    goal,
                    candidate,
                    known_role_ids,
                    explicit_capability_ids,
                )
                for candidate in candidate_classifications
            ]
            packet_selection_digest = (
                str(
                    (coordination_packet.get("capabilityPlan") or {}).get(
                        "selectionDigest"
                    )
                    or ""
                )
                if isinstance(coordination_packet, dict)
                and isinstance(coordination_packet.get("capabilityPlan"), dict)
                else ""
            )
            selected_index = 0
            if packet_selection_digest:
                for index, candidate_plan in enumerate(candidate_plans):
                    if (
                        candidate_plan.get("selectionDigest")
                        == packet_selection_digest
                    ):
                        selected_index = index
                        break
            classifications = candidate_classifications[selected_index]
            expected_capability_plan = candidate_plans[selected_index]
            expected_by_role = capability_assignments_by_role(expected_capability_plan)
            for agent in agents:
                if agent["id"] not in allowed_ids:
                    continue
                if not agent["capabilitiesProvided"]:
                    blockers.append(
                        f"Agent '{agent['id']}' must include capabilityIds from jstack_team_plan."
                    )
                    continue
                if len(agent["capabilityIds"]) != len(set(agent["capabilityIds"])):
                    blockers.append(
                        f"Agent '{agent['id']}' capabilityIds must not contain duplicates."
                    )
                try:
                    capability_core.validate_role_capabilities(
                        agent["id"], agent["capabilityIds"]
                    )
                except capability_core.CapabilityError as exc:
                    blockers.append(str(exc))
                    continue
                expected_ids = [
                    str(item["capabilityId"])
                    for item in expected_by_role.get(agent["id"], [])
                ]
                if agent["capabilityIds"] != expected_ids:
                    blockers.append(
                        f"Agent '{agent['id']}' capabilityIds do not match deterministic routing: expected "
                        + ", ".join(expected_ids)
                    )
    classification_ids = {item["id"] for item in classifications}
    if team_mode == "smart-subagents":
        high_risk_requirements = {
            "production_release": {"devops", "security", "qa"},
            "security_compliance": {"security", "reviewer"},
            "ui_product": {"product", "qa"},
            "data_financial": {"quant", "reviewer"},
            "architecture": {"architect", "reviewer"},
            "product": {"product", "reviewer"},
        }
        precedence = ["production_release", "security_compliance", "ui_product", "data_financial", "architecture", "product"]
        primary = next((item for item in precedence if item in classification_ids), None)
        required_roles = set(high_risk_requirements[primary]) if primary else set()
        if "ui_product" in classification_ids:
            required_roles.update({"product", "qa", "reviewer"})
        if primary is None and "normal" in classification_ids:
            required_roles.update({"investigator", "reviewer"})
        missing_required = sorted(required_roles - set(ids))
        if missing_required:
            blockers.append(
                "Smart-subagents plan is missing risk-required roles: " + ", ".join(missing_required)
            )
    duplicates = sorted({agent_id for agent_id in ids if ids.count(agent_id) > 1})
    if duplicates:
        blockers.append("Duplicate agent ids are not allowed: " + ", ".join(duplicates))
    specialist_count = len([agent for agent in agents if agent["id"] != "lead"])
    if specialist_count > max_specialists and not explicit_justification:
        blockers.append(f"Agent plan has {specialist_count} specialists; default maximum is {max_specialists} without lead justification.")
    if team_mode == "full-team":
        expected_ids = {agent["id"] for agent in AGENT_ROSTER}
        missing = sorted(expected_ids - set(ids))
        if missing:
            blockers.append("Full-team mode must account for all 11 roles. Missing ids: " + ", ".join(missing))
    if team_mode == "single-lead" and specialist_count:
        blockers.append("Single-lead mode may not include specialist agents.")
    if team_mode == "smart-subagents" and specialist_count > max_specialists and not explicit_justification:
        blockers.append("Smart-subagents mode should normally stay within two or three specialists unless the Lead justifies more.")
    if specialist_count > 0:
        blockers.extend(
            coordination_packet_errors(
                coordination_packet,
                goal,
                team_mode,
                ids,
                expected_capability_plan,
            )
        )
    if "production_release" in classification_ids and not explicit_release_requested:
        blockers.append(
            "Production/release-classified team planning requires an explicit request to assess that work. This flag never authorizes deploy/release actions."
        )

    write_owners: list[tuple[str, str]] = []
    ownership_map = coordination_packet.get("fileOwnershipMap", {}) if isinstance(coordination_packet, dict) else {}
    for agent in agents:
        if not agent["mayEdit"]:
            if agent["writeScope"]:
                warnings.append(f"Read-only specialist '{agent['id']}' declared a write scope that will not be honored.")
            continue
        if agent["id"] not in {"lead", "builder", "docs"}:
            blockers.append(f"Role '{agent['id']}' is read-only by policy and may not edit.")
        if agent["id"] != "lead" and not agent["writeScope"]:
            blockers.append(f"Editing specialist '{agent['id']}' requires an explicit write scope.")
        normalized_scopes: list[str] = []
        for raw_scope in agent["writeScope"]:
            try:
                scope = normalize_write_scope(raw_scope)
            except ToolError as exc:
                blockers.append(str(exc))
                continue
            if agent["id"] == "docs" and not (
                scope.startswith("docs/")
                or scope in {"README.md", "CHANGELOG.md", "SECURITY.md", "CONTRIBUTING.md"}
                or scope.endswith(".md")
            ):
                blockers.append(f"Documentation specialist may not own non-documentation scope '{scope}'.")
            for existing_scope, owner in write_owners:
                if owner != agent["id"] and scopes_overlap(scope, existing_scope):
                    blockers.append(f"Write-scope overlap: '{scope}' ({agent['id']}) overlaps '{existing_scope}' ({owner}).")
            write_owners.append((scope, agent["id"]))
            normalized_scopes.append(scope)
        agent["writeScope"] = normalized_scopes
        packet_scopes = ownership_map.get(agent["id"], []) if isinstance(ownership_map, dict) else []
        if isinstance(packet_scopes, str):
            packet_scopes = [packet_scopes]
        try:
            normalized_packet_scopes = [normalize_write_scope(str(item)) for item in packet_scopes]
        except ToolError as exc:
            blockers.append(str(exc))
            normalized_packet_scopes = []
        if agent["id"] != "lead" and sorted(normalized_packet_scopes) != sorted(normalized_scopes):
            blockers.append(f"Coordination packet ownership for '{agent['id']}' must match the agent writeScope.")
    for agent in agents:
        if agent["id"] != "lead" and re.search(r"\bspawn\b|\bdelegate\b|\bsubagent\b", agent["task"], re.IGNORECASE):
            blockers.append(f"Subagent '{agent['id']}' task appears to delegate/spawn; only the Lead Engineer may orchestrate.")

    return {
        "goal": goal,
        "teamMode": team_mode,
        "valid": not blockers,
        "blockers": blockers,
        "warnings": warnings,
        "classifications": classifications,
        "specialistCount": specialist_count,
        "maxSpecialists": max_specialists,
        "leadJustification": explicit_justification,
        "coordinationPacket": coordination_packet,
        "capabilityPlan": expected_capability_plan,
        "agents": agents,
        "blockedActions": team_blocked_actions(),
        "coordinationProtocol": TEAM_COORDINATION_PROTOCOL,
        "policy": TEAM_DISPATCH_POLICY,
    }


_SPECIALIST_IDENTIFIER_RE = re.compile(r"^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$")
_SPECIALIST_TRACE_RE = re.compile(r"^[0-9a-f]{32}$")
_SPECIALIST_SPAN_RE = re.compile(r"^[0-9a-f]{16}$")
_SPECIALIST_RUN_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$")
_SPECIALIST_RAW_KEYS = {
    "prompt",
    "prompts",
    "rawinput",
    "rawoutput",
    "rawcontent",
    "toolarguments",
    "arguments",
    "messages",
    "modelresponse",
}


def _specialist_digest(value: Any) -> str:
    return hashlib.sha256(
        json.dumps(value, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()


def _specialist_structured_limit(
    value: Any,
    field: str,
    *,
    maximum: int = SPECIALIST_MAX_STRUCTURED_BYTES,
) -> None:
    try:
        size = len(json.dumps(value, sort_keys=True, separators=(",", ":")).encode("utf-8"))
    except (TypeError, ValueError) as exc:
        raise ToolError(f"{field} must be bounded JSON data.") from exc
    if size > maximum:
        raise ToolError(
            f"{field} exceeds the {maximum}-byte structured data limit."
        )


def _reject_specialist_sensitive_content(value: Any, field: str = "arguments") -> None:
    if isinstance(value, str):
        if audit_core.contains_secret_like(value):
            raise ToolError(
                f"{field} contains a secret-like value. Redact it and reference safe evidence instead."
            )
        return
    if isinstance(value, dict):
        for key, child in value.items():
            normalized_key = re.sub(r"[^a-z]", "", str(key).lower())
            if normalized_key in _SPECIALIST_RAW_KEYS:
                raise ToolError(
                    f"{field}.{key} is forbidden: specialist telemetry and receipts may not store raw prompts, model output, or tool arguments."
                )
            _reject_specialist_sensitive_content(child, f"{field}.{key}")
    elif isinstance(value, list):
        for index, child in enumerate(value):
            _reject_specialist_sensitive_content(child, f"{field}[{index}]")


def _specialist_identifier(value: Any, field: str) -> str:
    normalized = str(value or "").strip()
    if not _SPECIALIST_IDENTIFIER_RE.fullmatch(normalized) or len(normalized) > 100:
        raise ToolError(f"{field} must be a lowercase kebab-case identifier.")
    return normalized


def _specialist_role_ids(values: Any, field: str = "team_role_ids") -> list[str]:
    if not isinstance(values, list) or not values:
        raise ToolError(f"{field} must be a non-empty array of JStack role ids.")
    roles = [str(item or "").strip() for item in values]
    if len(roles) != len(set(roles)):
        raise ToolError(f"{field} must not contain duplicates.")
    unknown = sorted(set(roles) - capability_core.ROSTER_ROLE_IDS)
    if unknown:
        raise ToolError(f"{field} contains unknown role ids: " + ", ".join(unknown))
    return roles


def _specialist_capability_ids(
    role_id: str, values: Any, field: str = "capability_ids"
) -> list[str]:
    if not isinstance(values, list) or not values:
        raise ToolError(f"{field} must be a non-empty capability id array.")
    normalized = [str(item or "").strip() for item in values]
    if len(normalized) != len(set(normalized)):
        raise ToolError(f"{field} must not contain duplicates.")
    return _capability_call(
        lambda: capability_core.validate_role_capabilities(role_id, normalized)
    )


def _specialist_write_scopes(values: Any) -> list[str]:
    if values is None:
        return []
    if not isinstance(values, list):
        raise ToolError("write_scope must be an array of repository-relative paths or globs.")
    scopes = [normalize_write_scope(str(item)) for item in values]
    if len(scopes) != len(set(scopes)):
        raise ToolError("write_scope must not contain duplicates.")
    return scopes


def _specialist_change_path(value: Any, field: str) -> str:
    path = normalize_write_scope(str(value or ""))
    if any(marker in path for marker in ("*", "?", "[")):
        raise ToolError(f"{field} must identify one concrete repository path, not a glob.")
    return path


def _path_owned_by_scope(path: str, scope: str) -> bool:
    if fnmatch.fnmatch(path, scope):
        return True
    prefix = scope_static_prefix(scope)
    return bool(prefix and (path == prefix or path.startswith(prefix + "/")))


def _specialist_timestamp(value: Any, field: str) -> _dt.datetime:
    try:
        parsed = _dt.datetime.fromisoformat(str(value))
    except (TypeError, ValueError) as exc:
        raise ToolError(f"{field} must be a valid ISO-8601 timestamp.") from exc
    if parsed.tzinfo is None:
        raise ToolError(f"{field} must include a timezone.")
    return parsed.astimezone(_dt.timezone.utc)


def _deterministic_specialist_team(
    goal: str,
    team_mode: str,
    explicit_capability_ids: list[str],
    *,
    ui_product: bool = False,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    classifications = classifications_with_product_interface(
        classify_work(goal), required=ui_product
    )
    team = choose_agent_team(
        goal,
        classifications,
        quality_level="enterprise",
        team_mode=team_mode,
        capability_ids=explicit_capability_ids,
    )
    return classifications, team


def _deterministic_specialist_team_for_roles(
    goal: str,
    team_mode: str,
    explicit_capability_ids: list[str],
    supplied_role_ids: list[str],
    *,
    capability_selection_digest: Optional[str] = None,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Accept either ordinary or UI-strengthened routing without new public fields."""
    candidates = [
        _deterministic_specialist_team(
            goal, team_mode, explicit_capability_ids, ui_product=ui_product
        )
        for ui_product in (False, True)
    ]
    for classifications, team in candidates:
        routed = [str(agent["id"]) for agent in team["agents"]]
        selection_digest = str(team["capabilityPlan"]["selectionDigest"])
        if supplied_role_ids == routed and (
            capability_selection_digest is None
            or capability_selection_digest == selection_digest
        ):
            return classifications, team
    raise ToolError(
        "team_role_ids and capability_selection_digest must exactly match deterministic ordinary or Product Interface JStack routing."
    )


def _optional_capability_selection_digest(value: Any) -> Optional[str]:
    if value is None:
        return None
    digest = str(value or "").strip()
    if not re.fullmatch(r"[0-9a-f]{64}", digest):
        raise ToolError(
            "capability_selection_digest must be the lowercase SHA-256 selectionDigest returned by JStack planning."
        )
    return digest


def _validate_specialist_result(
    result: Any,
    *,
    role_id: str,
    capability_ids: list[str],
    write_scopes: list[str],
    catalog: dict[str, Any],
) -> tuple[dict[str, Any], bool]:
    validate_schema_value(result, SPECIALIST_RESULT_SCHEMA, "result")
    _specialist_structured_limit(result, "result")
    _reject_specialist_sensitive_content(result, "result")
    normalized = json.loads(json.dumps(result))
    status = str(normalized["status"])
    blockers = normalized["blockers"]
    skipped = normalized["skippedChecks"]
    if status == "success" and blockers:
        raise ToolError("A successful specialist result may not contain blockers.")
    if status in {"blocked", "error"} and not blockers:
        raise ToolError(f"A {status} specialist result must contain at least one blocker.")
    if status == "partial" and not blockers and not skipped:
        raise ToolError("A partial specialist result must identify a blocker or skipped check.")

    evidence_kinds: list[str] = []
    evidence_status: dict[str, str] = {}
    evidence_references: set[str] = set()
    for index, evidence in enumerate(normalized["evidence"]):
        kind = _specialist_identifier(evidence["kind"], f"result.evidence[{index}].kind")
        if kind in evidence_kinds:
            raise ToolError(f"Duplicate specialist evidence kind: {kind}")
        evidence["kind"] = kind
        evidence_kinds.append(kind)
        evidence_status[kind] = str(evidence["status"])
        references = [str(item) for item in evidence["references"]]
        if len(references) != len(set(references)):
            raise ToolError(
                f"result.evidence[{index}].references must not contain duplicates."
            )
        evidence_references.update(references)

    indexed = _capability_call(lambda: capability_core.capability_by_id(catalog))
    required_evidence = sorted(
        {
            kind
            for capability_id in capability_ids
            for kind in indexed[capability_id]["requiredEvidence"]
        }
    )
    missing_evidence = sorted(set(required_evidence) - set(evidence_kinds))
    if missing_evidence:
        raise ToolError(
            "Specialist result is missing capability-required evidence kinds: "
            + ", ".join(missing_evidence)
        )

    finding_ids: set[str] = set()
    for index, finding in enumerate(normalized["findings"]):
        finding_id = _specialist_identifier(
            finding["findingId"], f"result.findings[{index}].findingId"
        )
        if finding_id in finding_ids:
            raise ToolError(f"Duplicate specialist findingId: {finding_id}")
        finding_ids.add(finding_id)
        finding["findingId"] = finding_id
        finding["resolutionKey"] = _specialist_identifier(
            finding["resolutionKey"], f"result.findings[{index}].resolutionKey"
        )
        finding_evidence = [
            _specialist_identifier(item, f"result.findings[{index}].evidenceKinds")
            for item in finding["evidenceKinds"]
        ]
        if len(finding_evidence) != len(set(finding_evidence)):
            raise ToolError(
                f"result.findings[{index}].evidenceKinds must not contain duplicates."
            )
        unknown_evidence = sorted(set(finding_evidence) - set(evidence_kinds))
        if unknown_evidence:
            raise ToolError(
                f"result.findings[{index}] references unknown evidence kinds: "
                + ", ".join(unknown_evidence)
            )
        finding["evidenceKinds"] = finding_evidence
        if finding.get("location"):
            finding["location"]["path"] = _specialist_change_path(
                finding["location"]["path"],
                f"result.findings[{index}].location.path",
            )
    if status == "success" and any(
        finding["disposition"] == "block" for finding in normalized["findings"]
    ):
        raise ToolError("A successful specialist result may not contain a blocking finding.")

    change_paths: set[str] = set()
    for index, change in enumerate(normalized["changes"]):
        path = _specialist_change_path(change["path"], f"result.changes[{index}].path")
        if path in change_paths:
            raise ToolError(f"Duplicate changed path in specialist result: {path}")
        change_paths.add(path)
        change["path"] = path
        if role_id not in {"lead", "builder", "docs"}:
            raise ToolError(f"Read-only role '{role_id}' may not report file changes.")
        if role_id != "lead" and not write_scopes:
            raise ToolError(f"Editing role '{role_id}' requires a non-empty write_scope.")
        if write_scopes and not any(_path_owned_by_scope(path, scope) for scope in write_scopes):
            raise ToolError(
                f"Changed path '{path}' is outside role '{role_id}' write_scope."
            )
        if role_id == "docs" and not (
            path.startswith("docs/")
            or path in {"README.md", "CHANGELOG.md", "SECURITY.md", "CONTRIBUTING.md"}
            or path.endswith(".md")
        ):
            raise ToolError(f"Documentation role may not report non-document change '{path}'.")

    blocker_codes: set[str] = set()
    for index, blocker in enumerate(blockers):
        code = _specialist_identifier(blocker["code"], f"result.blockers[{index}].code")
        if code in blocker_codes:
            raise ToolError(f"Duplicate specialist blocker code: {code}")
        blocker_codes.add(code)
        blocker["code"] = code

    required_evidence_complete = all(
        evidence_status.get(kind) in {"observed", "passed"}
        for kind in required_evidence
    )
    passed = (
        status == "success"
        and not blockers
        and required_evidence_complete
        and not any(item["status"] == "failed" for item in normalized["evidence"])
    )
    return normalized, passed


def _build_specialist_telemetry(
    telemetry: Any,
    *,
    result: dict[str, Any],
    context: dict[str, Any],
) -> dict[str, Any]:
    validate_schema_value(
        telemetry, SPECIALIST_TELEMETRY_INPUT_SCHEMA, "telemetry"
    )
    _specialist_structured_limit(telemetry, "telemetry")
    _reject_specialist_sensitive_content(telemetry, "telemetry")
    normalized = json.loads(json.dumps(telemetry))
    if normalized["rawContentStored"] is not False:
        raise ToolError("telemetry.rawContentStored must be false.")
    if normalized["status"] != result["status"]:
        raise ToolError("telemetry.status must exactly match result.status.")
    if not _SPECIALIST_RUN_RE.fullmatch(str(normalized["runId"])):
        raise ToolError("telemetry.runId has an invalid bounded identifier format.")
    if not _SPECIALIST_TRACE_RE.fullmatch(str(normalized["traceId"])):
        raise ToolError("telemetry.traceId must be 32 lowercase hexadecimal characters.")
    if not _SPECIALIST_SPAN_RE.fullmatch(str(normalized["spanId"])):
        raise ToolError("telemetry.spanId must be 16 lowercase hexadecimal characters.")
    started = _specialist_timestamp(normalized["startedAt"], "telemetry.startedAt")
    completed = _specialist_timestamp(normalized["completedAt"], "telemetry.completedAt")
    if completed < started:
        raise ToolError("telemetry.completedAt may not precede telemetry.startedAt.")
    elapsed_ms = int((completed - started).total_seconds() * 1000)
    if elapsed_ms > 86_400_000:
        raise ToolError("Specialist telemetry duration may not exceed 24 hours.")
    if normalized.get("durationMs") is not None and abs(int(normalized["durationMs"]) - elapsed_ms) > 1000:
        raise ToolError("telemetry.durationMs must agree with the supplied timestamps within one second.")
    normalized["durationMs"] = elapsed_ms
    evidence_references = {
        reference
        for evidence in result["evidence"]
        for reference in evidence["references"]
    }
    for index, tool_call in enumerate(normalized["toolCalls"]):
        evidence_ref = tool_call.get("evidenceRef")
        if evidence_ref and evidence_ref not in evidence_references:
            raise ToolError(
                f"telemetry.toolCalls[{index}].evidenceRef must reference result evidence."
            )
    normalized["inputDigest"] = _specialist_digest(context)
    normalized["outputDigest"] = _specialist_digest(result)
    return normalized


def tool_specialist_result(args: dict[str, Any]) -> dict[str, Any]:
    _specialist_structured_limit(args, "arguments")
    project_path = require_project_path(args.get("project_path"))
    goal = str(args.get("goal") or "").strip()
    if not goal:
        raise ToolError("goal is required.")
    team_mode = normalize_team_mode(args.get("team_mode"))
    if team_mode == "auto":
        raise ToolError("team_mode must be a resolved single-lead, smart-subagents, or full-team mode.")
    explicit_capability_ids = [str(item) for item in (args.get("explicit_capability_ids") or [])]
    supplied_role_ids = _specialist_role_ids(args.get("team_role_ids"))
    selection_digest = _optional_capability_selection_digest(
        args.get("capability_selection_digest")
    )
    _, team = _deterministic_specialist_team_for_roles(
        goal,
        team_mode,
        explicit_capability_ids,
        supplied_role_ids,
        capability_selection_digest=selection_digest,
    )
    expected_role_ids = [str(agent["id"]) for agent in team["agents"]]
    role_id = str(args.get("role_id") or "").strip()
    if role_id not in expected_role_ids:
        raise ToolError(f"role_id '{role_id}' is not in the deterministic team plan.")
    capability_ids = _specialist_capability_ids(role_id, args.get("capability_ids"))
    expected_assignments = capability_assignments_by_role(team["capabilityPlan"])
    expected_capability_ids = [
        str(item["capabilityId"])
        for item in expected_assignments.get(role_id, [])
    ]
    if capability_ids != expected_capability_ids:
        raise ToolError(
            f"capability_ids for role '{role_id}' must exactly match deterministic routing: "
            + ", ".join(expected_capability_ids)
        )
    write_scopes = _specialist_write_scopes(args.get("write_scope"))
    catalog = _capability_call(lambda: capability_core.load_catalog())
    result, result_passed = _validate_specialist_result(
        args.get("result"),
        role_id=role_id,
        capability_ids=capability_ids,
        write_scopes=write_scopes,
        catalog=catalog,
    )
    subject_before = evidence_subject(project_path)
    goal_digest = hashlib.sha256(goal.encode("utf-8")).hexdigest()
    telemetry_context = {
        "schemaVersion": "jstack.specialist.telemetry-input.v1",
        "goalDigest": goal_digest,
        "teamMode": team_mode,
        "teamRoleIds": supplied_role_ids,
        "roleId": role_id,
        "capabilityIds": capability_ids,
        "writeScope": write_scopes,
        "catalogDigest": team["capabilityPlan"]["catalogDigest"],
        "selectionDigest": team["capabilityPlan"]["selectionDigest"],
        "gitHead": subject_before["gitHead"],
        "projectFingerprint": subject_before["projectFingerprint"],
    }
    telemetry = _build_specialist_telemetry(
        args.get("telemetry"), result=result, context=telemetry_context
    )
    telemetry_passed = telemetry["status"] == "success" and all(
        item["status"] not in {"error", "blocked"}
        for item in telemetry["toolCalls"]
    )
    passed = result_passed and telemetry_passed
    subject_after = evidence_subject(project_path)
    if any(
        subject_after[field] != subject_before[field]
        for field in ("gitHead", "projectFingerprint", "policyDigest", "toolVersion")
    ):
        raise ToolError(
            "The project changed while the specialist result was being validated. Re-run against one stable Git state."
        )
    result_digest = _specialist_digest(result)
    telemetry_digest = _specialist_digest(telemetry)
    payload = {
        "kind": "specialist-result",
        "schemaVersion": "jstack.specialist.receipt.v1",
        "projectPath": subject_after["gitRoot"],
        "gitHead": subject_after["gitHead"],
        "projectFingerprint": subject_after["projectFingerprint"],
        "baseRef": subject_after.get("baseRef"),
        "baseCommit": subject_after.get("baseCommit"),
        "policyDigest": subject_after["policyDigest"],
        "toolVersion": SERVER_VERSION,
        "goalDigest": goal_digest,
        "teamMode": team_mode,
        "teamRoleIds": supplied_role_ids,
        "roleId": role_id,
        "capabilityIds": capability_ids,
        "capabilityCatalogVersion": team["capabilityPlan"]["catalogVersion"],
        "capabilityCatalogDigest": team["capabilityPlan"]["catalogDigest"],
        "capabilitySelectionDigest": team["capabilityPlan"]["selectionDigest"],
        "writeScope": write_scopes,
        "result": result,
        "resultDigest": result_digest,
        "telemetry": telemetry,
        "telemetryDigest": telemetry_digest,
        "passed": passed,
    }
    receipt = issue_receipt(payload)
    return {
        "schemaVersion": "jstack.specialist.result-issuance.v1",
        "passed": passed,
        "roleId": role_id,
        "capabilityIds": capability_ids,
        "capabilityCatalogDigest": team["capabilityPlan"]["catalogDigest"],
        "capabilitySelectionDigest": team["capabilityPlan"]["selectionDigest"],
        "goalDigest": goal_digest,
        "resultDigest": result_digest,
        "telemetry": telemetry,
        "telemetryDigest": telemetry_digest,
        "specialistResultReceipt": receipt,
        "receiptDigest": _receipt_digest(receipt),
        "receiptMeaning": (
            "Session-local proof that one structured specialist result and privacy-safe telemetry envelope passed schema, capability, permission, evidence, and current-Git binding checks. It does not prove semantic truth or authorize release."
        ),
    }


def _specialist_diagnostic(
    code: str,
    message: str,
    *,
    severity: str = "error",
    role_id: Optional[str] = None,
    resolution_key: Optional[str] = None,
) -> dict[str, Any]:
    diagnostic: dict[str, Any] = {
        "code": code,
        "severity": severity,
        "message": message,
    }
    if role_id:
        diagnostic["roleId"] = role_id
    if resolution_key:
        diagnostic["resolutionKey"] = resolution_key
    return diagnostic


def tool_specialist_handoff_check(args: dict[str, Any]) -> dict[str, Any]:
    _specialist_structured_limit(
        args,
        "arguments",
        maximum=SPECIALIST_MAX_HANDOFF_BYTES,
    )
    project_path = require_project_path(args.get("project_path"))
    goal = str(args.get("goal") or "").strip()
    if not goal:
        raise ToolError("goal is required.")
    team_mode = normalize_team_mode(args.get("team_mode"))
    if team_mode == "auto":
        raise ToolError("team_mode must be resolved before specialist handoff validation.")
    explicit_capability_ids = [str(item) for item in (args.get("explicit_capability_ids") or [])]
    selection_digest = _optional_capability_selection_digest(
        args.get("capability_selection_digest")
    )
    expected_agents_raw = args.get("expected_agents")
    if not isinstance(expected_agents_raw, list) or not expected_agents_raw:
        raise ToolError("expected_agents must be a non-empty array from jstack_team_plan.")
    for index, expected in enumerate(expected_agents_raw):
        validate_schema_value(
            expected, SPECIALIST_EXPECTED_AGENT_SCHEMA, f"expected_agents[{index}]"
        )
    expected_role_ids = [str(item["roleId"]) for item in expected_agents_raw]
    if len(expected_role_ids) != len(set(expected_role_ids)):
        raise ToolError("expected_agents may not contain duplicate roleId values.")
    _, team = _deterministic_specialist_team_for_roles(
        goal,
        team_mode,
        explicit_capability_ids,
        expected_role_ids,
        capability_selection_digest=selection_digest,
    )
    routed_role_ids = [str(agent["id"]) for agent in team["agents"]]
    routed_assignments = capability_assignments_by_role(team["capabilityPlan"])
    expected_by_role: dict[str, list[str]] = {}
    for index, expected in enumerate(expected_agents_raw):
        role_id = str(expected["roleId"])
        capability_ids = _specialist_capability_ids(
            role_id,
            expected["capabilityIds"],
            f"expected_agents[{index}].capabilityIds",
        )
        routed_capability_ids = [
            str(item["capabilityId"])
            for item in routed_assignments.get(role_id, [])
        ]
        if capability_ids != routed_capability_ids:
            raise ToolError(
                f"expected_agents[{index}].capabilityIds do not match deterministic routing for '{role_id}'."
            )
        expected_by_role[role_id] = capability_ids

    resolutions_raw = args.get("resolutions") or []
    if not isinstance(resolutions_raw, list):
        raise ToolError("resolutions must be an array.")
    resolutions: dict[str, dict[str, Any]] = {}
    for index, resolution in enumerate(resolutions_raw):
        validate_schema_value(
            resolution, SPECIALIST_RESOLUTION_SCHEMA, f"resolutions[{index}]"
        )
        _reject_specialist_sensitive_content(resolution, f"resolutions[{index}]")
        resolution_key = _specialist_identifier(
            resolution["resolutionKey"], f"resolutions[{index}].resolutionKey"
        )
        if resolution_key in resolutions:
            raise ToolError(f"Duplicate resolutionKey in resolutions: {resolution_key}")
        resolutions[resolution_key] = json.loads(json.dumps(resolution))

    receipts = args.get("receipts")
    if not isinstance(receipts, list) or not all(isinstance(item, str) for item in receipts):
        raise ToolError("receipts must be an array returned by jstack_specialist_result.")
    if len(receipts) > SPECIALIST_MAX_RECEIPTS or any(
        len(item) > SPECIALIST_MAX_RECEIPT_CHARS for item in receipts
    ):
        raise ToolError("receipts exceeds the bounded specialist handoff limits.")
    subject_before = evidence_subject(project_path)
    goal_digest = hashlib.sha256(goal.encode("utf-8")).hexdigest()
    diagnostics: list[dict[str, Any]] = []
    verified_by_role: dict[str, dict[str, Any]] = {}
    receipt_digests: list[str] = []
    for receipt in receipts:
        receipt_digest = _receipt_digest(receipt)
        if receipt_digest in receipt_digests:
            diagnostics.append(
                _specialist_diagnostic(
                    "JSTACK-SPECIALIST-DUPLICATE-RECEIPT",
                    "The same specialist receipt was supplied more than once.",
                )
            )
            continue
        receipt_digests.append(receipt_digest)
        try:
            verification = verify_receipt(
                receipt,
                "specialist-result",
                subject_before,
                expected_subject=subject_before,
                require_passed=False,
            )
        except ToolError:
            diagnostics.append(
                _specialist_diagnostic(
                    "JSTACK-SPECIALIST-RECEIPT-MALFORMED",
                    f"Receipt {receipt_digest[:12]} is malformed or from another server session.",
                )
            )
            continue
        payload = verification["payload"]
        role_id = str(payload.get("roleId") or "")
        if not verification["valid"]:
            diagnostics.append(
                _specialist_diagnostic(
                    "JSTACK-SPECIALIST-RECEIPT-STALE",
                    f"Receipt {receipt_digest[:12]} is stale or bound to another project state.",
                    role_id=role_id or None,
                )
            )
            continue
        receipt_checks = {
            "schemaVersion": payload.get("schemaVersion") == "jstack.specialist.receipt.v1",
            "goalDigest": payload.get("goalDigest") == goal_digest,
            "teamMode": payload.get("teamMode") == team_mode,
            "teamRoleIds": payload.get("teamRoleIds") == routed_role_ids,
            "catalogDigest": payload.get("capabilityCatalogDigest")
            == team["capabilityPlan"]["catalogDigest"],
            "selectionDigest": payload.get("capabilitySelectionDigest")
            == team["capabilityPlan"]["selectionDigest"],
            "expectedRole": role_id in expected_by_role,
            "capabilityIds": payload.get("capabilityIds") == expected_by_role.get(role_id),
            "resultDigest": payload.get("resultDigest")
            == _specialist_digest(payload.get("result")),
            "telemetryDigest": payload.get("telemetryDigest")
            == _specialist_digest(payload.get("telemetry")),
        }
        if not all(receipt_checks.values()):
            diagnostics.append(
                _specialist_diagnostic(
                    "JSTACK-SPECIALIST-RECEIPT-MISMATCH",
                    "A specialist receipt does not match the expected goal, team, capabilities, catalog, or structured payload digests.",
                    role_id=role_id or None,
                )
            )
            continue
        if role_id in verified_by_role:
            diagnostics.append(
                _specialist_diagnostic(
                    "JSTACK-SPECIALIST-DUPLICATE-ROLE",
                    f"Multiple receipts claim role '{role_id}'.",
                    role_id=role_id,
                )
            )
            continue
        verified_by_role[role_id] = {
            "receiptDigest": receipt_digest,
            "payload": payload,
        }
        if payload.get("passed") is not True:
            diagnostics.append(
                _specialist_diagnostic(
                    "JSTACK-SPECIALIST-RESULT-NOT-PASSED",
                    f"Role '{role_id}' returned a structurally valid but incomplete, blocked, or failed result.",
                    role_id=role_id,
                )
            )

    for role_id in routed_role_ids:
        if role_id not in verified_by_role:
            diagnostics.append(
                _specialist_diagnostic(
                    "JSTACK-SPECIALIST-MISSING-ROLE",
                    f"No current valid specialist receipt was supplied for role '{role_id}'.",
                    role_id=role_id,
                )
            )

    resolution_views: dict[str, list[dict[str, str]]] = {}
    resolution_evidence_references: dict[str, set[str]] = {}
    changed_path_owners: list[tuple[str, str]] = []
    telemetry_summary = {
        "runCount": 0,
        "toolCallCount": 0,
        "durationMs": 0,
        "inputTokens": 0,
        "outputTokens": 0,
        "rawContentStored": False,
    }
    for role_id, verified in verified_by_role.items():
        payload = verified["payload"]
        result = payload["result"]
        telemetry = payload["telemetry"]
        evidence_by_kind = {
            str(item["kind"]): set(str(reference) for reference in item["references"])
            for item in result.get("evidence") or []
        }
        telemetry_summary["runCount"] += 1
        telemetry_summary["toolCallCount"] += len(telemetry.get("toolCalls") or [])
        telemetry_summary["durationMs"] += int(telemetry.get("durationMs") or 0)
        telemetry_summary["inputTokens"] += int(telemetry.get("inputTokens") or 0)
        telemetry_summary["outputTokens"] += int(telemetry.get("outputTokens") or 0)
        telemetry_summary["rawContentStored"] = (
            telemetry_summary["rawContentStored"]
            or telemetry.get("rawContentStored") is not False
        )
        for finding in result.get("findings") or []:
            resolution_key = str(finding["resolutionKey"])
            resolution_views.setdefault(resolution_key, []).append(
                {
                    "roleId": role_id,
                    "disposition": str(finding["disposition"]),
                    "findingId": str(finding["findingId"]),
                }
            )
            relevant_references = resolution_evidence_references.setdefault(
                resolution_key, set()
            )
            for evidence_kind in finding.get("evidenceKinds") or []:
                relevant_references.update(evidence_by_kind.get(str(evidence_kind), set()))
        for change in result.get("changes") or []:
            path = str(change["path"])
            for prior_path, prior_owner in changed_path_owners:
                if prior_owner != role_id and scopes_overlap(path, prior_path):
                    diagnostics.append(
                        _specialist_diagnostic(
                            "JSTACK-SPECIALIST-CHANGE-OWNERSHIP-CONFLICT",
                            f"Changed path '{path}' claimed by '{role_id}' overlaps "
                            f"'{prior_path}' claimed by '{prior_owner}'.",
                            role_id=role_id,
                        )
                    )
            changed_path_owners.append((path, role_id))

    reconciliations: list[dict[str, Any]] = []
    for resolution_key, views in sorted(resolution_views.items()):
        dispositions = {
            item["disposition"]
            for item in views
            if item["disposition"] != "not-applicable"
        }
        resolution = resolutions.get(resolution_key)
        if len(dispositions) > 1 and resolution is None:
            diagnostics.append(
                _specialist_diagnostic(
                    "JSTACK-SPECIALIST-UNRESOLVED-CONTRADICTION",
                    f"Specialists disagree on '{resolution_key}': "
                    + ", ".join(
                        f"{item['roleId']}={item['disposition']}" for item in views
                    ),
                    resolution_key=resolution_key,
                )
            )
        if resolution is not None:
            unknown_references = sorted(
                set(str(item) for item in resolution["evidenceReferences"])
                - resolution_evidence_references.get(resolution_key, set())
            )
            if unknown_references:
                diagnostics.append(
                    _specialist_diagnostic(
                        "JSTACK-SPECIALIST-RESOLUTION-EVIDENCE-MISMATCH",
                        f"Lead resolution for '{resolution_key}' cites evidence not present "
                        "in the relevant signed specialist findings: "
                        + ", ".join(unknown_references),
                        resolution_key=resolution_key,
                    )
                )
            reconciliations.append(
                {
                    "resolutionKey": resolution_key,
                    "specialistViews": views,
                    "leadResolution": resolution,
                }
            )
            if resolution["decision"] == "block":
                diagnostics.append(
                    _specialist_diagnostic(
                        "JSTACK-SPECIALIST-LEAD-RESOLUTION-BLOCKS",
                        f"Lead resolution for '{resolution_key}' remains blocking.",
                        resolution_key=resolution_key,
                    )
                )
    for resolution_key in sorted(set(resolutions) - set(resolution_views)):
        diagnostics.append(
            _specialist_diagnostic(
                "JSTACK-SPECIALIST-UNREFERENCED-RESOLUTION",
                f"Resolution '{resolution_key}' does not correspond to a specialist finding.",
                severity="warning",
                resolution_key=resolution_key,
            )
        )
    subject_after = evidence_subject(project_path)
    if any(
        subject_after[field] != subject_before[field]
        for field in ("gitHead", "projectFingerprint", "policyDigest", "toolVersion")
    ):
        raise ToolError(
            "The project changed while specialist handoff receipts were being checked. Re-run against one stable state."
        )
    error_diagnostics = [item for item in diagnostics if item["severity"] == "error"]
    valid = not error_diagnostics
    handoff_receipt = None
    if valid:
        handoff_receipt = issue_receipt(
            {
                "kind": "specialist-handoff",
                "schemaVersion": "jstack.specialist.handoff-receipt.v1",
                "projectPath": subject_after["gitRoot"],
                "gitHead": subject_after["gitHead"],
                "projectFingerprint": subject_after["projectFingerprint"],
                "baseRef": subject_after.get("baseRef"),
                "baseCommit": subject_after.get("baseCommit"),
                "policyDigest": subject_after["policyDigest"],
                "toolVersion": SERVER_VERSION,
                "goalDigest": goal_digest,
                "teamMode": team_mode,
                "teamRoleIds": routed_role_ids,
                "capabilityCatalogDigest": team["capabilityPlan"]["catalogDigest"],
                "capabilitySelectionDigest": team["capabilityPlan"]["selectionDigest"],
                "specialistReceiptDigests": [
                    verified_by_role[role_id]["receiptDigest"]
                    for role_id in routed_role_ids
                ],
                "reconciliationDigest": _specialist_digest(reconciliations),
                "telemetrySummaryDigest": _specialist_digest(telemetry_summary),
                "passed": True,
            }
        )
    return {
        "schemaVersion": "jstack.specialist.handoff.v1",
        "valid": valid,
        "complete": valid,
        "goalDigest": goal_digest,
        "teamMode": team_mode,
        "teamRoleIds": routed_role_ids,
        "capabilityCatalogDigest": team["capabilityPlan"]["catalogDigest"],
        "capabilitySelectionDigest": team["capabilityPlan"]["selectionDigest"],
        "verifiedRoles": [
            {
                "roleId": role_id,
                "capabilityIds": expected_by_role[role_id],
                "receiptDigest": verified_by_role[role_id]["receiptDigest"],
                "resultStatus": verified_by_role[role_id]["payload"]["result"]["status"],
            }
            for role_id in routed_role_ids
            if role_id in verified_by_role
        ],
        "diagnostics": diagnostics,
        "reconciliations": reconciliations,
        "telemetrySummary": telemetry_summary,
        "specialistHandoffReceipt": handoff_receipt,
        "handoffReceiptDigest": _receipt_digest(handoff_receipt) if handoff_receipt else None,
        "receiptMeaning": (
            "When issued, this session-local receipt proves complete current-role coverage, structural validity, capability/catalog binding, Git-state binding, and explicit contradiction reconciliation. It does not prove semantic truth or authorize release."
        ),
    }


def tool_health(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    status = safe_run(["git", "status", "--short"], project_path, timeout=10)
    branch = safe_run(["git", "branch", "--show-current"], project_path, timeout=10)
    files = {
        "packageJson": (project_path / "package.json").exists(),
        "pyproject": (project_path / "pyproject.toml").exists(),
        "pytestIni": (project_path / "pytest.ini").exists(),
        "cargoToml": (project_path / "Cargo.toml").exists(),
        "goMod": (project_path / "go.mod").exists(),
        "readme": any((project_path / name).exists() for name in ["README.md", "README"]),
        "securityDoc": (project_path / "SECURITY.md").exists(),
        "architectureDoc": (project_path / "ARCHITECTURE.md").exists(),
    }
    dirty_count = len([line for line in status["stdout"].splitlines() if line.strip()])
    return {
        "projectPath": str(project_path),
        "gitRoot": git_root(project_path),
        "branch": branch["stdout"].strip() if branch["ok"] else None,
        "dirtyFileCount": dirty_count,
        "gitStatus": status,
        "projectFiles": files,
        "testCommands": discover_test_commands(project_path),
        "gstack": tool_detect_project({"project_path": str(project_path)}),
    }


def tool_review(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    evidence = git_change_evidence(project_path, str(args.get("base_ref") or "").strip() or None)
    checks = {
        "unstaged": safe_run(["git", "diff", "--check"], project_path, timeout=15),
        "staged": safe_run(["git", "diff", "--cached", "--check"], project_path, timeout=15),
    }
    if evidence["baseCommit"]:
        checks["committed"] = safe_run(
            ["git", "diff", "--check", f"{evidence['baseCommit']}..HEAD", "--"], project_path, timeout=15
        )
    failed_checks = [name for name, result in checks.items() if result["returncode"] != 0]
    combined = {
        "ok": not failed_checks,
        "returncode": 0 if not failed_checks else 1,
        "failedChecks": failed_checks,
        "checks": checks,
    }
    return {
        "projectPath": str(project_path),
        "status": safe_run(["git", "status", "--short"], project_path, timeout=10),
        "diffStat": safe_run(["git", "diff", "--stat"], project_path, timeout=15),
        "diffCheck": combined,
        "changedFiles": evidence["files"],
        "changeEvidence": evidence,
        "reviewGuidance": [
            "Lead with bugs, security risks, data leaks, auth/RBAC gaps, and missing tests.",
            "Check whether the diff touches secrets, auth boundaries, persistence, external integrations or deployment files.",
            "Run project tests outside this MCP when changes are substantial or deployment-facing.",
        ],
    }


SECRET_PATTERNS = [
    # OpenAI-style keys are standalone tokens.  Without the leading boundary,
    # long JStack identifiers such as ``jstack-beta1-...`` are false positives
    # because their final two letters also spell ``sk``.
    ("openai_key", re.compile(r"(?<![A-Za-z0-9])sk-[A-Za-z0-9_-]{20,}")),
    ("generic_api_key_assignment", re.compile(r"(?i)(api[_-]?key|secret|token|password)\s*[:=]\s*['\"][^'\"\n]{12,}['\"]")),
    ("private_key", re.compile(r"-----BEGIN (?:RSA |EC |OPENSSH |DSA )?PRIVATE KEY-----")),
    ("aws_access_key", re.compile(r"AKIA[0-9A-Z]{16}")),
]


def should_scan(path: Path) -> bool:
    if path.suffix.lower() in {
        ".png", ".jpg", ".jpeg", ".gif", ".webp", ".ico", ".pdf", ".zip", ".gz", ".tar",
        ".rar", ".7z", ".sqlite", ".db", ".woff", ".woff2", ".ttf", ".otf", ".mp3", ".mp4",
        ".mov", ".avi", ".dll", ".exe", ".dylib", ".so", ".pyc",
    }:
        return False
    return True


def tool_security_audit(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    base_ref = str(args.get("base_ref") or "").strip() or None
    subject = evidence_subject(project_path, base_ref)
    max_files = int(args.get("max_files") or 2000)
    max_file_bytes = int(args.get("max_file_bytes") or 2_000_000)
    findings: list[dict[str, Any]] = []
    scan_errors: list[dict[str, str]] = []
    skipped_binary = 0
    scanned = 0
    truncated = False
    for root, dirs, files in os.walk(project_path, followlinks=False):
        kept_dirs: list[str] = []
        for item in dirs:
            directory = Path(root) / item
            if item in EXCLUDED_DIRS:
                continue
            if directory.is_symlink():
                scan_errors.append({"path": str(directory.relative_to(project_path)), "reason": "symlink_directory_not_scanned"})
                continue
            kept_dirs.append(item)
        dirs[:] = kept_dirs
        for filename in files:
            if scanned >= max_files:
                truncated = True
                break
            path = Path(root) / filename
            relative = path.relative_to(project_path).as_posix()
            try:
                metadata = path.lstat()
            except OSError as exc:
                scan_errors.append({"path": relative, "reason": f"lstat_failed:{type(exc).__name__}"})
                continue
            if stat.S_ISLNK(metadata.st_mode):
                scan_errors.append({"path": relative, "reason": "symlink_file_not_scanned"})
                continue
            if not stat.S_ISREG(metadata.st_mode):
                scan_errors.append({"path": relative, "reason": "non_regular_file_not_scanned"})
                continue
            if not should_scan(path):
                skipped_binary += 1
                continue
            if metadata.st_size > max_file_bytes:
                scan_errors.append({"path": relative, "reason": f"file_exceeds_{max_file_bytes}_byte_limit"})
                continue
            scanned += 1
            try:
                flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
                descriptor = os.open(path, flags)
                opened = os.fstat(descriptor)
                if not stat.S_ISREG(opened.st_mode) or (
                    hasattr(metadata, "st_ino")
                    and (opened.st_ino != metadata.st_ino or opened.st_dev != metadata.st_dev)
                ):
                    os.close(descriptor)
                    scan_errors.append({"path": relative, "reason": "file_changed_during_scan"})
                    continue
                handle = os.fdopen(descriptor, "r", encoding="utf-8", errors="ignore")
            except OSError as exc:
                scan_errors.append({"path": relative, "reason": f"open_failed:{type(exc).__name__}"})
                continue
            with handle:
                for line_no, line in enumerate(handle, start=1):
                    for name, pattern in SECRET_PATTERNS:
                        if pattern.search(line):
                            findings.append({"file": relative, "line": line_no, "pattern": name})
                            break
                    if len(findings) >= 100:
                        truncated = True
                        break
            if len(findings) >= 100:
                break
        if scanned >= max_files or len(findings) >= 100:
            break
    if scanned >= max_files:
        truncated = True

    release_range_findings = 0
    if subject["baseCommit"] and subject["baseCommit"] != subject["gitHead"]:
        history = run_complete(
            [
                "git",
                "log",
                "--no-ext-diff",
                "--no-textconv",
                "--format=",
                "--patch",
                "--reverse",
                "--unified=0",
                f"{subject['baseCommit']}..{subject['gitHead']}",
                "--",
            ],
            project_path,
            timeout=30,
            max_bytes=10_000_000,
        )
        if not history["ok"]:
            scan_errors.append({"path": "<release-range>", "reason": f"history_scan_failed:{history['stderr']}"})
        else:
            for line_no, line in enumerate(_git_text(history).splitlines(), start=1):
                if not line.startswith(("+", "-")) or line.startswith(("+++", "---")):
                    continue
                for name, pattern in SECRET_PATTERNS:
                    if pattern.search(line[1:]):
                        findings.append(
                            {
                                "file": "<release-range>",
                                "line": line_no,
                                "pattern": name,
                                "scope": f"{subject['baseCommit']}..{subject['gitHead']}",
                            }
                        )
                        release_range_findings += 1
                        break
                if len(findings) >= 100:
                    truncated = True
                    break
    complete = not truncated and not scan_errors
    passed = complete and not findings
    receipt = issue_receipt(
        {
            "kind": "security",
            "projectPath": subject["gitRoot"],
            "scanRoot": subject["gitRoot"],
            "gitHead": subject["gitHead"],
            "projectFingerprint": subject["projectFingerprint"],
            "baseRef": subject["baseRef"],
            "baseCommit": subject["baseCommit"],
            "policyDigest": subject["policyDigest"],
            "toolVersion": SERVER_VERSION,
            "passed": passed,
            "findingCount": len(findings),
            "complete": complete,
        }
    )
    return {
        "projectPath": str(project_path),
        "scannedFiles": scanned,
        "skippedKnownBinaryFiles": skipped_binary,
        "truncated": truncated,
        "complete": complete,
        "scanErrors": scan_errors,
        "findingCount": len(findings),
        "releaseRangeFindingCount": release_range_findings,
        "findings": findings,
        "passed": passed,
        "evidenceReceipt": receipt,
        "evidenceState": subject,
        "note": "Bounded heuristic secret scan only. A complete clean result is required, and formal dependency/container/SAST scanning remains a separate production gate.",
    }


def audit_json_digest(value: Any) -> str:
    payload = json.dumps(
        value,
        ensure_ascii=True,
        allow_nan=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return "sha256:" + hashlib.sha256(payload).hexdigest()


def audit_enforce_json_limit(value: Any, label: str, maximum: int) -> None:
    try:
        size = len(
            json.dumps(
                value,
                ensure_ascii=True,
                allow_nan=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        )
    except (TypeError, ValueError) as exc:
        raise ToolError(f"{label} must be canonical JSON data.") from exc
    if size > maximum:
        raise ToolError(f"{label} exceeds the {maximum}-byte safety limit.")


def audit_reject_secret_values(value: Any, label: str) -> None:
    if isinstance(value, str):
        if audit_core.contains_secret_like(value):
            raise ToolError(
                f"{label} contains a secret-like value. Submit only a redacted classification and source location."
            )
        return
    if isinstance(value, dict):
        for child in value.values():
            audit_reject_secret_values(child, label)
        return
    if isinstance(value, list):
        for child in value:
            audit_reject_secret_values(child, label)


def audit_public_policy(project_path: Path) -> tuple[dict[str, Any], str]:
    policy = load_enterprise_policy(project_path)
    public = {key: value for key, value in policy.items() if not key.startswith("_")}
    return policy, audit_json_digest(public).split(":", 1)[1]


def audit_git_inventory_paths(project_path: Path) -> list[str]:
    result = run_complete(
        ["git", "ls-files", "--cached", "--others", "--exclude-standard", "-z"],
        project_path,
        timeout=30,
        max_bytes=20_000_000,
    )
    if not result["ok"]:
        raise ToolError(f"Could not enumerate the Git audit scope: {result['stderr']}")
    paths: list[str] = []
    for raw in result["stdout"].split(b"\0"):
        if not raw:
            continue
        try:
            relative = decode_git_relative_path(raw, "audit")
            relative = audit_core.normalize_repo_path(relative, "git audit path")
        except audit_core.AuditError as exc:
            raise ToolError("Git returned an audit path that cannot be represented safely.") from exc
        candidate = project_path / relative
        if candidate.is_file() or candidate.is_symlink():
            paths.append(relative)
    return sorted(set(paths))


def audit_effective_scope(
    project_path: Path,
    evidence_mode: str,
    profile: str,
    requested_scope: Any,
    base_ref: Optional[str],
) -> tuple[str, list[str], list[str]]:
    if requested_scope is not None:
        try:
            normalized_request = audit_core.normalize_scope(requested_scope)
        except audit_core.AuditError as exc:
            raise ToolError(str(exc)) from exc
        if profile == "release":
            if normalized_request != ["."]:
                raise ToolError(
                    "Release audits require repository scope; a caller-selected partial scope cannot certify a release."
                )
            scope_mode = "repository"
        else:
            scope_mode = "explicit"
    elif evidence_mode == "git" and profile == "quick":
        normalized_request = []
        scope_mode = "changed"
    else:
        normalized_request = ["."]
        scope_mode = "repository"

    if evidence_mode != "git":
        return scope_mode, normalized_request or ["."], normalized_request or ["."]

    all_paths = audit_git_inventory_paths(project_path)
    if scope_mode == "changed":
        changed = git_change_evidence(project_path, base_ref)["files"]
        effective = [path for path in changed if path in set(all_paths)]
        if not effective:
            effective = all_paths
        return scope_mode, ["<current-delta>"], effective or ["jstack.enterprise.json"]
    if normalized_request == ["."]:
        return scope_mode, normalized_request, all_paths or ["jstack.enterprise.json"]

    expanded: list[str] = []
    for requested in normalized_request:
        exact = requested in all_paths
        prefix = requested.rstrip("/") + "/"
        matches = [path for path in all_paths if path.startswith(prefix)]
        if exact:
            expanded.append(requested)
        expanded.extend(matches)
        if not exact and not matches:
            expanded.append(requested)
    return scope_mode, normalized_request, sorted(set(expanded))


def audit_release_range_digest(project_path: Path, base_ref: Optional[str]) -> Optional[str]:
    if not base_ref:
        return None
    evidence = git_change_evidence(project_path, base_ref)
    head = run_complete(
        ["git", "rev-parse", "HEAD"],
        project_path,
        timeout=10,
        max_bytes=4096,
    )
    if not head["ok"]:
        raise ToolError("Could not bind the audit release range to HEAD.")
    return audit_json_digest(
        {
            "baseCommit": evidence.get("baseCommit"),
            "gitHead": head["stdout"].decode("ascii", errors="strict").strip(),
            "files": sorted(set(evidence.get("files") or [])),
        }
    )


def audit_inventory_summary(inventory: dict[str, Any]) -> dict[str, Any]:
    return {
        "schemaVersion": inventory.get("schemaVersion"),
        "scopeManifestDigest": inventory.get("scopeManifestDigest"),
        "fileCount": inventory.get("fileCount"),
        "totalBytes": inventory.get("totalBytes"),
        "complete": inventory.get("complete"),
        "limits": inventory.get("limits"),
        "gaps": inventory.get("gaps"),
    }


def audit_subject_for_binding(
    project_path: Path,
    evidence_mode: str,
    base_ref: Optional[str],
    inventory: dict[str, Any],
) -> dict[str, Any]:
    if evidence_mode == "git":
        subject = evidence_subject(project_path, base_ref)
        return {
            **subject,
            "evidenceMode": "git",
            "projectPath": subject["gitRoot"],
        }
    _, policy_digest = audit_public_policy(project_path)
    return {
        "evidenceMode": "artifact-only",
        "projectPath": str(project_path),
        "gitRoot": None,
        "gitHead": None,
        "baseRef": None,
        "baseCommit": None,
        "projectFingerprint": str(inventory["scopeManifestDigest"]),
        "policyDigest": policy_digest,
        "toolVersion": SERVER_VERSION,
        "clean": None,
    }


def audit_adapter_executable(command: list[str], project_path: Path) -> dict[str, Any]:
    if command and command[0] in {"npm", "npx"}:
        return {
            "available": False,
            "reason": "project-local-node-toolchain-not-attested",
        }
    with tempfile.TemporaryDirectory(prefix="jstack-audit-plan-") as temp_home:
        env = approved_command_env([], Path(temp_home), project_path)
        executable = (
            sys.executable
            if command and command[0] in {"python", "python3", "py"}
            else shutil.which(command[0], path=env["PATH"]) if command else None
        )
    if not executable:
        return {"available": False, "reason": "executable-not-found"}
    resolved = Path(executable).resolve()
    try:
        resolved.relative_to(project_path)
    except ValueError:
        pass
    else:
        return {"available": False, "reason": "project-local-executable-rejected"}
    try:
        metadata = resolved.stat()
        if not stat.S_ISREG(metadata.st_mode) or metadata.st_size > 100_000_000:
            return {"available": False, "reason": "executable-identity-unsupported"}
        digest = hashlib.sha256()
        with resolved.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
    except OSError:
        return {"available": False, "reason": "executable-unreadable"}
    return {
        "available": True,
        "resolvedExecutable": str(resolved),
        "executableSha256": digest.hexdigest(),
    }


def audit_adapter_plans(
    inventory: dict[str, Any],
    subject: dict[str, Any],
    control_digest: str,
    project_path: Path,
) -> list[dict[str, Any]]:
    binding = {
        "repositoryRoot": str(project_path),
        "revision": str(subject.get("gitHead") or inventory["scopeManifestDigest"]),
        "workspaceFingerprint": str(subject["projectFingerprint"]),
        "policyDigest": str(subject["policyDigest"]),
        "controlDigest": control_digest,
        "scopeManifestDigest": str(inventory["scopeManifestDigest"]),
    }
    discovery = audit_core.discover_adapters(inventory, binding)
    plans: list[dict[str, Any]] = []
    for raw_plan in discovery["adapters"]:
        plan = dict(raw_plan)
        required_environment = plan.get("requiredEnvironment") or []
        if not isinstance(required_environment, list) or not all(
            isinstance(name, str)
            and re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name)
            for name in required_environment
        ):
            raise ToolError("Curated audit adapter required-environment metadata is invalid.")
        adapter_version = audit_json_digest(
            {
                "adapterId": plan["adapterId"],
                "capability": plan["capability"],
                "command": plan["command"],
                "environment": plan["environment"],
                "requiredEnvironment": required_environment,
            }
        )
        resolved_environment = dict(plan["environment"])
        missing_environment = [
            name
            for name in required_environment
            if not isinstance(os.environ.get(name), str)
            or not str(os.environ.get(name)).strip()
            or "\x00" in str(os.environ.get(name))
            or len(str(os.environ.get(name))) > 4096
        ]
        if not missing_environment:
            resolved_environment.update(
                {name: str(os.environ[name]) for name in required_environment}
            )
        executable = audit_adapter_executable(list(plan["command"]), project_path)
        if missing_environment:
            executable = {
                "available": False,
                "reason": "missing-required-environment:" + ",".join(missing_environment),
            }
        elif plan["adapterId"] == "osv-scanner-offline":
            cache_path = Path(
                resolved_environment["OSV_SCANNER_LOCAL_DB_CACHE_DIRECTORY"]
            ).expanduser()
            try:
                resolved_cache = cache_path.resolve(strict=True)
                resolved_cache.relative_to(project_path.resolve())
            except FileNotFoundError:
                executable = {
                    "available": False,
                    "reason": "osv-local-database-directory-not-found",
                }
            except OSError:
                executable = {
                    "available": False,
                    "reason": "osv-local-database-directory-unreadable",
                }
            except ValueError:
                if not resolved_cache.is_dir():
                    executable = {
                        "available": False,
                        "reason": "osv-local-database-path-is-not-a-directory",
                    }
                elif not os.access(resolved_cache, os.R_OK | os.X_OK):
                    executable = {
                        "available": False,
                        "reason": "osv-local-database-directory-unreadable",
                    }
                elif not (resolved_cache / "osv-scanner").is_dir():
                    executable = {
                        "available": False,
                        "reason": "osv-local-database-content-not-found",
                    }
                else:
                    resolved_environment[
                        "OSV_SCANNER_LOCAL_DB_CACHE_DIRECTORY"
                    ] = str(resolved_cache)
            else:
                executable = {
                    "available": False,
                    "reason": "osv-local-database-must-be-outside-repository",
                }
        plan["adapterVersion"] = adapter_version
        plan["environment"] = dict(sorted(resolved_environment.items()))
        plan["availability"] = executable
        if executable.get("available"):
            subject_value = dict(plan["approvalSubject"])
            subject_value.update(
                {
                    "adapterVersion": adapter_version,
                    "environment": plan["environment"],
                    "resolvedExecutable": executable["resolvedExecutable"],
                    "executableSha256": executable["executableSha256"],
                    "serverVersion": SERVER_VERSION,
                }
            )
            plan["approvalSubject"] = subject_value
            plan["approvalSubjectDigest"] = audit_json_digest(subject_value)
        plans.append(plan)
    return plans


def audit_run_approved_adapters(
    approvals: Any,
    plans: list[dict[str, Any]],
    project_path: Path,
    evidence_mode: str,
    base_ref: Optional[str],
    inventory: dict[str, Any],
    timeout: int,
) -> list[dict[str, Any]]:
    if approvals is None:
        return []
    if not isinstance(approvals, list):
        raise ToolError("adapter_approvals must be an array.")
    by_id = {plan["adapterId"]: plan for plan in plans}
    results: list[dict[str, Any]] = []
    seen: set[str] = set()
    for approval in approvals:
        if not isinstance(approval, dict):
            raise ToolError("Each adapter approval must be an object.")
        raw_subject = approval.get("subject")
        adapter_id = str(raw_subject.get("adapterId") or "") if isinstance(raw_subject, dict) else ""
        if not adapter_id or adapter_id in seen or adapter_id not in by_id:
            raise ToolError("Adapter approvals must reference unique applicable curated adapter subjects.")
        seen.add(adapter_id)
        plan = by_id[adapter_id]
        if not plan.get("availability", {}).get("available"):
            raise ToolError(f"Approved audit adapter is unavailable: {adapter_id}")
        for field in ("approvedBy", "approvalReference", "approvedAt"):
            if not isinstance(approval.get(field), str) or not str(approval[field]).strip():
                raise ToolError(f"Audit adapter approval requires non-empty {field} metadata.")
        try:
            approved_at = _dt.datetime.fromisoformat(str(approval["approvedAt"]).replace("Z", "+00:00"))
            if approved_at.tzinfo is None:
                raise ValueError("timezone required")
            approval_age = (_dt.datetime.now(_dt.timezone.utc) - approved_at.astimezone(_dt.timezone.utc)).total_seconds()
        except ValueError as exc:
            raise ToolError("Audit adapter approvedAt must be an unambiguous ISO-8601 timestamp.") from exc
        if not 0 <= approval_age <= RECEIPT_MAX_AGE_SECONDS:
            raise ToolError("Audit adapter approval is future-dated or older than the active evidence window.")
        audit_core.require_adapter_approval(approval, plan["approvalSubject"])
        current_executable = audit_adapter_executable(list(plan["command"]), project_path)
        expected_executable = plan["approvalSubject"]
        if (
            not current_executable.get("available")
            or current_executable.get("resolvedExecutable") != expected_executable["resolvedExecutable"]
            or current_executable.get("executableSha256") != expected_executable["executableSha256"]
        ):
            raise ToolError("Approved audit adapter executable identity changed before execution.")
        before = (
            project_state(project_path)["projectFingerprint"]
            if evidence_mode == "git"
            else inventory["scopeManifestDigest"]
        )
        execution = run_approved_project_command(
            list(plan["command"]),
            project_path,
            timeout=timeout,
            env_allowlist=[],
            fixed_env={**plan["environment"], "JSTACK_AUDIT_EXECUTION": "1"},
        )
        after_inventory = audit_core.inventory_repository(
            project_path,
            inventory["scope"],
            max_files=int(inventory["limits"]["maxFiles"]),
            max_bytes=int(inventory["limits"]["maxBytes"]),
            max_seconds=float(inventory["limits"]["maxSeconds"]),
        )
        after = (
            project_state(project_path)["projectFingerprint"]
            if evidence_mode == "git"
            else after_inventory["scopeManifestDigest"]
        )
        mutation_detected = before != after or after_inventory["scopeManifestDigest"] != inventory["scopeManifestDigest"]
        status = "stale" if mutation_detected else "passed" if execution["ok"] else "failed"
        if execution["returncode"] in {124, 125}:
            status = "capped"
        output_fingerprint = audit_json_digest(
            {
                "adapterVersion": plan["adapterVersion"],
                "returncode": execution["returncode"],
                "stdoutSha256": execution.get("stdoutSha256")
                or hashlib.sha256(str(execution["stdout"]).encode("utf-8")).hexdigest(),
                "stderrSha256": execution.get("stderrSha256")
                or hashlib.sha256(str(execution["stderr"]).encode("utf-8")).hexdigest(),
                "capturedOutputBytes": execution.get("capturedOutputBytes"),
                "mutationDetected": mutation_detected,
            }
        )
        result = audit_core.make_adapter_result(
            plan,
            approval,
            status,
            evidence_fingerprint=output_fingerprint,
            capped=status == "capped",
        )
        result.update(
            {
                "adapterVersion": plan["adapterVersion"],
                "returnCode": execution["returncode"],
                "mutationDetected": mutation_detected,
                "outputFingerprint": output_fingerprint,
            }
        )
        results.append(result)
    return sorted(results, key=lambda item: item["adapterId"])


def audit_artifact_secret_scan(project_path: Path, inventory: dict[str, Any]) -> dict[str, Any]:
    findings: list[dict[str, Any]] = []
    errors: list[dict[str, str]] = []
    scanned = 0
    for item in inventory.get("files", []):
        relative = str(item.get("path") or "")
        path = project_path / relative
        if not should_scan(path):
            continue
        if int(item.get("size") or 0) > 2_000_000:
            errors.append({"path": relative, "reason": "unsupported_or_oversized"})
            continue
        try:
            content = audit_core.read_repository_file(
                project_path,
                relative,
                max_bytes=max(1, int(item.get("size") or 0)),
                max_seconds=10,
            )
        except audit_core.AuditError as exc:
            errors.append({"path": relative, "reason": f"open_failed:{type(exc).__name__}"})
            continue
        if (
            len(content) != item.get("size")
            or hashlib.sha256(content).hexdigest() != item.get("sha256")
        ):
            errors.append({"path": relative, "reason": "file_identity_changed"})
            continue
        scanned += 1
        for line_number, line in enumerate(content.decode("utf-8", errors="ignore").splitlines(), start=1):
            for pattern_name, pattern in SECRET_PATTERNS:
                if pattern.search(line):
                    findings.append(
                        {"file": relative, "line": line_number, "pattern": pattern_name}
                    )
                    break
            if len(findings) >= 100:
                break
        if len(findings) >= 100:
            break
    complete = inventory.get("complete") is True and not errors and len(findings) < 100
    return {
        "scannedFiles": scanned,
        "complete": complete,
        "passed": complete and not findings,
        "findingCount": len(findings),
        "findings": findings,
        "scanErrors": errors,
        "evidenceReceipt": None,
        "note": "Advisory artifact-only credential-pattern scan; no Git-bound security receipt is available.",
    }


def audit_deterministic_evidence(
    subject_digest: str,
    inventory: dict[str, Any],
    security: dict[str, Any],
    review: Optional[dict[str, Any]],
    profile: str,
    subject: dict[str, Any],
) -> list[dict[str, Any]]:
    evidence = [
        {
            "id": "jstack-subject-binding",
            "type": "subject-binding",
            "status": "complete",
            "subjectFingerprint": subject_digest,
            "summary": "Repository or artifact subject is bound to the active MCP session.",
        },
        {
            "id": "jstack-scope-inventory",
            "type": "scope-inventory",
            "status": "complete" if inventory.get("complete") is True else "incomplete",
            "subjectFingerprint": subject_digest,
            "summary": "Bounded content-free inventory completed without a coverage gap."
            if inventory.get("complete") is True
            else "Bounded inventory reported one or more coverage gaps.",
        },
        {
            "id": "jstack-secret-scan",
            "type": "secret-scan",
            "status": "complete" if security.get("complete") is True else "incomplete",
            "subjectFingerprint": subject_digest,
            "summary": "Credential-pattern scan completed; finding values were not retained."
            if security.get("complete") is True
            else "Credential-pattern scan coverage was incomplete.",
        },
    ]
    if review is not None:
        diff_clean = bool(review.get("diffCheck", {}).get("ok"))
        evidence.append(
            {
                "id": "jstack-diff-hygiene",
                "type": "diff-hygiene",
                "status": "complete" if diff_clean else "incomplete",
                "subjectFingerprint": subject_digest,
                "summary": "Git diff whitespace/error checks passed."
                if diff_clean
                else "One or more Git diff checks failed.",
            }
        )
    if profile == "release":
        distinct = bool(subject.get("baseCommit")) and subject.get("baseCommit") != subject.get("gitHead")
        evidence.extend(
            [
                {
                    "id": "jstack-distinct-release-base",
                    "type": "distinct-release-base",
                    "status": "complete" if distinct else "incomplete",
                    "subjectFingerprint": subject_digest,
                    "summary": "Release audit has an exact distinct pre-release baseline."
                    if distinct
                    else "Release audit lacks an exact distinct pre-release baseline.",
                },
                {
                    "id": "jstack-current-security-receipt",
                    "type": "current-security-receipt",
                    "status": "complete"
                    if security.get("complete") is True and security.get("evidenceReceipt")
                    else "incomplete",
                    "subjectFingerprint": subject_digest,
                    "summary": "A current session-local security scan receipt is available."
                    if security.get("evidenceReceipt")
                    else "A Git-bound security scan receipt is unavailable.",
                },
            ]
        )
    return evidence


def audit_effective_fail_on(policy_value: Any, requested: Any) -> str:
    ordered = ["info", "low", "medium", "high", "critical", "none"]
    policy_text = str(policy_value or "high").strip().lower()
    requested_text = str(requested or policy_text).strip().lower()
    if policy_text not in ordered or requested_text not in ordered:
        raise ToolError("Audit failure threshold must be info, low, medium, high, critical, or none.")
    floor_index = min(ordered.index("high"), ordered.index(policy_text))
    return ordered[min(floor_index, ordered.index(requested_text))]


def audit_effective_required_domains(
    profile_definition: dict[str, Any], audit_policy: dict[str, Any]
) -> list[str]:
    configured = [
        "correctness" if str(item) == "reliability" else str(item)
        for item in audit_policy.get("requiredDomains", [])
    ]
    required = set(profile_definition["requiredDomains"]) | set(configured)
    return [domain for domain in audit_core.DOMAINS if domain in required]


def tool_audit(args: dict[str, Any]) -> dict[str, Any]:
    binding = resolve_project_binding(args.get("project_path"))
    project_path = Path(binding["projectPath"]).resolve()
    context_readiness = None
    if args.get("context_readiness_receipt"):
        context_goal = str(args.get("context_goal") or "").strip()
        if not context_goal:
            raise ToolError(
                "context_goal is required when context_readiness_receipt is supplied."
            )
        context_readiness = verify_context_readiness_receipt(
            str(args["context_readiness_receipt"]),
            goal=context_goal,
            workflow_mode="jstack-audit",
            binding=binding,
            context_brief=args.get("context_brief"),
        )
        expected_parameters = context_readiness["normalizedBrief"].get(
            "workflowParameters", {}
        )
        actual_parameters = audit_context_workflow_parameters(args)
        if expected_parameters != actual_parameters:
            raise ToolError(
                "Audit profile, scope, focus, or base_ref does not match the context-readiness brief. Re-run jstack_context_readiness with the exact audit workflow_parameters."
            )
    policy, _ = audit_public_policy(project_path)
    audit_policy = policy.get("audit", {})
    profile = str(args.get("profile") or audit_policy.get("defaultProfile") or "standard").strip().lower()
    try:
        profile_definition = audit_core.get_profile(profile)
    except audit_core.AuditError as exc:
        raise ToolError(str(exc)) from exc
    base_ref = str(args.get("base_ref") or "").strip() or None
    if binding["evidenceMode"] == "git":
        if base_ref is not None:
            resolved_base = resolve_base_ref(project_path, base_ref)
            base_ref = str(resolved_base.get("baseCommit") or "").strip() or None
        elif profile != "release":
            discovered_base = resolve_base_ref(project_path)
            base_ref = str(discovered_base.get("baseCommit") or "").strip() or None
    fail_on = audit_effective_fail_on(audit_policy.get("failOnSeverity"), args.get("fail_on"))
    required_domains = audit_effective_required_domains(profile_definition, audit_policy)
    audit_focus = str(args.get("focus") or "").strip()
    audit_capability_goal = audit_focus or (
        f"{profile} audit of " + " ".join(str(item) for item in (args.get("scope") or ["repository"]))
    )
    audit_capability_classifications = classify_work(audit_capability_goal)
    audit_capability_plan = specialist_capability_plan(
        audit_capability_goal,
        audit_capability_classifications,
        ["reviewer", "security", "qa"],
        [str(item) for item in (args.get("capability_ids") or [])],
    )
    capability_domains = set(audit_capability_plan["auditDomains"])
    required_domain_set = set(required_domains) | capability_domains
    required_domains = [
        domain for domain in audit_core.DOMAINS if domain in required_domain_set
    ]
    if profile == "quick" and args.get("adapter_approvals"):
        raise ToolError("Quick audits prohibit repository-controlled adapter execution.")
    scope_mode, requested_scope, effective_scope = audit_effective_scope(
        project_path,
        binding["evidenceMode"],
        profile,
        args.get("scope"),
        base_ref,
    )
    limits = profile_definition["limits"]
    try:
        inventory = audit_core.inventory_repository(
            project_path,
            effective_scope,
            max_files=int(limits["maxFiles"]),
            max_bytes=int(limits["maxBytes"]),
            max_seconds=float(limits["maxSeconds"]),
        )
        subject = audit_subject_for_binding(
            project_path,
            binding["evidenceMode"],
            base_ref,
            inventory,
        )
        control_digest = audit_core.controls_digest()
        subject_digest = audit_json_digest(
            {
                "projectPath": subject["projectPath"],
                "evidenceMode": subject["evidenceMode"],
                "gitHead": subject.get("gitHead"),
                "baseCommit": subject.get("baseCommit"),
                "projectFingerprint": subject["projectFingerprint"],
                "policyDigest": subject["policyDigest"],
                "controlDigest": control_digest,
                "scopeManifestDigest": inventory["scopeManifestDigest"],
                "profile": profile,
                "failOn": fail_on,
                "toolVersion": SERVER_VERSION,
            }
        )
        adapter_plans = audit_adapter_plans(inventory, subject, control_digest, project_path)
        adapter_results = audit_run_approved_adapters(
            [] if profile == "quick" else args.get("adapter_approvals"),
            adapter_plans,
            project_path,
            binding["evidenceMode"],
            base_ref,
            inventory,
            int(args.get("adapter_timeout_sec") or 120),
        )
    except audit_core.AuditError as exc:
        raise ToolError(str(exc)) from exc

    if binding["evidenceMode"] == "git":
        security = tool_security_audit(
            {
                "project_path": str(project_path),
                "base_ref": base_ref or "",
                "max_files": min(int(limits["maxFiles"]), 100_000),
                "max_file_bytes": 2_000_000,
            }
        )
        review = tool_review({"project_path": str(project_path), "base_ref": base_ref or ""})
    else:
        security = audit_artifact_secret_scan(project_path, inventory)
        review = None

    deterministic_evidence = audit_deterministic_evidence(
        subject_digest,
        inventory,
        security,
        review,
        profile,
        subject,
    )
    adapter_inventory = [
        {
            "adapterId": plan["adapterId"],
            "capability": plan["capability"],
            "adapterVersion": plan["adapterVersion"],
            "available": bool(plan.get("availability", {}).get("available")),
        }
        for plan in adapter_plans
    ]
    expires_at = (
        _dt.datetime.now(_dt.timezone.utc) + _dt.timedelta(seconds=RECEIPT_MAX_AGE_SECONDS)
    ).replace(microsecond=0).isoformat()
    token_payload = {
        "kind": "audit-session",
        "schemaVersion": "jstack.audit.session.v1",
        "expiresAt": expires_at,
        "projectPath": str(project_path),
        "evidenceMode": binding["evidenceMode"],
        "gitHead": subject.get("gitHead"),
        "baseRef": subject.get("baseRef"),
        "baseCommit": subject.get("baseCommit"),
        "projectFingerprint": subject["projectFingerprint"],
        "policyDigest": subject["policyDigest"],
        "controlDigest": control_digest,
        "subjectDigest": subject_digest,
        "scopeMode": scope_mode,
        "requestedScope": requested_scope,
        "scopeManifestDigest": inventory["scopeManifestDigest"],
        "profile": profile,
        "failOn": fail_on,
        "requiredDomains": required_domains,
        "requiredEvidence": profile_definition["requiredEvidence"],
        "adapterRequirements": profile_definition["adapterRequirements"],
        "adapterInventory": adapter_inventory,
        "adapterResults": adapter_results,
        "capabilityCatalogVersion": audit_capability_plan["catalogVersion"],
        "capabilityCatalogDigest": audit_capability_plan["catalogDigest"],
        "capabilitySelectionDigest": audit_capability_plan["selectionDigest"],
        "capabilityGoalDigest": audit_capability_plan["goalDigest"],
        "capabilityIds": [
            item["id"] for item in audit_capability_plan["selectedCapabilities"]
        ],
        "releaseRangeDigest": audit_release_range_digest(project_path, base_ref)
        if profile == "release" and binding["evidenceMode"] == "git"
        else None,
        "releaseScopeCovered": profile == "release"
        and binding["evidenceMode"] == "git"
        and scope_mode == "repository"
        and requested_scope == ["."]
        and inventory.get("complete") is True,
        "toolVersion": SERVER_VERSION,
        "contextBriefDigest": context_readiness.get("briefDigest")
        if context_readiness
        else None,
    }
    audit_session_token = issue_receipt(token_payload)
    return {
        "schemaVersion": "jstack.audit.session-response.v1",
        "projectBinding": binding,
        "contextGate": {
            "requiredByJStackWorkflow": True,
            "receiptBound": context_readiness is not None,
            "readiness": context_readiness,
        },
        "profile": profile,
        "failOn": fail_on,
        "subject": subject,
        "subjectDigest": subject_digest,
        "controlDigest": control_digest,
        "requestedScope": requested_scope,
        "scopeMode": scope_mode,
        "inventory": audit_inventory_summary(inventory),
        "coverageContract": {
            "requiredDomains": required_domains,
            "requiredEvidence": profile_definition["requiredEvidence"],
            "adapterRequirements": profile_definition["adapterRequirements"],
            "limits": profile_definition["limits"],
            "repositoryExecutionAllowed": profile != "quick",
            "capabilityRequiredDomains": audit_capability_plan["auditDomains"],
        },
        "specialistCapabilityPlan": audit_capability_plan,
        "deterministicEvidence": deterministic_evidence,
        "adapterPlans": adapter_plans,
        "adapterResults": adapter_results,
        "securityEvidence": {
            key: security.get(key)
            for key in (
                "complete",
                "passed",
                "findingCount",
                "scannedFiles",
                "scanErrors",
                "evidenceReceipt",
                "note",
            )
        },
        "reviewEvidence": {
            "diffCheck": review.get("diffCheck"),
            "changedFiles": review.get("changedFiles"),
        }
        if review
        else None,
        "auditSessionToken": audit_session_token,
        "expiresAt": expires_at,
        "limitations": binding["limitations"]
        + [
            "The deterministic MCP validates evidence structure and completeness; semantic finding truth remains a reasoned audit judgment.",
            "Curated local execution hardening is not an OS sandbox; use a container or VM for untrusted repositories.",
            "Offline adapter flags do not create an OS network firewall; use a container or VM when enforced network isolation is required.",
        ],
    }


def audit_rebuild_inventory(
    project_path: Path,
    token_payload: dict[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    mode = str(token_payload["evidenceMode"])
    profile = str(token_payload["profile"])
    base_ref = str(token_payload.get("baseCommit") or "").strip() or None
    scope_mode = str(token_payload["scopeMode"])
    if scope_mode == "changed":
        requested = None
    elif scope_mode == "repository":
        requested = ["."]
    else:
        requested = token_payload.get("requestedScope")
    _, _, effective_scope = audit_effective_scope(
        project_path,
        mode,
        profile,
        requested,
        base_ref,
    )
    profile_definition = audit_core.get_profile(profile)
    limits = profile_definition["limits"]
    inventory = audit_core.inventory_repository(
        project_path,
        effective_scope,
        max_files=int(limits["maxFiles"]),
        max_bytes=int(limits["maxBytes"]),
        max_seconds=float(limits["maxSeconds"]),
    )
    subject = audit_subject_for_binding(project_path, mode, base_ref, inventory)
    return inventory, subject


def audit_assert_session_subject(
    token_payload: dict[str, Any],
    binding: dict[str, Any],
    inventory: dict[str, Any],
    subject: dict[str, Any],
) -> None:
    capability_catalog = _capability_call(
        lambda: capability_core.catalog_summary()
    )
    checks = {
        "projectPath": token_payload.get("projectPath") == binding["projectPath"],
        "evidenceMode": token_payload.get("evidenceMode") == binding["evidenceMode"],
        "gitHead": token_payload.get("gitHead") == subject.get("gitHead"),
        "baseCommit": token_payload.get("baseCommit") == subject.get("baseCommit"),
        "projectFingerprint": token_payload.get("projectFingerprint") == subject.get("projectFingerprint"),
        "policyDigest": token_payload.get("policyDigest") == subject.get("policyDigest"),
        "controlDigest": token_payload.get("controlDigest") == audit_core.controls_digest(),
        "scopeManifestDigest": token_payload.get("scopeManifestDigest") == inventory.get("scopeManifestDigest"),
        "toolVersion": token_payload.get("toolVersion") == SERVER_VERSION,
        "capabilityCatalogVersion": token_payload.get("capabilityCatalogVersion")
        == capability_catalog["catalogVersion"],
        "capabilityCatalogDigest": token_payload.get("capabilityCatalogDigest")
        == capability_catalog["catalogDigest"],
    }
    if token_payload.get("profile") == "release" and binding["evidenceMode"] == "git":
        current_range_digest = audit_release_range_digest(
            Path(binding["projectPath"]),
            str(token_payload.get("baseCommit") or "").strip() or None,
        )
        checks["releaseRangeDigest"] = (
            token_payload.get("releaseRangeDigest") == current_range_digest
        )
        checks["releaseScopeCovered"] = token_payload.get("releaseScopeCovered") is True
    if not all(checks.values()):
        failed = ", ".join(key for key, value in checks.items() if not value)
        raise ToolError(f"Audit session evidence is stale; restart the audit. Changed bindings: {failed}.")


def audit_qa_evidence(
    project_path: Path,
    subject: dict[str, Any],
    subject_digest: str,
    receipts: Any,
) -> dict[str, Any]:
    if receipts is None:
        receipts = []
    if not isinstance(receipts, list) or not all(isinstance(item, str) for item in receipts):
        raise ToolError("qa_receipts must be an array of receipt strings.")
    commands = discover_test_commands(project_path)
    state = project_state(project_path)
    valid_by_key: dict[str, dict[str, Any]] = {}
    for receipt in receipts:
        verification = verify_receipt(
            receipt,
            "qa",
            state,
            expected_subject=subject,
        )
        payload = verification.get("payload") or {}
        if verification["valid"] and payload.get("commandKey"):
            valid_by_key[str(payload["commandKey"])] = payload
    missing = []
    for command in commands:
        payload = valid_by_key.get(command["key"])
        if not payload or payload.get("commandFingerprint") != command["commandFingerprint"]:
            missing.append(command["key"])
    complete = bool(commands) and not missing
    return {
        "id": "jstack-current-qa-receipts",
        "type": "current-qa-receipt",
        "status": "complete" if complete else "incomplete",
        "subjectFingerprint": subject_digest,
        "summary": "Current passing receipts cover every discovered QA command."
        if complete
        else "Current QA receipt coverage is missing or stale for: "
        + (", ".join(missing) if missing else "all commands (none discovered)"),
    }


def audit_merge_evidence(
    caller_evidence: Any,
    deterministic: list[dict[str, Any]],
    subject_digest: str,
) -> list[dict[str, Any]]:
    if not isinstance(caller_evidence, list):
        raise ToolError("evidence must be an array.")
    if len(caller_evidence) > 1000:
        raise ToolError("Audit evidence exceeds the 1000-record safety limit.")
    reserved = {item["id"] for item in deterministic}
    merged = [dict(item) for item in deterministic]
    seen = set(reserved)
    for raw in caller_evidence:
        if not isinstance(raw, dict):
            raise ToolError("Each audit evidence record must be an object.")
        item = dict(raw)
        evidence_id = str(item.get("id") or "").strip()
        if not evidence_id or evidence_id in seen:
            raise ToolError("Audit evidence identifiers must be non-empty and unique.")
        seen.add(evidence_id)
        if item.get("subjectFingerprint") != subject_digest:
            item["status"] = "stale"
            item["summary"] = "Evidence subject does not match the current audit session."
            item["subjectFingerprint"] = subject_digest
        merged.append(item)
    return merged


def audit_bind_domain_coverage(
    domain_coverage: Any,
    evidence: list[dict[str, Any]],
    subject_digest: str,
) -> Any:
    evidence_by_id = {str(item.get("id")): item for item in evidence}
    if isinstance(domain_coverage, dict):
        items = []
        for domain, value in domain_coverage.items():
            if isinstance(value, str):
                items.append({"domain": domain, "status": value})
            elif isinstance(value, dict):
                items.append({"domain": domain, **value})
            else:
                raise ToolError("domain_coverage values must be strings or objects.")
    elif isinstance(domain_coverage, list):
        items = [dict(item) if isinstance(item, dict) else item for item in domain_coverage]
    else:
        raise ToolError("domain_coverage must be an object or array.")
    if len(items) > len(audit_core.DOMAINS):
        raise ToolError("domain_coverage exceeds the supported audit domain count.")
    normalized = []
    for raw in items:
        if not isinstance(raw, dict):
            raise ToolError("Each domain coverage entry must be an object.")
        item = dict(raw)
        ids = item.get("evidenceIds", [])
        if not isinstance(ids, list) or not all(isinstance(value, str) for value in ids):
            raise ToolError("domain coverage evidenceIds must be an array of strings.")
        if item.get("status") in {"complete", "not-applicable"}:
            referenced = [evidence_by_id.get(value) for value in ids]
            exact = bool(ids) and all(
                record
                and record.get("status") == "complete"
                and record.get("subjectFingerprint") == subject_digest
                for record in referenced
            )
            if not exact:
                item["status"] = "incomplete"
                item["reason"] = "Coverage lacks complete evidence bound to this audit subject."
        normalized.append(item)
    return normalized


def audit_secret_candidates(
    security: dict[str, Any],
    subject_digest: str,
) -> list[dict[str, Any]]:
    candidates = []
    for finding in security.get("findings", []):
        path = str(finding.get("file") or "<release-range>")
        line = max(1, int(finding.get("line") or 1))
        pattern = str(finding.get("pattern") or "credential-pattern")
        candidates.append(
            {
                "schemaVersion": "jstack.audit.finding.v1",
                "ruleId": "security.secret-pattern",
                "domain": "security",
                "title": "Credential-like value detected",
                "severity": "high",
                "confidence": "high",
                "priority": "P0",
                "verificationState": "tool-confirmed",
                "status": "open",
                "location": {"path": path, "startLine": line, "endLine": line},
                "scope": [path],
                "claim": f"The bounded secret scanner detected the {pattern} pattern without retaining its value.",
                "evidence": [
                    {
                        "type": "secret-scan",
                        "status": "complete",
                        "summary": f"Pattern {pattern} detected at the reported location; raw value redacted.",
                        "subjectFingerprint": subject_digest,
                        "reproducible": True,
                    }
                ],
                "failurePath": ["Credential-like material is present in the audited tree or release range."],
                "preconditions": ["An actor, build, log, or published artifact can read the affected source history."],
                "impact": "Credential exposure may permit unauthorized access and requires immediate validation and revocation.",
                "likelihood": "Exposure depends on whether the detected value is live and who can access the repository or artifact.",
                "standards": ["NIST SSDF PW.4", "OWASP ASVS 5.0 V14"],
                "remediation": "Remove the value, revoke or rotate it, replace it with runtime secret injection, and inspect repository history.",
                "verificationPlan": "Repeat the complete current-tree and release-range secret scan after remediation and confirm revocation independently.",
                "residualRisk": "Heuristic matching can produce false positives and cannot prove whether a credential was used before revocation.",
            }
        )
    return candidates


def audit_validate_finding_locations(
    project_path: Path,
    inventory: dict[str, Any],
    findings: list[dict[str, Any]],
) -> None:
    files = {str(item["path"]): item for item in inventory.get("files", [])}
    for finding in findings:
        location = finding["location"]
        relative = str(location["path"])
        if relative == "<release-range>":
            continue
        manifest_item = files.get(relative)
        if not manifest_item:
            raise ToolError(f"Audit finding path is outside the bound inventory: {relative}")
        try:
            content = audit_core.read_repository_file(
                project_path,
                relative,
                max_bytes=max(1, int(manifest_item["size"])),
                max_seconds=30,
            )
        except audit_core.AuditError as exc:
            raise ToolError(f"Audit finding path could not be validated safely: {relative}") from exc
        if (
            len(content) != manifest_item["size"]
            or hashlib.sha256(content).hexdigest() != manifest_item["sha256"]
        ):
            raise ToolError(f"Audit finding source changed during range validation: {relative}")
        newline_count = content.count(b"\n")
        ends_with_newline = content.endswith(b"\n")
        line_count = max(1, newline_count if ends_with_newline else newline_count + 1)
        if int(location["endLine"]) > line_count:
            raise ToolError(
                f"Audit finding range exceeds {relative}'s {line_count} source lines."
            )


def audit_add_coverage_gap(
    coverage: dict[str, Any],
    kind: str,
    key: str,
    status: str,
    detail: str,
) -> None:
    gap = {"kind": kind, "key": key, "status": status, "detail": detail}
    if gap not in coverage["gaps"]:
        coverage["gaps"].append(gap)
        coverage["gaps"].sort(key=lambda item: (item["kind"], item["key"], item["status"], item["detail"]))
    coverage["complete"] = False


def audit_render_outputs(
    result: dict[str, Any], evidence_mode: str, requested_formats: list[str]
) -> dict[str, Any]:
    findings = result["findings"]
    gaps = result["coverage"]["gaps"]
    status = result["status"].upper()
    executive = (
        f"{status}: {result['findingCounts']['blocking']} blocking finding(s), "
        f"{len(gaps)} coverage gap(s), and {result['findingCounts']['suppressed']} accepted-risk suppression(s)."
    )
    lines = [
        "# JStack Audit Report",
        "",
        f"- Profile: `{result['profile']}`",
        f"- Status: `{result['status']}`",
        f"- Evidence mode: `{evidence_mode}`",
        f"- Failure threshold: `{result['failOn']}`",
        f"- Required coverage complete: `{str(result['coverage']['complete']).lower()}`",
        "",
        "## Findings",
    ]
    if not findings:
        lines.append("None.")
    for finding in findings:
        location = finding["location"]
        lines.extend(
            [
                "",
                f"### {finding['findingId']}: {finding['title']}",
                f"`{finding['severity']}` | `{finding['confidence']}` confidence | `{finding['priority']}` | `{finding['verificationState']}`",
                f"Location: `{location['path']}:{location['startLine']}`",
                "",
                finding["claim"],
                "",
                f"Remediation: {finding['remediation']['recommendedChange']}",
            ]
        )
    lines.extend(["", "## Coverage Gaps"])
    if not gaps:
        lines.append("None.")
    else:
        lines.extend(f"- {item['kind']} `{item['key']}`: {item['detail']}" for item in gaps)
    residual_risk = [item["detail"] for item in gaps]
    residual_risk.extend(
        finding["residualRisk"]
        for finding in findings
        if finding["verificationState"] == "unverified-hypothesis"
    )
    if evidence_mode == "artifact-only":
        residual_risk.append("Artifact-only evidence is advisory and cannot provide Git-bound release certification.")
    release_decision = (
        "go"
        if result["profile"] == "release" and evidence_mode == "git" and result["status"] == "pass"
        else "no-go"
        if result["profile"] == "release"
        else "not-applicable"
    )
    rendered: dict[str, Any] = {
        "executiveSummary": executive,
        "residualRisk": sorted(set(residual_risk)),
        "releaseDecision": release_decision,
    }
    if "markdown" in requested_formats:
        rendered["engineeringReport"] = "\n".join(lines)
        rendered["coverageMatrix"] = result["coverage"]["domains"]
    if "sarif" in requested_formats:
        rendered["sarif"] = audit_core.to_sarif(result)
    return rendered


def tool_audit_finalize(args: dict[str, Any]) -> dict[str, Any]:
    audit_reject_secret_values(
        {
            key: args.get(key)
            for key in ("domain_coverage", "evidence", "findings", "suppressions", "errors")
        },
        "Audit finalization input",
    )
    audit_enforce_json_limit(
        {
            key: args.get(key)
            for key in (
                "domain_coverage",
                "evidence",
                "findings",
                "suppressions",
                "qa_receipts",
                "errors",
            )
        },
        "Audit finalization input",
        AUDIT_MAX_STRUCTURED_INPUT_BYTES,
    )
    token = str(args.get("audit_session_token") or "").strip()
    token_payload = verify_signed_session_token(token, "audit-session")
    binding = resolve_project_binding(args.get("project_path"))
    project_path = Path(binding["projectPath"]).resolve()
    try:
        inventory, subject = audit_rebuild_inventory(project_path, token_payload)
        audit_assert_session_subject(token_payload, binding, inventory, subject)
    except audit_core.AuditError as exc:
        raise ToolError(str(exc)) from exc

    profile = str(token_payload["profile"])
    subject_digest = str(token_payload["subjectDigest"])
    evaluated_at = now_iso()
    if binding["evidenceMode"] == "git":
        security = tool_security_audit(
            {
                "project_path": str(project_path),
                "base_ref": str(token_payload.get("baseCommit") or ""),
                "max_files": min(int(inventory["limits"]["maxFiles"]), 100_000),
                "max_file_bytes": 2_000_000,
            }
        )
        review = tool_review(
            {
                "project_path": str(project_path),
                "base_ref": str(token_payload.get("baseCommit") or ""),
            }
        )
    else:
        security = audit_artifact_secret_scan(project_path, inventory)
        review = None
    deterministic = audit_deterministic_evidence(
        subject_digest,
        inventory,
        security,
        review,
        profile,
        subject,
    )
    if profile == "release" and binding["evidenceMode"] == "git":
        deterministic.append(
            audit_qa_evidence(project_path, subject, subject_digest, args.get("qa_receipts"))
        )
    evidence = audit_merge_evidence(args.get("evidence"), deterministic, subject_digest)
    domains = audit_bind_domain_coverage(args.get("domain_coverage"), evidence, subject_digest)
    try:
        coverage = audit_core.evaluate_coverage(
            profile,
            domains,
            evidence,
            token_payload.get("adapterResults", []),
            token_payload.get("requiredDomains", []),
        )
        if binding["evidenceMode"] == "artifact-only":
            audit_add_coverage_gap(
                coverage,
                "subject",
                "artifact-only",
                "unsupported",
                "Artifact-only evidence cannot produce a formal Git-bound audit pass or release decision.",
            )
        if profile == "release" and token_payload.get("releaseScopeCovered") is not True:
            audit_add_coverage_gap(
                coverage,
                "subject",
                "release-scope",
                "incomplete",
                "Release profile requires complete repository scope bound to the exact release range.",
            )
        raw_findings = args.get("findings")
        if not isinstance(raw_findings, list):
            raise ToolError("findings must be an array.")
        if len(raw_findings) > 500:
            raise ToolError("Audit findings exceed the 500-finding safety limit.")
        normalized_findings = audit_core.normalize_findings(
            [*raw_findings, *audit_secret_candidates(security, subject_digest)],
            subject_digest,
        )
        audit_validate_finding_locations(project_path, inventory, normalized_findings)
        result = audit_core.finalize_audit(
            profile,
            coverage,
            normalized_findings,
            evaluated_at,
            fail_on=str(token_payload["failOn"]),
            suppressions=args.get("suppressions") or [],
            errors=args.get("errors") or [],
        )
        final_inventory, final_subject = audit_rebuild_inventory(project_path, token_payload)
    except audit_core.AuditError as exc:
        raise ToolError(str(exc)) from exc
    stale_after_review = (
        final_inventory.get("scopeManifestDigest") != inventory.get("scopeManifestDigest")
        or final_subject.get("projectFingerprint") != subject.get("projectFingerprint")
        or final_subject.get("policyDigest") != subject.get("policyDigest")
    )
    if stale_after_review:
        audit_add_coverage_gap(
            coverage,
            "subject",
            "state-change",
            "stale",
            "Repository or policy state changed during audit finalization.",
        )
        result = audit_core.finalize_audit(
            profile,
            coverage,
            normalized_findings,
            evaluated_at,
            fail_on=str(token_payload["failOn"]),
            suppressions=args.get("suppressions") or [],
            errors=args.get("errors") or [],
        )

    requested_formats = args.get("formats") or ["json", "markdown", "sarif"]
    if (
        not isinstance(requested_formats, list)
        or not requested_formats
        or any(item not in {"json", "markdown", "sarif"} for item in requested_formats)
    ):
        raise ToolError("formats must contain json, markdown, and/or sarif.")
    outputs = audit_render_outputs(result, binding["evidenceMode"], requested_formats)
    audit_enforce_json_limit(
        outputs,
        "Audit rendered output",
        AUDIT_MAX_STRUCTURED_OUTPUT_BYTES,
    )
    receipt = None
    active_suppressions = sorted(
        [
            {
                "fingerprint": finding["fingerprint"],
                "expiresAt": finding["suppression"]["expiresAt"],
            }
            for finding in result["findings"]
            if finding.get("status") == "suppressed"
            and isinstance(finding.get("suppression"), dict)
            and finding["suppression"].get("expiresAt")
        ],
        key=lambda item: (item["expiresAt"], item["fingerprint"]),
    )
    if binding["evidenceMode"] == "git":
        expires_at = (
            _dt.datetime.now(_dt.timezone.utc) + _dt.timedelta(seconds=RECEIPT_MAX_AGE_SECONDS)
        ).replace(microsecond=0).isoformat()
        receipt = issue_receipt(
            {
                "kind": "audit",
                "schemaVersion": "jstack.audit.receipt.v1",
                "expiresAt": expires_at,
                "projectPath": subject["gitRoot"],
                "gitHead": subject["gitHead"],
                "baseRef": subject.get("baseRef"),
                "baseCommit": subject.get("baseCommit"),
                "projectFingerprint": subject["projectFingerprint"],
                "policyDigest": subject["policyDigest"],
                "controlDigest": token_payload["controlDigest"],
                "capabilityCatalogVersion": token_payload.get("capabilityCatalogVersion"),
                "capabilityCatalogDigest": token_payload.get("capabilityCatalogDigest"),
                "capabilitySelectionDigest": token_payload.get("capabilitySelectionDigest"),
                "capabilityIds": token_payload.get("capabilityIds", []),
                "contextBriefDigest": token_payload.get("contextBriefDigest"),
                "toolVersion": SERVER_VERSION,
                "adapterVersions": token_payload.get("adapterInventory", []),
                "adapterResults": [
                    {
                        key: item.get(key)
                        for key in (
                            "adapterId",
                            "capability",
                            "status",
                            "subjectValidated",
                            "approvalSubjectDigest",
                            "evidenceFingerprint",
                            "adapterVersion",
                            "returnCode",
                            "mutationDetected",
                            "outputFingerprint",
                        )
                    }
                    for item in token_payload.get("adapterResults", [])
                    if isinstance(item, dict)
                ],
                "profile": profile,
                "scope": token_payload.get("requestedScope"),
                "scopeMode": token_payload.get("scopeMode"),
                "releaseScopeCovered": token_payload.get("releaseScopeCovered") is True,
                "releaseRangeDigest": token_payload.get("releaseRangeDigest"),
                "requiredDomains": token_payload.get("requiredDomains"),
                "scopeManifestDigest": inventory["scopeManifestDigest"],
                "coverageDigest": audit_json_digest(result["coverage"]),
                "findingDigest": audit_json_digest(result["findings"]),
                "resultStatus": result["status"],
                "failureThreshold": result["failOn"],
                "findingCounts": result["findingCounts"],
                "evaluatedAt": evaluated_at,
                "activeSuppressions": active_suppressions,
                "complete": result["coverage"]["complete"] is True
                and result["status"] in {"pass", "fail"},
                "passed": result["status"] == "pass",
            }
        )
    release_certification_available = (
        binding["evidenceMode"] == "git"
        and profile == "release"
        and token_payload.get("releaseScopeCovered") is True
        and result["status"] == "pass"
        and result["coverage"]["complete"] is True
    )
    response: dict[str, Any] = {
        "schemaVersion": "jstack.audit.finalization.v1",
        "executiveSummary": outputs["executiveSummary"],
        "residualRisk": outputs["residualRisk"],
        "releaseDecision": outputs["releaseDecision"],
        "requestedFormats": sorted(set(requested_formats)),
        "auditReceipt": receipt,
        "gitBoundReceiptAvailable": receipt is not None,
        "releaseCertificationAvailable": release_certification_available,
        "specialistCapabilities": {
            "catalogVersion": token_payload.get("capabilityCatalogVersion"),
            "catalogDigest": token_payload.get("capabilityCatalogDigest"),
            "selectionDigest": token_payload.get("capabilitySelectionDigest"),
            "capabilityIds": token_payload.get("capabilityIds", []),
        },
        "contextBriefDigest": token_payload.get("contextBriefDigest"),
        "receiptMeaning": "Attests deterministic scope, coverage, finding/result digests, and state binding; it does not prove semantic finding truth.",
    }
    if "json" in requested_formats:
        response["result"] = result
    if "markdown" in requested_formats:
        response["engineeringReport"] = outputs["engineeringReport"]
        response["coverageMatrix"] = outputs["coverageMatrix"]
    if "sarif" in requested_formats:
        response["sarif"] = outputs["sarif"]
    audit_enforce_json_limit(
        response,
        "Audit finalization response",
        AUDIT_MAX_STRUCTURED_OUTPUT_BYTES,
    )
    return response


def tool_qa(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    commands = discover_test_commands(project_path)
    base_ref = str(args.get("base_ref") or "").strip() or None
    subject_before = evidence_subject(project_path, base_ref)
    state_before = {key: subject_before[key] for key in ("gitRoot", "gitHead", "projectFingerprint", "clean", "untrackedFiles")}
    run = bool(args.get("run") or False)
    command_key = str(args.get("command_key") or "").strip()
    result: Optional[dict[str, Any]] = None
    receipt: Optional[str] = None
    mutation_detected = False
    if run:
        if args.get("execution_approved") is not True:
            raise ToolError(
                "Running discovered commands executes repository-controlled code. Set execution_approved=true only after the user has approved trusted local execution."
            )
        trusted_revision = str(args.get("trusted_revision") or "").strip()
        trusted_fingerprint = str(args.get("trusted_project_fingerprint") or "").strip()
        trusted_policy_digest = str(args.get("trusted_policy_digest") or "").strip()
        if (
            trusted_revision != state_before["gitHead"]
            or trusted_fingerprint != state_before["projectFingerprint"]
            or trusted_policy_digest != subject_before["policyDigest"]
        ):
            raise ToolError(
                "Trusted revision/fingerprint does not match the current project state. Rediscover commands and review the project before approving execution."
            )
        if not command_key:
            raise ToolError("When run=true, command_key is required. Use jstack_qa with run=false to list allowed keys.")
        selected = next((command for command in commands if command["key"] == command_key), None)
        if not selected:
            raise ToolError(f"Unsupported command_key: {command_key}. Allowed: {[command['key'] for command in commands]}")
        env_allowlist = args.get("env_allowlist") or []
        if not isinstance(env_allowlist, list) or not all(isinstance(item, str) for item in env_allowlist):
            raise ToolError("env_allowlist must be an array of environment variable names.")
        if env_allowlist:
            raise ToolError("Forwarding host environment variables into repository-controlled QA is disabled by enterprise policy.")
        result = run_approved_project_command(
            selected["args"], project_path, timeout=int(args.get("timeout_sec") or 120), env_allowlist=env_allowlist
        )
        subject_after = evidence_subject(project_path, base_ref)
        state_after = {key: subject_after[key] for key in ("gitRoot", "gitHead", "projectFingerprint", "clean", "untrackedFiles")}
        mutation_detected = state_after["projectFingerprint"] != state_before["projectFingerprint"]
        passed = bool(result["ok"]) and not mutation_detected
        receipt = issue_receipt(
            {
                "kind": "qa",
                "projectPath": state_after["gitRoot"],
                "gitHead": state_after["gitHead"],
                "projectFingerprint": state_after["projectFingerprint"],
                "baseRef": subject_after["baseRef"],
                "baseCommit": subject_after["baseCommit"],
                "policyDigest": subject_after["policyDigest"],
                "toolVersion": SERVER_VERSION,
                "executionProfile": "local-scrubbed-no-os-sandbox-v1",
                "commandKey": selected["key"],
                "commandFingerprint": selected["commandFingerprint"],
                "returncode": result["returncode"],
                "passed": passed,
                "mutationDetected": mutation_detected,
            }
        )
    return {
        "projectPath": str(project_path),
        "evidenceState": state_before,
        "evidenceSubject": subject_before,
        "allowedCommands": commands,
        "executed": result is not None,
        "result": result,
        "mutationDetected": mutation_detected,
        "evidenceReceipt": receipt,
        "policy": (
            "Discovery is read-only. Execution runs repository-controlled code with stdin closed, a scrubbed environment, an isolated HOME, and process-group timeout handling. "
            "It still has the current user's filesystem and network privileges, so explicit trust approval and an exact revision/fingerprint are mandatory."
        ),
    }


def _performance_environment() -> dict[str, Any]:
    environment = {
        "system": platform.system() or "unknown",
        "release": platform.release() or "unknown",
        "machine": platform.machine() or "unknown",
        "pythonImplementation": platform.python_implementation(),
        "pythonVersion": platform.python_version(),
        "logicalCpuCount": os.cpu_count(),
        "executionProfile": "local-scrubbed-no-os-sandbox-v1",
        "toolVersion": SERVER_VERSION,
    }
    return {
        "metadata": environment,
        "digest": audit_core.performance_canonical_sha256(environment),
    }


def _load_performance_capture(path: Path) -> dict[str, Any]:
    try:
        listed = path.lstat()
    except FileNotFoundError as exc:
        raise ToolError(
            "The performance command passed but did not write JSTACK_PERFORMANCE_OUTPUT."
        ) from exc
    if stat.S_ISLNK(listed.st_mode) or not stat.S_ISREG(listed.st_mode):
        raise ToolError("Performance output must be one regular non-symlink JSON file.")
    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(path, flags)
    except FileNotFoundError as exc:
        raise ToolError(
            "The performance command passed but did not write JSTACK_PERFORMANCE_OUTPUT."
        ) from exc
    except OSError as exc:
        raise ToolError("Performance output could not be opened safely.") from exc
    try:
        before = os.fstat(descriptor)
        if (
            not stat.S_ISREG(before.st_mode)
            or listed.st_dev != before.st_dev
            or listed.st_ino != before.st_ino
        ):
            raise ToolError("Performance output must be one regular non-symlink JSON file.")
        if before.st_size <= 0 or before.st_size > PERFORMANCE_CAPTURE_MAX_BYTES:
            raise ToolError(
                f"Performance output must contain 1 to {PERFORMANCE_CAPTURE_MAX_BYTES} bytes."
            )
        chunks: list[bytes] = []
        remaining = PERFORMANCE_CAPTURE_MAX_BYTES + 1
        while remaining > 0:
            chunk = os.read(descriptor, min(65_536, remaining))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        after = os.fstat(descriptor)
        raw_bytes = b"".join(chunks)
    except OSError as exc:
        raise ToolError("Performance output could not be read safely.") from exc
    finally:
        os.close(descriptor)
    if (
        len(raw_bytes) != before.st_size
        or before.st_dev != after.st_dev
        or before.st_ino != after.st_ino
        or before.st_size != after.st_size
        or before.st_mtime_ns != after.st_mtime_ns
    ):
        raise ToolError("Performance output changed while it was being read.")

    def reject_duplicates(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise ToolError("Performance output contains a duplicate JSON key.")
            result[key] = value
        return result

    try:
        raw = json.loads(raw_bytes.decode("utf-8"), object_pairs_hook=reject_duplicates)
        normalized = audit_core.normalize_performance_capture(raw)
    except (UnicodeError, json.JSONDecodeError, audit_core.PerformanceProtocolError) as exc:
        raise ToolError(f"Performance output is invalid: {exc}") from exc
    audit_reject_secret_values(normalized, "Performance output")
    return normalized


def tool_performance_capture(args: dict[str, Any]) -> dict[str, Any]:
    """Discover or run one closed-protocol performance capture."""

    project_path = require_project_path(args.get("project_path"))
    commands = discover_test_commands(project_path)
    base_ref = str(args.get("base_ref") or "").strip() or None
    subject_before = evidence_subject(project_path, base_ref)
    source_before = _audit_source_subject(project_path, "Stage 5 performance capture")
    run = bool(args.get("run") or False)
    if not run:
        return {
            "projectPath": str(project_path),
            "evidenceSubject": subject_before,
            "sourceSubject": {
                "gitHead": source_before["gitHead"],
                "gitTree": source_before["gitTree"],
            },
            "allowedCommands": commands,
            "executed": False,
            "captureProtocol": {
                "schemaVersion": audit_core.PERFORMANCE_CAPTURE_SCHEMA_VERSION,
                "outputEnvironmentVariable": "JSTACK_PERFORMANCE_OUTPUT",
                "surfaces": list(audit_core.PERFORMANCE_SURFACES),
                "minimumSamples": 5,
                "requiresExactlyOnePrimaryMetric": True,
                "requiresGuardrailMetric": True,
            },
            "policy": (
                "Discovery is read-only. Capture execution is a separately authorized developer/QA action, "
                "not an Audit action, and accepts only a discovered command at an exact trusted Git state."
            ),
        }

    if args.get("execution_approved") is not True:
        raise ToolError(
            "Performance capture executes repository-controlled code. Set execution_approved=true only within a separately authorized trusted development or QA workflow."
        )
    trusted_revision = str(args.get("trusted_revision") or "").strip()
    trusted_fingerprint = str(args.get("trusted_project_fingerprint") or "").strip()
    trusted_policy_digest = str(args.get("trusted_policy_digest") or "").strip()
    if (
        trusted_revision != subject_before["gitHead"]
        or trusted_fingerprint != subject_before["projectFingerprint"]
        or trusted_policy_digest != subject_before["policyDigest"]
    ):
        raise ToolError(
            "Trusted revision/fingerprint does not match the current project state. Rediscover and review the project before capture."
        )
    disallowed_changes = [
        path for path in git_changed_files(project_path) if not path.startswith(".jstack-training/")
    ]
    if disallowed_changes:
        raise ToolError(
            "Performance capture requires committed project code; only Stage 5 training artifacts may be dirty: "
            + ", ".join(disallowed_changes)
        )
    command_key = str(args.get("command_key") or "").strip()
    selected = next((command for command in commands if command["key"] == command_key), None)
    if selected is None:
        raise ToolError(
            f"Unsupported command_key: {command_key}. Allowed: {[command['key'] for command in commands]}"
        )
    workload_id = str(args.get("workload_id") or "").strip()
    workload_digest = str(args.get("workload_digest") or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,127}", workload_id):
        raise ToolError("workload_id must be a bounded identifier.")
    if not re.fullmatch(r"[0-9a-f]{64}", workload_digest):
        raise ToolError("workload_digest must be a lowercase SHA-256 digest.")
    environment = _performance_environment()
    with tempfile.TemporaryDirectory(prefix="jstack-performance-capture-") as temp_dir:
        output_path = Path(temp_dir) / "capture.json"
        result = run_approved_project_command(
            selected["args"],
            project_path,
            timeout=int(args.get("timeout_sec") or 300),
            env_allowlist=[],
            fixed_env={
                "JSTACK_PERFORMANCE_OUTPUT": str(output_path),
                "JSTACK_PERFORMANCE_SCHEMA": audit_core.PERFORMANCE_CAPTURE_SCHEMA_VERSION,
                "JSTACK_PERFORMANCE_WORKLOAD_ID": workload_id,
                "JSTACK_PERFORMANCE_WORKLOAD_DIGEST": workload_digest,
            },
        )
        capture = _load_performance_capture(output_path) if result["ok"] else None
    subject_after = evidence_subject(project_path, base_ref)
    source_after = _audit_source_subject(project_path, "Stage 5 performance capture")
    mutation_detected = any(
        subject_after[field] != subject_before[field]
        for field in ("gitHead", "projectFingerprint", "policyDigest")
    )
    source_changed = any(
        source_after[field] != source_before[field] for field in ("gitHead", "gitTree")
    )
    mutation_detected = mutation_detected or source_changed
    capture_valid = capture is not None
    workload_matches = bool(
        capture
        and capture["workloadId"] == workload_id
        and capture["workloadDigest"] == workload_digest
    )
    passed = bool(result["ok"]) and capture_valid and workload_matches and not mutation_detected
    capture_digest = (
        audit_core.performance_canonical_sha256(capture) if capture is not None else None
    )
    summary = audit_core.summarize_performance_capture(capture) if capture is not None else []
    receipt = issue_receipt(
        {
            "kind": "performance",
            "projectPath": subject_after["gitRoot"],
            "gitHead": source_after["gitHead"],
            "gitTree": source_after["gitTree"],
            "projectFingerprint": subject_after["projectFingerprint"],
            "baseRef": subject_after["baseRef"],
            "baseCommit": subject_after["baseCommit"],
            "policyDigest": subject_after["policyDigest"],
            "toolVersion": SERVER_VERSION,
            "executionProfile": "local-scrubbed-no-os-sandbox-v1",
            "commandKey": selected["key"],
            "commandFingerprint": selected["commandFingerprint"],
            "workloadId": workload_id,
            "workloadDigest": workload_digest,
            "environmentDigest": environment["digest"],
            "captureDigest": capture_digest,
            "metricCount": len(capture["metrics"]) if capture else 0,
            "measurementIterations": capture["measurementIterations"] if capture else 0,
            "returncode": result["returncode"],
            "passed": passed,
            "mutationDetected": mutation_detected,
        }
    )
    return {
        "projectPath": str(project_path),
        "sourceSubject": {
            "gitHead": source_after["gitHead"],
            "gitTree": source_after["gitTree"],
        },
        "executed": True,
        "passed": passed,
        "workloadMatched": workload_matches,
        "mutationDetected": mutation_detected,
        "command": {
            "key": selected["key"],
            "commandFingerprint": selected["commandFingerprint"],
            "returncode": result["returncode"],
            "stdoutSha256": result.get("stdoutSha256"),
            "stderrSha256": result.get("stderrSha256"),
            "capturedOutputBytes": result.get("capturedOutputBytes"),
        },
        "environment": environment,
        "captureDigest": capture_digest,
        "capture": capture,
        "summary": summary,
        "evidenceReceipt": receipt,
        "receiptMeaning": (
            "The receipt binds the exact Git tree, discovered command, workload, local environment, and normalized samples. "
            "It does not prove workload realism, host isolation, measurement accuracy, production capacity, or optimization authority."
        ),
        "outputPolicy": "Only bounded structured measurements and output digests are returned; command stdout and stderr are not returned.",
    }


def _adversarial_environment() -> dict[str, Any]:
    metadata = {
        "system": platform.system() or "unknown",
        "release": platform.release() or "unknown",
        "machine": platform.machine() or "unknown",
        "pythonImplementation": platform.python_implementation(),
        "pythonVersion": platform.python_version(),
        "logicalCpuCount": os.cpu_count(),
        "executionProfile": "local-scrubbed-no-os-sandbox-v1",
        "networkIsolationEnforced": False,
        "toolVersion": SERVER_VERSION,
    }
    return {
        "metadata": metadata,
        "digest": audit_core.adversarial_canonical_sha256(metadata),
    }


def _load_adversarial_capture(path: Path) -> dict[str, Any]:
    try:
        listed = path.lstat()
    except FileNotFoundError as exc:
        raise ToolError(
            "The adversarial command passed but did not write JSTACK_ADVERSARIAL_OUTPUT."
        ) from exc
    if stat.S_ISLNK(listed.st_mode) or not stat.S_ISREG(listed.st_mode):
        raise ToolError("Adversarial output must be one regular non-symlink JSON file.")
    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(path, flags)
    except FileNotFoundError as exc:
        raise ToolError(
            "The adversarial command passed but did not write JSTACK_ADVERSARIAL_OUTPUT."
        ) from exc
    except OSError as exc:
        raise ToolError("Adversarial output could not be opened safely.") from exc
    try:
        before = os.fstat(descriptor)
        if (
            not stat.S_ISREG(before.st_mode)
            or listed.st_dev != before.st_dev
            or listed.st_ino != before.st_ino
        ):
            raise ToolError("Adversarial output must be one regular non-symlink JSON file.")
        if before.st_size <= 0 or before.st_size > ADVERSARIAL_CAPTURE_MAX_BYTES:
            raise ToolError(
                f"Adversarial output must contain 1 to {ADVERSARIAL_CAPTURE_MAX_BYTES} bytes."
            )
        chunks: list[bytes] = []
        remaining = ADVERSARIAL_CAPTURE_MAX_BYTES + 1
        while remaining > 0:
            chunk = os.read(descriptor, min(65_536, remaining))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        after = os.fstat(descriptor)
        raw_bytes = b"".join(chunks)
    except OSError as exc:
        raise ToolError("Adversarial output could not be read safely.") from exc
    finally:
        os.close(descriptor)
    if (
        len(raw_bytes) != before.st_size
        or before.st_dev != after.st_dev
        or before.st_ino != after.st_ino
        or before.st_size != after.st_size
        or before.st_mtime_ns != after.st_mtime_ns
    ):
        raise ToolError("Adversarial output changed while it was being read.")

    def reject_duplicates(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise ToolError("Adversarial output contains a duplicate JSON key.")
            result[key] = value
        return result

    try:
        raw = json.loads(raw_bytes.decode("utf-8"), object_pairs_hook=reject_duplicates)
        normalized = audit_core.normalize_adversarial_capture(raw)
    except (
        UnicodeError,
        json.JSONDecodeError,
        audit_core.AdversarialProtocolError,
    ) as exc:
        raise ToolError(f"Adversarial output is invalid: {exc}") from exc
    audit_reject_secret_values(normalized, "Adversarial output")
    return normalized


def tool_adversarial_capture(args: dict[str, Any]) -> dict[str, Any]:
    """Discover or run one closed-protocol adversarial verification capture."""

    project_path = require_project_path(args.get("project_path"))
    commands = discover_test_commands(project_path)
    base_ref = str(args.get("base_ref") or "").strip() or None
    subject_before = evidence_subject(project_path, base_ref)
    source_before = _audit_source_subject(project_path, "Stage 7 adversarial capture")
    run = bool(args.get("run") or False)
    if not run:
        return {
            "projectPath": str(project_path),
            "evidenceSubject": subject_before,
            "sourceSubject": {
                "gitHead": source_before["gitHead"],
                "gitTree": source_before["gitTree"],
            },
            "allowedCommands": commands,
            "executed": False,
            "captureProtocol": {
                "schemaVersion": audit_core.ADVERSARIAL_CAPTURE_SCHEMA_VERSION,
                "outputEnvironmentVariable": "JSTACK_ADVERSARIAL_OUTPUT",
                "categories": list(audit_core.ADVERSARIAL_CATEGORIES),
                "minimumCases": audit_core.ADVERSARIAL_MIN_CASES,
                "maximumCases": audit_core.ADVERSARIAL_MAX_CASES,
                "rerunsPerCase": audit_core.ADVERSARIAL_RERUNS_PER_CASE,
                "externalEffectClaim": audit_core.ADVERSARIAL_EXTERNAL_EFFECT,
                "rawPayloadsAllowed": False,
                "networkIsolationEnforced": False,
            },
            "policy": (
                "Discovery is read-only. Capture execution is a separately authorized trusted developer/QA action, "
                "not an Audit action, and accepts only a discovered command at an exact trusted Git state. "
                "The local runner is not an OS or network sandbox."
            ),
        }

    if args.get("execution_approved") is not True:
        raise ToolError(
            "Adversarial capture executes repository-controlled code. Set execution_approved=true only within a separately authorized trusted development or QA workflow."
        )
    trusted_revision = str(args.get("trusted_revision") or "").strip()
    trusted_fingerprint = str(args.get("trusted_project_fingerprint") or "").strip()
    trusted_policy_digest = str(args.get("trusted_policy_digest") or "").strip()
    if (
        trusted_revision != subject_before["gitHead"]
        or trusted_fingerprint != subject_before["projectFingerprint"]
        or trusted_policy_digest != subject_before["policyDigest"]
    ):
        raise ToolError(
            "Trusted revision/fingerprint does not match the current project state. Rediscover and review the project before capture."
        )
    permitted_changes = set(AUDIT_STAGE7_ARTIFACT_PATHS.values())
    disallowed_changes = [
        path for path in git_changed_files(project_path) if path not in permitted_changes
    ]
    if disallowed_changes:
        raise ToolError(
            "Adversarial capture requires committed project code; only the three exact Stage 7 training artifacts may be dirty: "
            + ", ".join(disallowed_changes)
        )
    command_key = str(args.get("command_key") or "").strip()
    selected = next((command for command in commands if command["key"] == command_key), None)
    if selected is None:
        raise ToolError(
            f"Unsupported command_key: {command_key}. Allowed: {[command['key'] for command in commands]}"
        )
    campaign_id = str(args.get("campaign_id") or "").strip()
    campaign_digest = str(args.get("campaign_digest") or "").strip()
    plan_digest = str(args.get("plan_digest") or "").strip()
    input_corpus_digest = str(args.get("input_corpus_digest") or "").strip()
    target_scope_digest = str(args.get("target_scope_digest") or "").strip()
    deterministic_seed = args.get("deterministic_seed")
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,127}", campaign_id):
        raise ToolError("campaign_id must be a bounded identifier.")
    for value, label in (
        (campaign_digest, "campaign_digest"),
        (plan_digest, "plan_digest"),
        (input_corpus_digest, "input_corpus_digest"),
        (target_scope_digest, "target_scope_digest"),
    ):
        if not re.fullmatch(r"[0-9a-f]{64}", value):
            raise ToolError(f"{label} must be a lowercase SHA-256 digest.")
    if (
        not isinstance(deterministic_seed, int)
        or isinstance(deterministic_seed, bool)
        or not 0 <= deterministic_seed <= 2**63 - 1
    ):
        raise ToolError("deterministic_seed must be an integer from 0 to 2^63-1.")
    timeout_seconds = args.get("timeout_sec", 300)
    if (
        not isinstance(timeout_seconds, int)
        or isinstance(timeout_seconds, bool)
        or not 10 <= timeout_seconds <= 1800
    ):
        raise ToolError("timeout_sec must be an integer from 10 to 1800.")
    environment = _adversarial_environment()
    with tempfile.TemporaryDirectory(prefix="jstack-adversarial-capture-") as temp_dir:
        output_path = Path(temp_dir) / "capture.json"
        result = run_approved_project_command(
            selected["args"],
            project_path,
            timeout=timeout_seconds,
            env_allowlist=[],
            fixed_env={
                "JSTACK_ADVERSARIAL_OUTPUT": str(output_path),
                "JSTACK_ADVERSARIAL_SCHEMA": audit_core.ADVERSARIAL_CAPTURE_SCHEMA_VERSION,
                "JSTACK_ADVERSARIAL_CAMPAIGN_ID": campaign_id,
                "JSTACK_ADVERSARIAL_CAMPAIGN_DIGEST": campaign_digest,
                "JSTACK_ADVERSARIAL_PLAN_DIGEST": plan_digest,
                "JSTACK_ADVERSARIAL_SEED": str(deterministic_seed),
                "JSTACK_ADVERSARIAL_INPUT_CORPUS_DIGEST": input_corpus_digest,
                "JSTACK_ADVERSARIAL_TARGET_SCOPE_DIGEST": target_scope_digest,
            },
        )
        capture = _load_adversarial_capture(output_path) if result["ok"] else None
    subject_after = evidence_subject(project_path, base_ref)
    source_after = _audit_source_subject(project_path, "Stage 7 adversarial capture")
    mutation_detected = any(
        subject_after[field] != subject_before[field]
        for field in ("gitHead", "projectFingerprint", "policyDigest")
    ) or any(
        source_after[field] != source_before[field] for field in ("gitHead", "gitTree")
    )
    binding_matches = bool(
        capture
        and capture["campaignId"] == campaign_id
        and capture["campaignDigest"] == campaign_digest
        and capture["planDigest"] == plan_digest
        and capture["deterministicSeed"] == deterministic_seed
        and capture["inputCorpusDigest"] == input_corpus_digest
        and capture["targetScopeDigest"] == target_scope_digest
    )
    passed = bool(result["ok"]) and capture is not None and binding_matches and not mutation_detected
    capture_digest = (
        audit_core.adversarial_canonical_sha256(capture) if capture is not None else None
    )
    summary = audit_core.summarize_adversarial_capture(capture) if capture is not None else None
    receipt = issue_receipt(
        {
            "kind": "adversarial",
            "projectPath": subject_after["gitRoot"],
            "gitHead": source_after["gitHead"],
            "gitTree": source_after["gitTree"],
            "projectFingerprint": subject_after["projectFingerprint"],
            "baseRef": subject_after["baseRef"],
            "baseCommit": subject_after["baseCommit"],
            "policyDigest": subject_after["policyDigest"],
            "toolVersion": SERVER_VERSION,
            "executionProfile": "local-scrubbed-no-os-sandbox-v1",
            "networkIsolationEnforced": False,
            "commandKey": selected["key"],
            "commandFingerprint": selected["commandFingerprint"],
            "campaignId": campaign_id,
            "campaignDigest": campaign_digest,
            "planDigest": plan_digest,
            "deterministicSeed": deterministic_seed,
            "inputCorpusDigest": input_corpus_digest,
            "targetScopeDigest": target_scope_digest,
            "environmentDigest": environment["digest"],
            "captureDigest": capture_digest,
            "caseSetDigest": summary["caseSetDigest"] if summary else None,
            "outcomeSetDigest": summary["outcomeSetDigest"] if summary else None,
            "caseCount": summary["caseCount"] if summary else 0,
            "testedCategoryCount": summary["testedCategoryCount"] if summary else 0,
            "returncode": result["returncode"],
            "passed": passed,
            "mutationDetected": mutation_detected,
        }
    )
    return {
        "projectPath": str(project_path),
        "sourceSubject": {
            "gitHead": source_after["gitHead"],
            "gitTree": source_after["gitTree"],
        },
        "executed": True,
        "passed": passed,
        "bindingMatched": binding_matches,
        "mutationDetected": mutation_detected,
        "command": {
            "key": selected["key"],
            "commandFingerprint": selected["commandFingerprint"],
            "returncode": result["returncode"],
            "stdoutSha256": result.get("stdoutSha256"),
            "stderrSha256": result.get("stderrSha256"),
            "capturedOutputBytes": result.get("capturedOutputBytes"),
        },
        "environment": environment,
        "captureDigest": capture_digest,
        "capture": capture,
        "summary": summary,
        "evidenceReceipt": receipt,
        "receiptMeaning": (
            "The receipt binds the exact Git tree, discovered command, campaign, plan, deterministic corpus, target scope, local environment, repeated case contracts, and digested outcomes. "
            "It does not prove host or network isolation, absence of external effects, exploitability, vulnerability absence, or production safety."
        ),
        "outputPolicy": (
            "Only bounded identifiers, classifications, counts, and SHA-256 digests are returned; raw inputs, payloads, source, stdout, and stderr are not returned."
        ),
    }


def context_dir(project_path: Path) -> Path:
    return Path.home() / ".jstack" / "mcp-context" / project_slug(project_path)


def tool_context_save(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    summary = str(args.get("summary") or "").strip()
    if not summary:
        raise ToolError("summary is required.")
    payload = {
        "savedAt": now_iso(),
        "projectPath": str(project_path),
        "gitRoot": git_root(project_path),
        "label": str(args.get("label") or "latest"),
        "summary": summary,
        "decisions": args.get("decisions") or [],
        "nextSteps": args.get("next_steps") or [],
        "filesTouched": args.get("files_touched") or [],
    }
    target_dir = context_dir(project_path)
    timestamp = _dt.datetime.now(_dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    save_path = target_dir / f"{timestamp}.json"
    latest_path = target_dir / "latest.json"
    atomic_write_json(save_path, payload)
    atomic_write_json(latest_path, payload)
    return {"saved": True, "path": str(save_path), "latestPath": str(latest_path), "context": payload}


def tool_context_restore(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    latest_path = context_dir(project_path) / "latest.json"
    if not latest_path.exists():
        raise ToolError(f"No saved JStack MCP context for {project_path}")
    data = read_json(latest_path)
    if data is None:
        raise ToolError(f"Saved context is not valid JSON: {latest_path}")
    return {"restored": True, "path": str(latest_path), "context": data}


def tool_ship_check(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    base_ref = str(args.get("base_ref") or "").strip()
    health = tool_health({"project_path": str(project_path)})
    review = tool_review({"project_path": str(project_path), "base_ref": base_ref or None})
    docs = health["projectFiles"]
    blockers = []
    if not base_ref:
        blockers.append("Ship check requires an explicit base_ref for the release delta.")
    if review["diffCheck"]["returncode"] not in (0,):
        blockers.append("git diff --check reported whitespace or conflict-marker issues")
    if not docs.get("readme"):
        blockers.append("README is missing")
    if not health["testCommands"]:
        blockers.append("No test commands detected")
    qa_receipts = args.get("qa_receipts") or []
    if not isinstance(qa_receipts, list) or not all(isinstance(item, str) for item in qa_receipts):
        raise ToolError("qa_receipts must be an array of receipts returned by jstack_qa.")
    subject = evidence_subject(project_path, base_ref or None)
    if base_ref and subject["baseCommit"] == subject["gitHead"]:
        blockers.append("Ship check base_ref must resolve to a distinct pre-release commit, not HEAD itself.")
    valid_receipts: dict[str, dict[str, Any]] = {}
    receipt_results: list[dict[str, Any]] = []
    for receipt in qa_receipts:
        verification = verify_receipt(receipt, "qa", subject, expected_subject=subject)
        receipt_results.append(verification)
        if verification["valid"]:
            valid_receipts[str(verification["payload"].get("commandKey") or "")] = verification["payload"]
    for command in health["testCommands"]:
        payload = valid_receipts.get(command["key"])
        if not payload:
            blockers.append(f"No current passing QA receipt for '{command['key']}'.")
        elif payload.get("commandFingerprint") != command["commandFingerprint"]:
            blockers.append(f"QA receipt for '{command['key']}' does not match the current command definition.")
    return {
        "projectPath": str(project_path),
        "ready": not blockers,
        "blockers": blockers,
        "evidenceState": subject,
        "qaEvidence": receipt_results,
        "healthSummary": {
            "branch": health["branch"],
            "dirtyFileCount": health["dirtyFileCount"],
            "testCommandCount": len(health["testCommands"]),
            "docs": docs,
        },
        "recommendedGate": [
            "Run focused tests for touched code.",
            "Run security scan for auth, secrets and external integration changes.",
            "Review the complete diff before requesting any protected action.",
            "Treat this check as evidence only; perform actions only when they are within explicit user scope and normal host/provider permissions.",
            "Save context after the local handoff or completed operation.",
        ],
    }


def tool_policy_check(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    goal = str(args.get("goal") or "").strip()
    explicit_release_requested = bool(args.get("explicit_release_requested") or False)
    protected_path_approval = str(args.get("protected_path_approval") or "").strip()
    target_environment = str(args.get("target_environment") or "local").strip().lower()
    policy = load_enterprise_policy(project_path)
    change_evidence = git_change_evidence(project_path, str(args.get("base_ref") or "").strip() or None)
    changed_files = change_evidence["files"]
    ui_applicability = _ui_applicability(
        project_path,
        goal=goal,
        paths=changed_files,
        baseline_head=str(change_evidence.get("baseCommit") or "").strip() or None,
    )
    protected_patterns = [str(item) for item in policy.get("protectedPaths", [])]
    protected_matches = [path for path in changed_files if path_matches_patterns(path, protected_patterns)]
    classifications = classify_work(goal) if goal else []
    classification_ids = {item["id"] for item in classifications}
    blockers: list[str] = []
    warnings: list[str] = []
    required_actions: list[str] = []

    if policy.get("_usingDefault"):
        warnings.append("No project JStack policy file found; using default enterprise policy.")
        required_actions.append("Add a project policy file such as jstack.enterprise.json or jstack.yml before treating the repo as production-governed.")
    if protected_matches and not protected_path_approval:
        blockers.append("Protected paths changed without an explicit project-specific approval record.")
    elif protected_matches:
        required_actions.append(f"Verify protected-path approval reference before mutation: {protected_path_approval}")
    if target_environment in {"production", "prod"} and not explicit_release_requested:
        blockers.append("Production target selected but explicit release approval was not provided.")
    if "production_release" in classification_ids and not explicit_release_requested:
        blockers.append("Release/deploy-classified work requires explicit release approval.")
    if goal and goal_is_sensitive(goal, policy):
        required_actions.append("Run jstack_security_audit and perform a human security/compliance review before release.")
    if "data_financial" in classification_ids:
        required_actions.append("Document data source, contract assumptions, failure modes, and reconciliation/rollback path.")
    if "ui_product" in classification_ids or ui_applicability["state"] == "required":
        required_actions.append(
            "Create a Product Interface contract before implementation and a current passing UI finalization receipt before UI completion or release."
        )
    ignored_legacy_fields = list(policy.get("_ignoredLegacyFields") or [])
    if ignored_legacy_fields:
        warnings.append(
            "Ignored retired custom-approval policy fields: "
            + ", ".join(ignored_legacy_fields)
            + ". Current JStack releases use host-native action safety."
        )
    if goal and re.search(
        r"\b(?:implement|build|finish|ship|deploy|release|publish|phase|remediat(?:e|ion))\b",
        goal,
        re.IGNORECASE,
    ):
        warnings.append(
            "Keep repository, Git, provider, deployment, and production actions within the user's explicit scope and normal host/provider permissions."
        )

    return {
        "projectPath": str(project_path),
        "policySource": policy.get("_sourcePath"),
        "usingDefaultPolicy": bool(policy.get("_usingDefault")),
        "targetEnvironment": target_environment,
        "explicitReleaseRequested": explicit_release_requested,
        "protectedPathApproval": protected_path_approval,
        "classifications": classifications,
        "productInterface": ui_applicability,
        "changedFiles": changed_files,
        "changeEvidence": change_evidence,
        "protectedPatterns": protected_patterns,
        "protectedMatches": protected_matches,
        "requiredChecks": policy.get("requiredChecks", []),
        "requiredActions": required_actions,
        "blockers": blockers,
        "warnings": warnings,
        "actionSafety": {
            "mode": "host-native",
            "customApprovalProtocol": False,
            "approvalTokenRequired": False,
            "terminalApprovalRequired": False,
            "explicitUserScopeRequired": True,
        },
        "policy": {key: value for key, value in policy.items() if not key.startswith("_")},
    }


def tool_preflight(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    goal = str(args.get("goal") or "").strip()
    strict = bool(args.get("strict", True))
    run_secret_scan = bool(args.get("run_secret_scan", True))
    policy_check = tool_policy_check(args)
    health = tool_health({"project_path": str(project_path)})
    review = tool_review({"project_path": str(project_path), "base_ref": args.get("base_ref")})
    blockers = list(policy_check["blockers"])
    warnings = list(policy_check["warnings"])

    if strict and policy_check["usingDefaultPolicy"]:
        blockers.append("Strict preflight requires a project JStack policy file.")
    if review["diffCheck"]["returncode"] != 0:
        blockers.append("git diff --check reported whitespace, conflict-marker, or patch hygiene issues.")
    if not health["testCommands"]:
        blockers.append("No test/build commands were discovered; define project checks or document why none exist.")
    if health["dirtyFileCount"] and not goal:
        warnings.append("Working tree has changes and no task goal was provided for risk classification.")

    security: Optional[dict[str, Any]] = None
    if run_secret_scan:
        security = tool_security_audit(
            {
                "project_path": str(project_path),
                "base_ref": args.get("base_ref"),
                "max_files": int(args.get("max_files") or 2000),
            }
        )
        if security["findingCount"] > 0:
            blockers.append("Secret/security scan found possible credentials or sensitive values.")
        if not security["complete"]:
            blockers.append("Secret/security scan was incomplete; truncation, symlinks, unreadable files, or size limits must be resolved.")
    elif strict and policy_check["policy"].get("security", {}).get("secretScanRequired", True):
        blockers.append("Strict preflight requires a complete secret/security scan.")

    required_evidence = [
        "Project instructions reviewed",
        "Risk class selected",
        "Changed files reviewed",
        "Protected paths checked",
        "Diff hygiene checked",
        "Test/build commands discovered",
        "Secret scan reviewed",
        "Applicable production launch profile and typed control evidence recorded",
        "Release approval recorded for production work",
        "Rollback/monitoring plan recorded for release work",
    ]
    return {
        "projectPath": str(project_path),
        "goal": goal,
        "strict": strict,
        "ready": not blockers,
        "blockers": blockers,
        "warnings": warnings,
        "requiredEvidence": required_evidence,
        "policyCheck": policy_check,
        "healthSummary": {
            "branch": health["branch"],
            "dirtyFileCount": health["dirtyFileCount"],
            "testCommands": health["testCommands"],
            "projectFiles": health["projectFiles"],
        },
        "reviewSummary": {
            "diffCheck": review["diffCheck"],
            "diffStat": review["diffStat"],
            "changedFiles": review["changedFiles"],
        },
        "securitySummary": security,
    }


def _launch_call(callback: Callable[[], Any]) -> Any:
    try:
        return callback()
    except launch_core.LaunchError as exc:
        raise ToolError(str(exc)) from exc


def _launch_safe_text(
    value: Any,
    field: str,
    *,
    minimum: int = 1,
    maximum: int = 2_000,
) -> str:
    normalized = str(value or "").strip()
    if not minimum <= len(normalized) <= maximum:
        raise ToolError(
            f"{field} must contain between {minimum} and {maximum} characters."
        )
    if audit_core.contains_secret_like(normalized):
        raise ToolError(f"{field} must not contain secret-like values.")
    return normalized


def _launch_environment(value: Any) -> str:
    environment = str(value or "production").strip().lower()
    if environment == "prod":
        environment = "production"
    if not re.fullmatch(r"[a-z][a-z0-9._-]{1,63}", environment):
        raise ToolError(
            "target_environment must be a lowercase environment identifier such as staging or production."
        )
    return environment


_LAUNCH_URL_SURFACES = frozenset(
    {
        "public-web",
        "browser-ui",
        "authenticated",
        "search-indexed",
        "performance-sensitive",
        "analytics",
        "payments",
        "commercial",
        "tracking",
        "ai-paid-endpoints",
    }
)


def _launch_target_url(
    value: Any,
    surfaces: list[str],
    target_environment: str,
) -> Optional[str]:
    raw = str(value or "").strip()
    requires_url = bool(set(surfaces) & _LAUNCH_URL_SURFACES)
    if not raw:
        if requires_url:
            raise ToolError(
                "target_url is required for the declared web, browser, analytics, payment, commercial, tracking, or costly-endpoint surfaces."
            )
        return None
    if len(raw) > 2_000:
        raise ToolError("target_url exceeds 2000 characters.")
    if audit_core.contains_secret_like(raw):
        raise ToolError("target_url must not contain secret-like values.")
    parsed = urllib.parse.urlsplit(raw)
    if (
        parsed.scheme.lower() not in {"http", "https"}
        or not parsed.hostname
        or parsed.username is not None
        or parsed.password is not None
        or parsed.query
        or parsed.fragment
    ):
        raise ToolError(
            "target_url must be an HTTP(S) origin or bounded path without credentials, query text, or a fragment."
        )
    hostname = parsed.hostname.lower().rstrip(".")
    if target_environment == "production":
        local_names = {"localhost", "127.0.0.1", "::1"}
        if parsed.scheme.lower() != "https":
            raise ToolError("Production launch targets must use HTTPS.")
        if hostname in local_names or hostname.endswith((".localhost", ".local")):
            raise ToolError("Production launch targets may not use a local hostname.")
    try:
        port = parsed.port
    except ValueError as exc:
        raise ToolError("target_url contains an invalid port.") from exc
    host = f"[{hostname}]" if ":" in hostname else hostname
    if port is not None:
        host += f":{port}"
    path = parsed.path or "/"
    return urllib.parse.urlunsplit((parsed.scheme.lower(), host, path, "", ""))


_LAUNCH_HINT_TEXT_SUFFIXES = frozenset(
    {
        ".c",
        ".cc",
        ".conf",
        ".cpp",
        ".cs",
        ".css",
        ".go",
        ".graphql",
        ".h",
        ".html",
        ".java",
        ".js",
        ".json",
        ".jsx",
        ".kt",
        ".mjs",
        ".php",
        ".prisma",
        ".py",
        ".rb",
        ".rs",
        ".sh",
        ".sql",
        ".svelte",
        ".toml",
        ".ts",
        ".tsx",
        ".vue",
        ".xml",
        ".yaml",
        ".yml",
    }
)
_LAUNCH_HINT_TEXT_NAMES = frozenset(
    {
        "dockerfile",
        "go.mod",
        "go.sum",
        "package-lock.json",
        "package.json",
        "pnpm-lock.yaml",
        "poetry.lock",
        "requirements.txt",
        "yarn.lock",
    }
)
_LAUNCH_HINT_SKIPPED_PREFIXES = (
    "docs/",
    "test/",
    "tests/",
    "fixtures/",
    "vendor/",
    "node_modules/",
    "dist/",
    "build/",
    "coverage/",
)


def _launch_surface_detection(project_path: Path) -> dict[str, Any]:
    """Read a bounded code/config corpus and return content-free surface hints."""
    paths = audit_git_inventory_paths(project_path)
    documents: list[tuple[str, str]] = []
    scanned_files = 0
    scanned_bytes = 0
    for relative in paths:
        normalized = relative.replace("\\", "/")
        lowered = normalized.lower()
        if lowered.startswith(_LAUNCH_HINT_SKIPPED_PREFIXES):
            continue
        candidate = project_path / normalized
        suffix = candidate.suffix.lower()
        name = candidate.name.lower()
        text = ""
        should_read = suffix in _LAUNCH_HINT_TEXT_SUFFIXES or name in _LAUNCH_HINT_TEXT_NAMES
        if should_read:
            if scanned_files >= LAUNCH_HINT_MAX_FILES:
                raise ToolError(
                    "Launch surface detection exceeded its 5000-file completeness limit."
                )
            try:
                metadata = candidate.stat()
            except OSError as exc:
                raise ToolError(
                    "Launch surface detection encountered an inaccessible project file."
                ) from exc
            if metadata.st_size > LAUNCH_HINT_MAX_FILE_BYTES:
                raise ToolError(
                    f"Launch surface detection requires an explicit disposition for oversized source/config file: {normalized}"
                )
            if scanned_bytes + metadata.st_size > LAUNCH_HINT_MAX_TOTAL_BYTES:
                raise ToolError(
                    "Launch surface detection exceeded its 8 MB completeness limit."
                )
            try:
                content = audit_core.read_repository_file(
                    project_path,
                    normalized,
                    max_bytes=LAUNCH_HINT_MAX_FILE_BYTES,
                    max_seconds=10,
                )
                text = content.decode("utf-8-sig", errors="replace")
            except (audit_core.AuditError, UnicodeError) as exc:
                raise ToolError(
                    f"Launch surface detection could not safely read source/config file: {normalized}"
                ) from exc
            scanned_files += 1
            scanned_bytes += metadata.st_size
        documents.append((normalized, text))
    hints = _launch_call(lambda: launch_core.detect_surface_hints(documents))
    hints = _launch_call(lambda: launch_core.normalize_surface_hints(hints))
    return {
        "schemaVersion": "jstack.launch.surface-hints.v1",
        "hints": hints,
        "hintDigest": launch_core.surface_hint_digest(hints),
        "scannedFiles": scanned_files,
        "scannedBytes": scanned_bytes,
        "complete": True,
        "sourceContentReturned": False,
    }


def _launch_artifact_path(
    project_path: Path,
    raw_path: str,
) -> tuple[Path, str, Path, str]:
    candidate = Path(raw_path).expanduser()
    if not candidate.is_absolute():
        candidate = project_path / candidate
    if candidate.is_symlink():
        raise ToolError("Launch evidence artifacts may not be symlinks.")
    try:
        resolved = candidate.resolve(strict=True)
    except OSError as exc:
        raise ToolError("Launch evidence artifact is missing or inaccessible.") from exc
    allowed_roots = [
        ("project", project_path.resolve()),
        ("external-evidence", (Path.home() / ".jstack" / "evidence").resolve(strict=False)),
    ]
    selected_root: Optional[Path] = None
    selected_kind: Optional[str] = None
    relative: Optional[str] = None
    for root_kind, root in allowed_roots:
        try:
            candidate_relative = resolved.relative_to(root)
        except ValueError:
            continue
        if candidate_relative.parts:
            selected_root = root
            selected_kind = root_kind
            relative = candidate_relative.as_posix()
            break
    if selected_root is None or selected_kind is None or relative is None:
        raise ToolError(
            "Launch evidence must be inside the Git project or ~/.jstack/evidence."
        )
    metadata = resolved.stat()
    if (
        not stat.S_ISREG(metadata.st_mode)
        or metadata.st_size > LAUNCH_MAX_ARTIFACT_BYTES
    ):
        raise ToolError(
            "Launch evidence must be a regular file no larger than 100 MB."
        )
    return selected_root, relative, resolved, selected_kind


def _launch_file_digest(root: Path, relative_path: str) -> tuple[int, str]:
    try:
        return audit_core.digest_repository_file(
            root,
            relative_path,
            max_bytes=LAUNCH_MAX_ARTIFACT_BYTES,
            max_seconds=LAUNCH_ARTIFACT_TIMEOUT_SECONDS,
        )
    except audit_core.AuditError as exc:
        raise ToolError(
            "Launch evidence artifact could not be opened with stable file identity."
        ) from exc


def _launch_observed_at(
    value: Any,
    *,
    max_age_minutes: int,
) -> tuple[_dt.datetime, _dt.datetime]:
    now = _dt.datetime.now(_dt.timezone.utc).replace(microsecond=0)
    if value is None or not str(value).strip():
        observed = now
    else:
        try:
            observed = _dt.datetime.fromisoformat(
                str(value).strip().replace("Z", "+00:00")
            )
        except ValueError as exc:
            raise ToolError("observed_at must be an ISO-8601 timestamp with timezone.") from exc
        if observed.tzinfo is None:
            raise ToolError("observed_at must include a timezone.")
        observed = observed.astimezone(_dt.timezone.utc).replace(microsecond=0)
    age = (now - observed).total_seconds()
    if age < -300:
        raise ToolError("observed_at may not be more than five minutes in the future.")
    if age > max_age_minutes * 60:
        raise ToolError("The launch evidence is already older than its allowed freshness window.")
    expires = observed + _dt.timedelta(minutes=max_age_minutes)
    if expires <= now:
        raise ToolError("The launch evidence has already expired.")
    return observed, expires


def _launch_selection(
    project_path: Path,
    surfaces: list[str],
    target_environment: str,
    target_url: Optional[str],
    risk_tier: str,
    deployment_fingerprint: str,
    surface_hint_digest_value: str,
    reconciliation_digest_value: str,
) -> tuple[dict[str, Any], dict[str, Any]]:
    policy = load_enterprise_policy(project_path)
    launch_policy = policy.get("launch", {})
    selection = _launch_call(
        lambda: launch_core.select_controls(
            surfaces,
            target_environment=target_environment,
            target_url=target_url,
            risk_tier=risk_tier,
            deployment_fingerprint=deployment_fingerprint,
            surface_hint_digest_value=surface_hint_digest_value,
            reconciliation_digest_value=reconciliation_digest_value,
            minimum_risk_tier=launch_policy.get("minimumRiskTier", "low"),
            required_control_ids=launch_policy.get("requiredControlIds", []),
            advisory_control_ids=launch_policy.get("advisoryControlIds", []),
        )
    )
    return policy, selection


def _launch_selected_contract(selection: dict[str, Any]) -> list[dict[str, Any]]:
    return [
        {
            "id": control["id"],
            "gateLevel": control["effectiveGateLevel"],
            "requirementIds": [
                requirement["id"]
                for requirement in control["activeEvidenceRequirements"]
            ],
        }
        for control in selection["selectedControls"]
    ]


def _launch_reconciliation_input(value: Any) -> list[dict[str, Any]]:
    if value is None:
        return []
    if not isinstance(value, list) or len(value) > len(launch_core.SURFACE_IDS):
        raise ToolError("surface_reconciliation must be a bounded array.")
    expected = {
        "surface",
        "decision",
        "owner",
        "rationale",
        "evidence_reference",
    }
    result: list[dict[str, Any]] = []
    for index, raw in enumerate(value):
        if not isinstance(raw, dict) or set(raw) != expected:
            raise ToolError(
                f"surface_reconciliation[{index}] must contain exactly surface, decision, owner, rationale, and evidence_reference."
            )
        result.append(
            {
                "surface": raw["surface"],
                "decision": raw["decision"],
                "owner": raw["owner"],
                "rationale": raw["rationale"],
                "evidenceReference": raw["evidence_reference"],
            }
        )
    return result


def _launch_session_payload(
    project_path: Path,
    session_token: str,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any], dict[str, Any]]:
    if not session_token or len(session_token) > LAUNCH_MAX_RECEIPT_CHARS:
        raise ToolError("launch_session_token is missing or exceeds the bounded receipt size.")
    state = project_state(project_path)
    first = verify_receipt(
        session_token,
        "launch-session",
        state,
        require_passed=False,
    )
    if not first["valid"]:
        raise ToolError(
            "Launch assessment token is stale or does not match the current project state."
        )
    payload = first["payload"]
    base_ref = str(payload.get("baseRef") or "").strip()
    if not base_ref:
        raise ToolError("Launch assessment token has no explicit base_ref binding.")
    subject = evidence_subject(project_path, base_ref)
    verification = verify_receipt(
        session_token,
        "launch-session",
        subject,
        expected_subject=subject,
        require_passed=False,
    )
    current_detection = _launch_surface_detection(project_path)
    policy, selection = _launch_selection(
        project_path,
        list(payload.get("surfaces") or []),
        str(payload.get("targetEnvironment") or ""),
        payload.get("targetUrl"),
        str(payload.get("riskTier") or ""),
        str(payload.get("deploymentFingerprint") or ""),
        current_detection["hintDigest"],
        str(payload.get("surfaceReconciliationDigest") or ""),
    )
    selected_contract = _launch_selected_contract(selection)
    reconciled_surfaces = {
        str(record.get("surface") or "")
        for record in payload.get("surfaceReconciliation", [])
        if isinstance(record, dict)
    }
    unresolved_current_hints = [
        hint["surface"]
        for hint in current_detection["hints"]
        if hint["surface"] not in set(selection["surfaces"])
        and hint["surface"] not in reconciled_surfaces
    ]
    checks = {
        "receipt": verification["valid"],
        "schemaVersion": payload.get("schemaVersion")
        == "jstack.launch.session.v2",
        "catalogVersion": payload.get("catalogVersion")
        == selection["catalogVersion"],
        "catalogDigest": payload.get("catalogDigest")
        == selection["catalogDigest"],
        "selectionDigest": payload.get("selectionDigest")
        == selection["selectionDigest"],
        "selectedControls": payload.get("selectedControls")
        == selected_contract,
        "targetEnvironment": payload.get("targetEnvironment")
        == selection["targetEnvironment"],
        "targetUrl": payload.get("targetUrl") == selection["targetUrl"],
        "surfaces": payload.get("surfaces") == selection["surfaces"],
        "riskTier": payload.get("riskTier") == selection["riskTier"],
        "deploymentFingerprint": payload.get("deploymentFingerprint")
        == selection["deploymentFingerprint"],
        "surfaceHintsCurrent": payload.get("surfaceHintDigest")
        == current_detection["hintDigest"],
        "surfaceReconciliation": payload.get("surfaceReconciliationDigest")
        == selection["surfaceReconciliationDigest"],
        "surfaceReconciliationComplete": not unresolved_current_hints,
    }
    if not all(checks.values()):
        raise ToolError(
            "Launch assessment token no longer matches the current catalogue, policy, or applicability contract."
        )
    return payload, subject, policy, selection


def _ui_existing_system(project_path: Path, value: Any) -> dict[str, Any]:
    if value is None:
        return {"present": False, "id": None, "evidence": [], "supportedThemes": []}
    expected = {"present", "id", "evidence_paths", "supported_themes"}
    if not isinstance(value, dict) or set(value) != expected:
        raise ToolError(
            "existing_system must contain exactly present, id, evidence_paths, and supported_themes."
        )
    present = value.get("present")
    if not isinstance(present, bool):
        raise ToolError("existing_system.present must be boolean.")
    if not present:
        if value.get("id") is not None or value.get("evidence_paths") != [] or value.get("supported_themes") != []:
            raise ToolError(
                "An absent existing system must use id=null, evidence_paths=[], and supported_themes=[]."
            )
        return {"present": False, "id": None, "evidence": [], "supportedThemes": []}
    system_id = str(value.get("id") or "").strip()
    paths = value.get("evidence_paths")
    themes = value.get("supported_themes")
    if not system_id or len(system_id) > 160:
        raise ToolError("existing_system.id must be a bounded non-empty identifier.")
    if (
        not isinstance(paths, list)
        or not 1 <= len(paths) <= ui_core.registry.MAX_EXISTING_SYSTEM_EVIDENCE
        or not all(isinstance(item, str) for item in paths)
    ):
        raise ToolError(
            "existing_system.evidence_paths must contain one to 256 repository-relative paths."
        )
    if len(paths) != len(set(paths)):
        raise ToolError("existing_system.evidence_paths must not contain duplicates.")
    if not isinstance(themes, list) or not themes or not all(isinstance(item, str) for item in themes):
        raise ToolError("existing_system.supported_themes must declare the established themes.")
    rows: list[dict[str, Any]] = []
    for index, raw_path in enumerate(paths):
        try:
            relative = decode_git_relative_path(raw_path.encode("utf-8"), "existing-system evidence")
            size, digest = audit_core.digest_repository_file(
                project_path,
                relative,
                max_bytes=10_000_000,
                max_seconds=15,
            )
        except (UnicodeEncodeError, audit_core.AuditError) as exc:
            raise ToolError(
                f"existing_system.evidence_paths[{index}] is not one safe stable regular repository file."
            ) from exc
        rows.append(
            {
                "pathSha256": hashlib.sha256(relative.encode("utf-8")).hexdigest(),
                "sha256": digest,
                "size": size,
            }
        )
    return {
        "present": True,
        "id": system_id,
        "evidence": sorted(rows, key=lambda item: item["pathSha256"]),
        "supportedThemes": themes,
    }


def _ui_global_established_system_paths(
    project_path: Path,
    tracked_paths: list[str],
) -> list[str]:
    """Select one content-qualified representative per detected project system."""
    candidates = sorted(
        path
        for path in tracked_paths
        if ui_core.is_established_system_path(path)
        and _ui_file_candidate_kind(path, scoped=True) is not None
    )
    if not candidates:
        return []
    detection = _ui_detection(project_path, candidates)
    if detection.get("inspectionTruncated"):
        raise ToolError(
            "Global Product Interface design-system detection was incomplete. "
            "Narrow or reorganize the system sources before issuing a contract."
        )
    representatives = {
        str(row["matchedFiles"][0])
        for row in detection["establishedSystemHints"]
        if isinstance(row.get("matchedFiles"), list) and row["matchedFiles"]
    }
    return sorted(representatives)


def tool_ui_reference_contract(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    subject_before = evidence_subject(project_path)
    if not subject_before["clean"]:
        raise ToolError(
            "A Product Interface reference contract requires a clean committed baseline. Commit or remove local changes first."
        )
    expected_fingerprint = str(args.get("project_fingerprint") or "").strip()
    if expected_fingerprint != subject_before["projectFingerprint"]:
        raise ToolError(
            "project_fingerprint is stale or does not match the server-derived reference baseline."
        )
    baseline = _ui_git_identity(project_path, subject_before)
    viewports = args.get("viewports")
    if viewports is None:
        viewports = [
            {"id": "desktop", "width": 1280, "height": 800, "dpr": 1},
            {"id": "mobile", "width": 390, "height": 844, "dpr": 1},
        ]
    prototype_mode = str(args.get("prototype_mode") or "none").strip()
    max_variants = args.get("max_variants")
    if max_variants is None:
        max_variants = 0 if prototype_mode == "none" else 2
    bundle_id = "reference-" + secrets.token_hex(12)
    try:
        contract = ui_core.build_reference_contract(
            goal=args.get("goal"),
            baseline=baseline,
            bundle_id=bundle_id,
            source_kinds=args.get("source_kinds"),
            viewports=viewports,
            prototype_mode=prototype_mode,
            max_variants=max_variants,
            external_provider_allowed=args.get("external_provider_allowed", False),
        )
    except ui_core.ReferenceError as exc:
        raise ToolError(str(exc)) from exc
    subject_after = evidence_subject(project_path)
    identity_after = _ui_git_identity(project_path, subject_after)
    if subject_after != subject_before or identity_after != baseline:
        raise ToolError(
            "The repository or policy changed while the reference contract was being derived."
        )
    expires = (
        _dt.datetime.now(_dt.timezone.utc)
        + _dt.timedelta(seconds=UI_REFERENCE_MAX_AGE_SECONDS)
    ).replace(microsecond=0).isoformat()
    token = issue_ui_reference_receipt(
        {
            "kind": "ui-reference-contract",
            "schemaVersion": "jstack.ui.reference-contract-receipt.v1",
            "projectPath": subject_before["gitRoot"],
            "gitHead": subject_before["gitHead"],
            "projectFingerprint": subject_before["projectFingerprint"],
            "policyDigest": subject_before["policyDigest"],
            "toolVersion": SERVER_VERSION,
            "contract": contract,
            "contractSha256": contract["contractSha256"],
            "bundleId": contract["bundleId"],
            "expiresAt": expires,
            "passed": False,
        }
    )
    if len(token) > UI_RECEIPT_MAX_CHARS:
        raise ToolError(
            "The reference contract exceeds the bounded receipt limit. Narrow the source or viewport scope."
        )
    reference_root = _ui_reference_root(project_path, contract["bundleId"])
    return {
        "schemaVersion": "jstack.ui.reference-contract-response.v1",
        "projectPath": str(project_path),
        "baseline": baseline,
        "contract": contract,
        "contractSha256": contract["contractSha256"],
        "referenceContractReceipt": token,
        "expiresAt": expires,
        "referenceRoot": str(reference_root),
        "referenceRootPolicy": {
            "serverSelected": True,
            "outsideRepository": True,
            "callerCreatesDirectoryMode": "0700",
            "fileMode": "0600",
            "relativeManifestOnly": True,
            "rawArtifactContentReturned": False,
        },
        "executionAuthorized": False,
        "limitations": [
            "This contract authorizes collection only from user-provided or explicitly approved references; it does not authorize crawling, authenticated browsing, or external-provider disclosure.",
            "Reference artifacts are design inputs, not candidate UI evidence, QA, accessibility proof, security evidence, release approval, or deployment authority.",
            "Prototype rendering must remain isolated with network access disabled; generated files stay outside the project until the user separately approves implementation.",
        ],
    }


def _ui_reference_contract_payload(
    project_path: Path,
    token: str,
    *,
    require_fresh: bool = True,
) -> tuple[dict[str, Any], dict[str, Any]]:
    if not token or len(token) > UI_RECEIPT_MAX_CHARS:
        raise ToolError("reference_contract_receipt must be one bounded signed receipt.")
    payload = verify_ui_reference_receipt(
        token,
        expected_kind="ui-reference-contract",
        require_fresh=require_fresh,
    )
    try:
        contract = ui_core.validate_reference_contract(payload.get("contract"))
    except ui_core.ReferenceError as exc:
        raise ToolError(str(exc)) from exc
    baseline = contract["baseline"]
    checks = {
        "schemaVersion": payload.get("schemaVersion")
        == "jstack.ui.reference-contract-receipt.v1",
        "projectPath": payload.get("projectPath") == str(project_path),
        "gitRoot": baseline.get("gitRoot") == str(project_path),
        "gitHead": payload.get("gitHead") == baseline.get("gitHead"),
        "projectFingerprint": payload.get("projectFingerprint")
        == baseline.get("projectFingerprint"),
        "policyDigest": payload.get("policyDigest") == baseline.get("policyDigest"),
        "toolVersion": payload.get("toolVersion") == SERVER_VERSION,
        "contractSha256": payload.get("contractSha256")
        == contract["contractSha256"],
        "bundleId": payload.get("bundleId") == contract["bundleId"],
        "notFinalization": payload.get("passed") is False,
    }
    if not all(checks.values()):
        raise ToolError(
            "Reference contract receipt no longer matches this project, server, or contract."
        )
    return payload, contract


def tool_ui_reference_finalize(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    token = str(args.get("reference_contract_receipt") or "").strip()
    _, contract = _ui_reference_contract_payload(
        project_path,
        token,
        require_fresh=True,
    )
    subject_before = evidence_subject(project_path)
    baseline = contract["baseline"]
    identity_before = _ui_git_identity(project_path, subject_before)
    if not subject_before["clean"] or identity_before != baseline:
        raise ToolError(
            "Reference finalization requires the same clean committed project baseline used by its contract."
        )
    reference_root = _ui_reference_root(project_path, contract["bundleId"])
    _validate_ui_evidence_root_authority(reference_root)
    manifest_relative = str(args.get("reference_manifest") or "").strip()
    try:
        first = ui_core.load_and_validate_reference_bundle(
            reference_root,
            manifest_relative,
            contract=contract,
        )
        second = ui_core.load_and_validate_reference_bundle(
            reference_root,
            manifest_relative,
            contract=contract,
        )
    except ui_core.ReferenceError as exc:
        raise ToolError(str(exc)) from exc
    if first != second:
        raise ToolError("Reference bundle changed during final verification.")
    subject_after = evidence_subject(project_path)
    identity_after = _ui_git_identity(project_path, subject_after)
    if subject_after != subject_before or identity_after != baseline:
        raise ToolError("The project changed during reference finalization.")
    binding = ui_core.reference_binding(first)
    expires = (
        _dt.datetime.now(_dt.timezone.utc)
        + _dt.timedelta(seconds=UI_REFERENCE_MAX_AGE_SECONDS)
    ).replace(microsecond=0).isoformat()
    finalization_token = issue_ui_reference_receipt(
        {
            "kind": "ui-reference-finalization",
            "schemaVersion": "jstack.ui.reference-finalization-receipt.v1",
            "projectPath": str(project_path),
            "gitHead": baseline["gitHead"],
            "projectFingerprint": baseline["projectFingerprint"],
            "policyDigest": baseline["policyDigest"],
            "toolVersion": SERVER_VERSION,
            "contract": contract,
            "contractSha256": contract["contractSha256"],
            "binding": binding,
            "expiresAt": expires,
            "passed": True,
        }
    )
    if len(finalization_token) > UI_RECEIPT_MAX_CHARS:
        raise ToolError("The reference finalization exceeds the bounded receipt limit.")
    return {
        "schemaVersion": "jstack.ui.reference-finalization.v1",
        "status": "passed",
        "projectPath": str(project_path),
        "baseline": baseline,
        "referenceBundle": binding,
        "validation": first,
        "referenceFinalizationReceipt": finalization_token,
        "expiresAt": expires,
        "candidateEvidenceQualified": False,
        "executionAuthorized": False,
        "limitations": [
            "This receipt proves only the integrity and declared provenance of a private reference bundle.",
            "It cannot satisfy jstack_ui_finalize, QA, accessibility, security, launch, release, or human approval requirements.",
        ],
    }


def _ui_reference_finalization_payload(
    project_path: Path,
    token: str,
    *,
    require_fresh: bool = True,
) -> tuple[dict[str, Any], dict[str, Any]]:
    if not token or len(token) > UI_RECEIPT_MAX_CHARS:
        raise ToolError("reference_bundle_receipt must be one bounded signed receipt.")
    payload = verify_ui_reference_receipt(
        token,
        expected_kind="ui-reference-finalization",
        require_fresh=require_fresh,
    )
    try:
        contract = ui_core.validate_reference_contract(payload.get("contract"))
        binding = ui_core.normalize_reference_bundle(payload.get("binding"))
    except (ui_core.ReferenceError, ui_core.UIError) as exc:
        raise ToolError(str(exc)) from exc
    baseline = contract["baseline"]
    checks = {
        "schemaVersion": payload.get("schemaVersion")
        == "jstack.ui.reference-finalization-receipt.v1",
        "projectPath": payload.get("projectPath") == str(project_path),
        "gitRoot": baseline.get("gitRoot") == str(project_path),
        "gitHead": payload.get("gitHead") == baseline.get("gitHead"),
        "projectFingerprint": payload.get("projectFingerprint")
        == baseline.get("projectFingerprint"),
        "policyDigest": payload.get("policyDigest") == baseline.get("policyDigest"),
        "toolVersion": payload.get("toolVersion") == SERVER_VERSION,
        "contractSha256": payload.get("contractSha256")
        == contract["contractSha256"],
        "bindingContract": binding is not None
        and binding.get("contractSha256") == contract["contractSha256"],
        "passed": payload.get("passed") is True,
    }
    if not all(checks.values()):
        raise ToolError(
            "Reference finalization receipt no longer matches this project, server, or bundle."
        )
    return payload, binding


def tool_ui_contract(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    subject_before = evidence_subject(project_path)
    if not subject_before["clean"]:
        raise ToolError(
            "A formal Product Interface contract requires a clean committed baseline. Commit or remove local changes first."
        )
    expected_fingerprint = str(args.get("project_fingerprint") or "").strip()
    if expected_fingerprint != subject_before["projectFingerprint"]:
        raise ToolError(
            "project_fingerprint is stale or does not match the server-derived baseline fingerprint."
        )
    baseline = _ui_git_identity(project_path, subject_before)
    reference_binding = None
    reference_token = str(args.get("reference_bundle_receipt") or "").strip()
    if reference_token:
        reference_payload, reference_binding = _ui_reference_finalization_payload(
            project_path,
            reference_token,
            require_fresh=True,
        )
        if (
            reference_payload.get("gitHead") != subject_before["gitHead"]
            or reference_payload.get("projectFingerprint")
            != subject_before["projectFingerprint"]
            or reference_payload.get("policyDigest") != subject_before["policyDigest"]
        ):
            raise ToolError(
                "The reference bundle was finalized against a different project baseline."
            )
    raw_allowed_paths = args.get("allowed_paths")
    if (
        not isinstance(raw_allowed_paths, list)
        or not 1 <= len(raw_allowed_paths) <= ui_core.registry.MAX_ALLOWED_PATHS
        or not all(isinstance(item, str) for item in raw_allowed_paths)
    ):
        raise ToolError(
            "allowed_paths must contain one to 100 repository-relative UI source glob patterns."
        )
    try:
        allowed_paths = ui_core.normalize_allowed_paths(raw_allowed_paths)
    except ui_core.UIError as exc:
        raise ToolError(str(exc)) from exc
    listed = run_complete(
        ["git", "ls-files", "-z"],
        project_path,
        timeout=20,
        max_bytes=10_000_000,
    )
    if not listed["ok"]:
        raise ToolError("Could not enumerate the contracted Product Interface baseline scope.")
    tracked_paths = [
        decode_git_relative_path(raw, "UI contract baseline")
        for raw in listed["stdout"].split(b"\0")
        if raw
    ]
    raw_existing_system = args.get("existing_system")
    existing_paths = (
        raw_existing_system.get("evidence_paths", [])
        if isinstance(raw_existing_system, dict)
        else []
    )
    global_system_paths = _ui_global_established_system_paths(
        project_path,
        tracked_paths,
    )
    detection_paths = sorted(
        {
            path
            for path in tracked_paths
            if path_matches_patterns(path, allowed_paths)
        }
        | {
            str(path)
            for path in existing_paths
            if isinstance(path, str)
        }
        | set(global_system_paths)
    )
    detection = _ui_detection(project_path, detection_paths)
    existing_system = _ui_existing_system(project_path, raw_existing_system)
    if existing_system["present"] and not bool(args.get("redesign_approved", False)):
        evidence_path_digests = {
            row["pathSha256"] for row in existing_system["evidence"]
        }
        missing_global_system_paths = [
            path
            for path in global_system_paths
            if hashlib.sha256(path.encode("utf-8")).hexdigest()
            not in evidence_path_digests
        ]
        if missing_global_system_paths:
            raise ToolError(
                "existing_system.evidence_paths must cover every globally detected design-system marker representative: "
                + ", ".join(missing_global_system_paths)
            )
    viewports = args.get("viewports")
    if viewports is None:
        viewports = [
            {"id": "desktop-wide", "width": 1440, "height": 900, "dpr": 1, "primary": False},
            {"id": "desktop", "width": 1280, "height": 800, "dpr": 1, "primary": True},
            {"id": "mobile", "width": 390, "height": 844, "dpr": 1, "primary": False},
        ]
    try:
        contract = ui_core.build_contract(
            goal=args.get("goal"),
            baseline=baseline,
            detection=detection,
            surfaces=args.get("surfaces"),
            platforms=args.get("platforms"),
            themes=args.get("themes"),
            viewports=viewports,
            allowed_paths=allowed_paths,
            platform_exclusions=args.get("platform_exclusions"),
            explicit_profile=args.get("profile_override"),
            surface_profiles=args.get("surface_profiles"),
            existing_system=existing_system,
            redesign_approved=args.get("redesign_approved", False),
            redesign_approval_reference=args.get("redesign_approval_reference"),
            reference_bundle=reference_binding,
        )
    except ui_core.UIError as exc:
        raise ToolError(str(exc)) from exc
    subject_after = evidence_subject(project_path)
    identity_after = _ui_git_identity(project_path, subject_after)
    if subject_after != subject_before or identity_after != baseline:
        raise ToolError(
            "The repository or Product Interface policy changed while the UI contract was being derived."
        )
    expires = (
        _dt.datetime.now(_dt.timezone.utc)
        + _dt.timedelta(seconds=UI_CONTRACT_MAX_AGE_SECONDS)
    ).replace(microsecond=0).isoformat()
    token = issue_ui_contract_receipt(
        {
            "kind": "ui-contract",
            "schemaVersion": "jstack.ui.contract-receipt.v1",
            "projectPath": subject_before["gitRoot"],
            "gitHead": subject_before["gitHead"],
            "projectFingerprint": subject_before["projectFingerprint"],
            "policyDigest": subject_before["policyDigest"],
            "toolVersion": SERVER_VERSION,
            "contract": contract,
            "contractSha256": contract["contractSha256"],
            "catalogSha256": contract["catalog"]["sha256"],
            "expiresAt": expires,
            "passed": False,
        }
    )
    if len(token) > UI_RECEIPT_MAX_CHARS:
        raise ToolError(
            "The Product Interface contract exceeds the bounded 250000-character receipt limit. Narrow allowed_paths, surfaces, viewports, or platform scope before implementation."
        )
    evidence_root = _ui_evidence_root(project_path)
    return {
        "schemaVersion": "jstack.ui.contract-response.v1",
        "projectPath": str(project_path),
        "baseline": baseline,
        "catalog": contract["catalog"],
        "detection": detection,
        "profileResolution": contract["profileResolution"],
        "referenceBundle": contract.get("referenceBundle"),
        "allowedPaths": contract["allowedPaths"],
        "platformExclusions": contract["platformExclusions"],
        "requirements": contract["requirements"],
        "surfaces": contract["surfaces"],
        "platforms": contract["platforms"],
        "themes": contract["themes"],
        "viewports": contract["viewports"],
        "evidenceMatrix": contract["evidenceMatrix"],
        "contractSha256": contract["contractSha256"],
        "uiContractReceipt": token,
        "expiresAt": expires,
        "evidenceRoot": str(evidence_root),
        "evidenceRootPolicy": {
            "serverSelected": True,
            "outsideRepository": True,
            "directoryMode": "0700",
            "fileMode": "0600",
            "relativeManifestOnly": True,
            "rawScreenshotContentReturned": False,
        },
        "executionAuthorized": False,
        "limitations": [
            "This receipt freezes semantic UI requirements at a clean Git baseline; it does not execute or approve implementation work.",
            "Profile defaults are original JStack guidance influenced by general craft qualities, not copied vendor themes, layouts, branding, assets, or source code.",
            (
                "The self-contained contract receipt remains verifiable across MCP restarts using a private per-user POSIX key; retain the opaque receipt unchanged."
                if _ui_contract_key_is_durable()
                else "This platform cannot safely persist the contract-signing key with stdlib-only filesystem guarantees, so the receipt is valid only in the current MCP server session."
            ),
        ],
    }


def _ui_contract_payload(
    project_path: Path,
    token: str,
    *,
    require_fresh: bool = True,
) -> tuple[dict[str, Any], dict[str, Any]]:
    if not token or len(token) > UI_RECEIPT_MAX_CHARS:
        raise ToolError("ui_contract_receipt must be one bounded signed receipt.")
    payload = verify_ui_contract_receipt(token, require_fresh=require_fresh)
    contract_raw = payload.get("contract")
    try:
        contract = ui_core.validate_contract(contract_raw)
    except ui_core.UIError as exc:
        raise ToolError(str(exc)) from exc
    baseline = contract["baseline"]
    checks = {
        "schemaVersion": payload.get("schemaVersion") == "jstack.ui.contract-receipt.v1",
        "projectPath": payload.get("projectPath") == str(project_path),
        "gitRoot": baseline.get("gitRoot") == str(project_path),
        "gitHead": payload.get("gitHead") == baseline.get("gitHead"),
        "projectFingerprint": payload.get("projectFingerprint")
        == baseline.get("projectFingerprint"),
        "contractSha256": payload.get("contractSha256") == contract["contractSha256"],
        "catalogSha256": payload.get("catalogSha256") == ui_core.canonical_digest(ui_core.load_catalog()),
        "policyDigest": payload.get("policyDigest") == baseline.get("policyDigest"),
        "toolVersion": payload.get("toolVersion") == SERVER_VERSION,
        "notFinalization": payload.get("passed") is False,
    }
    if not all(checks.values()):
        raise ToolError(
            "UI contract receipt no longer matches this project, server, or Product Interface catalogue."
        )
    return payload, contract


def _validate_ui_candidate_scope(
    candidate_delta: dict[str, Any],
    candidate_scope: dict[str, Any],
    contract: dict[str, Any],
) -> list[str]:
    if any(
        "160000" in {record.get("baselineMode"), record.get("candidateMode")}
        for record in candidate_delta["changeRecords"]
    ):
        raise ToolError(
            "UI finalization cannot authorize a changed Git submodule without an independently bounded submodule Product Interface contract."
        )
    candidate_ui_paths = list(candidate_scope["matchedPaths"])
    if not candidate_delta["changeRecords"] or not candidate_ui_paths:
        raise ToolError(
            "UI finalization requires at least one baseline-to-candidate change to a detected contracted UI path."
        )
    path_violations = [
        path
        for path in candidate_ui_paths
        if not path_matches_patterns(path, contract["allowedPaths"])
    ]
    if path_violations:
        raise ToolError(
            "Detected candidate UI paths escape the contracted allowed_paths boundary: "
            + ", ".join(path_violations)
        )
    target_platforms = set(contract["platforms"])
    excluded_platforms = {
        row["platform"] for row in contract["platformExclusions"]
    }
    detected_candidate_platforms = set(candidate_scope["platforms"])
    uncovered_platforms = sorted(
        detected_candidate_platforms - target_platforms - excluded_platforms
    )
    if uncovered_platforms:
        raise ToolError(
            "The candidate adds or changes UI platforms outside the contracted evidence scope: "
            + ", ".join(uncovered_platforms)
        )
    mixed_excluded_paths = sorted(
        (
            row["path"],
            sorted(set(row["platforms"]) & excluded_platforms),
        )
        for row in candidate_scope["pathPlatforms"]
        if set(row["platforms"]) & target_platforms
        and set(row["platforms"]) & excluded_platforms
    )
    if mixed_excluded_paths:
        raise ToolError(
            "Candidate UI paths also affect explicitly excluded platform adapters; "
            "evidence for one adapter cannot qualify another: "
            + ", ".join(
                f"{path} ({'/'.join(platforms)})"
                for path, platforms in mixed_excluded_paths
            )
        )
    excluded_only_paths = sorted(
        row["path"]
        for row in candidate_scope["pathPlatforms"]
        if not (set(row["platforms"]) & target_platforms)
    )
    if excluded_only_paths:
        raise ToolError(
            "Candidate UI paths map only to excluded, non-target platforms: "
            + ", ".join(excluded_only_paths)
        )
    contracted_surface_kinds = {row["kind"] for row in contract["surfaces"]}
    uncovered_surface_kinds = sorted(
        set(candidate_scope["creativeSurfaceKinds"]) - contracted_surface_kinds
    )
    if uncovered_surface_kinds:
        raise ToolError(
            "The candidate adds or changes creative UI surface classes outside the contract: "
            + ", ".join(uncovered_surface_kinds)
        )
    return candidate_ui_paths


def tool_ui_finalize(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    token = str(args.get("ui_contract_receipt") or "").strip()
    _, contract = _ui_contract_payload(project_path, token, require_fresh=False)
    baseline = contract["baseline"]
    candidate_before = _ui_candidate_delta(project_path, baseline["gitHead"])
    if not candidate_before["clean"]:
        raise ToolError(
            "UI finalization requires a clean committed candidate with no hidden index flags or untracked files."
        )
    if candidate_before["commonDir"] != baseline["commonDir"] or candidate_before["gitRoot"] != baseline["gitRoot"]:
        raise ToolError("UI contract cannot be transplanted to another repository or worktree identity.")
    current_subject = evidence_subject(project_path, baseline["gitHead"])
    if current_subject["policyDigest"] != baseline["policyDigest"]:
        raise ToolError("Project policy changed after the UI baseline contract was issued.")
    candidate_documents = _ui_collect_changed_documents(
        project_path,
        baseline["gitHead"],
        candidate_before["changeRecords"],
    )
    repository_context = _ui_changed_repository_context_by_path(
        project_path,
        baseline["gitHead"],
        candidate_before["changeRecords"],
    )
    candidate_detection = ui_core.detect_product_ui(
        candidate_documents, context_platforms_by_path=repository_context
    )
    candidate_scope = ui_core.detect_product_ui_scope(
        candidate_documents, context_platforms_by_path=repository_context
    )
    candidate_ui_paths = _validate_ui_candidate_scope(
        candidate_before, candidate_scope, contract
    )
    qa_receipt = str(args.get("qa_receipt") or "").strip()
    qa_verification = verify_receipt(
        qa_receipt,
        "qa",
        current_subject,
        expected_subject=current_subject,
    )
    qa_payload = qa_verification["payload"]
    command_key = str(args.get("build_command_key") or "").strip()
    current_commands = {item["key"]: item for item in discover_test_commands(project_path)}
    selected = current_commands.get(command_key)
    if (
        not qa_verification["valid"]
        or selected is None
        or qa_payload.get("commandKey") != command_key
        or qa_payload.get("commandFingerprint") != selected["commandFingerprint"]
    ):
        raise ToolError(
            "UI finalization requires a current passing QA receipt for the exact discovered build/test command."
        )
    build_sha256 = str(args.get("build_sha256") or "").strip()
    runtime_sha256 = str(args.get("runtime_sha256") or "").strip()
    if not re.fullmatch(r"[0-9a-f]{64}", build_sha256) or not re.fullmatch(r"[0-9a-f]{64}", runtime_sha256):
        raise ToolError("build_sha256 and runtime_sha256 must be lowercase SHA-256 digests.")
    expected_candidate = {
        "gitHead": candidate_before["gitHead"],
        "treeSha256": candidate_before["treeSha256"],
        "projectFingerprint": candidate_before["projectFingerprint"],
        "buildCommandKey": command_key,
        "buildCommandSha256": selected["commandFingerprint"],
        "buildSha256": build_sha256,
        "runtimeSha256": runtime_sha256,
    }
    manifest_relative = str(args.get("evidence_manifest") or "").strip()
    evidence_root = _ui_evidence_root(project_path)
    _validate_ui_evidence_root_authority(evidence_root)
    try:
        evidence_first = ui_core.load_and_validate_evidence(
            evidence_root,
            manifest_relative,
            contract=contract,
            expected_candidate=expected_candidate,
        )
        evidence_second = ui_core.load_and_validate_evidence(
            evidence_root,
            manifest_relative,
            contract=contract,
            expected_candidate=expected_candidate,
        )
    except ui_core.EvidenceError as exc:
        raise ToolError(str(exc)) from exc
    if evidence_first != evidence_second:
        raise ToolError("UI evidence changed during final verification.")
    candidate_after = _ui_candidate_delta(project_path, baseline["gitHead"])
    if candidate_after != candidate_before:
        raise ToolError("The candidate Git state changed during UI finalization.")
    receipt_payload = {
        "kind": "ui-finalization",
        "schemaVersion": "jstack.ui.finalization-receipt.v1",
        "projectPath": str(project_path),
        "gitHead": candidate_after["gitHead"],
        "projectFingerprint": candidate_after["projectFingerprint"],
        "baseCommit": baseline["gitHead"],
        "policyDigest": baseline["policyDigest"],
        "toolVersion": SERVER_VERSION,
        "treeSha256": candidate_after["treeSha256"],
        "commonDirSha256": hashlib.sha256(candidate_after["commonDir"].encode("utf-8")).hexdigest(),
        "changedPathsSha256": candidate_after["changedPathsSha256"],
        "changeRecordsSha256": candidate_after["changeRecordsSha256"],
        "diffSha256": candidate_after["diffSha256"],
        "candidateDetectionSha256": candidate_detection["detectionSha256"],
        "candidateDetectionScopeSha256": candidate_scope["scopeSha256"],
        "candidateUiPathsSha256": ui_core.canonical_digest(candidate_ui_paths),
        "contractSha256": contract["contractSha256"],
        "catalogSha256": contract["catalog"]["sha256"],
        "evidenceManifestSha256": evidence_first["manifestSha256"],
        "evidenceManifestRawSha256": evidence_first["manifestRawSha256"],
        "captureSetSha256": evidence_first["captureSetSha256"],
        "checkSetSha256": evidence_first["checkSetSha256"],
        "productObservationSetSha256": evidence_first["productObservationSetSha256"],
        "buildCommandKey": command_key,
        "buildCommandSha256": selected["commandFingerprint"],
        "buildSha256": build_sha256,
        "runtimeSha256": runtime_sha256,
        "qaReceiptSha256": hashlib.sha256(qa_receipt.encode("utf-8")).hexdigest(),
        "complete": True,
        "passed": True,
        "executionAuthorized": False,
    }
    final_receipt = issue_receipt(receipt_payload)
    return {
        "schemaVersion": "jstack.ui.finalization.v1",
        "projectPath": str(project_path),
        "baseline": baseline,
        "candidate": {
            key: candidate_after[key]
            for key in (
                "gitHead", "treeSha256", "projectFingerprint", "changedPathsSha256",
                "changeRecordsSha256", "diffSha256"
            )
        },
        "catalog": contract["catalog"],
        "contract": {
            "sha256": contract["contractSha256"],
            "defaultProfile": contract["profileResolution"]["defaultProfile"],
            "surfaceCount": len(contract["surfaces"]),
            "matrixCellCount": len(contract["evidenceMatrix"]),
        },
        "evidence": evidence_first,
        "passed": True,
        "blockers": [],
        "warnings": [] if evidence_first["humanAestheticApprovalProvided"] else [
            "Independent human aesthetic approval was not supplied; it remains optional and is not implied."
        ],
        "uiReceipt": final_receipt,
        "executionAuthorized": False,
        "limitations": [
            "JStack verified bounded evidence bytes, matrix coverage, objective result records, Git/build bindings, and accountable observation digests.",
            "Screenshot hashes do not independently prove that the producer displayed the declared route or that its visual judgment was honest.",
            "This receipt does not replace QA, security, audit, launch assurance, release approval, rollback, monitoring, or deployment evidence and authorizes no action.",
        ],
    }


def tool_launch_assess(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    base_ref = str(args.get("base_ref") or "").strip()
    if not base_ref:
        raise ToolError(
            "Launch assessment requires an explicit base_ref; automatic discovery is not a release evidence boundary."
        )
    subject = evidence_subject(project_path, base_ref)
    if subject["baseCommit"] == subject["gitHead"]:
        raise ToolError(
            "Launch base_ref must resolve to a distinct pre-release commit; HEAD cannot be its own baseline."
        )
    if not subject["clean"]:
        raise ToolError(
            "Launch assessment requires a clean committed working tree so evidence can bind an exact release candidate."
        )
    raw_surfaces = args.get("surfaces")
    if not isinstance(raw_surfaces, list):
        raise ToolError("surfaces must be an explicit array that includes 'core'.")
    surfaces = _launch_call(lambda: launch_core.normalize_surfaces(raw_surfaces))
    risk_tier = _launch_call(
        lambda: launch_core.normalize_risk_tier(args.get("risk_tier"))
    )
    deployment_fingerprint = _launch_call(
        lambda: launch_core.normalize_deployment_fingerprint(
            args.get("deployment_fingerprint")
        )
    )
    target_environment = _launch_environment(args.get("target_environment"))
    target_url = _launch_target_url(
        args.get("target_url"),
        surfaces,
        target_environment,
    )
    profile_owner = _launch_safe_text(
        args.get("profile_owner"),
        "profile_owner",
        maximum=200,
    )
    raw_reference = args.get("profile_reference")
    if target_environment == "production":
        profile_reference = _launch_safe_text(
            raw_reference,
            "profile_reference",
            maximum=500,
        )
    else:
        profile_reference = (
            _launch_safe_text(
                raw_reference,
                "profile_reference",
                maximum=500,
            )
            if str(raw_reference or "").strip()
            else "not-required-for-non-production"
        )
    detection = _launch_surface_detection(project_path)
    reconciled = _launch_call(
        lambda: launch_core.reconcile_surface_hints(
            detection["hints"],
            surfaces,
            _launch_reconciliation_input(args.get("surface_reconciliation")),
            profile_owner=profile_owner,
        )
    )
    policy, selection = _launch_selection(
        project_path,
        surfaces,
        target_environment,
        target_url,
        risk_tier,
        deployment_fingerprint,
        reconciled["hintDigest"],
        reconciled["reconciliationDigest"],
    )
    if policy.get("launch", {}).get("requireProfileDeclaration") and not profile_owner:
        raise ToolError("Launch policy requires an accountable profile owner.")
    if reconciled["unresolvedHints"]:
        return {
            "schemaVersion": "jstack.launch.assessment.v2",
            "projectPath": str(project_path),
            "baseRef": subject["baseRef"],
            "targetEnvironment": target_environment,
            "targetUrl": target_url,
            "riskTier": selection["riskTier"],
            "derivedRiskFloor": selection["derivedRiskFloor"],
            "deploymentFingerprint": deployment_fingerprint,
            "profile": {
                "owner": profile_owner,
                "surfaces": selection["surfaces"],
                "declarationIsInference": False,
            },
            "surfaceDetection": detection,
            "surfaceReconciliation": reconciled["records"],
            "readyToCollect": False,
            "blockers": [
                "Detected surface hint requires inclusion or an accountable not-applicable reconciliation: "
                + str(hint["surface"])
                for hint in reconciled["unresolvedHints"]
            ],
            "launchSessionToken": None,
            "executionAuthorized": False,
        }
    expires = (
        _dt.datetime.now(_dt.timezone.utc).replace(microsecond=0)
        + _dt.timedelta(seconds=LAUNCH_SESSION_MAX_AGE_SECONDS)
    ).isoformat()
    selected_contract = _launch_selected_contract(selection)
    token = issue_receipt(
        {
            "kind": "launch-session",
            "schemaVersion": "jstack.launch.session.v2",
            "projectPath": subject["gitRoot"],
            "gitHead": subject["gitHead"],
            "projectFingerprint": subject["projectFingerprint"],
            "baseRef": subject["baseRef"],
            "baseCommit": subject["baseCommit"],
            "policyDigest": subject["policyDigest"],
            "toolVersion": SERVER_VERSION,
            "catalogVersion": selection["catalogVersion"],
            "catalogDigest": selection["catalogDigest"],
            "selectionDigest": selection["selectionDigest"],
            "surfaces": selection["surfaces"],
            "riskTier": selection["riskTier"],
            "derivedRiskFloor": selection["derivedRiskFloor"],
            "policyRiskFloor": selection["policyRiskFloor"],
            "deploymentFingerprint": selection["deploymentFingerprint"],
            "surfaceHintDigest": reconciled["hintDigest"],
            "surfaceReconciliationDigest": reconciled[
                "reconciliationDigest"
            ],
            "surfaceReconciliation": reconciled["records"],
            "targetEnvironment": target_environment,
            "targetUrl": target_url,
            "selectedControls": selected_contract,
            "profileOwner": profile_owner,
            "profileReferenceDigest": hashlib.sha256(
                profile_reference.encode("utf-8")
            ).hexdigest(),
            "expiresAt": expires,
            "passed": False,
        }
    )
    return {
        "schemaVersion": "jstack.launch.assessment.v2",
        "projectPath": str(project_path),
        "baseRef": subject["baseRef"],
        "targetEnvironment": target_environment,
        "targetUrl": target_url,
        "riskTier": selection["riskTier"],
        "derivedRiskFloor": selection["derivedRiskFloor"],
        "policyRiskFloor": selection["policyRiskFloor"],
        "deploymentFingerprint": selection["deploymentFingerprint"],
        "profile": {
            "owner": profile_owner,
            "referenceDigest": hashlib.sha256(
                profile_reference.encode("utf-8")
            ).hexdigest(),
            "surfaces": selection["surfaces"],
            "declarationIsInference": False,
        },
        "surfaceDetection": detection,
        "surfaceReconciliation": reconciled["records"],
        "catalog": {
            "schemaVersion": launch_core.CATALOG_SCHEMA_VERSION,
            "version": selection["catalogVersion"],
            "digest": selection["catalogDigest"],
            "sourceProvenance": launch_core.load_catalog()["sourceProvenance"],
        },
        "selection": selection,
        "launchSessionToken": token,
        "expiresAt": expires,
        "readyToCollect": True,
        "executionAuthorized": False,
        "evidenceContract": {
            "statuses": list(launch_core.FINAL_STATUSES),
            "evidenceKinds": list(launch_core.EVIDENCE_KINDS),
            "artifactFormats": list(launch_core.ARTIFACT_FORMATS),
            "artifactRoots": [str(project_path), "~/.jstack/evidence"],
            "artifactMaximumBytes": LAUNCH_MAX_ARTIFACT_BYTES,
            "rawArtifactContentReturned": False,
            "semanticTruthCertified": False,
            "outcomesDerivedByJStack": True,
            "proseOrArbitraryFilesAccepted": False,
        },
        "actionSafety": {
            "assessmentIsNotExecution": True,
            "mode": "host-native",
            "customApprovalProtocol": False,
        },
    }


def tool_launch_evidence_register(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    session_token = str(args.get("launch_session_token") or "").strip()
    session, subject, policy, selection = _launch_session_payload(
        project_path,
        session_token,
    )
    control_id = str(args.get("control_id") or "").strip()
    selected = {
        str(control["id"]): control for control in selection["selectedControls"]
    }
    if control_id not in selected:
        raise ToolError(
            "control_id is not selected by the current launch applicability contract."
        )
    control = selected[control_id]
    requirement_id = str(args.get("requirement_id") or "").strip()
    requirements = {
        str(requirement["id"]): requirement
        for requirement in control["activeEvidenceRequirements"]
    }
    if requirement_id not in requirements:
        raise ToolError(
            "requirement_id is not active for this control and launch risk tier."
        )
    requirement = requirements[requirement_id]
    evidence_kind = str(args.get("evidence_kind") or "").strip()
    if evidence_kind not in requirement["evidenceKinds"]:
        raise ToolError(
            "evidence_kind is not permitted for this evidence requirement; use one of: "
            + ", ".join(requirement["evidenceKinds"])
        )
    artifact_format = str(args.get("artifact_format") or "").strip()
    if artifact_format not in requirement["artifactFormats"]:
        raise ToolError(
            "artifact_format is not permitted for this evidence requirement; use one of: "
            + ", ".join(requirement["artifactFormats"])
        )
    source_reference = _launch_safe_text(
        args.get("source_reference"),
        "source_reference",
        maximum=500,
    )
    artifact_root, artifact_relative, artifact, artifact_root_kind = (
        _launch_artifact_path(
            project_path,
            str(args.get("artifact_path") or ""),
        )
    )
    artifact_size, artifact_digest = _launch_file_digest(
        artifact_root,
        artifact_relative,
    )
    try:
        artifact_content = audit_core.read_repository_file(
            artifact_root,
            artifact_relative,
            max_bytes=LAUNCH_MAX_ARTIFACT_BYTES,
            max_seconds=LAUNCH_ARTIFACT_TIMEOUT_SECONDS,
        )
    except audit_core.AuditError as exc:
        raise ToolError(
            "Launch evidence artifact could not be read with stable bounded identity."
        ) from exc
    if (
        len(artifact_content) != artifact_size
        or hashlib.sha256(artifact_content).hexdigest() != artifact_digest
    ):
        raise ToolError("Launch evidence artifact changed while it was being evaluated.")
    expected_target = {
        "gitHead": subject["gitHead"],
        "targetEnvironment": session["targetEnvironment"],
        "deploymentFingerprint": session["deploymentFingerprint"],
    }
    try:
        normalized = launch_core.parse_artifact_bytes(
            artifact_content,
            artifact_format=artifact_format,
            control_id=control_id,
            requirement_id=requirement_id,
            expected_target=expected_target,
        )
        evaluation = launch_core.evaluate_requirement(
            normalized,
            requirement,
        )
    except launch_core.EvidenceError as exc:
        raise ToolError(str(exc)) from exc
    if requirement["independent"] and not evaluation["producerIndependent"]:
        raise ToolError(
            "This evidence requirement requires an independent producer."
        )
    outcome = str(evaluation["derivedOutcome"])
    if outcome == "not-applicable" and not control["allowNotApplicable"]:
        raise ToolError(
            "This selected launch control does not permit a not-applicable outcome."
        )
    max_age_minutes = min(
        int(control["maxAgeMinutes"]),
        int(policy.get("launch", {}).get("maxEvidenceAgeMinutes", 1440)),
    )
    observed, expires = _launch_observed_at(
        evaluation["observedAt"],
        max_age_minutes=max_age_minutes,
    )
    session_digest = hashlib.sha256(session_token.encode("utf-8")).hexdigest()
    receipt = issue_receipt(
        {
            "kind": "launch-evidence",
            "schemaVersion": "jstack.launch.evidence.v2",
            "projectPath": subject["gitRoot"],
            "gitHead": subject["gitHead"],
            "projectFingerprint": subject["projectFingerprint"],
            "baseCommit": subject["baseCommit"],
            "policyDigest": subject["policyDigest"],
            "toolVersion": SERVER_VERSION,
            "catalogVersion": selection["catalogVersion"],
            "catalogDigest": selection["catalogDigest"],
            "selectionDigest": selection["selectionDigest"],
            "launchSessionDigest": session_digest,
            "riskTier": selection["riskTier"],
            "deploymentFingerprint": selection["deploymentFingerprint"],
            "controlId": control_id,
            "requirementId": requirement_id,
            "category": control["category"],
            "gateLevel": control["effectiveGateLevel"],
            "evidenceKind": evidence_kind,
            "artifactFormat": artifact_format,
            "derivedOutcome": outcome,
            "machineEvaluated": evaluation["machineEvaluated"],
            "producerFingerprint": evaluation["producerFingerprint"],
            "producerIndependent": evaluation["producerIndependent"],
            "semanticDigest": evaluation["semanticDigest"],
            "assertionCount": evaluation["assertionCount"],
            "requiredAssertionCount": evaluation["requiredAssertionCount"],
            "observationCount": evaluation["observationCount"],
            "complete": evaluation["complete"],
            "truncated": evaluation["truncated"],
            "findingCounts": evaluation["findingCounts"],
            "sourceReferenceDigest": hashlib.sha256(
                source_reference.encode("utf-8")
            ).hexdigest(),
            "artifactSha256": artifact_digest,
            "artifactSize": artifact_size,
            "artifactPathDigest": hashlib.sha256(
                str(artifact).encode("utf-8")
            ).hexdigest(),
            "artifactRootKind": artifact_root_kind,
            "observedAt": observed.isoformat(),
            "expiresAt": expires.isoformat(),
            "passed": outcome == "pass",
        }
    )
    return {
        "schemaVersion": "jstack.launch.evidence-registration.v2",
        "control": {
            "id": control_id,
            "requirementId": requirement_id,
            "category": control["category"],
            "gateLevel": control["effectiveGateLevel"],
            "evidenceKind": evidence_kind,
            "artifactFormat": artifact_format,
            "derivedOutcome": outcome,
            "machineEvaluated": evaluation["machineEvaluated"],
        },
        "artifact": {
            "sha256": artifact_digest,
            "size": artifact_size,
            "pathDigest": hashlib.sha256(str(artifact).encode("utf-8")).hexdigest(),
            "rootKind": artifact_root_kind,
            "contentReturned": False,
        },
        "observedAt": observed.isoformat(),
        "expiresAt": expires.isoformat(),
        "launchEvidenceReceipt": receipt,
        "executionAuthorized": False,
        "attestationLimit": (
            "JStack parsed the bounded artifact, derived its outcome from the selected "
            "assertion contract, and bound it to the exact Git/environment/deployment "
            "target. JStack does not certify producer honesty, legal conclusions, or "
            "facts that the evidence source did not independently observe."
        ),
    }


def _launch_waivers(
    values: Any,
    *,
    selected: dict[str, dict[str, Any]],
    policy: dict[str, Any],
    risk_tier: str,
) -> dict[str, dict[str, Any]]:
    if values is None:
        return {}
    if not isinstance(values, list) or len(values) > LAUNCH_MAX_RECEIPTS:
        raise ToolError(
            f"waivers must be an array of at most {LAUNCH_MAX_RECEIPTS} records."
        )
    if values and not policy.get("launch", {}).get("allowWaivers", True):
        raise ToolError("Enterprise launch policy disables waivers.")
    if values and risk_tier == "critical":
        raise ToolError("Critical-risk launch controls may not be waived.")
    expected_fields = {
        "control_id",
        "owner",
        "reason",
        "approval_reference",
        "expires_at",
        "compensating_control",
        "residual_risk",
    }
    now = _dt.datetime.now(_dt.timezone.utc)
    result: dict[str, dict[str, Any]] = {}
    for index, raw in enumerate(values):
        if not isinstance(raw, dict) or set(raw) != expected_fields:
            raise ToolError(
                f"waivers[{index}] must contain exactly control_id, owner, reason, approval_reference, expires_at, compensating_control, and residual_risk."
            )
        control_id = str(raw.get("control_id") or "").strip()
        if control_id not in selected:
            raise ToolError(f"waivers[{index}].control_id is not selected.")
        if control_id in result:
            raise ToolError(f"Duplicate waiver for launch control: {control_id}")
        control = selected[control_id]
        if (
            risk_tier in {"high", "critical"}
            and control["category"] == "security"
        ):
            raise ToolError(
                f"High- and critical-risk security control '{control_id}' may not be waived."
            )
        if control["effectiveGateLevel"] == "blocker" or not control["waivable"]:
            raise ToolError(f"Launch control '{control_id}' may not be waived.")
        owner = _launch_safe_text(raw.get("owner"), f"waivers[{index}].owner", maximum=200)
        reason = _launch_safe_text(
            raw.get("reason"),
            f"waivers[{index}].reason",
            minimum=10,
            maximum=1_000,
        )
        reference = _launch_safe_text(
            raw.get("approval_reference"),
            f"waivers[{index}].approval_reference",
            maximum=500,
        )
        compensating = _launch_safe_text(
            raw.get("compensating_control"),
            f"waivers[{index}].compensating_control",
            minimum=10,
            maximum=1_000,
        )
        residual = _launch_safe_text(
            raw.get("residual_risk"),
            f"waivers[{index}].residual_risk",
            minimum=10,
            maximum=1_000,
        )
        try:
            expires = _dt.datetime.fromisoformat(
                str(raw.get("expires_at") or "").replace("Z", "+00:00")
            )
        except ValueError as exc:
            raise ToolError(
                f"waivers[{index}].expires_at must be an ISO-8601 timestamp with timezone."
            ) from exc
        if expires.tzinfo is None:
            raise ToolError(f"waivers[{index}].expires_at must include a timezone.")
        expires = expires.astimezone(_dt.timezone.utc)
        if not now < expires <= now + _dt.timedelta(days=30):
            raise ToolError(
                f"waivers[{index}].expires_at must be in the future and no more than 30 days away."
            )
        record_subject = {
            "controlId": control_id,
            "owner": owner,
            "reason": reason,
            "approvalReference": reference,
            "expiresAt": expires.replace(microsecond=0).isoformat(),
            "compensatingControl": compensating,
            "residualRisk": residual,
        }
        result[control_id] = {
            "controlId": control_id,
            "owner": owner,
            "expiresAt": record_subject["expiresAt"],
            "recordDigest": hashlib.sha256(
                json.dumps(
                    record_subject,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest(),
        }
    return result


def tool_launch_finalize(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    session_token = str(args.get("launch_session_token") or "").strip()
    session, subject, policy, selection = _launch_session_payload(
        project_path,
        session_token,
    )
    raw_receipts = args.get("evidence_receipts")
    if not isinstance(raw_receipts, list) or len(raw_receipts) > LAUNCH_MAX_RECEIPTS:
        raise ToolError(
            f"evidence_receipts must be an array of at most {LAUNCH_MAX_RECEIPTS} receipts."
        )
    if any(
        not isinstance(receipt, str)
        or not receipt
        or len(receipt) > LAUNCH_MAX_RECEIPT_CHARS
        for receipt in raw_receipts
    ):
        raise ToolError("Each launch evidence receipt must be a bounded non-empty string.")
    if len(raw_receipts) != len(set(raw_receipts)):
        raise ToolError("evidence_receipts must not contain duplicate receipt values.")
    selected = {
        str(control["id"]): control for control in selection["selectedControls"]
    }
    requirements_by_control = {
        control_id: {
            str(requirement["id"]): requirement
            for requirement in control["activeEvidenceRequirements"]
        }
        for control_id, control in selected.items()
    }
    waivers = _launch_waivers(
        args.get("waivers"),
        selected=selected,
        policy=policy,
        risk_tier=selection["riskTier"],
    )
    evidence_by_requirement: dict[
        tuple[str, str],
        list[tuple[dict[str, Any], str]],
    ] = {}
    receipt_verification: list[dict[str, Any]] = []
    blockers: list[str] = []
    warnings: list[str] = []
    session_digest = hashlib.sha256(session_token.encode("utf-8")).hexdigest()
    now = _dt.datetime.now(_dt.timezone.utc)
    evidence_expiries: list[_dt.datetime] = []
    seen_semantic_evidence: set[tuple[str, str, str]] = set()
    for index, receipt in enumerate(raw_receipts):
        try:
            verification = verify_receipt(
                receipt,
                "launch-evidence",
                subject,
                expected_subject=subject,
                require_passed=False,
            )
        except ToolError:
            blockers.append(f"Launch evidence receipt {index + 1} is malformed or unsigned.")
            continue
        payload = verification["payload"]
        control_id = str(payload.get("controlId") or "")
        requirement_id = str(payload.get("requirementId") or "")
        control = selected.get(control_id)
        requirement = requirements_by_control.get(control_id, {}).get(requirement_id)
        contract_checks = {
            "receipt": verification["valid"],
            "schemaVersion": payload.get("schemaVersion")
            == "jstack.launch.evidence.v2",
            "selectedControl": control is not None,
            "selectedRequirement": requirement is not None,
            "catalogVersion": payload.get("catalogVersion")
            == selection["catalogVersion"],
            "catalogDigest": payload.get("catalogDigest")
            == selection["catalogDigest"],
            "selectionDigest": payload.get("selectionDigest")
            == selection["selectionDigest"],
            "session": payload.get("launchSessionDigest") == session_digest,
            "riskTier": payload.get("riskTier") == selection["riskTier"],
            "deploymentFingerprint": payload.get("deploymentFingerprint")
            == selection["deploymentFingerprint"],
        }
        if control is not None and requirement is not None:
            contract_checks.update(
                {
                    "category": payload.get("category") == control["category"],
                    "gateLevel": payload.get("gateLevel")
                    == control["effectiveGateLevel"],
                    "evidenceKind": payload.get("evidenceKind")
                    in requirement["evidenceKinds"],
                    "artifactFormat": payload.get("artifactFormat")
                    in requirement["artifactFormats"],
                    "outcome": payload.get("derivedOutcome")
                    in {"pass", "fail", "incomplete", "not-applicable"},
                    "notApplicableAllowed": payload.get("derivedOutcome")
                    != "not-applicable"
                    or control["allowNotApplicable"],
                    "machineEvaluation": payload.get("machineEvaluated")
                    is requirement["machineVerifiable"],
                    "independence": not requirement["independent"]
                    or payload.get("producerIndependent") is True,
                }
            )
        contract_checks["artifactIdentity"] = bool(
            isinstance(payload.get("artifactSha256"), str)
            and re.fullmatch(r"[0-9a-f]{64}", payload["artifactSha256"])
            and isinstance(payload.get("artifactSize"), int)
            and not isinstance(payload.get("artifactSize"), bool)
            and 0 <= payload["artifactSize"] <= LAUNCH_MAX_ARTIFACT_BYTES
        )
        contract_checks["semanticIdentity"] = bool(
            isinstance(payload.get("semanticDigest"), str)
            and re.fullmatch(r"[0-9a-f]{64}", payload["semanticDigest"])
            and isinstance(payload.get("producerFingerprint"), str)
            and re.fullmatch(r"[0-9a-f]{64}", payload["producerFingerprint"])
            and isinstance(payload.get("observationCount"), int)
            and not isinstance(payload.get("observationCount"), bool)
            and payload["observationCount"] >= 0
            and isinstance(payload.get("complete"), bool)
            and isinstance(payload.get("truncated"), bool)
        )
        valid = all(contract_checks.values())
        receipt_verification.append(
            {
                "index": index,
                "controlId": control_id or None,
                "requirementId": requirement_id or None,
                "valid": valid,
                "checks": contract_checks,
            }
        )
        if not valid:
            blockers.append(
                f"Launch evidence receipt {index + 1} does not match the current v2 launch contract."
            )
            continue
        semantic_key = (
            control_id,
            requirement_id,
            str(payload["semanticDigest"]),
        )
        if semantic_key in seen_semantic_evidence:
            blockers.append(
                f"Duplicate semantic evidence targets '{control_id}/{requirement_id}'."
            )
            continue
        seen_semantic_evidence.add(semantic_key)
        receipt_digest = hashlib.sha256(receipt.encode("utf-8")).hexdigest()
        evidence_by_requirement.setdefault(
            (control_id, requirement_id),
            [],
        ).append((payload, receipt_digest))
        try:
            evidence_expiry = _dt.datetime.fromisoformat(str(payload["expiresAt"]))
            if evidence_expiry.tzinfo is None:
                raise ValueError("timezone")
            evidence_expiries.append(evidence_expiry.astimezone(_dt.timezone.utc))
        except (KeyError, ValueError):
            blockers.append(
                f"Launch evidence for '{control_id}/{requirement_id}' has no valid expiry."
            )

    control_results: list[dict[str, Any]] = []
    for control in selection["selectedControls"]:
        control_id = str(control["id"])
        gate_level = str(control["effectiveGateLevel"])
        waiver = waivers.get(control_id)
        if waiver:
            control_results.append(
                {
                    "controlId": control_id,
                    "sequence": control["sequence"],
                    "category": control["category"],
                    "gateLevel": gate_level,
                    "status": "waived",
                    "evidenceReceiptDigests": [],
                    "requirementResults": [],
                    "waiverDigest": waiver["recordDigest"],
                }
            )
            continue
        requirement_results: list[dict[str, Any]] = []
        requirement_statuses: list[str] = []
        control_evidence_digests: list[str] = []
        passing_producers_by_requirement: dict[str, set[str]] = {}
        for requirement in control["activeEvidenceRequirements"]:
            requirement_id = str(requirement["id"])
            records = evidence_by_requirement.get(
                (control_id, requirement_id),
                [],
            )
            receipt_digests = sorted(record[1] for record in records)
            control_evidence_digests.extend(receipt_digests)
            outcomes = [str(record[0]["derivedOutcome"]) for record in records]
            pass_count = outcomes.count("pass")
            producers = {
                str(record[0]["producerFingerprint"])
                for record in records
                if record[0].get("derivedOutcome") == "pass"
            }
            passing_producers_by_requirement[requirement_id] = producers
            independent_passes = [
                record
                for record in records
                if record[0].get("derivedOutcome") == "pass"
                and record[0].get("producerIndependent") is True
            ]
            if not records:
                requirement_status = "incomplete"
                detail = "no current evidence"
            elif "fail" in outcomes:
                requirement_status = "fail"
                detail = "at least one structured evidence result failed"
                if len(set(outcomes)) > 1:
                    blockers.append(
                        f"Contradictory evidence targets '{control_id}/{requirement_id}'."
                    )
            elif "incomplete" in outcomes:
                requirement_status = "incomplete"
                detail = "at least one evidence result is incomplete or truncated"
            elif "not-applicable" in outcomes and "pass" in outcomes:
                requirement_status = "incomplete"
                detail = "pass and not-applicable outcomes conflict"
            elif outcomes and set(outcomes) == {"not-applicable"}:
                requirement_status = (
                    "not-applicable"
                    if control["allowNotApplicable"]
                    else "fail"
                )
                detail = (
                    "accountable not-applicable evidence"
                    if control["allowNotApplicable"]
                    else "not-applicable is forbidden for this control"
                )
            elif pass_count < int(requirement["minimumCount"]):
                requirement_status = "incomplete"
                detail = "minimum evidence count is not met"
            elif len(producers) < int(requirement["minimumDistinctProducers"]):
                requirement_status = "incomplete"
                detail = "minimum distinct producer count is not met"
            elif requirement["independent"] and not independent_passes:
                requirement_status = "incomplete"
                detail = "independent producer evidence is absent"
            else:
                requirement_status = "pass"
                detail = "structured requirement contract passed"
            requirement_statuses.append(requirement_status)
            requirement_results.append(
                {
                    "requirementId": requirement_id,
                    "status": requirement_status,
                    "evidenceCount": len(records),
                    "passingEvidenceCount": pass_count,
                    "distinctProducerCount": len(producers),
                    "independentEvidencePresent": bool(independent_passes),
                    "evidenceReceiptDigests": receipt_digests,
                    "detail": detail,
                }
            )
        if (
            selection["riskTier"] == "critical"
            and control_id == "security-final-independent-scan"
        ):
            scanner_producers = passing_producers_by_requirement.get(
                "independent-security-scan",
                set(),
            )
            human_producers = passing_producers_by_requirement.get(
                "critical-human-security-review",
                set(),
            )
            if scanner_producers & human_producers:
                for result in requirement_results:
                    if (
                        result["requirementId"]
                        == "critical-human-security-review"
                    ):
                        result["status"] = "incomplete"
                        result["detail"] = (
                            "critical human review must use a producer distinct "
                            "from the independent scanner"
                        )
                blockers.append(
                    "Critical security review and scanner evidence must come "
                    "from distinct producers."
                )
                requirement_statuses = [
                    str(result["status"])
                    for result in requirement_results
                ]
        if "fail" in requirement_statuses:
            status = "fail"
        elif "incomplete" in requirement_statuses:
            status = "incomplete"
        elif "not-applicable" in requirement_statuses and "pass" in requirement_statuses:
            status = "incomplete"
        elif requirement_statuses and set(requirement_statuses) == {"not-applicable"}:
            status = "not-applicable"
        elif requirement_statuses and set(requirement_statuses) == {"pass"}:
            status = "pass"
        else:
            status = "incomplete"
        if status in {"fail", "incomplete"}:
            message = f"Launch control '{control_id}' has derived outcome '{status}'."
            if gate_level in {"blocker", "required"}:
                blockers.append(message)
            else:
                warnings.append(message)
        control_results.append(
            {
                "controlId": control_id,
                "sequence": control["sequence"],
                "category": control["category"],
                "gateLevel": gate_level,
                "status": status,
                "evidenceReceiptDigests": sorted(set(control_evidence_digests)),
                "requirementResults": requirement_results,
                "waiverDigest": None,
            }
        )

    blockers = list(dict.fromkeys(blockers))
    warnings = list(dict.fromkeys(warnings))
    ready = not blockers
    expiry_candidates = [
        now + _dt.timedelta(seconds=LAUNCH_RECEIPT_MAX_AGE_SECONDS),
        *evidence_expiries,
        *(
            _dt.datetime.fromisoformat(waiver["expiresAt"])
            for waiver in waivers.values()
        ),
    ]
    expires = min(expiry_candidates).astimezone(_dt.timezone.utc).replace(
        microsecond=0
    )
    launch_receipt = issue_receipt(
        {
            "kind": "launch",
            "schemaVersion": "jstack.launch.receipt.v2",
            "projectPath": subject["gitRoot"],
            "gitHead": subject["gitHead"],
            "projectFingerprint": subject["projectFingerprint"],
            "baseRef": subject["baseRef"],
            "baseCommit": subject["baseCommit"],
            "policyDigest": subject["policyDigest"],
            "toolVersion": SERVER_VERSION,
            "catalogVersion": selection["catalogVersion"],
            "catalogDigest": selection["catalogDigest"],
            "selectionDigest": selection["selectionDigest"],
            "riskTier": selection["riskTier"],
            "derivedRiskFloor": selection["derivedRiskFloor"],
            "policyRiskFloor": selection["policyRiskFloor"],
            "deploymentFingerprint": selection["deploymentFingerprint"],
            "surfaceHintDigest": selection["surfaceHintDigest"],
            "surfaceReconciliationDigest": selection[
                "surfaceReconciliationDigest"
            ],
            "targetEnvironment": session["targetEnvironment"],
            "targetUrl": session.get("targetUrl"),
            "surfaces": selection["surfaces"],
            "profileOwner": session["profileOwner"],
            "profileReferenceDigest": session["profileReferenceDigest"],
            "controlResults": control_results,
            "activeWaivers": list(waivers.values()),
            "complete": ready,
            "passed": ready,
            "expiresAt": expires.isoformat(),
        }
    )
    return {
        "schemaVersion": "jstack.launch.finalization.v2",
        "projectPath": str(project_path),
        "targetEnvironment": session["targetEnvironment"],
        "targetUrl": session.get("targetUrl"),
        "surfaces": selection["surfaces"],
        "riskTier": selection["riskTier"],
        "derivedRiskFloor": selection["derivedRiskFloor"],
        "deploymentFingerprint": selection["deploymentFingerprint"],
        "ready": ready,
        "complete": ready,
        "passed": ready,
        "executionAuthorized": False,
        "blockers": blockers,
        "warnings": warnings,
        "controlResults": control_results,
        "waivers": list(waivers.values()),
        "receiptVerification": receipt_verification,
        "launchReceipt": launch_receipt,
        "expiresAt": expires.isoformat(),
        "attestationLimit": (
            "The receipt proves that JStack parsed current target-bound evidence and "
            "derived every control status from the catalogued assertion contract. It "
            "does not certify producer honesty, facts outside the observed scope, or "
            "jurisdiction-dependent legal conclusions."
        ),
        "actionSafety": {
            "launchReadyIsNotExecution": True,
            "mode": "host-native",
            "customApprovalProtocol": False,
        },
    }


def tool_release_readiness(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    base_ref = str(args.get("base_ref") or "").strip()
    target_environment = _launch_environment(args.get("target_environment"))
    explicit_release_requested = bool(args.get("explicit_release_requested") or False)
    rollback_plan = str(args.get("rollback_plan") or "").strip()
    monitoring_plan = str(args.get("monitoring_plan") or "").strip()
    canary_plan = str(args.get("canary_plan") or "").strip()
    approved_by = str(args.get("approved_by") or "").strip()
    approval_reference = str(args.get("approval_reference") or "").strip()
    security_reviewed_by = str(args.get("security_reviewed_by") or "").strip()
    preflight_args = dict(args)
    preflight_args["strict"] = True
    preflight_args["target_environment"] = target_environment
    preflight_args["explicit_release_requested"] = explicit_release_requested
    preflight = tool_preflight(preflight_args)
    ship = tool_ship_check(
        {
            "project_path": str(project_path),
            "base_ref": base_ref,
            "qa_receipts": args.get("qa_receipts") or [],
        }
    )
    blockers = list(preflight["blockers"]) + list(ship["blockers"])
    warnings = list(preflight["warnings"])
    subject = evidence_subject(project_path, base_ref or None)
    if not base_ref:
        blockers.append("Release readiness requires an explicit base_ref; automatic upstream discovery is not an approval boundary.")
    elif subject["baseCommit"] == subject["gitHead"]:
        blockers.append("Release base_ref must resolve to a distinct pre-release commit; HEAD cannot be its own baseline.")
    if not subject["clean"]:
        blockers.append("Release readiness requires a clean committed working tree; commit or remove local changes, then rerun all evidence checks.")

    qa_receipts = args.get("qa_receipts") or []
    if not isinstance(qa_receipts, list) or not all(isinstance(item, str) for item in qa_receipts):
        raise ToolError("qa_receipts must be an array of receipts returned by jstack_qa.")
    required_commands = discover_test_commands(project_path)
    verified_qa: list[dict[str, Any]] = []
    receipt_by_key: dict[str, dict[str, Any]] = {}
    for receipt in qa_receipts:
        verification = verify_receipt(receipt, "qa", subject, expected_subject=subject)
        verified_qa.append(verification)
        payload = verification["payload"]
        command_key = str(payload.get("commandKey") or "")
        if verification["valid"] and command_key:
            receipt_by_key[command_key] = payload
    for command in required_commands:
        payload = receipt_by_key.get(command["key"])
        if not payload:
            blockers.append(f"Missing a current passing QA receipt for discovered command '{command['key']}'.")
        elif payload.get("commandFingerprint") != command["commandFingerprint"]:
            blockers.append(f"QA receipt for '{command['key']}' does not match the currently discovered command definition.")
    if not required_commands:
        blockers.append("No test/lint/typecheck/build commands were discovered; release readiness cannot be established.")

    security_receipt = str(args.get("security_receipt") or "").strip()
    if not security_receipt and preflight.get("securitySummary"):
        security_receipt = str(preflight["securitySummary"].get("evidenceReceipt") or "")
    verified_security: Optional[dict[str, Any]] = None
    if security_receipt:
        verified_security = verify_receipt(security_receipt, "security", subject, expected_subject=subject)
        if not verified_security["valid"]:
            blockers.append("Security evidence receipt is not a current, complete, clean result for this commit and project state.")
    else:
        blockers.append("Release readiness requires a current security evidence receipt.")

    enterprise_policy = load_enterprise_policy(project_path)
    launch_policy = enterprise_policy.get("launch", {})
    launch_required = bool(
        target_environment == "production"
        and launch_policy.get("requireReceiptForProduction", True)
    )
    launch_receipt = str(args.get("launch_receipt") or "").strip()
    verified_launch: Optional[dict[str, Any]] = None
    launch_passes_release = False
    release_audit_surfaces: list[str] = []
    if launch_receipt:
        if len(launch_receipt) > LAUNCH_MAX_RECEIPT_CHARS:
            raise ToolError("launch_receipt exceeds the bounded receipt size.")
        verified_launch = verify_receipt(
            launch_receipt,
            "launch",
            subject,
            expected_subject=subject,
            require_passed=False,
        )
        launch_payload = verified_launch.get("payload") or {}
        try:
            current_detection = _launch_surface_detection(project_path)
            _, receipt_selection = _launch_selection(
                project_path,
                list(launch_payload.get("surfaces") or []),
                str(launch_payload.get("targetEnvironment") or ""),
                launch_payload.get("targetUrl"),
                str(launch_payload.get("riskTier") or ""),
                str(launch_payload.get("deploymentFingerprint") or ""),
                current_detection["hintDigest"],
                str(
                    launch_payload.get("surfaceReconciliationDigest")
                    or ""
                ),
            )
            launch_contract_current = (
                launch_payload.get("catalogVersion")
                == receipt_selection["catalogVersion"]
                and launch_payload.get("catalogDigest")
                == receipt_selection["catalogDigest"]
                and launch_payload.get("selectionDigest")
                == receipt_selection["selectionDigest"]
                and launch_payload.get("surfaces")
                == receipt_selection["surfaces"]
                and launch_payload.get("riskTier")
                == receipt_selection["riskTier"]
                and launch_payload.get("deploymentFingerprint")
                == receipt_selection["deploymentFingerprint"]
                and launch_payload.get("surfaceHintDigest")
                == current_detection["hintDigest"]
            )
        except ToolError:
            receipt_selection = None
            launch_contract_current = False
        launch_passes_release = (
            verified_launch["valid"]
            and launch_payload.get("schemaVersion")
            == "jstack.launch.receipt.v2"
            and launch_payload.get("complete") is True
            and launch_payload.get("passed") is True
            and launch_payload.get("targetEnvironment") == target_environment
            and launch_contract_current
        )
        if launch_required and not launch_passes_release:
            blockers.append(
                "Production release requires a current complete passing launch-assurance receipt for this exact release candidate and environment."
            )
        elif not launch_passes_release:
            warnings.append(
                "An optional launch-assurance receipt was supplied but is not current, complete, passing, or environment-matched."
            )
        if launch_passes_release and receipt_selection is not None:
            release_audit_surfaces = sorted(
                set(receipt_selection["surfaces"])
                & set(
                    launch_policy.get("requireReleaseAuditForSurfaces", [])
                )
            )
    elif launch_required:
        blockers.append(
            "Production release requires a current complete passing launch-assurance receipt from jstack_launch_finalize."
        )

    audit_policy = enterprise_policy.get("audit", {})
    audit_required = bool(
        audit_policy.get("releaseRequiresAuditReceipt")
        or release_audit_surfaces
    )
    audit_receipt = str(args.get("audit_receipt") or "").strip()
    verified_audit: Optional[dict[str, Any]] = None
    if audit_receipt:
        verified_audit = verify_receipt(
            audit_receipt,
            "audit",
            subject,
            expected_subject=subject,
            require_passed=False,
        )
        audit_payload = verified_audit.get("payload") or {}
        active_suppressions = audit_payload.get("activeSuppressions") or []
        suppressions_current = isinstance(active_suppressions, list)
        if suppressions_current:
            now_utc = _dt.datetime.now(_dt.timezone.utc)
            for suppression in active_suppressions:
                try:
                    expiry = _dt.datetime.fromisoformat(
                        str(suppression["expiresAt"]).replace("Z", "+00:00")
                    )
                    if expiry.tzinfo is None or expiry.astimezone(_dt.timezone.utc) <= now_utc:
                        raise ValueError("expired suppression")
                except (KeyError, TypeError, ValueError):
                    suppressions_current = False
                    break
        expected_release_range_digest = audit_release_range_digest(
            project_path,
            str(subject.get("baseCommit") or "").strip() or None,
        )
        audit_passes_release = (
            verified_audit["valid"]
            and audit_payload.get("passed") is True
            and audit_payload.get("complete") is True
            and audit_payload.get("resultStatus") == "pass"
            and audit_payload.get("profile") == str(audit_policy.get("releaseProfile") or "release")
            and audit_payload.get("scopeMode") == "repository"
            and audit_payload.get("scope") == ["."]
            and audit_payload.get("releaseScopeCovered") is True
            and audit_payload.get("releaseRangeDigest") == expected_release_range_digest
            and suppressions_current
        )
        if audit_required and not audit_passes_release:
            blockers.append("Release policy requires a current complete passing release-profile audit receipt.")
        elif not audit_passes_release:
            warnings.append("An optional audit receipt was supplied but is not a current complete passing release-profile result.")
    elif audit_required:
        blockers.append("Release policy requires a current complete passing release-profile audit receipt.")

    release_change_evidence = (
        git_change_evidence(project_path, base_ref) if base_ref else None
    )
    release_changed_files = (
        release_change_evidence["files"] if release_change_evidence else []
    )
    ui_applicability = _ui_applicability(
        project_path,
        goal=str(args.get("goal") or ""),
        paths=release_changed_files,
        baseline_head=(
            str(release_change_evidence.get("baseCommit") or "").strip()
            if release_change_evidence
            else None
        ),
    )
    ui_required = ui_applicability["state"] == "required"
    if ui_applicability["state"] == "review-required":
        blockers.append(
            "The release delta has unresolved Product Interface applicability and cannot be released until its bounded UI scope is resolved."
        )
    ui_receipt = str(args.get("ui_receipt") or "").strip()
    verified_ui: Optional[dict[str, Any]] = None
    ui_passes_release = False
    if ui_receipt:
        if len(ui_receipt) > UI_RECEIPT_MAX_CHARS:
            raise ToolError("ui_receipt exceeds the bounded receipt size.")
        verified_ui = verify_receipt(
            ui_receipt,
            "ui-finalization",
            subject,
            expected_subject=subject,
            require_passed=False,
        )
        ui_payload = verified_ui.get("payload") or {}
        ui_passes_release = (
            verified_ui["valid"]
            and ui_payload.get("schemaVersion")
            == "jstack.ui.finalization-receipt.v1"
            and ui_payload.get("baseCommit") == subject.get("baseCommit")
            and ui_payload.get("complete") is True
            and ui_payload.get("passed") is True
            and ui_payload.get("executionAuthorized") is False
            and ui_payload.get("catalogSha256")
            == ui_core.canonical_digest(ui_core.load_catalog())
        )
        if ui_required and not ui_passes_release:
            blockers.append(
                "The release delta changes Product Interface surfaces and requires a current complete passing UI finalization receipt for this exact candidate."
            )
        elif not ui_passes_release:
            warnings.append(
                "An optional UI finalization receipt was supplied but is not current, complete, passing, or baseline-matched."
            )
    elif ui_required:
        blockers.append(
            "The release delta changes Product Interface surfaces and requires a receipt from jstack_ui_finalize."
        )

    if not explicit_release_requested:
        blockers.append(
            "Release readiness requires an explicit user request for this evidence assessment. This flag never authorizes a release action."
        )
    if target_environment in {"production", "prod"} and not approved_by:
        blockers.append("Production release requires an approver name or approval reference.")
    if target_environment in {"production", "prod"} and not approval_reference:
        blockers.append("Production release requires an environment-specific approval reference from outside the MCP.")
    if target_environment in {"production", "prod"} and not rollback_plan:
        blockers.append("Production release requires a rollback plan.")
    if target_environment in {"production", "prod"} and not (monitoring_plan or canary_plan):
        blockers.append("Production release requires a monitoring or canary plan.")
    if goal_is_sensitive(str(args.get("goal") or ""), enterprise_policy) and not security_reviewed_by:
        blockers.append("Sensitive release work requires a named human security reviewer or review reference.")

    return {
        "projectPath": str(project_path),
        "targetEnvironment": target_environment,
        "ready": not blockers,
        "executionAuthorized": False,
        "blockers": list(dict.fromkeys(blockers)),
        "warnings": warnings,
        "approval": {
            "explicitReleaseRequested": explicit_release_requested,
            "meaning": "Request to assess readiness only; actual release execution remains a separate host/provider operation.",
            "approvedBy": approved_by,
            "approvalReference": approval_reference,
            "securityReviewedBy": security_reviewed_by,
        },
        "plans": {
            "rollbackPlan": rollback_plan,
            "monitoringPlan": monitoring_plan,
            "canaryPlan": canary_plan,
        },
        "evidenceState": subject,
        "qaEvidence": {
            "requiredCommands": required_commands,
            "verifiedReceipts": verified_qa,
        },
        "securityEvidence": verified_security,
        "launchEvidence": {
            "required": launch_required,
            "verification": verified_launch,
            "passesRelease": launch_passes_release,
            "releaseAuditRequiredBySurfaces": release_audit_surfaces,
        },
        "auditEvidence": {
            "required": audit_required,
            "requiredByLaunchSurfaces": release_audit_surfaces,
            "verification": verified_audit,
        },
        "productInterfaceEvidence": {
            "applicability": ui_applicability,
            "required": ui_required,
            "verification": verified_ui,
            "passesRelease": ui_passes_release,
            "doesNotReplaceQaSecurityAuditOrLaunch": True,
        },
        "preflight": preflight,
        "shipCheck": ship,
        "releaseStandard": [
            "No unresolved blockers.",
            "Tests and security checks are evidenced or explicitly blocked.",
            "Changed user-facing UI surfaces have a current candidate-bound Product Interface finalization receipt.",
            "Applicable launch controls are resolved by current typed evidence, explicit not-applicable proof, or a bounded non-blocker waiver.",
            "Rollback and monitoring are documented before production.",
            "External actions stay within explicit user scope and normal host/provider permissions; JStack adds no approval token or terminal ceremony.",
        ],
        "actionSafety": {
            "readinessIsNotExecution": True,
            "mode": "host-native",
            "customApprovalProtocol": False,
            "approvalTokenRequired": False,
            "terminalApprovalRequired": False,
        },
    }


def parse_backtest_report(report_path: Path) -> dict[str, Any]:
    text = report_path.read_text(encoding="utf-8", errors="ignore")
    compact = re.sub(r"\s+", " ", text)
    metrics: dict[str, Any] = {
        "path": str(report_path),
        "historyQualityPercent": percentage_from_text(compact, ["History Quality", "Modelling quality", "Modeling quality"]),
    }
    metric_patterns = {
        "totalNetProfit": r"Total Net Profit[^-0-9]{0,80}(-?[0-9][0-9,]*(?:\.[0-9]+)?)",
        "profitFactor": r"Profit Factor[^0-9]{0,80}([0-9]+(?:\.[0-9]+)?)",
        "totalTrades": r"Total Trades[^0-9]{0,80}([0-9]+)",
        "maxDrawdown": r"(?:Maximal drawdown|Equity Drawdown Maximal|Balance Drawdown Maximal)[^-0-9]{0,80}(-?[0-9][0-9,]*(?:\.[0-9]+)?)",
    }
    for key, pattern in metric_patterns.items():
        match = re.search(pattern, compact, re.IGNORECASE)
        if not match:
            continue
        raw_value = match.group(1).replace(",", "")
        try:
            metrics[key] = float(raw_value) if "." in raw_value else int(raw_value)
        except ValueError:
            metrics[key] = raw_value
    return metrics


def tool_quant_backtest_review(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    evidence = args.get("evidence") or {}
    if not isinstance(evidence, dict):
        raise ToolError("evidence must be an object when provided.")
    strict = bool(args.get("strict", True))
    report_path_raw = str(args.get("report_path") or evidence.get("report_path") or "").strip()
    report_metrics: Optional[dict[str, Any]] = None
    warnings: list[str] = []
    blockers: list[str] = []
    if report_path_raw:
        report_path = Path(report_path_raw).expanduser()
        if not report_path.is_absolute():
            report_path = project_path / report_path
        if report_path.is_symlink():
            blockers.append(f"Backtest report may not be a symlink: {report_path}")
        elif not report_path.exists():
            blockers.append(f"Backtest report path does not exist: {report_path}")
        elif not report_path.is_file():
            blockers.append(f"Backtest report must be a regular file: {report_path}")
        elif report_path.stat().st_size > 10_000_000:
            blockers.append("Backtest report exceeds the 10 MB review limit.")
        else:
            resolved_report = report_path.resolve()
            try:
                resolved_report.relative_to(project_path)
            except ValueError:
                blockers.append("Backtest report must be inside the reviewed project directory.")
            else:
                report_metrics = parse_backtest_report(resolved_report)
    elif strict:
        blockers.append("Strict quant review requires a backtest report path.")

    policy = load_enterprise_policy(project_path)
    quant_policy = policy.get("quant", {})
    required = [str(item) for item in quant_policy.get("requiredEvidence", [])]
    key_aliases = {
        "date_range": ["date_range", "start_date", "end_date"],
        "history_quality_or_modelling_quality": ["history_quality", "modelling_quality", "modeling_quality"],
        "settings_file": ["settings_file", "set_file", "ini_file"],
        "source_version": ["source_version", "ea_version", "git_commit"],
        "in_sample_out_of_sample_split": ["in_sample_out_of_sample_split", "oos_split", "out_of_sample"],
        "walk_forward_or_forward_test_plan": ["walk_forward", "forward_test_plan"],
        "drawdown_stress_test": ["drawdown_stress_test", "monte_carlo", "stress_test"],
        "no_lookahead_bias_review": ["no_lookahead_bias_review", "lookahead_bias_review"],
    }
    missing: list[str] = []
    for item in required:
        aliases = key_aliases.get(item, [item])
        report_satisfies = item == "history_quality_or_modelling_quality" and report_metrics is not None and report_metrics.get("historyQualityPercent") is not None
        if not report_satisfies and not any(evidence.get(alias) not in (None, "", False, []) for alias in aliases):
            missing.append(item)
    if missing:
        blockers.append("Missing required quant/backtest evidence: " + ", ".join(missing))

    min_quality = float(quant_policy.get("minimumHistoryQualityPercent") or 99.0)
    supplied_quality = evidence.get("history_quality") or evidence.get("modelling_quality") or evidence.get("modeling_quality")
    detected_quality = report_metrics.get("historyQualityPercent") if report_metrics else None
    quality_value = detected_quality if detected_quality is not None else supplied_quality
    if detected_quality is not None and supplied_quality is not None:
        try:
            if float(str(supplied_quality).replace("%", "")) != float(detected_quality):
                blockers.append("Supplied history/modelling quality conflicts with the parsed report; parsed report evidence takes precedence.")
        except ValueError:
            blockers.append("Supplied history/modelling quality is not numeric and conflicts with parsed report evidence.")
    if quality_value is not None:
        try:
            quality_float = float(str(quality_value).replace("%", ""))
            if quality_float < min_quality:
                blockers.append(f"History/modelling quality {quality_float}% is below policy minimum {min_quality}%.")
        except ValueError:
            warnings.append(f"Could not parse history/modelling quality value: {quality_value}")
    elif strict:
        blockers.append("No history/modelling quality value was supplied or detected.")

    if report_metrics:
        if strict:
            missing_metrics = [
                key for key in ("historyQualityPercent", "totalTrades", "profitFactor", "totalNetProfit")
                if report_metrics.get(key) is None
            ]
            if missing_metrics:
                blockers.append("Backtest report is missing required parsed metrics: " + ", ".join(missing_metrics))
        if report_metrics.get("totalTrades") == 0:
            blockers.append("Backtest report shows zero trades.")
        if isinstance(report_metrics.get("totalNetProfit"), (int, float)) and report_metrics["totalNetProfit"] < 0:
            warnings.append("Backtest report appears unprofitable; do not optimize until the failure mode is diagnosed.")
        if isinstance(report_metrics.get("profitFactor"), (int, float)) and report_metrics["profitFactor"] < 1.0:
            warnings.append("Profit factor is below 1.0; strategy edge is not demonstrated on this sample.")

    return {
        "projectPath": str(project_path),
        "policySource": policy.get("_sourcePath"),
        "readyForProductionClaim": not blockers,
        "blockers": blockers,
        "warnings": warnings,
        "requiredEvidence": required,
        "missingEvidence": missing,
        "evidence": evidence,
        "reportMetrics": report_metrics,
        "quantReviewStandard": [
            "No production or investor-facing claim without reproducible report files.",
            "Separate in-sample, out-of-sample, and forward-test evidence.",
            "Document spread, commission, slippage, symbol contract specs, and data source.",
            "Freeze parameters before out-of-sample or forward validation.",
            "Reject results with lookahead bias, hidden optimization, missing cost model, or poor history quality.",
        ],
    }


def _loop_service(project_path: Path) -> loop_core.LoopService:
    return loop_core.LoopService(Path.home(), project_path)


def _loop_call(operation: Callable[[], dict[str, Any]]) -> dict[str, Any]:
    try:
        return operation()
    except loop_core.LoopError as exc:
        raise ToolError(str(exc)) from exc


def git_worktree_attestation(project_path: Path) -> dict[str, Any]:
    git_dir_result = run_complete(["git", "rev-parse", "--git-dir"], project_path, timeout=8)
    common_dir_result = run_complete(["git", "rev-parse", "--git-common-dir"], project_path, timeout=8)
    if not git_dir_result["ok"] or not common_dir_result["ok"]:
        raise ToolError("Could not attest the Git worktree layout for loop autonomy.")

    def resolved(raw: str) -> Path:
        candidate = Path(raw.strip())
        if not candidate.is_absolute():
            candidate = project_path / candidate
        return candidate.resolve()

    git_dir = resolved(_git_text(git_dir_result))
    common_dir = resolved(_git_text(common_dir_result))
    return {
        "isLinkedWorktree": git_dir != common_dir,
        "gitDirDigest": hashlib.sha256(str(git_dir).encode("utf-8")).hexdigest(),
        "commonDirDigest": hashlib.sha256(str(common_dir).encode("utf-8")).hexdigest(),
    }


def stable_loop_contract_context(
    project_path: Path,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    subject_before = evidence_subject(project_path)
    policy = load_enterprise_policy(project_path)
    worktree = git_worktree_attestation(project_path)
    subject_after = evidence_subject(project_path)
    if any(
        subject_after[field] != subject_before[field]
        for field in ("gitHead", "projectFingerprint", "policyDigest", "toolVersion")
    ):
        raise ToolError(
            "The project changed while the loop contract context was being collected. Re-run against one stable Git state."
        )
    return subject_after, policy, worktree


def _receipt_digest(receipt: str) -> str:
    return hashlib.sha256(receipt.encode("utf-8")).hexdigest()


def _reject_loop_secret_inputs(args: dict[str, Any]) -> None:
    receipt_fields = {
        "qa_receipts",
        "security_receipt",
        "audit_receipts",
        "launch_receipt",
        "ui_contract_receipt",
        "ui_receipt",
        "specialist_handoff_receipt",
        "goal_readiness_receipt",
        "program_readiness_receipt",
        "loop_completion_receipt",
    }

    def visit(value: Any, field: str) -> None:
        if field in receipt_fields:
            return
        if isinstance(value, str):
            if audit_core.contains_secret_like(value):
                raise ToolError(
                    "Loop input contains a secret-like value. Remove it, use only a redacted external reference, and revoke it first if it was exposed."
                )
            return
        if isinstance(value, dict):
            for key, child in value.items():
                visit(child, str(key))
        elif isinstance(value, list):
            for child in value:
                visit(child, field)

    visit(args, "arguments")


def _loop_receipt_evidence(
    args: dict[str, Any],
    subject: dict[str, Any],
    capability_contract: Optional[dict[str, Any]] = None,
    expected_goal_digest: Optional[str] = None,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    evidence: dict[str, Any] = {"qa": [], "audit": []}
    invalid: list[dict[str, Any]] = []

    qa_receipts = args.get("qa_receipts") or []
    if not isinstance(qa_receipts, list) or not all(isinstance(item, str) for item in qa_receipts):
        raise ToolError("qa_receipts must be an array of receipts returned by jstack_qa.")
    if len(qa_receipts) > LOOP_MAX_QA_RECEIPTS or any(
        len(item) > LOOP_MAX_RECEIPT_CHARS for item in qa_receipts
    ):
        raise ToolError("qa_receipts exceeds the bounded loop evidence limits.")
    seen_qa: set[str] = set()
    for receipt in qa_receipts:
        digest = _receipt_digest(receipt)
        if digest in seen_qa:
            continue
        seen_qa.add(digest)
        try:
            verification = verify_receipt(receipt, "qa", subject, expected_subject=subject)
        except ToolError:
            invalid.append({"kind": "qa", "receiptDigest": digest, "reason": "malformed-or-wrong-session"})
            continue
        if not verification["valid"]:
            invalid.append(
                {
                    "kind": "qa",
                    "receiptDigest": digest,
                    "checks": verification["checks"],
                }
            )
            continue
        payload = verification["payload"]
        evidence["qa"].append(
            {
                "type": "qa-receipt",
                "commandKey": payload.get("commandKey"),
                "commandFingerprint": payload.get("commandFingerprint"),
                "receiptDigest": digest,
                "passed": True,
            }
        )

    security_receipt = str(args.get("security_receipt") or "").strip()
    if len(security_receipt) > LOOP_MAX_RECEIPT_CHARS:
        raise ToolError("security_receipt exceeds the bounded loop evidence limit.")
    if security_receipt:
        digest = _receipt_digest(security_receipt)
        try:
            verification = verify_receipt(
                security_receipt, "security", subject, expected_subject=subject
            )
        except ToolError:
            invalid.append(
                {"kind": "security", "receiptDigest": digest, "reason": "malformed-or-wrong-session"}
            )
        else:
            if verification["valid"]:
                payload = verification["payload"]
                evidence["security"] = {
                    "type": "security-receipt",
                    "receiptDigest": digest,
                    "findingCount": payload.get("findingCount"),
                    "complete": payload.get("complete") is True,
                    "passed": True,
                }
            else:
                invalid.append(
                    {
                        "kind": "security",
                        "receiptDigest": digest,
                        "checks": verification["checks"],
                    }
                )

    audit_receipts = args.get("audit_receipts") or []
    if not isinstance(audit_receipts, list) or not all(isinstance(item, str) for item in audit_receipts):
        raise ToolError("audit_receipts must be an array of receipts returned by jstack_audit_finalize.")
    if len(audit_receipts) > LOOP_MAX_AUDIT_RECEIPTS or any(
        len(item) > LOOP_MAX_RECEIPT_CHARS for item in audit_receipts
    ):
        raise ToolError("audit_receipts exceeds the bounded loop evidence limits.")
    seen_audit: set[str] = set()
    for receipt in audit_receipts:
        digest = _receipt_digest(receipt)
        if digest in seen_audit:
            continue
        seen_audit.add(digest)
        try:
            verification = verify_receipt(receipt, "audit", subject, expected_subject=subject)
        except ToolError:
            invalid.append({"kind": "audit", "receiptDigest": digest, "reason": "malformed-or-wrong-session"})
            continue
        if not verification["valid"]:
            invalid.append(
                {
                    "kind": "audit",
                    "receiptDigest": digest,
                    "checks": verification["checks"],
                }
            )
            continue
        payload = verification["payload"]
        evidence["audit"].append(
            {
                "type": "audit-receipt",
                "profile": payload.get("profile"),
                "receiptDigest": digest,
                "coverageDigest": payload.get("coverageDigest"),
                "findingDigest": payload.get("findingDigest"),
                "complete": payload.get("complete") is True,
                "passed": True,
            }
        )

    launch_receipt = str(args.get("launch_receipt") or "").strip()
    if len(launch_receipt) > LOOP_MAX_RECEIPT_CHARS:
        raise ToolError("launch_receipt exceeds the bounded loop evidence limit.")
    if launch_receipt:
        digest = _receipt_digest(launch_receipt)
        try:
            verification = verify_receipt(
                launch_receipt,
                "launch",
                subject,
                expected_subject=subject,
            )
        except ToolError:
            invalid.append(
                {
                    "kind": "launch",
                    "receiptDigest": digest,
                    "reason": "malformed-or-wrong-session",
                }
            )
        else:
            payload = verification["payload"]
            try:
                project_path = Path(subject["gitRoot"])
                environment = _launch_environment(
                    payload.get("targetEnvironment")
                )
                surfaces = _launch_call(
                    lambda: launch_core.normalize_surfaces(
                        list(payload.get("surfaces") or [])
                    )
                )
                current_detection = _launch_surface_detection(project_path)
                _, selection = _launch_selection(
                    project_path,
                    surfaces,
                    environment,
                    payload.get("targetUrl"),
                    str(payload.get("riskTier") or ""),
                    str(payload.get("deploymentFingerprint") or ""),
                    current_detection["hintDigest"],
                    str(payload.get("surfaceReconciliationDigest") or ""),
                )
                contract_checks = {
                    "schemaVersion": payload.get("schemaVersion")
                    == "jstack.launch.receipt.v2",
                    "complete": payload.get("complete") is True,
                    "passed": payload.get("passed") is True,
                    "targetEnvironment": payload.get("targetEnvironment")
                    == environment,
                    "surfaces": payload.get("surfaces") == surfaces,
                    "riskTier": payload.get("riskTier")
                    == selection["riskTier"],
                    "deploymentFingerprint": payload.get(
                        "deploymentFingerprint"
                    )
                    == selection["deploymentFingerprint"],
                    "surfaceHintDigest": payload.get("surfaceHintDigest")
                    == current_detection["hintDigest"],
                    "catalogVersion": payload.get("catalogVersion")
                    == selection["catalogVersion"],
                    "catalogDigest": payload.get("catalogDigest")
                    == selection["catalogDigest"],
                    "selectionDigest": payload.get("selectionDigest")
                    == selection["selectionDigest"],
                }
            except ToolError:
                environment = None
                surfaces = []
                selection = None
                contract_checks = {"launchContract": False}
            if verification["valid"] and all(contract_checks.values()):
                evidence["launch"] = {
                    "type": "launch-receipt",
                    "receiptDigest": digest,
                    "targetEnvironment": environment,
                    "surfaces": surfaces,
                    "riskTier": selection["riskTier"],
                    "deploymentFingerprint": selection[
                        "deploymentFingerprint"
                    ],
                    "selectionDigest": selection["selectionDigest"],
                    "complete": True,
                    "passed": True,
                }
            else:
                invalid.append(
                    {
                        "kind": "launch",
                        "receiptDigest": digest,
                        "checks": {
                            **verification["checks"],
                            **contract_checks,
                        },
                    }
                )

    ui_receipt = str(args.get("ui_receipt") or "").strip()
    if len(ui_receipt) > UI_RECEIPT_MAX_CHARS:
        raise ToolError("ui_receipt exceeds the bounded Product Interface evidence limit.")
    if ui_receipt:
        digest = _receipt_digest(ui_receipt)
        try:
            verification = verify_receipt(
                ui_receipt,
                "ui-finalization",
                subject,
                expected_subject=subject,
                require_passed=False,
            )
        except ToolError:
            invalid.append(
                {
                    "kind": "ui",
                    "receiptDigest": digest,
                    "reason": "malformed-or-wrong-session",
                }
            )
        else:
            payload = verification["payload"]
            ui_checks = {
                "schemaVersion": payload.get("schemaVersion")
                == "jstack.ui.finalization-receipt.v1",
                "baseCommit": payload.get("baseCommit") == subject.get("baseCommit"),
                "complete": payload.get("complete") is True,
                "passed": payload.get("passed") is True,
                "noAuthority": payload.get("executionAuthorized") is False,
                "contractSha256": bool(
                    re.fullmatch(r"[0-9a-f]{64}", str(payload.get("contractSha256") or ""))
                ),
                "catalogSha256": payload.get("catalogSha256")
                == ui_core.canonical_digest(ui_core.load_catalog()),
                "evidenceManifestSha256": bool(
                    re.fullmatch(
                        r"[0-9a-f]{64}",
                        str(payload.get("evidenceManifestSha256") or ""),
                    )
                ),
                "buildSha256": bool(
                    re.fullmatch(r"[0-9a-f]{64}", str(payload.get("buildSha256") or ""))
                ),
                "runtimeSha256": bool(
                    re.fullmatch(r"[0-9a-f]{64}", str(payload.get("runtimeSha256") or ""))
                ),
            }
            if verification["valid"] and all(ui_checks.values()):
                evidence["ui"] = {
                    "type": "ui-finalization-receipt",
                    "schemaVersion": loop_core.UI_EVIDENCE_SCHEMA,
                    "receiptDigest": digest,
                    "contractSha256": payload["contractSha256"],
                    "catalogSha256": payload["catalogSha256"],
                    "baseCommit": payload["baseCommit"],
                    "gitHead": payload["gitHead"],
                    "projectFingerprint": payload["projectFingerprint"],
                    "evidenceManifestSha256": payload["evidenceManifestSha256"],
                    "buildSha256": payload["buildSha256"],
                    "runtimeSha256": payload["runtimeSha256"],
                    "complete": True,
                    "passed": True,
                    "executionAuthorized": False,
                }
            else:
                invalid.append(
                    {
                        "kind": "ui",
                        "receiptDigest": digest,
                        "checks": {**verification["checks"], **ui_checks},
                    }
                )
    specialist_handoff_receipt = str(
        args.get("specialist_handoff_receipt") or ""
    ).strip()
    if len(specialist_handoff_receipt) > LOOP_MAX_RECEIPT_CHARS:
        raise ToolError(
            "specialist_handoff_receipt exceeds the bounded loop evidence limit."
        )
    if specialist_handoff_receipt:
        digest = _receipt_digest(specialist_handoff_receipt)
        try:
            verification = verify_receipt(
                specialist_handoff_receipt,
                "specialist-handoff",
                subject,
            )
        except ToolError:
            invalid.append(
                {
                    "kind": "specialist-handoff",
                    "receiptDigest": digest,
                    "reason": "malformed-or-wrong-session",
                }
            )
        else:
            payload = verification["payload"]
            capability_checks = {
                "schemaVersion": payload.get("schemaVersion")
                == "jstack.specialist.handoff-receipt.v1",
                "policyDigest": payload.get("policyDigest")
                == subject.get("policyDigest"),
                "toolVersion": payload.get("toolVersion")
                == subject.get("toolVersion"),
                "catalogDigest": capability_contract is None
                or payload.get("capabilityCatalogDigest")
                == capability_contract.get("catalogDigest"),
                "selectionDigest": capability_contract is None
                or payload.get("capabilitySelectionDigest")
                == capability_contract.get("selectionDigest"),
                "teamMode": capability_contract is None
                or payload.get("teamMode")
                == capability_contract.get("executionMode"),
                "teamRoleIds": capability_contract is None
                or payload.get("teamRoleIds")
                == capability_contract.get("teamRoleIds"),
                "goalDigest": expected_goal_digest is None
                or payload.get("goalDigest") == expected_goal_digest,
            }
            if verification["valid"] and all(capability_checks.values()):
                evidence["specialistHandoff"] = {
                    "type": "specialist-handoff-receipt",
                    "receiptDigest": digest,
                    "catalogDigest": payload.get("capabilityCatalogDigest"),
                    "selectionDigest": payload.get("capabilitySelectionDigest"),
                    "teamRoleIds": payload.get("teamRoleIds"),
                    "passed": True,
                }
            else:
                invalid.append(
                    {
                        "kind": "specialist-handoff",
                        "receiptDigest": digest,
                        "checks": {
                            **verification["checks"],
                            **capability_checks,
                        },
                    }
                )
    return evidence, invalid


def _loop_artifact_evidence(
    project_path: Path, acceptance_criteria: list[dict[str, Any]]
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    artifacts: list[dict[str, Any]] = []
    invalid: list[dict[str, Any]] = []
    seen: set[str] = set()
    total_bytes = 0
    total_limit = 100_000_000
    per_file_limit = 25_000_000
    deadline = time.monotonic() + 30
    for criterion in acceptance_criteria:
        verifier = criterion.get("verifier") or {}
        if verifier.get("type") != "artifact":
            continue
        relative = str(verifier.get("path") or "")
        if relative in seen:
            continue
        seen.add(relative)
        remaining_bytes = total_limit - total_bytes
        remaining_seconds = int(deadline - time.monotonic())
        if remaining_bytes <= 0 or remaining_seconds <= 0:
            artifacts.append({"type": "artifact", "path": relative, "exists": False})
            invalid.append({"kind": "artifact", "path": relative, "reason": "aggregate-limit"})
            continue
        try:
            size, digest = audit_core.digest_repository_file(
                project_path,
                relative,
                max_bytes=min(per_file_limit, remaining_bytes),
                max_seconds=max(1, remaining_seconds),
            )
        except audit_core.AuditError:
            artifacts.append({"type": "artifact", "path": relative, "exists": False})
            invalid.append({"kind": "artifact", "path": relative, "reason": "missing-or-unsafe"})
        else:
            total_bytes += size
            artifacts.append(
                {
                    "type": "artifact",
                    "path": relative,
                    "exists": True,
                    "size": size,
                    "sha256": digest,
                }
            )
    return artifacts, invalid


def _loop_iteration_evidence(
    project_path: Path,
    loop_status: dict[str, Any],
    args: dict[str, Any],
) -> dict[str, Any]:
    baseline = str(loop_status["baselineCommit"])
    subject = evidence_subject(project_path, baseline)
    change_evidence = git_change_evidence(project_path, baseline)
    if (
        subject.get("baseCommit") != baseline
        or change_evidence.get("baseCommit") != baseline
    ):
        raise ToolError(
            "The loop baseline is no longer the exact Git merge base of HEAD. Stop this loop and start a new contract after the branch, reset, or rebase is resolved."
        )
    changed_files = change_evidence["files"]
    product_interface = _enforce_iteration_ui_route(
        project_path,
        loop_status,
        baseline=baseline,
        changed_files=changed_files,
    )
    policy = load_enterprise_policy(project_path)
    protected_patterns = [str(item) for item in policy.get("protectedPaths", [])]
    protected_files = [
        path for path in changed_files if path_matches_patterns(path, protected_patterns)
    ]
    capability_contract = loop_status.get("capabilityContract")
    if capability_contract is not None and not _loop_capability_contract_matches(
        loop_status
    ):
        raise ToolError(
            "The loop capability contract no longer matches the current catalog or "
            "deterministic routing. Run goal readiness and an approved material "
            "contract revision before continuing."
        )
    evidence, invalid = _loop_receipt_evidence(
        args,
        subject,
        capability_contract,
        hashlib.sha256(str(loop_status.get("goal") or "").encode("utf-8")).hexdigest(),
    )
    if (
        loop_status.get("executionMode") in {"smart-subagents", "full-team"}
        and not evidence.get("specialistHandoff")
    ):
        raise ToolError(
            "Multi-agent loop checkpoints and finalization require a current passed specialist_handoff_receipt bound to this capability contract and Git state."
        )
    review = tool_review({"project_path": str(project_path), "base_ref": baseline})
    evidence["review"] = {
        "type": "deterministic-review",
        "passed": review["diffCheck"]["returncode"] == 0
        and review.get("changeEvidence", {}).get("complete") is True,
        "diffCheckReturncode": review["diffCheck"]["returncode"],
        "changedFileCount": len(changed_files),
        "changeEvidenceComplete": review.get("changeEvidence", {}).get("complete") is True,
    }
    artifacts, artifact_invalid = _loop_artifact_evidence(
        project_path, loop_status["acceptanceCriteria"]
    )
    evidence["artifacts"] = artifacts
    evidence["invalid"] = [*invalid, *artifact_invalid]
    subject_after = evidence_subject(project_path, baseline)
    if any(
        subject_after[field] != subject[field]
        for field in ("gitHead", "projectFingerprint", "policyDigest", "toolVersion")
    ):
        raise ToolError(
            "The project changed while loop evidence was being collected. Re-run the checkpoint against one stable state."
        )
    return {
        "subject": subject_after,
        "policy": policy,
        "changedFiles": changed_files,
        "protectedFiles": protected_files,
        "productInterface": product_interface,
        "evidence": evidence,
    }


def _verified_goal_readiness_attestation(
    receipt: Any, subject: dict[str, Any]
) -> dict[str, Any]:
    if not isinstance(receipt, str) or not receipt or len(receipt) > LOOP_MAX_RECEIPT_CHARS:
        raise ToolError(
            "A bounded goal_readiness_receipt returned by jstack_loop_goal_readiness is required."
        )
    verification = verify_receipt(
        receipt,
        "goal-readiness",
        subject,
        expected_subject=subject,
    )
    payload = verification["payload"]
    if (
        not verification["valid"]
        or payload.get("schemaVersion") != loop_core.GOAL_READINESS_RECEIPT_SCHEMA
        or not _prompt_receipt_binding_valid(payload)
    ):
        raise ToolError(
            "The goal-readiness receipt is stale, malformed, from another session, or bound to a different project state."
        )
    return {**payload, "receiptDigest": _receipt_digest(receipt)}


def _loop_capability_contract(
    goal: str,
    execution_mode: str,
    explicit_capability_ids: list[str],
    *,
    ui_product: bool = False,
) -> dict[str, Any]:
    _, team = _deterministic_specialist_team(
        goal,
        execution_mode,
        explicit_capability_ids,
        ui_product=ui_product,
    )
    capability_plan = team["capabilityPlan"]
    assignments = capability_assignments_by_role(capability_plan)
    contract = {
        "schemaVersion": (
            "jstack.loop.capability-contract.v2"
            if ui_product
            else "jstack.loop.capability-contract.v1"
        ),
        "catalogVersion": capability_plan["catalogVersion"],
        "catalogDigest": capability_plan["catalogDigest"],
        "selectionDigest": capability_plan["selectionDigest"],
        "goalDigest": capability_plan["goalDigest"],
        "executionMode": execution_mode,
        "teamRoleIds": [str(agent["id"]) for agent in team["agents"]],
        "roleCapabilities": {
            str(agent["id"]): [
                str(item["capabilityId"])
                for item in assignments.get(str(agent["id"]), [])
            ]
            for agent in team["agents"]
        },
        "explicitCapabilityIds": list(explicit_capability_ids),
        "auditDomains": capability_plan["auditDomains"],
        "loopControls": capability_plan["loopControls"],
        "permissionInvariant": capability_plan["permissionInvariant"],
    }
    if ui_product:
        contract["uiProduct"] = True
    return contract


def _loop_capability_contract_matches(loop_status: dict[str, Any]) -> Optional[bool]:
    capability_contract = loop_status.get("capabilityContract")
    if capability_contract is None:
        return None
    expected = _loop_capability_contract(
        str(loop_status.get("goal") or ""),
        str(loop_status.get("executionMode") or ""),
        [
            str(item)
            for item in capability_contract.get("explicitCapabilityIds") or []
        ],
        ui_product=isinstance(loop_status.get("uiContract"), dict),
    )
    return expected == capability_contract


def _loop_args_with_capabilities(
    args: dict[str, Any],
    prior_status: Optional[dict[str, Any]] = None,
    *,
    ui_product: Optional[bool] = None,
) -> dict[str, Any]:
    enriched = dict(args)
    goal = str(args.get("goal") or (prior_status or {}).get("goal") or "").strip()
    execution_mode = str(
        args.get("execution_mode")
        or (prior_status or {}).get("executionMode")
        or ""
    ).strip()
    if not goal or execution_mode not in {"single-lead", "smart-subagents", "full-team"}:
        return enriched
    prior_contract = (prior_status or {}).get("capabilityContract") or {}
    if "capability_ids" in args:
        raw_capability_ids = args.get("capability_ids") or []
    else:
        raw_capability_ids = prior_contract.get("explicitCapabilityIds") or []
    if not isinstance(raw_capability_ids, list):
        raise ToolError("capability_ids must be an array.")
    explicit_capability_ids = [str(item) for item in raw_capability_ids]
    if ui_product is None:
        ui_product = isinstance((prior_status or {}).get("uiContract"), dict)
    enriched["goal"] = goal
    enriched["execution_mode"] = execution_mode
    enriched["capability_contract"] = _loop_capability_contract(
        goal,
        execution_mode,
        explicit_capability_ids,
        ui_product=ui_product,
    )
    return enriched


def _loop_ui_contract_binding(
    project_path: Path,
    subject: dict[str, Any],
    receipt: Any,
) -> dict[str, str]:
    token = str(receipt or "").strip()
    _, contract = _ui_contract_payload(project_path, token)
    baseline = contract["baseline"]
    checks = {
        "gitRoot": baseline.get("gitRoot") == subject.get("gitRoot"),
        "gitHead": baseline.get("gitHead") == subject.get("gitHead"),
        "projectFingerprint": baseline.get("projectFingerprint")
        == subject.get("projectFingerprint"),
        "policyDigest": baseline.get("policyDigest") == subject.get("policyDigest"),
    }
    if not all(checks.values()):
        raise ToolError(
            "The Product Interface contract receipt must bind the exact clean loop baseline project state."
        )
    return {
        "schemaVersion": loop_core.UI_CONTRACT_BINDING_SCHEMA,
        "contractSha256": contract["contractSha256"],
        "catalogSha256": contract["catalog"]["sha256"],
        "baselineGitHead": baseline["gitHead"],
        "baselineProjectFingerprint": baseline["projectFingerprint"],
        "baselinePolicyDigest": baseline["policyDigest"],
    }


def _loop_args_with_ui_contract(
    args: dict[str, Any],
    project_path: Path,
    subject: dict[str, Any],
    prior_status: Optional[dict[str, Any]] = None,
) -> dict[str, Any]:
    enriched = dict(args)
    receipt = args.get("ui_contract_receipt")
    if receipt is not None:
        enriched["ui_contract_binding"] = _loop_ui_contract_binding(
            project_path, subject, receipt
        )
    elif isinstance((prior_status or {}).get("uiContract"), dict):
        enriched["ui_contract_binding"] = dict(prior_status["uiContract"])
    enriched.pop("ui_contract_receipt", None)
    enriched.pop("prompt_compilation_receipt", None)
    enriched.pop("prompt_contract", None)
    return enriched


def _has_public_ui_verifier(criteria: Any) -> bool:
    return isinstance(criteria, list) and any(
        isinstance(item, dict)
        and isinstance(item.get("verifier"), dict)
        and item["verifier"].get("type") == "ui"
        for item in criteria
    )


def _ui_contract_scope_paths(
    project_path: Path, path_patterns: Any
) -> Optional[list[str]]:
    """Resolve declared contract globs to tracked paths without widening scope."""
    if path_patterns is None:
        return None
    if (
        not isinstance(path_patterns, list)
        or len(path_patterns) > 100
        or not all(isinstance(item, str) for item in path_patterns)
    ):
        return None
    patterns = [item.replace("\\", "/") for item in path_patterns]
    root = Path(git_root(project_path) or project_path).resolve()
    listed = run_complete(
        ["git", "ls-files", "-z"], root, timeout=20, max_bytes=10_000_000
    )
    if not listed["ok"]:
        raise ToolError(
            "Could not enumerate the declared Product Interface contract scope."
        )
    tracked = [
        decode_git_relative_path(raw, "Product Interface contract scope")
        for raw in listed["stdout"].split(b"\0")
        if raw
    ]
    return sorted(
        path for path in tracked if path_matches_patterns(path, patterns)
    )


def _ui_contract_applicability(
    project_path: Path,
    *,
    goals: list[str],
    path_patterns: Any,
) -> dict[str, Any]:
    """Classify a future loop/program contract from its goal and declared scope."""
    combined_goal = "\n".join(
        item.strip() for item in goals if isinstance(item, str) and item.strip()
    )
    scoped_paths = _ui_contract_scope_paths(project_path, path_patterns)
    scoped_gitlinks: list[str] = []
    if scoped_paths:
        root = Path(git_root(project_path) or project_path).resolve()
        listed = run_complete(
            ["git", "ls-files", "-s", "-z"],
            root,
            timeout=20,
            max_bytes=20_000_000,
        )
        if not listed["ok"]:
            raise ToolError(
                "Could not inspect the declared Product Interface scope for Git submodules."
            )
        selected = set(scoped_paths)
        for raw in listed["stdout"].split(b"\0"):
            if not raw:
                continue
            header, separator, encoded_path = raw.partition(b"\t")
            fields = header.split()
            if (
                not separator
                or len(fields) != 3
                or fields[0] not in {b"100644", b"100755", b"120000", b"160000"}
            ):
                raise ToolError(
                    "Git returned invalid index metadata for Product Interface scope resolution."
                )
            relative = decode_git_relative_path(
                encoded_path, "Product Interface scoped index"
            )
            if fields[0] == b"160000" and relative in selected:
                scoped_gitlinks.append(relative)
    applicability = _ui_applicability(
        project_path,
        goal=combined_goal,
        paths=scoped_paths,
    )
    if scoped_gitlinks:
        applicability = {
            "schemaVersion": "jstack.ui.applicability.v1",
            "state": "review-required",
            "reason": "declared-scope-includes-gitlink",
            "goalDigest": hashlib.sha256(combined_goal.encode("utf-8")).hexdigest(),
            "changedScopeEvaluated": True,
            "detection": applicability["detection"],
        }
        applicability["applicabilitySha256"] = ui_core.canonical_digest(
            applicability
        )
    if isinstance(path_patterns, list) and all(
        isinstance(item, str) for item in path_patterns
    ):
        declared_documents = [
            (item.replace("\\", "/"), "")
            for item in path_patterns
            if item and len(item) <= 500
        ]
        declared_paths = [path for path, _ in declared_documents]
        declared_detection = ui_core.detect_product_ui(
            declared_documents,
            context_platforms_by_path=_ui_repository_context_by_path(
                project_path, declared_paths
            ),
        )
        if (
            not scoped_gitlinks
            and applicability["state"] == "inactive"
            and declared_detection["applicable"]
        ):
            applicability = {
                "schemaVersion": "jstack.ui.applicability.v1",
                "state": "required",
                "reason": "declared-ui-scope",
                "goalDigest": hashlib.sha256(
                    combined_goal.encode("utf-8")
                ).hexdigest(),
                "changedScopeEvaluated": True,
                "detection": declared_detection,
            }
            applicability["applicabilitySha256"] = ui_core.canonical_digest(
                applicability
            )
    return applicability


def _loop_ui_contract_inputs(
    args: dict[str, Any], prior_status: Optional[dict[str, Any]] = None
) -> tuple[list[str], Any, Any]:
    goal = args.get("goal")
    if goal is None and prior_status is not None:
        goal = prior_status.get("goal")
    if "allowed_paths" in args:
        path_patterns = args.get("allowed_paths")
    elif prior_status is not None:
        path_patterns = prior_status.get("allowedPaths")
    else:
        path_patterns = None
    if "acceptance_criteria" in args:
        criteria = args.get("acceptance_criteria")
    elif prior_status is not None:
        criteria = prior_status.get("acceptanceCriteria")
    else:
        criteria = None
    return [str(goal or "")], path_patterns, criteria


def _program_ui_contract_inputs(
    args: dict[str, Any], prior_status: Optional[dict[str, Any]] = None
) -> tuple[list[str], Any, Any]:
    goal = args.get("goal")
    if goal is None and prior_status is not None:
        goal = prior_status.get("goal")
    if "phases" in args:
        phases = args.get("phases")
        normalized = False
    elif prior_status is not None:
        phases = prior_status.get("phases")
        normalized = True
    else:
        phases = None
        normalized = False
    goals = [str(goal or "")]
    path_patterns: Any = None
    if isinstance(phases, list):
        path_patterns = []
        for phase in phases:
            if not isinstance(phase, dict):
                path_patterns = None
                break
            goals.append(str(phase.get("goal") or ""))
            field = "allowedPaths" if normalized else "allowed_paths"
            value = phase.get(field, [])
            if not isinstance(value, list):
                path_patterns = None
                break
            path_patterns.extend(value)
    if "final_acceptance_criteria" in args:
        criteria = args.get("final_acceptance_criteria")
    elif prior_status is not None:
        criteria = prior_status.get("finalAcceptanceCriteria")
    else:
        criteria = None
    return goals, path_patterns, criteria


def _ui_readiness_gaps(
    applicability: dict[str, Any], *, ui_bound: bool, has_ui_verifier: bool
) -> list[str]:
    state = applicability["state"]
    if state == "review-required":
        return ["product-interface-scope-review"]
    if ui_bound:
        return [] if has_ui_verifier else ["product-interface-verifier"]
    if has_ui_verifier:
        return ["product-interface-contract"]
    if state == "inactive":
        return []
    gaps: list[str] = []
    if not ui_bound:
        gaps.append("product-interface-contract")
    if not has_ui_verifier:
        gaps.append("product-interface-verifier")
    return gaps


def _ui_readiness_questions(gaps: list[str], *, program: bool) -> list[dict[str, Any]]:
    questions: list[dict[str, Any]] = []
    for gap in gaps:
        if gap == "product-interface-contract":
            question = (
                "Create a Product Interface contract with jstack_ui_contract and supply its exact ui_contract_receipt for this baseline."
            )
            why = (
                "Automatic routing classified the goal or declared path scope as Product Interface work, so a v1 contract would omit its required semantic UI boundary."
            )
            recommended = (
                "Use the smallest accurate surface, platform, theme, viewport, and allowed-path contract, then retry readiness with that receipt."
            )
        elif gap == "product-interface-verifier":
            location = "final acceptance" if program else "loop acceptance"
            question = f"Add a dedicated ui verifier to the {location} criteria."
            why = (
                "A Product Interface receipt freezes requirements, but completion also needs exact candidate-bound UI finalization evidence."
            )
            recommended = (
                "Add one criterion whose verifier type is ui; keep QA, review, security, audit, and launch criteria separate."
            )
        elif gap == "product-interface-new-loop":
            question = (
                "Stop this v1 loop and start a new UI-bound loop from the current baseline."
            )
            why = (
                "The frozen loop revision input cannot add a Product Interface receipt, so upgrading this existing non-UI contract in place would bypass the public MCP boundary."
            )
            recommended = (
                "Run jstack_ui_contract, then pass its ui_contract_receipt plus a dedicated ui verifier through jstack_loop_goal_readiness and jstack_loop_start."
            )
        else:
            question = (
                "Narrow the goal and allowed path scope so Product Interface applicability can be decided before starting."
            )
            why = (
                "Repository evidence indicates UI capability, but the proposed contract has no bounded scope that proves whether interface work is included."
            )
            recommended = (
                "Declare the smallest accurate allowed paths; if UI remains in scope, obtain jstack_ui_contract and add a dedicated ui verifier."
            )
        item: dict[str, Any] = {
            "id": gap,
            "question": question,
            "why": why,
            "recommendedDefault": recommended,
        }
        if program:
            item["blocking"] = True
        else:
            item.update(
                {
                    "category": "product-interface",
                    "priority": "blocking",
                    "resolves": [gap],
                }
            )
        questions.append(item)
    return questions[:3]


def _ui_readiness_block(gaps: list[str], *, program: bool) -> dict[str, Any]:
    result: dict[str, Any] = {
        "schemaVersion": (
            program_core.PROGRAM_READINESS_SCHEMA
            if program
            else loop_core.GOAL_READINESS_SCHEMA
        ),
        "status": "needs_context",
        "ready": False,
        "gaps": gaps,
        "questions": _ui_readiness_questions(gaps, program=program),
        "receiptIssued": False,
    }
    if not program:
        result.update(
            {
                "confirmationRequired": False,
                "readinessDigest": None,
            }
        )
    return result


def _merge_ui_readiness_block(
    assessment: dict[str, Any], gaps: list[str], *, program: bool
) -> dict[str, Any]:
    block = _ui_readiness_block(gaps, program=program)
    merged = dict(assessment)
    merged.update({"status": "needs_context", "ready": False})
    merged["gaps"] = list(
        dict.fromkeys([*gaps, *(assessment.get("gaps") or [])])
    )
    merged["questions"] = [
        *block["questions"], *(assessment.get("questions") or [])
    ][:3]
    merged["receiptIssued"] = False
    if not program:
        merged["confirmationRequired"] = False
        merged["readinessDigest"] = None
    return merged


def _enforce_ui_contract_route(
    applicability: dict[str, Any],
    *,
    ui_bound: bool,
    has_ui_verifier: bool,
    operation: str,
) -> None:
    gaps = _ui_readiness_gaps(
        applicability,
        ui_bound=ui_bound,
        has_ui_verifier=has_ui_verifier,
    )
    if not gaps:
        return
    if applicability["state"] == "review-required":
        raise ToolError(
            f"{operation} is review-required for Product Interface applicability. Narrow the goal and allowed paths, rerun readiness, and if UI remains in scope obtain jstack_ui_contract and add a dedicated ui verifier."
        )
    missing = []
    if "product-interface-contract" in gaps:
        missing.append("a valid ui_contract_receipt from jstack_ui_contract")
    if "product-interface-verifier" in gaps:
        missing.append("a dedicated ui acceptance verifier")
    raise ToolError(
        f"Automatic Product Interface routing requires {operation} to include "
        + " and ".join(missing)
        + "."
    )


def _enforce_iteration_ui_route(
    project_path: Path,
    loop_status: dict[str, Any],
    *,
    baseline: str,
    changed_files: list[str],
) -> dict[str, Any]:
    """Reclassify the exact delta so UI work cannot emerge under a v1 contract."""
    applicability = _ui_applicability(
        project_path,
        goal=str(loop_status.get("goal") or ""),
        paths=changed_files,
        baseline_head=baseline,
    )
    ui_bound = isinstance(loop_status.get("uiContract"), dict)
    has_ui_verifier = _has_public_ui_verifier(
        loop_status.get("acceptanceCriteria")
    )
    if ui_bound:
        if not has_ui_verifier:
            raise ToolError(
                "The Product Interface loop binding is missing its dedicated ui verifier. Stop and replace the invalid loop contract."
            )
        return applicability
    if applicability["state"] == "inactive":
        return applicability
    if applicability["state"] == "review-required":
        raise ToolError(
            "The actual baseline-to-candidate delta became review-required for Product Interface scope after this non-UI contract was frozen. Stop it, resolve the UI scope, and start a new UI-bound loop or program from a clean baseline."
        )
    raise ToolError(
        "Product Interface work emerged in the actual baseline-to-candidate delta after this non-UI contract was frozen. Stop it and start a new UI-bound loop or program with jstack_ui_contract and a dedicated ui verifier; checkpoint or completion under the v1 contract is not allowed."
    )


def tool_loop_goal_readiness(args: dict[str, Any]) -> dict[str, Any]:
    _reject_loop_secret_inputs(args)
    project_path = require_project_path(args.get("project_path"))
    subject, policy, worktree = stable_loop_contract_context(project_path)
    service = _loop_service(project_path)
    loop_id = str(args.get("loop_id") or "").strip() or None
    prior_contract_digest = None
    prior_status = None
    if loop_id:
        status = _loop_call(lambda: service.status(loop_id))
        if status["status"] in {"succeeded", "stopped"}:
            raise ToolError("Terminal loops cannot receive a revised goal-readiness receipt.")
        prior_contract_digest = status["contractDigest"]
        prior_status = status
    prompt_goal = str(
        args.get("goal")
        or (prior_status or {}).get("goal")
        or ""
    ).strip()
    prompt_binding = (
        _prompt_orchestration_binding(
            args,
            goal=prompt_goal,
            workflow_mode="jstack-loop",
            binding=resolve_project_binding(str(project_path)),
        )
        if prompt_goal
        else None
    )
    enriched_args = _loop_args_with_ui_contract(
        args, project_path, subject, prior_status
    )
    ui_goals, ui_paths, ui_criteria = _loop_ui_contract_inputs(
        args, prior_status
    )
    ui_applicability = _ui_contract_applicability(
        project_path, goals=ui_goals, path_patterns=ui_paths
    )
    ui_bound = isinstance(enriched_args.get("ui_contract_binding"), dict)
    enriched_args = _loop_args_with_capabilities(
        enriched_args,
        prior_status,
        ui_product=ui_bound or ui_applicability["state"] == "required",
    )
    has_ui_verifier = _has_public_ui_verifier(ui_criteria)
    ui_gaps = _ui_readiness_gaps(
        ui_applicability,
        ui_bound=ui_bound,
        has_ui_verifier=has_ui_verifier,
    )
    if (
        prior_status is not None
        and not isinstance(prior_status.get("uiContract"), dict)
        and ui_applicability["state"] != "inactive"
    ):
        blocked = _ui_readiness_block(
            ["product-interface-new-loop"], program=False
        )
        blocked["promptCompilation"] = prompt_binding
        return blocked
    if ui_bound != has_ui_verifier:
        blocked = _ui_readiness_block(
            ui_gaps,
            program=False,
        )
        blocked["promptCompilation"] = prompt_binding
        return blocked
    try:
        assessment = _loop_call(
            lambda: loop_core.assess_goal_readiness(
                enriched_args,
                project_root=str(project_path),
                subject=subject,
                worktree=worktree["isLinkedWorktree"],
                policy_source=policy.get("_sourcePath"),
                policy_digest=subject["policyDigest"],
                loop_id=loop_id,
                prior_contract_digest=prior_contract_digest,
            )
        )
    except ToolError:
        if ui_gaps:
            blocked = _ui_readiness_block(ui_gaps, program=False)
            blocked["promptCompilation"] = prompt_binding
            return blocked
        raise
    assessment.pop("_contract", None)
    if ui_gaps:
        blocked = _merge_ui_readiness_block(
            assessment, ui_gaps, program=False
        )
        blocked["promptCompilation"] = prompt_binding
        return blocked
    if assessment.get("ready") is not True:
        assessment["receiptIssued"] = False
        assessment["promptCompilation"] = prompt_binding
        return assessment
    if _prompt_mode() != "disabled" and prompt_binding is None:
        raise ToolError(
            "A non-empty goal is required before Prompt Compiler-bound loop readiness can issue a receipt."
        )
    subject_after = evidence_subject(project_path)
    if any(
        subject_after[field] != subject[field]
        for field in ("gitHead", "projectFingerprint", "policyDigest", "toolVersion")
    ):
        raise ToolError(
            "The project changed during goal-readiness assessment. Re-run the intake against one stable state."
        )
    expires_at = (
        _dt.datetime.now(_dt.timezone.utc)
        + _dt.timedelta(seconds=GOAL_READINESS_RECEIPT_MAX_AGE_SECONDS)
    ).replace(microsecond=0).isoformat()
    confirmation_reference = str(assessment.get("confirmationReference") or "")
    receipt = issue_receipt(
        {
            "kind": "goal-readiness",
            "schemaVersion": loop_core.GOAL_READINESS_RECEIPT_SCHEMA,
            "expiresAt": expires_at,
            "projectPath": subject_after["gitRoot"],
            "gitHead": subject_after["gitHead"],
            "projectFingerprint": subject_after["projectFingerprint"],
            "baseRef": subject_after.get("baseRef"),
            "baseCommit": subject_after.get("baseCommit"),
            "policyDigest": subject_after["policyDigest"],
            "toolVersion": SERVER_VERSION,
            "loopId": loop_id,
            "priorContractDigest": prior_contract_digest,
            "readinessDigest": assessment["readinessDigest"],
            "contractInputDigest": assessment["contractInputDigest"],
            "contextDigest": assessment["contextDigest"],
            "confirmationRequired": assessment["confirmationRequired"],
            "confirmationReferenceDigest": (
                hashlib.sha256(confirmation_reference.encode("utf-8")).hexdigest()
                if confirmation_reference
                else None
            ),
            "passed": True,
            **_prompt_receipt_binding_fields(prompt_binding),
        }
    )
    assessment["goalReadinessReceipt"] = receipt
    assessment["receiptExpiresAt"] = expires_at
    assessment["receiptIssued"] = True
    assessment["promptCompilation"] = prompt_binding
    assessment["receiptMeaning"] = (
        "Session-local proof that the exact goal context and contract were readiness-checked "
        "against the current project state; it executes no implementation or external action "
        "and does not widen user scope."
    )
    return assessment


def tool_loop_start(args: dict[str, Any]) -> dict[str, Any]:
    _reject_loop_secret_inputs(args)
    project_path = require_project_path(args.get("project_path"))
    subject, policy, worktree = stable_loop_contract_context(project_path)
    enriched_args = _loop_args_with_ui_contract(args, project_path, subject)
    ui_goals, ui_paths, ui_criteria = _loop_ui_contract_inputs(args)
    ui_applicability = _ui_contract_applicability(
        project_path, goals=ui_goals, path_patterns=ui_paths
    )
    ui_bound = isinstance(enriched_args.get("ui_contract_binding"), dict)
    enriched_args = _loop_args_with_capabilities(
        enriched_args,
        ui_product=ui_bound or ui_applicability["state"] == "required",
    )
    _enforce_ui_contract_route(
        ui_applicability,
        ui_bound=ui_bound,
        has_ui_verifier=_has_public_ui_verifier(ui_criteria),
        operation="loop start",
    )
    readiness_attestation = _verified_goal_readiness_attestation(
        args.get("goal_readiness_receipt"), subject
    )
    service = _loop_service(project_path)
    result = _loop_call(
        lambda: service.start(
            enriched_args,
            subject=subject,
            worktree=worktree["isLinkedWorktree"],
            policy_source=policy.get("_sourcePath"),
            policy_digest=subject["policyDigest"],
            readiness_attestation=readiness_attestation,
        )
    )
    result["worktreeAttestation"] = worktree
    result["nativeGoalContract"] = {
        "createGoalRequired": True,
        "objective": result["goal"],
        "tokenBudget": args.get("token_budget"),
        "completionRule": "Call update_goal complete only after jstack_loop_finalize returns a current passed completionReceipt.",
        "blockedRule": "Call update_goal blocked only after the same blocker repeats for three consecutive Codex Goal turns.",
    }
    return result


def tool_loop_status(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    service = _loop_service(project_path)
    result = _loop_call(lambda: service.status(str(args.get("loop_id") or "") or None))
    subject = evidence_subject(project_path, result["baselineCommit"])
    result["projectState"] = {
        "gitHead": subject["gitHead"],
        "projectFingerprint": subject["projectFingerprint"],
        "clean": subject["clean"],
        "policyDigest": subject["policyDigest"],
        "toolVersion": subject["toolVersion"],
    }
    result["snapshotMatchesCurrentProject"] = (
        result.get("currentFingerprint") == subject["projectFingerprint"]
    )
    result["baselineAncestryValid"] = (
        subject.get("baseCommit") == result["baselineCommit"]
    )
    result["policyMatchesContract"] = result["policyDigest"] == subject["policyDigest"]
    result["toolVersionMatchesContract"] = (
        result["contractToolVersion"] == subject["toolVersion"]
    )
    result["capabilityCatalogMatchesContract"] = (
        _loop_capability_contract_matches(result)
    )
    result["productInterfaceCatalogMatchesContract"] = (
        None
        if result.get("uiContract") is None
        else result["uiContract"].get("catalogSha256")
        == ui_core.canonical_digest(ui_core.load_catalog())
    )
    return result


def tool_loop_checkpoint(args: dict[str, Any]) -> dict[str, Any]:
    _reject_loop_secret_inputs(args)
    project_path = require_project_path(args.get("project_path"))
    service = _loop_service(project_path)
    loop_id = str(args.get("loop_id") or "")
    status = _loop_call(lambda: service.status(loop_id))
    context = _loop_iteration_evidence(project_path, status, args)
    return _loop_call(
        lambda: service.checkpoint(
            loop_id,
            expected_contract_digest=status["contractDigest"],
            subject=context["subject"],
            policy_digest=context["subject"]["policyDigest"],
            changed_files=context["changedFiles"],
            protected_files=context["protectedFiles"],
            evidence=context["evidence"],
            summary=str(args.get("iteration_summary") or ""),
            failure_signature=args.get("failure_signature"),
            blocker=args.get("blocker"),
        )
    )


def tool_loop_revise(args: dict[str, Any]) -> dict[str, Any]:
    _reject_loop_secret_inputs(args)
    project_path = require_project_path(args.get("project_path"))
    subject, policy, worktree = stable_loop_contract_context(project_path)
    service = _loop_service(project_path)
    loop_id = str(args.get("loop_id") or "")
    prior_status = _loop_call(lambda: service.status(loop_id))
    enriched_args = _loop_args_with_ui_contract(
        args, project_path, subject, prior_status
    )
    ui_goals, ui_paths, ui_criteria = _loop_ui_contract_inputs(
        args, prior_status
    )
    ui_applicability = _ui_contract_applicability(
        project_path, goals=ui_goals, path_patterns=ui_paths
    )
    prior_ui_bound = isinstance(prior_status.get("uiContract"), dict)
    ui_bound = isinstance(enriched_args.get("ui_contract_binding"), dict)
    enriched_args = _loop_args_with_capabilities(
        enriched_args,
        prior_status,
        ui_product=ui_bound or ui_applicability["state"] == "required",
    )
    if not prior_ui_bound and ui_applicability["state"] != "inactive":
        raise ToolError(
            "The revised loop is Product Interface applicable, but the frozen public loop revision contract cannot add ui_contract_receipt. Stop this loop and start a new UI-bound loop through jstack_ui_contract, jstack_loop_goal_readiness, and jstack_loop_start with a dedicated ui verifier."
        )
    _enforce_ui_contract_route(
        ui_applicability,
        ui_bound=ui_bound,
        has_ui_verifier=_has_public_ui_verifier(ui_criteria),
        operation="loop revision",
    )
    readiness_attestation = None
    if args.get("goal_readiness_receipt") is not None:
        readiness_attestation = _verified_goal_readiness_attestation(
            args.get("goal_readiness_receipt"), subject
        )
    return _loop_call(
        lambda: service.revise(
            loop_id,
            enriched_args,
            subject=subject,
            worktree=worktree["isLinkedWorktree"],
            policy_source=policy.get("_sourcePath"),
            policy_digest=subject["policyDigest"],
            readiness_attestation=readiness_attestation,
        )
    )


def tool_loop_stop(args: dict[str, Any]) -> dict[str, Any]:
    _reject_loop_secret_inputs(args)
    project_path = require_project_path(args.get("project_path"))
    service = _loop_service(project_path)
    return _loop_call(
        lambda: service.stop(
            str(args.get("loop_id") or ""),
            str(args.get("reason") or ""),
        )
    )


def tool_loop_finalize(args: dict[str, Any]) -> dict[str, Any]:
    _reject_loop_secret_inputs(args)
    project_path = require_project_path(args.get("project_path"))
    service = _loop_service(project_path)
    loop_id = str(args.get("loop_id") or "")
    status = _loop_call(lambda: service.status(loop_id))
    context = _loop_iteration_evidence(project_path, status, args)
    result = _loop_call(
        lambda: service.finalize(
            loop_id,
            expected_contract_digest=status["contractDigest"],
            subject=context["subject"],
            policy_digest=context["subject"]["policyDigest"],
            changed_files=context["changedFiles"],
            protected_files=context["protectedFiles"],
            evidence=context["evidence"],
            summary=str(args.get("completion_summary") or ""),
        )
    )
    receipt_subject = evidence_subject(project_path, status["baselineCommit"])
    if any(
        receipt_subject[field] != context["subject"][field]
        for field in ("gitHead", "projectFingerprint", "policyDigest", "toolVersion")
    ):
        raise ToolError(
            "The project changed after loop finalization. No completion receipt was issued; restore the finalized state and revalidate it."
        )
    expires_at = (
        _dt.datetime.now(_dt.timezone.utc) + _dt.timedelta(seconds=RECEIPT_MAX_AGE_SECONDS)
    ).replace(microsecond=0).isoformat()
    receipt = issue_receipt(
        {
            "kind": "loop",
            "schemaVersion": "jstack.loop.receipt.v1",
            "expiresAt": expires_at,
            "projectPath": receipt_subject["gitRoot"],
            "gitHead": receipt_subject["gitHead"],
            "projectFingerprint": receipt_subject["projectFingerprint"],
            "baseRef": receipt_subject["baseRef"],
            "baseCommit": receipt_subject["baseCommit"],
            "policyDigest": receipt_subject["policyDigest"],
            "toolVersion": SERVER_VERSION,
            "loopId": loop_id,
            "contractDigest": result["contractDigest"],
            "completionEvidenceDigest": result["completionEvidenceDigest"],
            "latestEventHash": result["latestEventHash"],
            "executionMode": result["executionMode"],
            "capabilityCatalogDigest": (result.get("capabilityContract") or {}).get(
                "catalogDigest"
            ),
            "capabilitySelectionDigest": (result.get("capabilityContract") or {}).get(
                "selectionDigest"
            ),
            "specialistHandoffReceiptDigest": (
                context["evidence"].get("specialistHandoff") or {}
            ).get("receiptDigest"),
            "uiFinalizationReceiptDigest": (
                context["evidence"].get("ui") or {}
            ).get("receiptDigest"),
            "uiContractSha256": (result.get("uiContract") or {}).get(
                "contractSha256"
            ),
            "autonomyLevel": result["autonomyLevel"],
            "riskTier": result["riskTier"],
            "passed": True,
        }
    )
    result["completionReceipt"] = receipt
    result["receiptMeaning"] = (
        "Session-local proof that the current Git state satisfied the versioned loop contract; "
        "it authorizes no repository, Git, release, deployment, production, or other blocked action."
    )
    return result


def _program_service(project_path: Path) -> program_core.ProgramService:
    return program_core.ProgramService(Path.home(), project_path)


def _program_args_with_ui_contract(
    args: dict[str, Any],
    project_path: Path,
    subject: dict[str, Any],
    prior_status: Optional[dict[str, Any]] = None,
) -> dict[str, Any]:
    """Replace a public opaque receipt with one exact server-derived UI binding."""
    enriched = dict(args)
    receipt = args.get("ui_contract_receipt")
    if receipt is not None:
        enriched["ui_contract_binding"] = _loop_ui_contract_binding(
            project_path, subject, receipt
        )
    elif isinstance((prior_status or {}).get("uiContract"), dict):
        enriched["ui_contract_binding"] = dict(prior_status["uiContract"])
    enriched.pop("ui_contract_receipt", None)
    enriched.pop("prompt_compilation_receipt", None)
    enriched.pop("prompt_contract", None)
    return enriched


def _program_operation_id(args: dict[str, Any]) -> str:
    value = args.get("operation_id")
    if not isinstance(value, str) or not re.fullmatch(
        r"[A-Za-z0-9][A-Za-z0-9._:-]{0,99}", value
    ):
        raise ToolError(
            "A unique operation_id using 1-100 letters, numbers, dots, underscores, colons, or hyphens is required."
        )
    return value


def _program_call(operation: Callable[[], dict[str, Any]]) -> dict[str, Any]:
    try:
        return operation()
    except program_core.ProgramError as exc:
        raise ToolError(str(exc)) from exc


def _program_policy_gaps(args: dict[str, Any], policy: dict[str, Any]) -> list[dict[str, str]]:
    criteria = args.get("final_acceptance_criteria") or []
    verifiers = [
        item.get("verifier") or {}
        for item in criteria
        if isinstance(item, dict)
    ]
    gaps: list[dict[str, str]] = []
    program_policy = policy.get("program") or {}
    if program_policy.get("requireFinalAudit") is True and not any(
        verifier.get("type") == "audit" and verifier.get("profile") == "release"
        for verifier in verifiers
    ):
        gaps.append(
            {
                "id": "final-release-audit",
                "question": "Add a final audit criterion using the release profile so program completion has complete current audit coverage.",
                "why": "Enterprise program policy requires repository-wide release-audit evidence before the complete program can be certified.",
                "recommendedDefault": "Add a final acceptance criterion with verifier type audit and profile release.",
            }
        )
    if program_policy.get("requireCurrentEvidence") is True and not any(
        verifier.get("type") == "security" for verifier in verifiers
    ):
        gaps.append(
            {
                "id": "final-security",
                "question": "Add a final security criterion backed by a current JStack security receipt.",
                "why": "Phase-level checks do not prove that the final integrated program state satisfies the current security policy.",
                "recommendedDefault": "Add a final acceptance criterion with verifier type security.",
            }
        )
    if program_policy.get("requireCurrentEvidence") is True and not any(
        verifier.get("type") == "review" for verifier in verifiers
    ):
        gaps.append(
            {
                "id": "final-review",
                "question": "Add a final deterministic review criterion for the complete integrated program delta.",
                "why": "A final review catches integration defects and scope drift that isolated phase evidence can miss.",
                "recommendedDefault": "Add a final acceptance criterion with verifier type review.",
            }
        )
    return gaps


def _verified_program_readiness_attestation(
    receipt: Any, subject: dict[str, Any]
) -> dict[str, Any]:
    if (
        not isinstance(receipt, str)
        or not receipt
        or len(receipt) > PROGRAM_MAX_RECEIPT_CHARS
    ):
        raise ToolError(
            "A bounded program_readiness_receipt returned by jstack_program_goal_readiness is required."
        )
    verification = verify_receipt(
        receipt,
        "program-goal-readiness",
        subject,
        expected_subject=subject,
    )
    payload = verification["payload"]
    if (
        not verification["valid"]
        or payload.get("schemaVersion")
        != program_core.PROGRAM_READINESS_RECEIPT_SCHEMA
        or not _prompt_receipt_binding_valid(payload)
    ):
        raise ToolError(
            "The program-readiness receipt is stale, malformed, from another session, or bound to a different project state."
        )
    return {**payload, "receiptDigest": _receipt_digest(receipt)}


def _program_baseline_ancestry(project_path: Path, baseline: str) -> bool:
    result = run_complete(
        ["git", "merge-base", baseline, "HEAD"],
        project_path,
        timeout=10,
    )
    return result["ok"] and _git_text(result).strip() == baseline


def _canonical_program_payload(value: dict[str, Any]) -> bytes:
    return json.dumps(
        value,
        ensure_ascii=True,
        allow_nan=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")


def _program_human_decision(
    project_path: Path,
    program_id: str,
    gate_id: str,
    approver_id: str,
    approver_role: str,
    decision: str,
    reference: str,
    valid_for_minutes: Optional[int],
) -> dict[str, Any]:
    context = _program_call(
        lambda: _program_service(project_path).gate_context(program_id, gate_id)
    )
    gate = context["gate"]
    if gate["type"] != "human":
        raise ToolError("Only human program gates accept conversational decisions.")
    if not re.fullmatch(r"[a-z][a-z0-9]*(?:-[a-z0-9]+)*", approver_id):
        raise ToolError("approver_id must use lowercase hyphen-case.")
    if approver_role not in gate["requiredRoles"]:
        raise ToolError("approver_role must be one of the roles required by this gate.")
    if decision not in {"approved", "rejected"}:
        raise ToolError("Program gate decision must be approved or rejected.")
    reference = str(reference or "").strip()
    if not reference or len(reference) > 500:
        raise ToolError("A bounded approval_reference is required.")
    if audit_core.contains_secret_like(reference):
        raise ToolError("Approval references must not contain secret-like values.")
    requested = valid_for_minutes
    if requested is None:
        requested = min(60, int(gate["maxAgeMinutes"]))
    if (
        not isinstance(requested, int)
        or isinstance(requested, bool)
        or not 1 <= requested <= int(gate["maxAgeMinutes"])
    ):
        raise ToolError(
            "valid_for_minutes must be within the gate maximum of %d."
            % gate["maxAgeMinutes"]
        )
    issued = _dt.datetime.now(_dt.timezone.utc).replace(microsecond=0)
    record = {
        "schemaVersion": program_core.HUMAN_DECISION_SCHEMA,
        "programId": program_id,
        "gateId": gate_id,
        "contractDigest": context["contractDigest"],
        "gateDigest": context["gateDigest"],
        "approverId": approver_id,
        "roles": [approver_role],
        "decision": decision,
        "referenceDigest": hashlib.sha256(reference.encode("utf-8")).hexdigest(),
        "issuedAt": issued.isoformat(),
        "expiresAt": (issued + _dt.timedelta(minutes=requested)).isoformat(),
    }
    record["decisionDigest"] = hashlib.sha256(
        _canonical_program_payload(record)
    ).hexdigest()
    return record


def _program_artifact_path(
    project_path: Path, raw_path: str
) -> tuple[Path, str, Path]:
    candidate = Path(raw_path).expanduser()
    if not candidate.is_absolute():
        candidate = project_path / candidate
    if candidate.is_symlink():
        raise ToolError("Program evidence artifacts may not be symlinks.")
    try:
        resolved = candidate.resolve(strict=True)
    except OSError as exc:
        raise ToolError("Program evidence artifact is missing or inaccessible.") from exc
    allowed_roots = [
        project_path.resolve(),
        (Path.home() / ".jstack" / "evidence").resolve(strict=False),
    ]
    selected_root = None
    relative = None
    for root in allowed_roots:
        try:
            candidate_relative = resolved.relative_to(root)
        except ValueError:
            continue
        if candidate_relative.parts:
            selected_root = root
            relative = candidate_relative.as_posix()
            break
    if selected_root is None or relative is None:
        raise ToolError(
            "External evidence must be inside the Git project or ~/.jstack/evidence."
        )
    metadata = resolved.stat()
    if not stat.S_ISREG(metadata.st_mode) or metadata.st_size > PROGRAM_MAX_ARTIFACT_BYTES:
        raise ToolError("Program evidence must be a regular file no larger than 100 MB.")
    return selected_root, relative, resolved


def _program_file_digest(
    root: Path,
    relative_path: str,
    *,
    maximum: int,
) -> tuple[int, str]:
    try:
        return audit_core.digest_repository_file(
            root,
            relative_path,
            max_bytes=maximum,
            max_seconds=PROGRAM_ARTIFACT_TIMEOUT_SECONDS,
        )
    except audit_core.AuditError as exc:
        raise ToolError(
            "Program evidence artifact could not be opened with stable file identity."
        ) from exc


def _program_phase_output_digests(
    child_project: Path,
    outputs: list[dict[str, Any]],
) -> dict[str, str]:
    result: dict[str, str] = {}
    total = 0
    for output in outputs:
        remaining = PROGRAM_MAX_ARTIFACT_BYTES - total
        if remaining <= 0:
            raise ToolError("Program phase outputs exceed the aggregate 100 MB boundary.")
        try:
            size, digest = audit_core.digest_repository_file(
                child_project,
                output["path"],
                max_bytes=min(25_000_000, remaining),
                max_seconds=PROGRAM_ARTIFACT_TIMEOUT_SECONDS,
            )
        except audit_core.AuditError as exc:
            raise ToolError(
                "Program phase output is missing or unsafe: %s" % output["path"]
            ) from exc
        total += size
        result[output["id"]] = digest
    return result


def _program_child_integrity(
    status: dict[str, Any],
    *,
    verify_outputs: bool,
) -> dict[str, Any]:
    results: list[dict[str, Any]] = []
    for phase in status.get("phases", []):
        proof = phase.get("completionProof")
        child = phase.get("child")
        if not isinstance(proof, dict):
            continue
        checks: dict[str, bool] = {}
        error = None
        try:
            if not isinstance(child, dict):
                raise ToolError("missing child binding")
            child_project = require_project_path(child.get("projectPath"))
            worktree = git_worktree_attestation(child_project)
            child_service = _loop_service(child_project)
            child_status = _loop_call(
                lambda: child_service.status(str(child.get("loopId") or ""))
            )
            attestation = _loop_call(
                lambda: child_service.completion_attestation(
                    str(child.get("loopId") or "")
                )
            )
            checks = {
                "commonRepository": worktree["commonDirDigest"]
                == status["commonDirDigest"],
                "loopId": attestation.get("loopId") == proof.get("loopId"),
                "projectPath": attestation.get("projectPath")
                == proof.get("projectPath"),
                "contractDigest": attestation.get("contractDigest")
                == proof.get("contractDigest"),
                "completionEvidence": attestation.get("completionEvidenceDigest")
                == proof.get("loopCompletionEvidenceDigest"),
                "eventHead": attestation.get("latestEventHash")
                == proof.get("loopLatestEventHash"),
                "passed": attestation.get("passed") is True,
            }
            child_ui_contract = child.get("uiContract")
            if isinstance(child_ui_contract, dict):
                checks.update(
                    {
                        "uiProofSchema": proof.get("schemaVersion")
                        == program_core.PHASE_COMPLETION_PROOF_SCHEMA_V2,
                        "uiStatusContract": child_status.get("uiContract")
                        == child_ui_contract,
                        "uiAttestationContract": attestation.get("uiContract")
                        == child_ui_contract,
                        "uiProofContract": proof.get("uiContract")
                        == child_ui_contract,
                        "uiReceipt": proof.get(
                            "loopUiFinalizationReceiptDigest"
                        )
                        == attestation.get("uiFinalizationReceiptDigest"),
                    }
                )
            else:
                checks.update(
                    {
                        "nonUiProofSchema": proof.get("schemaVersion")
                        == program_core.PHASE_COMPLETION_PROOF_SCHEMA,
                        "nonUiStatus": child_status.get("uiContract") is None,
                        "nonUiAttestation": attestation.get("uiContract") is None,
                    }
                )
            if verify_outputs:
                current_outputs = _program_phase_output_digests(
                    child_project, phase.get("outputs") or []
                )
                checks["outputs"] = current_outputs == phase.get("outputDigests", {})
        except (ToolError, OSError) as exc:
            error = str(exc)
            checks["load"] = False
        results.append(
            {
                "phaseId": phase["id"],
                "valid": bool(checks) and all(checks.values()),
                "checks": checks,
                "error": error,
            }
        )
    return {
        "valid": all(item["valid"] for item in results),
        "phases": results,
        "outputsVerified": verify_outputs,
    }


def _program_status_integrity(
    project_path: Path,
    status: dict[str, Any],
    *,
    verify_outputs: bool = False,
) -> dict[str, Any]:
    subject = evidence_subject(project_path)
    worktree = git_worktree_attestation(project_path)
    child_integrity = _program_child_integrity(
        status, verify_outputs=verify_outputs
    )
    context_checks = {
        "policy": status["policyDigest"] == subject["policyDigest"],
        "toolVersion": status["contractToolVersion"] == subject["toolVersion"],
        "commonRepository": status["commonDirDigest"]
        == worktree["commonDirDigest"],
        "baselineAncestry": _program_baseline_ancestry(
            project_path, status["baselineCommit"]
        ),
    }
    passed = all(context_checks.values()) and child_integrity["valid"]
    status["integrity"] = {
        "valid": passed,
        "contextChecks": context_checks,
        "childProofs": child_integrity,
        "currentProject": {
            "gitHead": subject["gitHead"],
            "projectFingerprint": subject["projectFingerprint"],
            "policyDigest": subject["policyDigest"],
            "toolVersion": subject["toolVersion"],
        },
    }
    if not passed and status["status"] not in {"completed", "cancelled"}:
        status["status"] = "blocked"
        status["decision"] = "needs_revision"
        status["readyPhaseIds"] = []
    status["completionRevalidatable"] = passed
    return status


def tool_program_goal_readiness(args: dict[str, Any]) -> dict[str, Any]:
    _reject_loop_secret_inputs(args)
    project_path = require_project_path(args.get("project_path"))
    subject, policy, worktree = stable_loop_contract_context(project_path)
    service = _program_service(project_path)
    program_id = str(args.get("program_id") or "").strip() or None
    prior_contract_digest = None
    prior_status = None
    if program_id:
        status = _program_call(lambda: service.status(program_id))
        if status["status"] in {"completed", "cancelled"}:
            raise ToolError("Terminal programs cannot receive a revised readiness receipt.")
        prior_contract_digest = status["contractDigest"]
        prior_status = status
    prompt_goal = str(
        args.get("goal")
        or (prior_status or {}).get("goal")
        or ""
    ).strip()
    prompt_binding = (
        _prompt_orchestration_binding(
            args,
            goal=prompt_goal,
            workflow_mode="jstack-loop",
            binding=resolve_project_binding(str(project_path)),
        )
        if prompt_goal
        else None
    )
    enriched_args = _program_args_with_ui_contract(
        args, project_path, subject, prior_status
    )
    ui_goals, ui_paths, ui_criteria = _program_ui_contract_inputs(
        args, prior_status
    )
    ui_applicability = _ui_contract_applicability(
        project_path, goals=ui_goals, path_patterns=ui_paths
    )
    ui_gaps = _ui_readiness_gaps(
        ui_applicability,
        ui_bound=isinstance(enriched_args.get("ui_contract_binding"), dict),
        has_ui_verifier=_has_public_ui_verifier(ui_criteria),
    )
    if ui_gaps:
        contract_gaps = [
            field
            for field in (
                "goal",
                "owner",
                "stakeholders",
                "phases",
                "final_acceptance_criteria",
            )
            if enriched_args.get(field) is None
            or enriched_args.get(field) == ""
            or enriched_args.get(field) == []
        ]
        if contract_gaps:
            incomplete_assessment = _program_call(
                lambda: program_core.assess_program_readiness(
                    enriched_args,
                    project_root=str(project_path),
                    subject=subject,
                    policy_source=policy.get("_sourcePath"),
                    policy_digest=subject["policyDigest"],
                    common_dir_digest=worktree["commonDirDigest"],
                    program_policy=policy.get("program"),
                    program_id=program_id,
                    prior_contract_digest=prior_contract_digest,
                )
            )
            blocked = _merge_ui_readiness_block(
                incomplete_assessment, ui_gaps, program=True
            )
            blocked["promptCompilation"] = prompt_binding
            return blocked
        blocked = _ui_readiness_block(ui_gaps, program=True)
        blocked["promptCompilation"] = prompt_binding
        return blocked
    policy_gaps = _program_policy_gaps(enriched_args, policy)
    if policy_gaps:
        blocked = {
            "schemaVersion": program_core.PROGRAM_READINESS_SCHEMA,
            "status": "needs_context",
            "ready": False,
            "gaps": [item["id"] for item in policy_gaps],
            "questions": [
                {
                    "id": item["id"],
                    "question": item["question"],
                    "why": item["why"],
                    "recommendedDefault": item["recommendedDefault"],
                    "blocking": True,
                }
                for item in policy_gaps[:3]
            ],
            "receiptIssued": False,
        }
        blocked["promptCompilation"] = prompt_binding
        return blocked
    assessment = _program_call(
        lambda: program_core.assess_program_readiness(
            enriched_args,
            project_root=str(project_path),
            subject=subject,
            policy_source=policy.get("_sourcePath"),
            policy_digest=subject["policyDigest"],
            common_dir_digest=worktree["commonDirDigest"],
            program_policy=policy.get("program"),
            program_id=program_id,
            prior_contract_digest=prior_contract_digest,
        )
    )
    assessment.pop("_contract", None)
    if assessment.get("ready") is not True:
        assessment["receiptIssued"] = False
        assessment["promptCompilation"] = prompt_binding
        return assessment
    if _prompt_mode() != "disabled" and prompt_binding is None:
        raise ToolError(
            "A non-empty goal is required before Prompt Compiler-bound program readiness can issue a receipt."
        )
    subject_after = evidence_subject(project_path)
    if any(
        subject_after[field] != subject[field]
        for field in ("gitHead", "projectFingerprint", "policyDigest", "toolVersion")
    ):
        raise ToolError(
            "The project changed during program-readiness assessment. Re-run against one stable state."
        )
    expires_at = (
        _dt.datetime.now(_dt.timezone.utc)
        + _dt.timedelta(seconds=GOAL_READINESS_RECEIPT_MAX_AGE_SECONDS)
    ).replace(microsecond=0).isoformat()
    confirmation_reference = str(assessment.get("confirmationReference") or "")
    receipt = issue_receipt(
        {
            "kind": "program-goal-readiness",
            "schemaVersion": program_core.PROGRAM_READINESS_RECEIPT_SCHEMA,
            "expiresAt": expires_at,
            "projectPath": subject_after["gitRoot"],
            "gitHead": subject_after["gitHead"],
            "projectFingerprint": subject_after["projectFingerprint"],
            "baseRef": subject_after.get("baseRef"),
            "baseCommit": subject_after.get("baseCommit"),
            "policyDigest": subject_after["policyDigest"],
            "toolVersion": SERVER_VERSION,
            "programId": program_id,
            "priorContractDigest": prior_contract_digest,
            "readinessDigest": assessment["readinessDigest"],
            "contractInputDigest": assessment["contractInputDigest"],
            "confirmationRequired": assessment["confirmationRequired"],
            "confirmationReferenceDigest": (
                hashlib.sha256(confirmation_reference.encode("utf-8")).hexdigest()
                if confirmation_reference
                else None
            ),
            "passed": True,
            **_prompt_receipt_binding_fields(prompt_binding),
        }
    )
    assessment.update(
        {
            "programReadinessReceipt": receipt,
            "receiptExpiresAt": expires_at,
            "receiptIssued": True,
            "promptCompilation": prompt_binding,
            "receiptMeaning": (
                "Session-local proof that the exact program DAG and acceptance boundary were readiness-checked; "
                "it does not approve implementation, release, deployment, or a human gate."
            ),
        }
    )
    return assessment


def tool_program_start(args: dict[str, Any]) -> dict[str, Any]:
    _reject_loop_secret_inputs(args)
    operation_id = _program_operation_id(args)
    project_path = require_project_path(args.get("project_path"))
    subject, policy, worktree = stable_loop_contract_context(project_path)
    if subject.get("clean") is not True:
        raise ToolError("Program orchestration must start from a clean Git worktree.")
    enriched_args = _program_args_with_ui_contract(args, project_path, subject)
    ui_goals, ui_paths, ui_criteria = _program_ui_contract_inputs(args)
    ui_applicability = _ui_contract_applicability(
        project_path, goals=ui_goals, path_patterns=ui_paths
    )
    _enforce_ui_contract_route(
        ui_applicability,
        ui_bound=isinstance(enriched_args.get("ui_contract_binding"), dict),
        has_ui_verifier=_has_public_ui_verifier(ui_criteria),
        operation="program start",
    )
    policy_gaps = _program_policy_gaps(enriched_args, policy)
    if policy_gaps:
        raise ToolError(
            "Program contract does not satisfy policy: "
            + ", ".join(item["id"] for item in policy_gaps)
        )
    attestation = _verified_program_readiness_attestation(
        args.get("program_readiness_receipt"), subject
    )
    service = _program_service(project_path)
    result = _program_call(
        lambda: service.start(
            enriched_args,
            subject=subject,
            policy_source=policy.get("_sourcePath"),
            policy_digest=subject["policyDigest"],
            common_dir_digest=worktree["commonDirDigest"],
            program_policy=policy.get("program"),
            readiness_attestation=attestation,
            operation_id=operation_id,
        )
    )
    result = _program_status_integrity(project_path, result)
    result["nativeGoalContract"] = {
        "createGoalRequired": True,
        "objective": result["goal"],
        "completionRule": (
            "Complete the native goal only after jstack_program_finalize returns a current passed completionReceipt."
        ),
        "blockedRule": (
            "Human or external waiting states are durable pauses, not native Goal blocked status."
        ),
    }
    return result


def tool_program_status(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    service = _program_service(project_path)
    result = _program_call(
        lambda: service.status(str(args.get("program_id") or "") or None)
    )
    return _program_status_integrity(project_path, result)


def tool_program_next(args: dict[str, Any]) -> dict[str, Any]:
    project_path = require_project_path(args.get("project_path"))
    service = _program_service(project_path)
    result = _program_call(
        lambda: service.next(str(args.get("program_id") or ""))
    )
    result = _program_status_integrity(project_path, result)
    if result["status"] != "running":
        result["scheduledPhaseIds"] = []
    return result


def tool_program_phase_bind(args: dict[str, Any]) -> dict[str, Any]:
    _reject_loop_secret_inputs(args)
    operation_id = _program_operation_id(args)
    project_path = require_project_path(args.get("project_path"))
    child_project = require_project_path(
        args.get("child_project_path") or args.get("project_path")
    )
    program_id = str(args.get("program_id") or "")
    phase_id = str(args.get("phase_id") or "")
    loop_id = str(args.get("loop_id") or "")
    parent_status = tool_program_status(
        {"project_path": str(project_path), "program_id": program_id}
    )
    if parent_status["status"] != "running":
        raise ToolError("Program integrity or lifecycle state does not allow phase binding.")
    child_status = _loop_call(lambda: _loop_service(child_project).status(loop_id))
    if child_status["status"] != "active":
        raise ToolError("Only an active bounded child loop can be bound to a program phase.")
    worktree = git_worktree_attestation(child_project)
    child = {
        "loopId": loop_id,
        "projectPath": str(child_project),
        "contractDigest": child_status["contractDigest"],
        "baselineCommit": child_status["baselineCommit"],
        "commonDirDigest": worktree["commonDirDigest"],
        "isLinkedWorktree": worktree["isLinkedWorktree"],
        "goal": child_status["goal"],
        "executionMode": child_status["executionMode"],
        "autonomyLevel": child_status["autonomyLevel"],
        "riskTier": child_status["riskTier"],
        "allowedPaths": child_status["allowedPaths"],
        "blockedActions": child_status["blockedActions"],
        "acceptanceCriteria": child_status["acceptanceCriteria"],
    }
    if isinstance(child_status.get("uiContract"), dict):
        child["uiContract"] = dict(child_status["uiContract"])
    result = _program_call(
        lambda: _program_service(project_path).bind_phase(
            program_id, phase_id, child, operation_id=operation_id
        )
    )
    return _program_status_integrity(project_path, result)


def tool_program_phase_complete(args: dict[str, Any]) -> dict[str, Any]:
    _reject_loop_secret_inputs(args)
    operation_id = _program_operation_id(args)
    project_path = require_project_path(args.get("project_path"))
    program_id = str(args.get("program_id") or "")
    phase_id = str(args.get("phase_id") or "")
    status = _program_call(lambda: _program_service(project_path).status(program_id))
    phase = next((item for item in status["phases"] if item["id"] == phase_id), None)
    if phase is None or not isinstance(phase.get("child"), dict):
        raise ToolError("Program phase has no bound child loop.")
    child = phase["child"]
    child_project = require_project_path(child["projectPath"])
    subject = evidence_subject(child_project, child["baselineCommit"])
    receipt = args.get("loop_completion_receipt")
    if not isinstance(receipt, str) or len(receipt) > PROGRAM_MAX_RECEIPT_CHARS:
        raise ToolError("A bounded current child loop completion receipt is required.")
    verification = verify_receipt(
        receipt,
        "loop",
        subject,
        expected_subject=subject,
    )
    durable = _loop_call(
        lambda: _loop_service(child_project).completion_attestation(child["loopId"])
    )
    payload = verification["payload"]
    if (
        not verification["valid"]
        or payload.get("loopId") != child["loopId"]
        or payload.get("contractDigest") != child["contractDigest"]
        or payload.get("completionEvidenceDigest")
        != durable["completionEvidenceDigest"]
        or payload.get("latestEventHash") != durable["latestEventHash"]
    ):
        raise ToolError("Child loop completion receipt and durable loop state do not match.")
    child_ui_contract = child.get("uiContract")
    ui_receipt_digest = payload.get("uiFinalizationReceiptDigest")
    if isinstance(child_ui_contract, dict):
        ui_checks = {
            "contract": durable.get("uiContract") == child_ui_contract,
            "contractSha256": payload.get("uiContractSha256")
            == child_ui_contract.get("contractSha256"),
            "receiptDigest": isinstance(ui_receipt_digest, str)
            and bool(re.fullmatch(r"[0-9a-f]{64}", ui_receipt_digest)),
            "durableReceipt": durable.get("uiFinalizationReceiptDigest")
            == ui_receipt_digest,
        }
        if not all(ui_checks.values()):
            raise ToolError(
                "UI child loop completion does not bind the exact durable Product Interface contract and receipt."
            )
    elif ui_receipt_digest is not None or durable.get("uiContract") is not None:
        raise ToolError(
            "A non-UI child loop may not supply Product Interface completion evidence."
        )
    output_digests = _program_phase_output_digests(
        child_project, phase.get("outputs") or []
    )
    proof = {
        "schemaVersion": (
            program_core.PHASE_COMPLETION_PROOF_SCHEMA_V2
            if isinstance(child_ui_contract, dict)
            else program_core.PHASE_COMPLETION_PROOF_SCHEMA
        ),
        "programId": program_id,
        "phaseId": phase_id,
        "phaseDigest": phase["phaseDigest"],
        "loopId": child["loopId"],
        "projectPath": str(child_project),
        "contractDigest": child["contractDigest"],
        "loopCompletionEvidenceDigest": durable["completionEvidenceDigest"],
        "loopLatestEventHash": durable["latestEventHash"],
        "loopReceiptDigest": _receipt_digest(receipt),
        "completedAt": durable["completedAt"],
        "passed": True,
    }
    if isinstance(child_ui_contract, dict):
        proof["uiContract"] = child_ui_contract
        proof["loopUiFinalizationReceiptDigest"] = ui_receipt_digest
    result = _program_call(
        lambda: _program_service(project_path).complete_phase(
            program_id,
            phase_id,
            proof,
            output_digests,
            operation_id=operation_id,
        )
    )
    return _program_status_integrity(project_path, result)


def tool_program_gate_resolve(args: dict[str, Any]) -> dict[str, Any]:
    _reject_loop_secret_inputs(args)
    operation_id = _program_operation_id(args)
